    def handle_month(self, query: dict[str, list[str]]) -> None:
        self.refresh_journals()
        year = int(first(query, "year") or today_local().year)
        month = int(first(query, "month") or today_local().month)
        prefix = f"{year:04d}-{month:02d}-"
        storage = Storage(self.configured_db_path)
        try:
            counts = journal_counts_for_month(
                storage,
                prefix=prefix,
                journals=self.configured_journals,
            )
        finally:
            storage.close()

        self.send_json(
            {
                "year": year,
                "month": month,
                "journals": self.configured_journals,
                "counts": counts,
            }
        )

    def handle_report(self, query: dict[str, list[str]]) -> None:
        self.refresh_journals()
        selected = first(query, "date") or today_local().isoformat()
        auto_fetch = first(query, "auto_fetch") != "0" and not self.documentation_mode
        force_fetch = first(query, "force_fetch") == "1" and not self.documentation_mode
        requested_refresh_journal = clean_text(first(query, "refresh_journal") or "")
        refresh_journal = ""
        if requested_refresh_journal:
            refresh_journal = next(
                (
                    journal
                    for journal in self.configured_journals
                    if journal.casefold() == requested_refresh_journal.casefold()
                ),
                "",
            )
            if not refresh_journal:
                self.send_error_json(HTTPStatus.BAD_REQUEST, "Unknown journal")
                return
        fetched = False
        missing_journals: list[str] = []
        storage = Storage(self.configured_db_path)
        try:
            selected_date = date.fromisoformat(selected)
            missing_journals = missing_fetch_journals_for_date(storage, selected, self.configured_journals)
            if force_fetch and refresh_journal:
                sources_to_fetch = manual_refresh_journals_for_date(selected, [refresh_journal])
            else:
                sources_to_fetch = manual_refresh_journals_for_date(selected, self.configured_journals) if force_fetch else missing_journals
            if (force_fetch or auto_fetch) and selected_date <= today_local() and sources_to_fetch and try_start_fetch(selected):
                storage.close()
                fetch_storage = None
                try:
                    config = load_config(db_path=self.configured_db_path)
                    fetch_storage = Storage(self.configured_db_path)
                    start_fetch_progress(selected, sources_to_fetch)
                    fetch_missing_sources_for_date(
                        config=config,
                        storage=fetch_storage,
                        selected=selected,
                        selected_date=selected_date,
                        missing_sources=sources_to_fetch,
                    )
                    fetched = True
                finally:
                    finish_fetch_progress(selected)
                    finish_active_fetch(selected)
                    if fetch_storage:
                        fetch_storage.close()
                storage = Storage(self.configured_db_path)
                self.configured_journals = configured_source_names(config)
                missing_journals = missing_fetch_journals_for_date(storage, selected, self.configured_journals)
            papers = storage.list_papers(
                start_date=selected,
                end_date=selected,
                journals=self.configured_journals,
            )
            papers = annotate_papers_with_library_status(storage, papers)
            fetch_errors = journal_fetch_errors_for_date(storage, selected, self.configured_journals)
            late_unread_ids = unread_late_arrival_paper_ids(storage, selected, self.configured_journals)
            late_arrivals = late_arrivals_for_seen_date(storage, selected, self.configured_journals)
        finally:
            storage.close()
        papers = [paper for paper in papers if paper.get("section_allowed") != 0]
        self.send_json(
            {
                "date": selected,
                "journals": self.configured_journals,
                "papers": [
                    monitor_paper_to_api(
                        paper,
                        late_arrival_unread=str(paper.get("paper_id") or "") in late_unread_ids,
                    )
                    for paper in papers
                ],
                "journalCounts": count_by_journal(papers),
                "lateArrivals": late_arrival_summaries(late_arrivals),
                "fetched": fetched,
                "forcedFetch": force_fetch,
                "refreshedJournal": refresh_journal,
                "missingJournals": missing_journals,
                "fetchErrors": fetch_errors,
                "fetchActive": is_fetch_active(selected),
            }
        )

    def handle_fetch_progress(self, query: dict[str, list[str]]) -> None:
        selected = first(query, "date") or today_local().isoformat()
        kind = clean_text(first(query, "kind") or "")
        self.send_json({"date": selected, "kind": kind, "progress": get_fetch_progress(selected, kind=kind)})

    def handle_monitor_auto_status(self) -> None:
        storage = Storage(self.configured_db_path)
        try:
            journal = json_setting(storage, AUTO_JOURNAL_MONITOR_STATUS_SETTING, {})
            arxiv = json_setting(storage, AUTO_ARXIV_MONITOR_STATUS_SETTING, {})
            subject = json_setting(storage, AUTO_SUBJECT_MONITOR_STATUS_SETTING, {})
            author = json_setting(storage, AUTO_AUTHOR_MONITOR_STATUS_SETTING, {})
            subject_retry = read_auto_subject_retry_state(storage)
        finally:
            storage.close()
        self.send_json(
            {
                "journal": journal if isinstance(journal, dict) else {},
                "arxiv": arxiv if isinstance(arxiv, dict) else {},
                "subject": subject if isinstance(subject, dict) else {},
                "author": author if isinstance(author, dict) else {},
                "subject_retry": subject_retry,
                "timezone": system_timezone_name(),
                "checked_at": now_iso(),
            }
        )

    def handle_arxiv_daily_refresh(self, query: dict[str, list[str]]) -> None:
        selected = first(query, "date") or datetime.now().astimezone().date().isoformat()
        if self.documentation_mode:
            self.send_json({"date": selected, "status": "skipped", "reason": "documentation_mode"})
            return
        try:
            selected_date = date.fromisoformat(selected)
        except ValueError:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Invalid date")
            return
        if selected_date > today_local():
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Future dates cannot be refreshed")
            return
        selected = selected_date.isoformat()
        force_fetch = first(query, "force") == "1" or first(query, "force_fetch") == "1"
        ready_at = arxiv_ready_time(selected_date)
        now = datetime.now().astimezone()
        if ready_at is None:
            self.send_json({"date": selected, "status": "skipped", "reason": "no_arxiv_announcement"})
            return
        if now < ready_at:
            self.send_json({"date": selected, "status": "skipped", "reason": "arxiv_not_ready", "readyAt": ready_at.isoformat()})
            return
        storage = Storage(self.configured_db_path)
        try:
            missing = missing_fetch_journals_for_date(storage, selected, [ARXIV_JOURNAL_NAME])
        finally:
            storage.close()
        if not force_fetch and ARXIV_JOURNAL_NAME not in missing:
            self.send_json({"date": selected, "status": "skipped"})
            return
        if not try_start_fetch(selected):
            self.send_json({"date": selected, "status": "active"})
            return

        def refresh_arxiv() -> None:
            fetch_storage = Storage(self.configured_db_path)
            try:
                start_fetch_progress(selected, [ARXIV_JOURNAL_NAME])
                result = fetch_one_arxiv_preprint_source(
                    storage=fetch_storage,
                    start_date=selected_date,
                    end_date=selected_date,
                    categories=configured_arxiv_categories(fetch_storage),
                    force_latest=selected_date >= today_local(),
                    require_latest_listing=selected_date >= today_local(),
                )
                match_local_arxiv_for_all_subjects(fetch_storage, selected_date)
                if result.get("source_statuses", {}).get("arxiv") == "success" and int(result.get("saved") or 0) > 0:
                    schedule_pending_arxiv_metadata_retry(fetch_storage, selected)
                    announcement_key, target_date, _ready_at = arxiv_auto_target(datetime.now(local_timezone()))
                    if target_date == selected_date:
                        fetch_storage.set_setting(AUTO_ARXIV_MONITOR_LAST_ANNOUNCEMENT_SETTING, announcement_key)
            finally:
                finish_fetch_progress(selected)
                finish_active_fetch(selected)
                fetch_storage.close()

        threading.Thread(target=refresh_arxiv, daemon=True).start()
        self.send_json({"date": selected, "status": "started"})

    def handle_paper(self, query: dict[str, list[str]]) -> None:
        paper_id = first(query, "paper_id")
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            paper = storage.get_paper(paper_id)
            if paper:
                annotated = annotate_papers_with_library_status(storage, [paper])
                paper = annotated[0] if annotated else paper
        finally:
            storage.close()
        if not paper:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Paper not found")
            return
        self.send_json({"paper": paper_to_api(paper)})

    def handle_paper_files(self, query: dict[str, list[str]]) -> None:
        paper_id = clean_text(first(query, "paper_id") or "")
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            paper = storage.get_paper(paper_id)
            if not paper:
                self.send_error_json(HTTPStatus.NOT_FOUND, "Paper not found")
                return
            resources = storage.list_paper_resources(paper_id)
            resolved = storage.resolve_default_paper_resource(paper_id)
            from .publication_notices import for_paper
            notices = for_paper(storage,paper['paper_id'])
            paper = storage.get_paper(paper_id) or paper
        finally:
            storage.close()
        self.send_json(
            {
                "paper_id": paper_id,
                "storage_key": paper.get("storage_key") or "",
                "primary_resource_id": int(paper.get("primary_resource_id") or 0),
                "preferred_resource_id": int(paper.get("preferred_resource_id") or 0),
                "preferred_resource_manual": bool(paper.get("preferred_resource_manual")),
                "default_resource_id": int((resolved or {}).get("id") or 0),
                "resolved_resource_id": int((resolved or {}).get("id") or 0),
                "files": paper_resources_to_api(resources),
                "publication_notices": notices,
            }
        )

    def handle_paper_semantic_influential(self, query: dict[str, list[str]]) -> None:
        paper_id = first(query, "paper_id")
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            paper = storage.get_paper(paper_id)
        finally:
            storage.close()
        if not paper:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Paper not found")
            return
        try:
            citations = fetch_semantic_scholar_influential_citations(paper, limit=20)
        except SemanticScholarRateLimitError as exc:
            self.send_error_json(HTTPStatus.TOO_MANY_REQUESTS, str(exc))
            return
        except Exception as exc:
            self.send_error_json(
                HTTPStatus.BAD_GATEWAY,
                "Semantic Scholar could not load influential citations right now. Try again later.",
            )
            return
        self.send_json({"paper_id": paper_id, "citations": citations})

    def handle_download(self, payload: dict[str, Any]) -> None:
        paper_id = str(payload.get("paper_id") or "")
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
            return
        with paper_download_lock(self.configured_db_path, paper_id):
            storage = Storage(self.configured_db_path)
            try:
                force_download = bool(payload.get("force"))
                target_dir = local_copy_dir_for_download_context(storage, payload)
                if target_dir is None:
                    target_dir = preferred_local_pdf_dir_for_paper(storage, paper_id)
                if target_dir:
                    reconcile_paper_pdf_storage(storage, paper_id, target_dir=target_dir)
                download_snapshot = snapshot_primary_resource_before_download(
                    storage,
                    paper_id,
                    force=force_download,
                )
                try:
                    result = download_paper(
                        storage=storage,
                        paper_id=paper_id,
                        target_dir=target_dir,
                        force=force_download,
                    )
                    register_downloaded_paper_resource(
                        storage,
                        paper_id,
                        result=result,
                        snapshot=download_snapshot,
                    )
                finally:
                    cleanup_download_resource_snapshot(download_snapshot)
                if target_dir:
                    reconcile_paper_pdf_storage(storage, paper_id, target_dir=target_dir)
                if target_dir:
                    context = clean_text(str(payload.get("context") or "")).lower()
                    if context == "my-publications":
                        sync_my_publication_alias(storage, paper_id)
                    elif context in {"library", "workspace", "space"}:
                        folder_id = int(payload.get("folder_id") or 0)
                        item_id = int(payload.get("item_id") or 0)
                        if item_id:
                            item = storage.get_library_item(item_id)
                            if item:
                                folder_id = int(item.get("folder_id") or folder_id or 1)
                        if folder_id:
                            sync_alias_for_library_item(storage, paper_id, folder_id)
                sync_all_pdf_aliases_for_paper(storage, paper_id)
                paper = storage.get_paper(paper_id)
            finally:
                storage.close()
            response_payload: dict[str, Any] = {
                "result": result,
                "paper": paper_to_api(paper) if paper else None,
            }
            browser_fallback = published_pdf_browser_fallback(paper, result)
            if browser_fallback:
                response_payload["browser_fallback"] = browser_fallback
            self.send_json(response_payload)

    def handle_manual_pdf(self) -> None:
        fields, files = self.read_multipart_body()
        paper_id = str(fields.get("paper_id") or "")
        upload = files.get("pdf")
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
            return
        if not upload:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "PDF file is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            target_path, paper = attach_manual_pdf_to_paper(
                storage,
                paper_id=paper_id,
                filename=str(upload.get("filename") or ""),
                context=fields,
                content=upload.get("content") or b"",
                preserve_filename=str(fields.get("preserve_filename") or "") == "1",
            )
            files_snapshot = paper_files_state_payload(storage, paper_id)
            paper = storage.get_paper(paper_id)
        except KeyError:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Paper not found")
            return
        except (FileNotFoundError, ValueError) as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        except (OSError, sqlite3.Error):
            logging.getLogger(__name__).exception("Could not import PDF for %s", paper_id)
            self.send_error_json(HTTPStatus.INTERNAL_SERVER_ERROR, "Could not save the PDF. Check the destination folder and try again.")
            return
        finally:
            storage.close()
        self.send_json({"result": {"status": "success", "merged_pdf_path": str(target_path)}, "paper": paper_to_api(paper) if paper else None, "paper_files": [files_snapshot]})

    def handle_add_paper_file(self) -> None:
        fields, files = self.read_multipart_body()
        paper_id = clean_text(fields.get("paper_id") or "")
        upload = files.get("file")
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
            return
        if not upload:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "file is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            resource = attach_file_to_paper(
                storage,
                paper_id=paper_id,
                filename=str(upload.get("filename") or "Attached File"),
                content=upload.get("content") or b"",
                file_role=fields.get("file_role") or "other",
                version_role=fields.get("version_role") or "",
                version_label=fields.get("version_label") or "",
                file_type=fields.get("file_type") or "",
                file_source=fields.get("file_source") or "user_import",
                source_detail=fields.get("source_detail") or "",
                annotation_state=fields.get("annotation_state") or "",
            )
            resources = storage.list_paper_resources(paper_id)
            paper = storage.get_paper(paper_id)
            stored = next(
                (item for item in resources if int(item.get("id") or 0) == int(resource.get("id") or 0)),
                resource,
            )
        except KeyError:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Paper not found")
            return
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        finally:
            storage.close()
        self.send_json(
            {
                "status": "duplicate" if resource.get("duplicate") else "added",
                "file": paper_resource_to_api(stored),
                "paper": paper_to_api(paper) if paper else None,
            }
        )

    def handle_add_paper_file_path(self, payload: dict[str, Any]) -> None:
        paper_id = clean_text(str(payload.get("paper_id") or ""))
        source_path = Path(str(payload.get("source_path") or "")).expanduser()
        if not paper_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "paper_id is required")
