    def handle_publication_search(self, query: dict[str, list[str]]) -> None:
        search_text = (first(query, "q") or "").strip()
        kind = (first(query, "kind") or "auto").strip().lower()
        if not search_text:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "q is required")
            return
        try:
            results = search_publications(search_text, kind=kind)
        except Exception as exc:
            self.send_error_json(HTTPStatus.BAD_GATEWAY, report_publication_error(exc, operation="Publication lookup"))
            return
        self.send_json({"results": [publication_candidate_to_api(paper) for paper in results]})

    def handle_google_scholar_profile_search(self, query: dict[str, list[str]]) -> None:
        search_text = (first(query, "q") or "").strip()
        if not search_text:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "q is required")
            return
        if normalize_researchgate_profile_url(search_text):
            try:
                profiles = researchgate_openalex_profiles(search_text, limit=12)
            except Exception as exc:
                self.send_error_json(
                    HTTPStatus.BAD_GATEWAY,
                    report_publication_error(exc, operation="Author lookup"),
                )
                return
            storage = Storage(self.configured_db_path)
            try:
                global_cooldown = google_scholar_global_cooldown(storage)
            finally:
                storage.close()
            self.send_json({
                "profiles": profiles,
                "scholarCooldown": global_cooldown,
                "source": "researchgate",
            })
            return
        storage = Storage(self.configured_db_path)
        try:
            local_profiles = local_google_scholar_profiles(storage, search_text, limit=20)
            global_cooldown = google_scholar_global_cooldown(storage)
        finally:
            storage.close()
        if local_profiles:
            self.send_json({"profiles": local_profiles, "scholarCooldown": global_cooldown})
            return
        if global_cooldown.get("active"):
            self.send_error_json(
                HTTPStatus.TOO_MANY_REQUESTS,
                google_scholar_global_cooldown_message(global_cooldown),
            )
            return
        try:
            if google_scholar_user_id(search_text):
                scholar_payload = fetch_google_scholar_profile_payload(search_text, limit=1)
                profile = sanitize_google_scholar_profile(scholar_payload.get("profile") or {})
                profiles = [profile] if profile.get("user_id") else []
            else:
                profiles = search_google_scholar_profiles(search_text, limit=20)
        except GoogleScholarBlockedError as exc:
            cooldown = start_google_scholar_global_cooldown_for_db(
                self.configured_db_path,
                message=str(exc),
            )
            self.send_error_json(
                HTTPStatus.TOO_MANY_REQUESTS,
                google_scholar_global_cooldown_message(cooldown),
            )
            return
        except Exception as exc:
            self.send_error_json(HTTPStatus.BAD_GATEWAY, report_publication_error(exc, operation="Profile lookup"))
            return
        self.send_json({
            "profiles": merge_google_scholar_profiles(local_profiles, profiles, search_text, limit=20),
            "scholarCooldown": global_cooldown,
        })

    def handle_author_monitor(self, query: dict[str, list[str]]) -> None:
        author_monitor_id = int(first(query, "author_id") or 0)
        storage = Storage(self.configured_db_path)
        try:
            if first(query, "summary") == "1":
                authors = [author_monitor_to_api(row) for row in storage.list_author_monitors()]
                cache_status = storage.author_monitor_card_cache_status()
                payload = {
                    "authors": authors,
                    "unreadCount": sum(int(item.get("unread_count") or 0) for item in authors),
                    "checkedAt": now_iso(),
                    "scholarCooldown": google_scholar_global_cooldown(storage),
                    "metadataWork": author_metadata_work.snapshot(storage),
                    "indexReady": bool(cache_status.get("ready")),
                    "indexPendingCount": int(cache_status.get("pending_count") or 0),
                }
                if not payload["indexReady"]:
                    request_author_monitor_card_cache_build(self.configured_db_path)
            elif first(query, "index") == "1":
                payload = author_monitor_index_snapshot(
                    storage, include_metadata_work=first(query, "cards_only") != "1"
                )
                if not payload.get("indexReady"):
                    request_author_monitor_card_cache_build(self.configured_db_path)
            else:
                payload = author_monitor_snapshot(
                    storage, author_monitor_id=author_monitor_id,
                    include_metadata_work=first(query, "cards_only") != "1",
                )
        finally:
            storage.close()
        self.send_json(payload)

    def handle_add_author_monitor(self, payload: dict[str, Any]) -> None:
        profile = sanitize_author_monitor_profile(payload.get("profile"))
        source_type = clean_text(profile.get("source_type") or "google_scholar")
        if not profile.get("source_author_id") or not profile.get("name"):
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Choose an author profile first")
            return
        storage = Storage(self.configured_db_path)
        try:
            global_cooldown = google_scholar_global_cooldown(storage)
            if source_type == "google_scholar" and global_cooldown.get("active"):
                self.send_error_json(
                    HTTPStatus.TOO_MANY_REQUESTS,
                    google_scholar_global_cooldown_message(global_cooldown),
                )
                return
            existing = next(
                (
                    item for item in storage.list_author_monitors()
                    if clean_text(item.get("source_type") or "google_scholar") == source_type
                    and clean_text(item.get("source_author_id") or item.get("scholar_user_id") or "")
                    == clean_text(profile.get("source_author_id") or "")
                ),
                None,
            )
            monitor = existing or storage.add_author_monitor(profile)
            author_monitor_id = int(monitor.get("id") or 0)
            can_refresh = (
                source_type == "google_scholar"
                or bool(
                    clean_text(
                        profile.get("openalex_author_id")
                        or monitor.get("openalex_author_id")
                        or profile.get("semantic_scholar_author_id")
                        or monitor.get("semantic_scholar_author_id")
                        or ""
                    )
                )
            )
            needs_initial_import = can_refresh and (
                not existing or storage.author_monitor_paper_count(author_monitor_id) == 0
            )
            if needs_initial_import:
                source_label = (
                    "Google Scholar"
                    if source_type == "google_scholar"
                    else (
                        "OpenAlex"
                        if profile.get("openalex_author_id")
                        or monitor.get("openalex_author_id")
                        else "Semantic Scholar"
                    )
                )
                storage.update_author_monitor(
                    author_monitor_id,
                    status="queued",
                    message=f"Initial {source_label} import queued...",
                )
            elif not can_refresh:
                storage.update_author_monitor(
                    author_monitor_id,
                    status="success",
                    message="ResearchGate profile saved. A publication-data match is required to enable automatic refresh.",
                )
        finally:
            storage.close()
        if needs_initial_import:
            threading.Thread(
                target=refresh_author_monitor_for_db,
                kwargs={
                    "db_path": self.configured_db_path,
                    "author_monitor_id": author_monitor_id,
                    "initial": True,
                    "force": True,
                },
                name=f"author-monitor-initial-{author_monitor_id}",
                daemon=True,
            ).start()
            result = {"status": "queued", "added": 0}
        elif not can_refresh:
            result = {"status": "manual", "added": 0}
        else:
            result = {"status": "existing", "added": 0}
        storage = Storage(self.configured_db_path)
        try:
            snapshot = author_monitor_snapshot(storage, author_monitor_id=author_monitor_id)
        finally:
            storage.close()
        self.send_json({**snapshot, "refresh": result, "selectedAuthorId": author_monitor_id})

    def handle_refresh_author_monitor(self, payload: dict[str, Any]) -> None:
        author_monitor_id = int(payload.get("author_id") or 0)
        view_author_id = (
            int(payload.get("view_author_id") or 0)
            if "view_author_id" in payload
            else author_monitor_id
        )
        full_metadata = bool(payload.get("full_metadata"))
        storage = Storage(self.configured_db_path)
        try:
            monitors = storage.list_author_monitors()
            selected_monitor = next(
                (
                    item for item in monitors
                    if int(item.get("id") or 0) == author_monitor_id
                ),
                None,
            )
            global_cooldown = google_scholar_global_cooldown(storage)
            selected_source = clean_text(
                (selected_monitor or {}).get("source_type") or "google_scholar"
            )
            if (
                selected_monitor
                and selected_source != "google_scholar"
                and not normalize_openalex_author_id(
                    selected_monitor.get("openalex_author_id")
                )
                and not normalize_semantic_scholar_author_id(
                    selected_monitor.get("semantic_scholar_author_id")
                )
            ):
                self.send_error_json(
                    HTTPStatus.BAD_REQUEST,
                    "This ResearchGate author has no publication-data match, so automatic refresh is unavailable",
                )
                return
            if (
                global_cooldown.get("active")
                and author_monitor_id
                and selected_source == "google_scholar"
            ):
                self.send_error_json(
                    HTTPStatus.TOO_MANY_REQUESTS,
                    google_scholar_global_cooldown_message(global_cooldown),
                )
                return
            if full_metadata and not author_monitor_id:
                self.send_error_json(
                    HTTPStatus.BAD_REQUEST,
                    "Updating all Scholar citations must be run for one author at a time",
                )
                return
            if full_metadata and selected_source != "google_scholar":
                self.send_error_json(
                    HTTPStatus.BAD_REQUEST,
                    "Full Scholar citation updates are only available for Google Scholar authors",
                )
                return
            if full_metadata:
                active_monitor = next(
                    (
                        item for item in storage.list_author_monitors()
                        if str(item.get("status") or "") in {"queued", "refreshing"}
                    ),
                    None,
                )
                if active_monitor:
                    self.send_error_json(
                        HTTPStatus.CONFLICT,
                        f"Wait for the current Scholar job for {clean_text(active_monitor.get('name') or 'another author')} to finish",
                    )
                    return
            author_ids = (
                [author_monitor_id]
                if author_monitor_id and selected_monitor
                else [
                    int(item["id"])
                    for item in monitors
                    if (
                        clean_text(item.get("source_type") or "google_scholar")
                        == "google_scholar"
                        or bool(
                            normalize_openalex_author_id(
                                item.get("openalex_author_id")
                            )
                        )
                        or bool(
                            normalize_semantic_scholar_author_id(
                                item.get("semantic_scholar_author_id")
                            )
                        )
                    )
                    if not (
                        global_cooldown.get("active")
                        and clean_text(item.get("source_type") or "google_scholar")
                        == "google_scholar"
                    )
                ]
            )
        finally:
            storage.close()
        if author_monitor_id and not author_ids:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Monitored author not found")
            return
        if full_metadata:
            storage = Storage(self.configured_db_path)
            try:
                monitor = storage.get_author_monitor(author_monitor_id)
                storage.update_author_monitor(
                    author_monitor_id,
                    status="queued",
                    message="Updating all Google Scholar citations...",
                )
            finally:
                storage.close()
            threading.Thread(
                target=refresh_author_monitor_for_db,
                kwargs={
                    "db_path": self.configured_db_path,
                    "author_monitor_id": author_monitor_id,
                    "initial": False,
                    "force": True,
                    "full_metadata": True,
                },
                name=f"author-monitor-scholar-backfill-{author_monitor_id}",
                daemon=True,
            ).start()
            storage = Storage(self.configured_db_path)
            try:
                snapshot = author_monitor_snapshot(storage, author_monitor_id=author_monitor_id)
            finally:
                storage.close()
            self.send_json({
                **snapshot,
                "refreshes": [{
                    "author_id": author_monitor_id,
                    "status": "queued",
                    "full_metadata": True,
                    "estimated_pages": max(1, (int((monitor or {}).get("paper_count") or 0) + 99) // 100),
                }],
            })
            return
        results = [
            refresh_author_monitor_for_db(
                self.configured_db_path,
                current_id,
                initial=False,
                force=True,
            )
            for current_id in author_ids
        ]
        storage = Storage(self.configured_db_path)
        try:
            snapshot = author_monitor_snapshot(storage, author_monitor_id=view_author_id)
        finally:
            storage.close()
        self.send_json({**snapshot, "refreshes": results})

    def handle_delete_author_monitor(self, payload: dict[str, Any]) -> None:
        author_monitor_id = int(payload.get("author_id") or 0)
        if not author_monitor_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "author_id is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            if not storage.get_author_monitor(author_monitor_id):
                self.send_error_json(HTTPStatus.NOT_FOUND, "Monitored author not found")
                return
            storage.delete_author_monitor(author_monitor_id)
            snapshot = author_monitor_snapshot(storage, author_monitor_id=-1)
        finally:
            storage.close()
        self.send_json(snapshot)

    def handle_set_author_monitor_homepage(self, payload: dict[str, Any]) -> None:
        author_monitor_id = int(payload.get("author_id") or 0)
        if not author_monitor_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "author_id is required")
            return
        homepage_override_url = clean_text(payload.get("homepage_url") or "")
        if homepage_override_url:
            parsed = urlparse(homepage_override_url)
            if parsed.scheme not in {"http", "https"} or not parsed.netloc:
                self.send_error_json(
                    HTTPStatus.BAD_REQUEST,
                    "Homepage must be a complete http or https URL",
                )
                return
        storage = Storage(self.configured_db_path)
        try:
            if not storage.get_author_monitor(author_monitor_id):
                self.send_error_json(HTTPStatus.NOT_FOUND, "Monitored author not found")
                return
            updated = storage.set_author_monitor_homepage_override(
                author_monitor_id,
                homepage_override_url or None,
            )
        finally:
            storage.close()
        self.send_json({"author": author_monitor_to_api(updated)})

    def handle_author_monitor_photo(
        self,
        query: dict[str, list[str]],
    ) -> None:
        author_monitor_id = int(first(query, "author_id") or 0)
        if not author_monitor_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "author_id is required")
            return
        cached_photo = author_monitor_photo_from_memory(
            self.configured_db_path,
            author_monitor_id,
        )
        if cached_photo:
            content_type, content = cached_photo
            self.send_bytes(content, content_type=content_type)
            return
        storage = Storage(self.configured_db_path)
        try:
            author = storage.get_author_monitor(author_monitor_id)
        finally:
            storage.close()
        if not author:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Monitored author not found")
            return
        photo_path = managed_author_photo_path(
            author.get("avatar_override_path"),
            self.configured_db_path,
        )
        if not photo_path or not photo_path.exists() or not photo_path.is_file():
            author = cache_author_monitor_source_photo(
                self.configured_db_path,
                author_monitor_id,
            ) or author
            photo_path = managed_author_photo_path(
                author.get("avatar_override_path"),
                self.configured_db_path,
            )
        if not photo_path or not photo_path.exists() or not photo_path.is_file():
            self.send_error_json(HTTPStatus.NOT_FOUND, "Author photo not found")
            return
        content_type = mimetypes.guess_type(str(photo_path))[0] or "application/octet-stream"
        content = photo_path.read_bytes()
        remember_author_monitor_photo(
            self.configured_db_path,
            author_monitor_id,
            content_type,
            content,
        )
        self.send_bytes(content, content_type=content_type)

    def handle_set_author_monitor_photo(self) -> None:
        try:
            fields, files = self.read_multipart_body()
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        author_monitor_id = int(fields.get("author_id") or 0)
        upload = files.get("photo")
        if not author_monitor_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "author_id is required")
            return
        if not upload:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Photo file is required")
            return
        content = upload.get("content") or b""
        try:
            updated = save_author_monitor_photo(
                self.configured_db_path,
                author_monitor_id,
                content,
            )
        except KeyError:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Monitored author not found")
            return
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        self.send_json({"author": author_monitor_to_api(updated)})

    def handle_choose_author_monitor_photo(self, payload: dict[str, Any]) -> None:
        author_monitor_id = int(payload.get("author_id") or 0)
        if not author_monitor_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "author_id is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            author = storage.get_author_monitor(author_monitor_id)
        finally:
            storage.close()
        if not author:
            self.send_error_json(HTTPStatus.NOT_FOUND, "Monitored author not found")
            return
        try:
            script = (
                'POSIX path of (choose file with prompt '
                '"Choose a PNG, JPEG, or WebP author photo." '
                "default location (path to pictures folder))"
            )
            result = subprocess.run(
                ["/usr/bin/osascript", "-e", script],
                check=True,
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
            )
        except subprocess.CalledProcessError:
            self.send_json({"cancelled": True})
            return
        photo_path = Path(result.stdout.strip()).expanduser()
        if not photo_path.exists() or not photo_path.is_file():
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Selected photo was not found")
            return
        try:
            if photo_path.stat().st_size > AUTHOR_PHOTO_MAX_BYTES:
                raise ValueError("Photo must be 10 MB or smaller")
            updated = save_author_monitor_photo(
                self.configured_db_path,
                author_monitor_id,
                photo_path.read_bytes(),
            )
        except (OSError, ValueError) as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        self.send_json({"author": author_monitor_to_api(updated)})

