    def handle_set_field_settings(self, payload: dict[str, Any]) -> None:
        requested = payload.get("standalone_fields")
        if not isinstance(requested, list):
            self.send_error_json(HTTPStatus.BAD_REQUEST, "standalone_fields must be a list")
            return
        requested_values = [clean_text(str(value)) for value in requested]
        known = {code for code, _label in FIELD_DEFINITIONS}
        unknown = sorted({value for value in requested_values if value and value not in known})
        if unknown:
            self.send_error_json(HTTPStatus.BAD_REQUEST, f"Unknown field: {unknown[0]}")
            return
        standalone = normalize_standalone_fields(requested_values)
        storage = Storage(self.configured_db_path)
        try:
            storage.set_setting(
                FIELD_STANDALONE_SETTING,
                json.dumps(standalone, ensure_ascii=False),
            )
            response = field_settings_payload(storage)
        finally:
            storage.close()
        self.send_json({"field_settings": response})

    def handle_set_arxiv_settings(self, payload: dict[str, Any]) -> None:
        requested = payload.get("scope_ids")
        if not isinstance(requested, list):
            self.send_error_json(HTTPStatus.BAD_REQUEST, "scope_ids must be a list")
            return
        requested_values = [clean_text(str(value)) for value in requested if clean_text(str(value))]
        normalized = normalize_arxiv_scope_ids(requested_values)
        if not normalized:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Select at least one arXiv subject group")
            return
        if set(normalized) != set(requested_values):
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Choose valid arXiv subject groups")
            return
        storage = Storage(self.configured_db_path)
        try:
            storage.set_setting(ARXIV_SCOPE_GROUPS_SETTING, json.dumps(normalized, ensure_ascii=False))
            # Mirror the first scope for older app bundles that still understand
            # only one primary/secondary pair.
            first_primary, first_secondary = normalized[0].split("/", 1)
            storage.set_setting(ARXIV_PRIMARY_SUBJECT_SETTING, first_primary)
            storage.set_setting(ARXIV_SECONDARY_SUBJECT_SETTING, first_secondary)
            # A different archive has its own announcement state. Keep previously
            # fetched papers, but let the scheduler assess the new scope afresh.
            for key in (
                AUTO_ARXIV_MONITOR_LAST_ANNOUNCEMENT_SETTING,
                AUTO_ARXIV_MONITOR_LAST_ATTEMPT_SETTING,
                AUTO_ARXIV_MONITOR_STATUS_SETTING,
                AUTO_ARXIV_METADATA_RETRY_SETTING,
            ):
                storage.set_setting(key, "")
            response = arxiv_settings_payload(storage)
        finally:
            storage.close()
        self.send_json({"arxiv": response})

    def handle_set_citation_settings(self, payload: dict[str, Any]) -> None:
        provider = clean_text(str(payload.get("provider") or "ads")).lower()
        if provider == "openalex":
            self.handle_set_openalex_citation_settings(payload)
            return
        if provider == "semantic_scholar":
            self.handle_set_semantic_scholar_citation_settings(payload)
            return
        action = clean_text(str(payload.get("action") or "save")).lower()
        requested_token = clean_text(str(payload.get("ads_token") or ""))
        storage = Storage(self.configured_db_path)
        try:
            if action == "clear":
                storage.set_setting(ADS_API_TOKEN_SETTING, "")
                self.send_json({"ads": {"configured": False, "status": "cleared"}})
                return
            token = requested_token or ads_api_token(storage)
            if action == "test":
                if not token:
                    self.send_json({"ads": {"configured": False, "status": "not_configured", "ok": False}})
                    return
                try:
                    ok = test_ads_token(token)
                except Exception:
                    ok = False
                self.send_json({"ads": {"configured": bool(ads_api_token(storage)), "status": "connected" if ok else "invalid", "ok": ok}})
                return
            if requested_token:
                storage.set_setting(ADS_API_TOKEN_SETTING, requested_token)
                token = requested_token
            test_requested = bool(payload.get("test"))
            ok: bool | None = None
            if test_requested and token:
                try:
                    ok = test_ads_token(token)
                except Exception:
                    ok = False
            self.send_json({
                "ads": {
                    "configured": bool(token),
                    "status": "connected" if ok else ("invalid" if ok is False else ("configured" if token else "not_configured")),
                    "ok": ok,
                }
            })
        finally:
            storage.close()

    def handle_set_openalex_citation_settings(
        self,
        payload: dict[str, Any],
    ) -> None:
        action = clean_text(str(payload.get("action") or "save")).lower()
        requested_key = clean_text(str(payload.get("openalex_key") or ""))
        storage = Storage(self.configured_db_path)
        try:
            stored_key = openalex_api_key(storage)
            if action == "clear":
                storage.set_setting(OPENALEX_API_KEY_SETTING, "")
                configure_openalex_api_key("")
                self.send_json({
                    "openalex": openalex_settings_payload(storage),
                })
                return
            key = requested_key or stored_key or clean_text(
                os.getenv("OPENALEX_API_KEY", "")
            )
            if action == "test":
                result = test_openalex_api_key(key)
                result["configured"] = bool(stored_key or os.getenv("OPENALEX_API_KEY"))
                self.send_json({"openalex": openalex_settings_to_api(result)})
                return
            if not requested_key:
                self.send_error_json(
                    HTTPStatus.BAD_REQUEST,
                    "Paste an OpenAlex API key before saving",
                )
                return
            storage.set_setting(OPENALEX_API_KEY_SETTING, requested_key)
            configure_openalex_api_key(requested_key)
            try:
                result = refresh_openalex_rate_limit_status(requested_key)
            except Exception:
                result = {
                    "configured": True,
                    "status": "invalid",
                    "ok": False,
                    "paused": False,
                }
            self.send_json({"openalex": openalex_settings_to_api(result)})
        finally:
            storage.close()

    def handle_set_semantic_scholar_citation_settings(
        self,
        payload: dict[str, Any],
    ) -> None:
        action = clean_text(str(payload.get("action") or "save")).lower()
        requested_key = clean_text(str(payload.get("semantic_scholar_key") or ""))
        storage = Storage(self.configured_db_path)
        try:
            stored_key = semantic_scholar_stored_api_key(storage)
            environment_key = clean_text(os.getenv("SEMANTIC_SCHOLAR_API_KEY", ""))
            if action == "clear":
                storage.set_setting(SEMANTIC_SCHOLAR_API_KEY_SETTING, "")
                configure_semantic_scholar_api_key("")
                self.send_json({
                    "semantic_scholar": semantic_scholar_settings_payload(storage),
                })
                return
            key = requested_key or stored_key or environment_key
            if action == "test":
                result = test_semantic_scholar_api_key(key)
                result["configured"] = bool(stored_key or environment_key)
                result["source"] = "sqlite" if stored_key else ("environment" if environment_key else "")
                self.send_json({"semantic_scholar": result})
                return
            if not requested_key:
                self.send_error_json(
                    HTTPStatus.BAD_REQUEST,
                    "Paste a Semantic Scholar API key before saving",
                )
                return
            storage.set_setting(SEMANTIC_SCHOLAR_API_KEY_SETTING, requested_key)
            configure_semantic_scholar_api_key(requested_key)
            result = test_semantic_scholar_api_key(requested_key)
            result.update({"configured": True, "source": "sqlite"})
            self.send_json({"semantic_scholar": result})
        finally:
            storage.close()

