    def handle_rename_library_item(self, payload: dict[str, Any]) -> None:
        item_id = int(payload.get("item_id") or 0)
        name = str(payload.get("name") or "")
        storage = Storage(self.configured_db_path)
        try:
            item, paper, sync = rename_library_item_and_sync_files(
                storage,
                item_id=item_id,
                name=name,
            )
            item_api = library_item_to_api(item, paper)
            refreshed_paper_files = paper_files_state_payloads(storage, [str(paper.get("paper_id") or "")])
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        except PermissionError as exc:
            self.send_error_json(HTTPStatus.FORBIDDEN, str(exc))
            return
        except OSError as exc:
            self.send_error_json(HTTPStatus.INTERNAL_SERVER_ERROR, str(exc))
            return
        finally:
            storage.close()
        self.send_json({
            "item_id": int(item.get("id") or item_id),
            "item": item_api,
            "paper": paper_to_api(paper),
            "file_sync": sync,
            "paper_files": refreshed_paper_files,
        })

    def handle_rename_library_pdf(self, payload: dict[str, Any]) -> None:
        item_id = int(payload.get("item_id") or 0)
        include_snapshot = payload.get("snapshot", True) is not False
        storage = Storage(self.configured_db_path)
        try:
            result = rename_library_item_pdf_from_metadata(storage, item_id)
            item = storage.get_library_item(item_id)
            paper = storage.get_paper(str((item or {}).get("paper_id") or result.get("paper_id") or ""))
            item_api = library_item_to_api(item, paper) if item and paper else None
            paper_api = paper_to_api(paper) if paper else None
            refreshed_paper_files = paper_files_state_payloads(
                storage,
                [str((paper or {}).get("paper_id") or result.get("paper_id") or "")],
            )
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except FileNotFoundError as exc:
            self.send_error_json(HTTPStatus.NOT_FOUND, str(exc))
            return
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        except PermissionError as exc:
            self.send_error_json(HTTPStatus.FORBIDDEN, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"renamed": result, "item": item_api, "paper": paper_api, "paper_files": refreshed_paper_files, **snapshot})

    def handle_move_library_entry(self, payload: dict[str, Any]) -> None:
        entry_type = str(payload.get("type") or "")
        target_folder_id = int(payload.get("target_folder_id") or 1)
        include_snapshot = payload.get("snapshot", True) is not False
        storage = Storage(self.configured_db_path)
        try:
            special = ensure_library_special_folders(storage)
            unsorted_id = int(special["unsorted"].get("id") or 1)
            recycle_id = int(special["recycle"].get("id") or 1)
            moved: dict[str, Any] | None = None
            moved_response: dict[str, Any] = {}
            affected_paper_ids: set[str] = set()
            if entry_type == "item":
                item_id = int(payload.get("id") or 0)
                source_item = storage.get_library_item(item_id)
                if not source_item:
                    raise ValueError("Library item not found")
                affected_paper_ids.add(str(source_item.get("paper_id") or ""))
                canonical_moved = move_or_alias_library_item_pdf(
                    storage,
                    item=source_item,
                    target_folder_id=target_folder_id,
                )
                if target_folder_id == recycle_id:
                    moved = storage.move_library_item_to_trash(item_id=item_id, recycle_folder_id=recycle_id)
                else:
                    moved = storage.move_library_item(item_id=item_id, folder_id=target_folder_id)
                if moved:
                    moved_paper_id = str(moved.get("paper_id") or source_item.get("paper_id") or "")
                    if canonical_moved:
                        sync_all_pdf_aliases_for_paper(storage, moved_paper_id)
                    else:
                        sync_alias_for_library_item(
                            storage,
                            moved_paper_id,
                            int(moved.get("folder_id") or target_folder_id),
                        )
                    updated_paper = storage.get_paper(moved_paper_id)
                    if updated_paper:
                        annotated = annotate_papers_with_library_status(storage, [updated_paper])
                        updated_paper = annotated[0] if annotated else updated_paper
                        moved_response = library_item_to_api(moved, updated_paper)
                    else:
                        moved_response = dict(moved or {})
            elif entry_type == "folder":
                folder_id = int(payload.get("id") or 0)
                folder = storage.get_library_folder(folder_id)
                if not folder:
                    raise ValueError("Folder not found")
                if folder_id in {1, unsorted_id, recycle_id} or folder.get("parent_id") is None:
                    raise ValueError("This folder cannot be moved")
                pdf_move_plan = folder_tree_pdf_move_plan(storage, folder_id)
                affected_paper_ids.update(str(entry.get("paper_id") or "") for entry in pdf_move_plan)
                if target_folder_id == recycle_id:
                    moved = storage.move_library_folder_to_trash(folder_id=folder_id, recycle_folder_id=recycle_id)
                else:
                    moved = storage.move_library_folder(folder_id=folder_id, parent_id=target_folder_id)
                apply_folder_tree_pdf_move_plan(storage, pdf_move_plan)
                moved_response = library_folder_to_api(moved, storage) if moved else {}
            else:
                self.send_error_json(HTTPStatus.BAD_REQUEST, "type must be item or folder")
                return
            refreshed_paper_files = paper_files_state_payloads(storage, affected_paper_ids)
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"moved": moved_response, "paper_files": refreshed_paper_files, **snapshot})

    def handle_reorder_library_entry(self, payload: dict[str, Any]) -> None:
        entry_type = str(payload.get("type") or "")
        entry_id = int(payload.get("id") or 0)
        parent_id = int(payload.get("parent_folder_id") or 1)
        target_id = int(payload.get("target_id") or 0)
        position = str(payload.get("position") or "before")
        include_snapshot = payload.get("snapshot", True) is not False
        storage = Storage(self.configured_db_path)
        try:
            reordered = storage.reorder_library_entry(
                entry_type=entry_type,
                entry_id=entry_id,
                parent_id=parent_id,
                target_id=target_id,
                position=position,
            )
            if entry_type == "folder":
                reordered_api = library_folder_to_api(reordered, storage)
            else:
                paper = storage.get_paper(str((reordered or {}).get("paper_id") or ""))
                reordered_api = library_item_to_api(reordered, paper) if reordered and paper else dict(reordered or {})
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"reordered": reordered_api, **snapshot})

    def handle_delete_library_entry(self, payload: dict[str, Any]) -> None:
        entry_type = str(payload.get("type") or "")
        entry_id = int(payload.get("id") or 0)
        confirmed = bool(payload.get("confirmed"))
        include_snapshot = payload.get("snapshot", True) is not False
        storage = Storage(self.configured_db_path)
        try:
            deleted = self.delete_library_entry_in_storage(storage, entry_type, entry_id, confirmed=confirmed)
            refreshed_files = deleted.get("paper_files", []) + paper_files_state_payloads(storage, [])
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except (ValueError, sqlite3.Error) as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        except OSError as exc:
            status = HTTPStatus.FORBIDDEN if isinstance(exc, PermissionError) else HTTPStatus.INTERNAL_SERVER_ERROR
            self.send_error_json(status, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"deleted": deleted, "paper_files": refreshed_files, **snapshot})

    def handle_delete_library_entries(self, payload: dict[str, Any]) -> None:
        entries = payload.get("entries")
        if not isinstance(entries, list) or not entries:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "entries must be a non-empty list")
            return
        confirmed = bool(payload.get("confirmed"))
        include_snapshot = payload.get("snapshot", True) is not False
        storage = Storage(self.configured_db_path)
        deleted: list[dict[str, Any]] = []
        try:
            recycle_id = int(ensure_library_special_folders(storage)["recycle"]["id"])
            all_in_recycle = True
            for entry in entries:
                if not isinstance(entry, dict):
                    raise ValueError("Each entry must be an object")
                entry_id = int(entry.get("id") or 0)
                item = storage.get_library_item(entry_id) if entry.get("type") == "item" else None
                folder_id = int(item["folder_id"]) if item else entry_id if entry.get("type") == "folder" else 0
                all_in_recycle = all_in_recycle and bool(folder_id) and library_folder_is_within(storage, folder_id, recycle_id)
            if all_in_recycle:
                result = delete_recycle_selection(storage, entries, recycle_id=recycle_id, confirmed=confirmed)
                deleted = [{"type": entry["type"], "id": int(entry["id"]), "mode": "removed",
                            "paper_ids": result["paper_ids"], "cleanup": result["cleanup"],
                            "retained_paper_ids": result["retained_paper_ids"], "paper_files": result["paper_files"]} for entry in entries]
            for entry in ([] if all_in_recycle else entries):
                entry_type = str(entry.get("type") or "")
                entry_id = int(entry.get("id") or 0)
                result = self.delete_library_entry_in_storage(storage, entry_type, entry_id, confirmed=confirmed)
                deleted.append(result or {"type": entry_type, "id": entry_id})
            refreshed_files = list({p["paper_id"]: p for result in deleted for p in result.get("paper_files", [])}.values())
            refreshed_files += paper_files_state_payloads(storage, [])
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except (ValueError, sqlite3.Error) as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        except OSError as exc:
            status = HTTPStatus.FORBIDDEN if isinstance(exc, PermissionError) else HTTPStatus.INTERNAL_SERVER_ERROR
            self.send_error_json(status, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"deleted": deleted, "paper_files": refreshed_files, **snapshot})

    def handle_library_delete_preview(self, payload: dict[str, Any]) -> None:
        entries = payload.get("entries")
        if isinstance(entries, list):
            preview_entries = entries
        elif payload.get("clear_special"):
            preview_entries = [{"type": "folder", "id": int(payload.get("folder_id") or 0)}]
        else:
            preview_entries = [{"type": str(payload.get("type") or ""), "id": int(payload.get("id") or 0)}]
        storage = Storage(self.configured_db_path)
        try:
            special = ensure_library_special_folders(storage)
            recycle_id = int(special["recycle"].get("id") or 0)
            preview = preview_recycle_selection(storage, preview_entries, recycle_id=recycle_id,
                                                empty=bool(payload.get("clear_special")))
        except (ValueError, sqlite3.Error) as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"preview": preview})

    def delete_library_entry_in_storage(self, storage: Storage, entry_type: str, entry_id: int, *, confirmed: bool = False) -> dict[str, Any]:
        special = ensure_library_special_folders(storage)
        unsorted_id = int(special["unsorted"].get("id") or 1)
        recycle_id = int(special["recycle"].get("id") or 1)
        if entry_type == "item":
            item = storage.get_library_item(entry_id)
            if not item:
                raise ValueError("Library item not found")
            folder_id = int(item.get("folder_id") or 1)
            paper_ids = [str(item.get("paper_id") or "")]
            if library_folder_is_within(storage, folder_id, recycle_id):
                result = delete_recycle_selection(storage, [{"type": "item", "id": entry_id}],
                                                  recycle_id=recycle_id, confirmed=confirmed)
                return {"type": "item", "id": entry_id, "mode": "removed", **result}
            else:
                remaining = first_outside_reference_item(storage, paper_ids[0], recycle_id, exclude_item_id=entry_id)
                retained_by_my_publications = paper_has_my_publication_reference(storage, paper_ids[0])
                if remaining or retained_by_my_publications:
                    storage.delete_library_item(item_id=entry_id)
                    promote_canonical_pdf_outside_recycle(storage, paper_ids[0], recycle_id)
                    remove_pdf_aliases_for_paper_in_folders(storage, paper_ids[0], [folder_id])
                    updated_paper = storage.get_paper(paper_ids[0])
                    moved_api: dict[str, Any] = {}
                    retained_paper_api: dict[str, Any] = {}
                    updated_remaining = None
                    if remaining:
                        updated_remaining = storage.get_library_item(int(remaining.get("id") or 0)) or remaining
                    if updated_paper:
                        annotated = annotate_papers_with_library_status(storage, [updated_paper])
                        updated_paper = annotated[0] if annotated else updated_paper
                        retained_paper_api = paper_to_library_summary_api(updated_paper)
                    if updated_paper and updated_remaining:
                        moved_api = library_item_to_api(updated_remaining, updated_paper)
                    return {
                        "type": "item",
                        "id": entry_id,
                        "mode": "removed",
                        "paper_ids": paper_ids,
                        "moved": moved_api,
                        "paper": retained_paper_api,
                        "handoff_folder_id": int((updated_remaining or {}).get("folder_id") or 0),
                        "retained_by_my_publications": bool(retained_by_my_publications),
                    }
                move_or_alias_library_item_pdf(storage, item=item, target_folder_id=recycle_id)
                moved = storage.move_library_item_to_trash(item_id=entry_id, recycle_folder_id=recycle_id)
                sync_all_pdf_aliases_for_paper(storage, str(item.get("paper_id") or ""))
                moved_item = storage.get_library_item(int((moved or {}).get("id") or entry_id)) or moved or {}
                moved_paper = storage.get_paper(str(item.get("paper_id") or ""))
                moved_api = dict(moved_item or {})
                if moved_paper:
                    annotated = annotate_papers_with_library_status(storage, [moved_paper])
                    moved_paper = annotated[0] if annotated else moved_paper
                    moved_api = library_item_to_api(moved_item, moved_paper)
                return {"type": "item", "id": entry_id, "mode": "trashed", "moved": moved_api, "recycle_folder_id": recycle_id}
        if entry_type == "folder":
            folder = storage.get_library_folder(entry_id)
            if not folder:
                raise ValueError("Folder not found")
            if int(folder.get("id") or 0) in {1, unsorted_id, recycle_id} or folder.get("parent_id") is None:
                raise ValueError("This folder cannot be deleted")
            if library_folder_is_within(storage, int(folder.get("parent_id") or 0), recycle_id):
                result = delete_recycle_selection(storage, [{"type": "folder", "id": entry_id}],
                                                  recycle_id=recycle_id, confirmed=confirmed)
                return {"type": "folder", "id": entry_id, "mode": "removed", **result}
            else:
                pdf_move_plan = folder_tree_pdf_move_plan(storage, entry_id)
                moved = storage.move_library_folder_to_trash(folder_id=entry_id, recycle_folder_id=recycle_id)
                apply_folder_tree_pdf_move_plan(storage, pdf_move_plan)
                moved_api = library_folder_to_api(moved, storage) if moved else {}
                return {"type": "folder", "id": entry_id, "mode": "trashed", "moved": moved_api, "recycle_folder_id": recycle_id}
        raise ValueError("type must be item or folder")

    def handle_delete_library_item_file(self, payload: dict[str, Any]) -> None:
        entry_type = str(payload.get("type") or "")
        entry_id = int(payload.get("id") or 0)
        item_id = int(payload.get("item_id") or 0)
        confirmed = bool(payload.get("confirmed"))
        if item_id and not entry_type:
            entry_type = "item"
            entry_id = item_id
        if entry_type not in {"item", "folder"} or not entry_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "type and id are required")
            return
        if not confirmed:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "confirmation is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            special = ensure_library_special_folders(storage)
            recycle_id = int(special["recycle"].get("id") or 1)
            if entry_type == "item":
                item = storage.get_library_item(entry_id)
                if not item:
                    self.send_error_json(HTTPStatus.NOT_FOUND, "Library item not found")
                    return
                if not library_folder_is_within(storage, int(item.get("folder_id") or 0), recycle_id):
                    self.send_error_json(HTTPStatus.BAD_REQUEST, "Local copies can only be deleted from Recycle")
                    return
                paper_ids = [str(item.get("paper_id") or "")]
            else:
                folder = storage.get_library_folder(entry_id)
                if not folder:
                    self.send_error_json(HTTPStatus.NOT_FOUND, "Folder not found")
                    return
                protected_ids = {
                    1,
                    int(special["unsorted"].get("id") or 0),
                    int(special["recycle"].get("id") or 0),
                }
                if int(folder.get("id") or 0) in protected_ids or folder.get("parent_id") is None:
                    self.send_error_json(HTTPStatus.BAD_REQUEST, "This folder cannot be deleted")
                    return
                if not library_folder_is_within(storage, int(folder.get("parent_id") or 0), recycle_id):
                    self.send_error_json(HTTPStatus.BAD_REQUEST, "Local copies can only be deleted from Recycle")
                    return
                paper_ids = storage.library_paper_ids_in_folder_tree(folder_id=entry_id)
            deleted = delete_library_paper_files(storage, paper_ids)
            if not deleted and entry_type == "item":
                self.send_error_json(HTTPStatus.NOT_FOUND, "No local copies are available for this selection")
                return
            if entry_type == "item":
                storage.delete_library_item(item_id=entry_id)
            if entry_type == "folder":
                storage.delete_library_folder(folder_id=entry_id)
            snapshot = library_snapshot(storage)
        except IsADirectoryError:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Refusing to delete a folder")
            return
        except PermissionError as exc:
            self.send_error_json(HTTPStatus.FORBIDDEN, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"deleted": deleted, **snapshot})

    def handle_clear_library_special_folder(self, payload: dict[str, Any]) -> None:
        folder_id = int(payload.get("folder_id") or 0)
        confirmed = bool(payload.get("confirmed"))
        include_snapshot = payload.get("snapshot", True) is not False
        if not folder_id:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "folder_id is required")
            return
        storage = Storage(self.configured_db_path)
        try:
            special = ensure_library_special_folders(storage)
            allowed_ids = {
                int(special["recycle"].get("id") or 0),
            }
            folder = storage.get_library_folder(folder_id)
            if not folder or folder_id not in allowed_ids:
                self.send_error_json(HTTPStatus.BAD_REQUEST, "Only Recycle can be cleared")
                return
            result = delete_recycle_selection(storage, [], recycle_id=folder_id,
                                              empty=True, confirmed=confirmed)
            removed, cleanup = result["removed"], result["cleanup"]
            refreshed_files = result["paper_files"]
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except (ValueError, sqlite3.Error) as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        except IsADirectoryError:
            self.send_error_json(HTTPStatus.BAD_REQUEST, "Refusing to delete a folder")
            return
        except PermissionError as exc:
            self.send_error_json(HTTPStatus.FORBIDDEN, str(exc))
            return
        except OSError as exc:
            self.send_error_json(HTTPStatus.INTERNAL_SERVER_ERROR, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"removed": removed, "cleanup": cleanup, "paper_files": refreshed_files, **snapshot})

    def handle_recover_library_entry(self, payload: dict[str, Any]) -> None:
        entry_type = str(payload.get("type") or "")
        entry_id = int(payload.get("id") or 0)
        include_snapshot = payload.get("snapshot", True) is not False
        storage = Storage(self.configured_db_path)
        try:
            recovered = self.recover_library_entry_in_storage(storage, entry_type, entry_id)
            if entry_type == "folder" and recovered:
                recovered = library_folder_to_api(recovered, storage)
            refreshed_files = paper_files_state_payloads(storage, [])
            snapshot = library_snapshot(storage) if include_snapshot else {}
        except ValueError as exc:
            self.send_error_json(HTTPStatus.BAD_REQUEST, str(exc))
            return
        finally:
            storage.close()
        self.send_json({"recovered": dict(recovered or {}), "paper_files": refreshed_files, **snapshot})

    def recover_library_entry_in_storage(self, storage: Storage, entry_type: str, entry_id: int) -> dict[str, Any]:
        special = ensure_library_special_folders(storage)
        unsorted_id = int(special["unsorted"].get("id") or 1)
        recycle_id = int(special["recycle"].get("id") or 1)
        if entry_type == "item":
            source = storage.get_library_item(entry_id)
            if not source:
                raise ValueError("Library item not found")
            target_folder_id = int(source.get("original_folder_id") or unsorted_id)
            if (
                not storage.get_library_folder(target_folder_id)
                or library_folder_is_within(storage, target_folder_id, recycle_id)
            ):
                target_folder_id = unsorted_id
            move_or_alias_library_item_pdf(storage, item=source, target_folder_id=target_folder_id)
            recovered = storage.recover_library_item(item_id=entry_id, fallback_folder_id=unsorted_id)
            paper_id = str(source.get("paper_id") or "")
            sync_all_pdf_aliases_for_paper(storage, paper_id)
            recovered_paper = storage.get_paper(paper_id)
            if recovered_paper:
                annotated = annotate_papers_with_library_status(storage, [recovered_paper])
                recovered_paper = annotated[0] if annotated else recovered_paper
                return library_item_to_api(recovered, recovered_paper)
            return dict(recovered or {})
        if entry_type == "folder":
            move_plan = folder_tree_pdf_move_plan(storage, entry_id)
            recovered = storage.recover_library_folder(folder_id=entry_id, fallback_parent_id=1)
            apply_folder_tree_pdf_move_plan(storage, move_plan)
            return dict(recovered or {})
        raise ValueError("type must be item or folder")

