def author_monitor_paper_to_api(paper: dict[str, Any]) -> dict[str, Any]:
    """Return the compact fields needed by the Author Monitor list."""
    raw = parse_raw_json(paper)
    google_scholar = raw.get("google_scholar") if isinstance(raw.get("google_scholar"), dict) else {}
    openalex_monitor = (
        raw.get("openalex_author_monitor")
        if isinstance(raw.get("openalex_author_monitor"), dict)
        else {}
    )
    scholar_count = int_or_none(google_scholar.get("citation_count"))
    openalex_count = int_or_none(
        openalex_monitor.get("cited_by_count")
        if openalex_monitor
        else raw.get("cited_by_count")
    )
    semantic_monitor = (
        raw.get("semantic_scholar_author_monitor")
        if isinstance(raw.get("semantic_scholar_author_monitor"), dict)
        else {}
    )
    semantic_raw = (
        raw.get("semantic_scholar")
        if isinstance(raw.get("semantic_scholar"), dict)
        else {}
    )
    semantic_count = int_or_none(
        semantic_monitor.get("citation_count")
        if semantic_monitor
        else semantic_raw.get("citationCount")
    )
    openalex_checked_at = clean_text(openalex_monitor.get("checked_at") or "")
    semantic_checked_at = clean_text(semantic_monitor.get("checked_at") or "")
    semantic_is_latest_monitor = bool(semantic_monitor) and (
        not openalex_monitor
        or semantic_checked_at >= openalex_checked_at
    )
    if semantic_is_latest_monitor and semantic_count is not None:
        fallback_count = semantic_count
        fallback_source = "Semantic Scholar"
    elif openalex_count is not None:
        fallback_count = openalex_count
        fallback_source = "OpenAlex"
    else:
        fallback_count = semantic_count
        fallback_source = "Semantic Scholar" if semantic_count is not None else ""
    enrichment = raw.get("author_monitor_enrichment") if isinstance(raw.get("author_monitor_enrichment"), dict) else {}
    return {
        "paper_id": paper.get("paper_id") or "",
        "storage_key": paper.get("storage_key") or "",
        "title": paper.get("title") or "",
        "journal": display_journal_name(paper),
        "publication_date": paper.get("publication_date") or "",
        "doi": paper.get("doi") or "",
        "url": paper.get("url") or paper.get("landing_url") or "",
        "authors": author_summary(paper),
        "full_authors": full_author_names(paper),
        "preprint_id": preprint_identifier(paper, raw=raw),
        "metadata_refresh": metadata_refresh.marker(paper),
        "citation_label": citation_label(paper, full_lead=True),
        "google_scholar_citation_count": scholar_count,
        "citation_count": scholar_count if scholar_count is not None else fallback_count,
        "citation_count_source": "Google Scholar" if scholar_count is not None else fallback_source,
        "identifier_lookup": {
            "status": clean_text(enrichment.get("status") or ""),
            "message": clean_text(enrichment.get("message") or ""),
            "attempted_at": clean_text(enrichment.get("attempted_at") or ""),
        },
        "in_library": bool(paper.get("in_library")),
        "library_item_count": int(paper.get("library_item_count") or 0),
        "library_status_loaded": "in_library" in paper or "library_item_count" in paper,
        "author_details": {},
        "author_details_loaded": False,
        "full_detail": False,
    }


def author_monitor_card_cache_payload(paper: dict[str, Any]) -> dict[str, Any]:
    """Build the persisted, rebuildable subset used to draw Author Monitor cards."""
    payload = author_monitor_paper_to_api(paper)
    for key in (
        "full_authors",
        "in_library",
        "library_item_count",
        "library_status_loaded",
        "author_details",
        "author_details_loaded",
    ):
        payload.pop(key, None)
    return payload


def rebuild_author_monitor_card_cache(
    db_path: Path,
    *,
    batch_size: int = 400,
) -> int:
    """Incrementally refresh the SQLite-derived card index without blocking UI reads."""
    if not AUTHOR_MONITOR_CARD_CACHE_BUILD_LOCK.acquire(blocking=False):
        return 0
    rebuilt = 0
    try:
        while True:
            storage = Storage(db_path)
            try:
                candidates = storage.list_author_monitor_card_cache_candidates(
                    limit=batch_size
                )
                if not candidates:
                    return rebuilt
                rows = [
                    (
                        clean_text(paper.get("paper_id") or ""),
                        json.dumps(
                            author_monitor_card_cache_payload(paper),
                            ensure_ascii=False,
                            separators=(",", ":"),
                        ),
                        int(paper.get("card_cache_revision") or 0),
                    )
                    for paper in candidates
                    if clean_text(paper.get("paper_id") or "")
                ]
                rebuilt += storage.upsert_author_monitor_card_cache(rows)
            finally:
                storage.close()
            # Yield between batches so the local HTTP server remains responsive
            # during the one-time migration of an existing large monitor.
            time.sleep(0.01)
    finally:
        AUTHOR_MONITOR_CARD_CACHE_BUILD_LOCK.release()


def request_author_monitor_card_cache_build(db_path: Path) -> None:
    threading.Thread(
        target=rebuild_author_monitor_card_cache,
        args=(db_path,),
        daemon=True,
        name="author-monitor-card-cache",
    ).start()


