def library_folder_children_snapshot(storage: Storage, folder_id: int) -> dict[str, Any]:
    ensure_library_special_folders(storage)
    folder = storage.get_library_folder(int(folder_id))
    if not folder:
        raise ValueError("Library folder not found")
    return {
        "folder_id": int(folder_id),
        "folder": library_folder_to_api(folder, storage),
        "folders": [library_folder_to_api(child, storage) for child in storage.list_library_child_folders(int(folder_id))],
        "items": [library_item_to_api(item, item) for item in storage.list_library_items_for_folder(int(folder_id))],
    }


def library_folder_tree_snapshot(storage: Storage, folder_id: int) -> dict[str, Any]:
    root = storage.get_library_folder(int(folder_id))
    if not root:
        raise ValueError("Library folder not found")
    folders: list[dict[str, Any]] = []
    items: list[dict[str, Any]] = []
    pending = [root]
    while pending:
        folder = pending.pop()
        current_id = int(folder.get("id") or 0)
        folders.append(library_folder_to_api(folder, storage))
        children = storage.list_library_child_folders(current_id)
        pending.extend(reversed(children))
        items.extend(
            library_item_to_api(item, item)
            for item in storage.list_library_items_for_folder(current_id)
        )
    return {"root_folder_id": int(folder_id), "folders": folders, "items": items}


def library_bootstrap_snapshot(storage: Storage) -> dict[str, Any]:
    special = ensure_library_special_folders(storage)
    workspace_tabs = library_workspace_tabs(storage)
    root_children = library_folder_children_snapshot(storage, 1)
    return {
        "root_id": 1,
        "unsorted_id": int(special["unsorted"].get("id") or 0),
        "recycle_id": int(special["recycle"].get("id") or 0),
        "folders": [
            library_folder_to_api(folder, storage, include_native_path=False)
            for folder in storage.list_library_folders()
        ],
        "children": root_children,
        "shortcut_tabs": library_shortcut_tabs(storage),
        "workspace_tabs": workspace_tabs,
    }


def library_search_normalize(value: Any) -> str:
    normalized = unicodedata.normalize("NFD", clean_text(str(value or "")).casefold())
    without_marks = "".join(
        character
        for character in normalized
        if unicodedata.category(character) != "Mn"
    )
    return re.sub(r"[\W_]+", " ", without_marks, flags=re.UNICODE).strip()


def library_file_search_snapshot(
    storage: Storage,
    query: str,
    *,
    limit: int = 400,
) -> dict[str, Any]:
    cleaned_query = clean_text(query)[:300]
    if not cleaned_query:
        return {"query": "", "results": [], "total": 0}
    match = search_matching.scorer(cleaned_query)

    scores = {}
    paper_extras = {}

    def score(blob, paper_id, doi, raw_json):
        key = (paper_id, blob)
        if key in scores:
            return scores[key]
        if paper_id not in paper_extras:
            paper = {"paper_id": paper_id, "doi": doi, "raw_json": raw_json}
            raw = parse_raw_json(paper)
            authors = (authors_from_openalex(raw) or authors_from_crossref(raw)
                       or authors_from_arxiv(raw) or authors_from_datacite(raw)
                       or authors_from_google_scholar(raw))
            paper_extras[paper_id] = " ".join(authors + [preprint_identifier(paper, raw=raw)])
        scores[key] = match(f"{blob} {paper_extras[paper_id]}")
        return scores[key]

    storage.conn.create_function("gewu_search_score", 4, score)
    search_blob = """
        LOWER(
          COALESCE(library_items.display_name, '') || ' ' ||
          COALESCE(papers.title, '') || ' ' ||
          COALESCE(papers.storage_key, '') || ' ' ||
          COALESCE(papers.original_filename, '') || ' ' ||
          COALESCE(papers.doi, '') || ' ' ||
          COALESCE(papers.journal, '') || ' ' ||
          COALESCE(papers.abstract, '') || ' ' ||
          COALESCE(papers.url, '') || ' ' ||
          COALESCE(papers.landing_url, '') || ' ' ||
          COALESCE(papers.original_relative_path, '') || ' ' ||
          folder_paths.path
        )
    """
    score_sql = f"gewu_search_score({search_blob}, papers.paper_id, papers.doi, papers.raw_json)"
    bounded_limit = max(1, min(500, int(limit or 400)))
    try:
        rows = storage.conn.execute(
            f"""
            WITH RECURSIVE folder_paths(id, path, trashed_at) AS (
              SELECT id, name, COALESCE(trashed_at, '')
              FROM library_folders
              WHERE parent_id IS NULL
              UNION ALL
              SELECT
                child.id,
                folder_paths.path || ' / ' || child.name,
                CASE
                  WHEN folder_paths.trashed_at <> '' THEN folder_paths.trashed_at
                  ELSE COALESCE(child.trashed_at, '')
                END
              FROM library_folders AS child
              JOIN folder_paths ON child.parent_id = folder_paths.id
            )
            SELECT
              library_items.id,
              library_items.folder_id,
              library_items.paper_id,
              library_items.display_name,
              library_items.created_at,
              papers.title,
              papers.storage_key,
              papers.journal,
              papers.publication_date,
              papers.doi,
              papers.url,
              papers.landing_url,
              papers.source,
              papers.main_pdf_path,
              papers.merged_pdf_path,
              papers.source_path,
              papers.original_filename,
              folder_paths.path AS folder_path,
              {score_sql} AS search_score,
              COUNT(*) OVER() AS search_total
            FROM library_items
            JOIN papers ON papers.paper_id = library_items.paper_id
            JOIN folder_paths ON folder_paths.id = library_items.folder_id
            WHERE COALESCE(library_items.trashed_at, '') = ''
              AND folder_paths.trashed_at = ''
              AND {score_sql} > 0
            ORDER BY
              search_score DESC,
              LOWER(COALESCE(NULLIF(library_items.display_name, ''), papers.title)),
              library_items.id
            LIMIT ?
            """,
            (bounded_limit,),
        ).fetchall()
    finally:
        storage.conn.create_function("gewu_search_score", 4, None)
    total = int(rows[0]["search_total"] or 0) if rows else 0

    def search_item_to_api(row: sqlite3.Row) -> dict[str, Any]:
        merged_path = clean_text(row["merged_pdf_path"] or "")
        main_path = clean_text(row["main_pdf_path"] or "")
        source_path = clean_text(row["source_path"] or "")
        original_filename = clean_text(row["original_filename"] or "")
        local_path = merged_path or main_path or source_path
        paper = {
            "paper_id": clean_text(row["paper_id"] or ""),
            "storage_key": clean_text(row["storage_key"] or ""),
            "title": clean_text(row["title"] or ""),
            "journal": clean_text(row["journal"] or ""),
            "publication_date": clean_text(row["publication_date"] or ""),
            "doi": clean_text(row["doi"] or ""),
            "source": clean_text(row["source"] or ""),
            "original_filename": original_filename,
            "file_extension": Path(original_filename or local_path).suffix.lower(),
            "full_detail": False,
            "storage_mode": "copy" if local_path else "link",
        }
        if merged_path:
            paper["merged_pdf_path"] = merged_path
        if main_path and main_path != merged_path:
            paper["main_pdf_path"] = main_path
        if source_path and not merged_path and not main_path:
            paper["source_path"] = source_path
        item_api = {
            "id": int(row["id"] or 0),
            "folder_id": int(row["folder_id"] or 0),
            "paper_id": clean_text(row["paper_id"] or ""),
            "created_at": clean_text(row["created_at"] or ""),
            "paper": paper,
        }
        display_name = clean_text(row["display_name"] or "")
        if display_name and display_name != paper["title"]:
            item_api["display_name"] = display_name
        return item_api

    return {
        "query": cleaned_query,
        "total": total,
        "results": [
            {
                "type": "item",
                "id": int(row["id"] or 0),
                "parentFolderId": int(item_api.get("folder_id") or 0),
                "path": clean_text(row["folder_path"] or ""),
                "item": item_api,
            }
            for row in rows
            for item_api in [search_item_to_api(row)]
        ],
    }


