def library_path_snapshot(storage: Storage, folder_id: int) -> dict[str, Any]:
    ensure_library_special_folders(storage)
    folder = storage.get_library_folder(int(folder_id))
    if not folder:
        raise ValueError("Library folder not found")
    path_ids: list[int] = []
    current = folder
    guard = 0
    while current and guard < 128:
        guard += 1
        path_ids.append(int(current.get("id") or 0))
        parent_id = current.get("parent_id")
        if parent_id is None:
            break
        current = storage.get_library_folder(int(parent_id))
    path_ids = [folder_id for folder_id in reversed(path_ids) if folder_id]
    children = [library_folder_children_snapshot(storage, path_id) for path_id in path_ids]
    return {"folder_id": int(folder_id), "path_ids": path_ids, "children": children}


def summarize_import_result(result: dict[str, Any]) -> dict[str, Any]:
    keys = [
        "dry_run",
        "copy_mode",
        "source_root",
        "total_files",
        "paper_candidates_seen",
        "processed_files",
        "identity_conflicts",
        "created_papers",
        "updated_papers",
        "existing_papers",
        "pdf_attachments_to_import",
        "created_resources",
        "library_items_created",
        "library_items_existing",
        "reused_existing_files",
        "resources_or_attachments_to_import",
        "skipped",
        "skipped_system_metadata",
        "mac_aliases_found",
        "missing_source_files",
        "pdf_doi_extracted_count",
        "pdf_doi_missing_count",
        "doi_duplicates",
        "arxiv_duplicates",
        "duplicate_paper_candidates",
        "doi_metadata_refreshed",
        "identifier_metadata_refreshed",
        "identifier_recovery_attempted",
        "identifiers_recovered",
        "identifier_recovery_unresolved",
        "identifier_recovery_sources",
        "report_path",
        "copy_target_root",
        "target_folder_id",
        "target_folder_name",
        "target_library_path",
        "metadata_mode",
        "import_batch_id",
    ]
    summary = {key: result.get(key) for key in keys if key in result}
    summary["errors"] = result.get("errors") or []
    summary["warnings"] = (result.get("warnings") or [])[:20]
    summary["warning_count"] = len(result.get("warnings") or [])
    summary["missing_sources"] = result.get("missing_sources") or []
    summary["pdfs_without_doi"] = result.get("pdfs_without_doi") or []
    summary["identifier_recoveries"] = result.get("identifier_recoveries") or []
    summary["aliases"] = result.get("aliases") or []
    summary["duplicate_dois"] = result.get("duplicate_dois") or []
    summary["duplicate_arxiv_ids"] = result.get("duplicate_arxiv_ids") or []
    return summary


