def local_pdf_path_for_identifier_extraction(paper: dict[str, Any]) -> Path | None:
    for key in ("merged_pdf_path", "main_pdf_path"):
        value = clean_text(paper.get(key) or "")
        if value and value.lower().endswith(".pdf"):
            return Path(value).expanduser()
    return None


def readable_local_pdf_path_for_identifier_recovery(paper: dict[str, Any]) -> Path | None:
    pdf_path = local_pdf_path_for_identifier_extraction(paper)
    if pdf_path is None or pdf_path.suffix.lower() != ".pdf":
        return None
    try:
        return pdf_path if pdf_path.exists() and pdf_path.is_file() else None
    except OSError:
        return None


def extract_identifier_from_pdf_or_title(
    pdf_path: Path,
    paper: dict[str, Any],
    *,
    title_lookup: Callable[[str], dict[str, str]] | None = None,
    pdf_evidence: tuple[str, list[str], list[str]] | None = None,
) -> dict[str, str]:
    if pdf_evidence is None:
        pdf_metadata_title, page_texts = pdf_identifier_page_texts(pdf_path)
        layout_titles = pdf_layout_title_candidates(pdf_path)
    else:
        pdf_metadata_title, page_texts, layout_titles = pdf_evidence
    title_candidates = article_title_candidates_for_identifier(
        paper,
        pdf_metadata_title,
        pdf_path,
        layout_titles=layout_titles,
    )
    title_page_text = title_page_text_for_identifier(page_texts, title_candidates)
    if title_page_text:
        doi = preferred_published_doi_from_text(title_page_text)
        if doi:
            return {"kind": "doi", "identifier": doi, "source": "pdf_title_page"}
        arxiv_id = explicit_arxiv_id_from_text(title_page_text) or arxiv_id_from_arxiv_doi(title_page_text)
        if arxiv_id:
            return {"kind": "arxiv", "identifier": arxiv_id, "source": "pdf_title_page"}
    lookup = title_lookup or identifier_from_title_lookup
    fallback_titles = [
        *title_candidates,
        Path(pdf_path).stem,
    ]
    lookup_completed = False
    lookup_errors: list[str] = []
    for title in dedup_clean_texts(fallback_titles):
        found = lookup(title)
        if found.get("identifier"):
            return {
                **found,
                "matched_title": title,
            }
        lookup_status = clean_text(found.get("lookup_status") or "completed")
        if lookup_status == "completed":
            lookup_completed = True
        elif found.get("lookup_error"):
            lookup_errors.append(clean_text(found.get("lookup_error") or ""))
    if lookup_completed:
        return {"kind": "", "identifier": "", "source": "", "lookup_status": "completed"}
    if lookup_errors:
        return {
            "kind": "",
            "identifier": "",
            "source": "",
            "lookup_status": "unavailable",
            "lookup_error": "; ".join(dedup_clean_texts(lookup_errors)),
        }
    return {"kind": "", "identifier": "", "source": "", "lookup_status": "not_attempted"}


def pdf_identifier_page_texts(pdf_path: Path, *, page_limit: int = 5, reader: PdfReader | None = None) -> tuple[str, list[str]]:
    metadata_title = ""
    page_texts: list[str] = []
    try:
        reader = reader if reader is not None else PdfReader(str(pdf_path))
        info = reader.metadata or {}
        metadata_title = clean_text(getattr(info, "title", "") or info.get("/Title", ""))
        for page in reader.pages[:max(1, int(page_limit or 3))]:
            try:
                page_texts.append(page.extract_text() or "")
            except Exception:
                page_texts.append("")
                continue
    except Exception:
        return metadata_title, page_texts
    return metadata_title, page_texts


def article_title_candidates_for_identifier(
    paper: dict[str, Any],
    pdf_metadata_title: str,
    pdf_path: Path,
    *,
    layout_titles: list[str] | None = None,
) -> list[str]:
    candidates = [
        clean_text(paper.get("title") or ""),
        clean_text(pdf_metadata_title),
        *(layout_titles or []),
    ]
    filename_stem_key = normalized_title_key(Path(pdf_path).stem)
    filtered: list[str] = []
    for candidate in dedup_clean_texts(candidates):
        key = normalized_title_key(candidate)
        if not key or key == filename_stem_key:
            continue
        if is_placeholder_publication_title(candidate):
            continue
        if ".pdf" in candidate.lower() or len(title_tokens(candidate)) < 3:
            continue
        filtered.append(candidate)
    return filtered


def pdf_layout_title_candidates(pdf_path: Path, *, page_limit: int = 3, reader: PdfReader | None = None, first_page_result: dict | None = None) -> list[str]:
    scored: list[tuple[float, str]] = []
    first_page_scored: list[tuple[float, str]] = []
    if first_page_result is not None:
        first_page_result["titles"] = []
    try:
        reader = reader if reader is not None else PdfReader(str(pdf_path))
    except Exception:
        return []
    for page_index, page in enumerate(reader.pages[:max(1, int(page_limit or 1))]):
        fragments: list[dict[str, float | str]] = []

        def collect_fragment(
            text: str,
            _cm: list[float],
            tm: list[float],
            _font: dict[str, Any] | None,
            font_size: float,
        ) -> None:
            value = clean_text(text)
            if not value or len(value) > 500:
                return
            try:
                x = float(tm[4])
                y = float(tm[5])
                size = abs(float(font_size or 0))
            except (IndexError, TypeError, ValueError):
                return
            if size <= 0:
                return
            fragments.append({"text": value, "x": x, "y": y, "size": size})

        try:
            page.extract_text(visitor_text=collect_fragment)
        except Exception:
            continue
        if not fragments:
            continue
        try:
            page_height = float(page.mediabox.height)
        except Exception:
            page_height = 792.0
        body_sizes = [
            float(fragment["size"])
            for fragment in fragments
            if len(title_tokens(str(fragment["text"]))) >= 2
        ]
        if not body_sizes:
            continue
        largest_size = max(body_sizes)
        reliable_font_sizes = largest_size >= 5.0
        minimum_title_size = (
            max(8.0, largest_size * 0.68)
            if reliable_font_sizes
            else largest_size * 0.9
        )
        title_fragments = [
            fragment
            for fragment in fragments
            if float(fragment["size"]) >= minimum_title_size
            and float(fragment["y"]) >= page_height * (0.34 if reliable_font_sizes else 0.58)
            and plausible_pdf_title_text(str(fragment["text"]), allow_fragment=True)
        ]
        title_fragments.sort(key=lambda fragment: (-float(fragment["y"]), float(fragment["x"])))
        groups: list[list[dict[str, float | str]]] = []
        for fragment in title_fragments:
            if not groups:
                groups.append([fragment])
                continue
            previous = groups[-1][-1]
            line_gap = abs(float(previous["y"]) - float(fragment["y"]))
            allowed_gap = max(float(previous["size"]), float(fragment["size"])) * 2.35
            if not reliable_font_sizes:
                allowed_gap = max(30.0, allowed_gap)
            if line_gap <= allowed_gap:
                groups[-1].append(fragment)
            else:
                groups.append([fragment])
        for group in groups:
            candidate = normalize_pdf_layout_title(
                " ".join(str(fragment["text"]) for fragment in group)
            )
            if not plausible_pdf_title_text(candidate):
                continue
            average_size = sum(float(fragment["size"]) for fragment in group) / len(group)
            token_count = len(title_tokens(candidate))
            vertical_position = (
                sum(float(fragment["y"]) for fragment in group)
                / len(group)
                / page_height
            )
            if reliable_font_sizes:
                score = (
                    average_size
                    + min(token_count, 24) * 0.18
                    + min(len(candidate), 180) * 0.005
                    + vertical_position * 2.0
                    - page_index * 1.5
                )
            else:
                score = (
                    vertical_position * 12.0
                    + min(token_count, 14) * 0.10
                    - max(0, token_count - 20) * 0.20
                    - max(0, len(candidate) - 180) * 0.02
                    - page_index * 1.5
                )
            scored.append((score, candidate))
            if page_index == 0:
                first_page_scored.append((score, candidate))
    def ranked_titles(candidates: list[tuple[float, str]]) -> list[str]:
        results: list[str] = []
        seen: set[str] = set()
        for _score, candidate in sorted(candidates, key=lambda item: item[0], reverse=True):
            key = normalized_title_key(candidate)
            if not key or key in seen:
                continue
            seen.add(key)
            results.append(candidate)
        return results[:6]

    if first_page_result is not None:
        first_page_result["titles"] = ranked_titles(first_page_scored)
    return ranked_titles(scored)


def normalize_pdf_layout_title(value: str) -> str:
    text = re.sub(r"(?<=\w)-\s+(?=[a-z])", "", value or "")
    text = re.sub(r"\s+", " ", text).strip(" \t\r\n–—|")
    return normalize_publication_title(text)


def plausible_pdf_title_text(value: str, *, allow_fragment: bool = False) -> bool:
    text = clean_text(value)
    key = normalized_title_key(text)
    tokens = title_tokens(text)
    if not text or not key or is_placeholder_publication_title(text):
        return False
    if not allow_fragment and len(text) > 350:
        return False
    if len(text) < (8 if allow_fragment else 16) or len(tokens) < (2 if allow_fragment else 3):
        return False
    if text.count("/C") > 2:
        return False
    if re.search(r"\b(?:doi|arxiv)\s*[:/]", text, flags=re.I):
        return False
    if re.search(r"\b(?:issn|pp\.?|vol\.?|nos?\.?)\b", text, flags=re.I):
        return False
    letters = re.findall(r"[A-Za-z]", text)
    uppercase_ratio = (
        sum(1 for letter in letters if letter.isupper()) / len(letters)
        if letters
        else 0.0
    )
    if uppercase_ratio > 0.9 and len(tokens) <= 6:
        return False
    if text.lower().startswith((
        "article",
        "abstract",
        "authors",
        "copyright",
        "in: proceedings",
        "letter",
        "proceedings",
        "published by",
        "research article",
        "received ",
        "accepted ",
        "supplementary information",
    )):
        return False
    if re.search(
        r"\b(?:department|university|institute|laboratory|labs|room|avenue|ave\.?|received|usa)\b",
        text,
        flags=re.I,
    ):
        return False
    if text.count("@") or text.count(";") >= 3:
        return False
    return True


def title_page_text_for_identifier(page_texts: list[str], title_candidates: list[str]) -> str:
    if not title_candidates:
        return ""
    for page_text in page_texts:
        cleaned = clean_text(page_text)
        if not cleaned:
            continue
        page_key = normalized_title_key(cleaned)
        page_tokens = title_tokens(cleaned)
        for title in title_candidates:
            title_key = normalized_title_key(title)
            title_words = title_tokens(title)
            if not title_key or not title_words:
                continue
            if title_key in page_key:
                return cleaned
            overlap = len(title_words & page_tokens) / max(1, len(title_words))
            if overlap >= 0.82:
                return cleaned
    return ""


def dedup_clean_texts(values: list[str]) -> list[str]:
    results: list[str] = []
    seen: set[str] = set()
    for value in values:
        text = clean_text(value)
        key = normalized_title_key(text)
        if not text or key in seen:
            continue
        seen.add(key)
        results.append(text)
    return results


def doi_candidates_from_text(value: str) -> list[str]:
    text = re.sub(r"(10\.\d{4,9}/)\s+", r"\1", value or "", flags=re.I)
    candidates: list[str] = []
    for match in re.finditer(r"10\.\d{4,9}/[^\s\"<>]+", text, flags=re.I):
        doi = normalize_publication_doi(match.group(0).strip().rstrip(".,;:)]}"))
        if doi and looks_like_doi(doi) and doi not in candidates:
            candidates.append(doi)
    return candidates


def preferred_published_doi_from_text(value: str) -> str:
    for doi in doi_candidates_from_text(value):
        if doi_is_likely_published_version(doi):
            return doi
    return ""


def arxiv_id_from_arxiv_doi(value: str) -> str:
    for doi in doi_candidates_from_text(value):
        match = re.search(r"10\.48550/arxiv[.:/](\d{4}\.\d{4,5})(?:v\d+)?", doi, flags=re.I)
        if match:
            return normalize_arxiv_identifier(match.group(1))
    return ""


def explicit_arxiv_id_from_text(value: str) -> str:
    patterns = [
        r"\barxiv\s*[:：]\s*([a-z-]+(?:\.[A-Z]{2})?/\d{7})(?:v\d+)?\b",
        r"\barxiv\s*[:：]\s*(\d{4}\.\d{4,5})(?:v\d+)?\b",
    ]
    for pattern in patterns:
        match = re.search(pattern, value or "", flags=re.I)
        if match:
            return normalize_arxiv_identifier(match.group(1))
    return ""


def identifier_from_title_lookup(title: str) -> dict[str, str]:
    query = clean_text(title)
    if len(query) < 8:
        return {"kind": "", "identifier": "", "source": "", "lookup_status": "not_attempted"}
    completed_sources: list[str] = []
    lookup_errors: list[str] = []
    try:
        candidates = search_crossref_publications(query, kind="title", rows=6, timeout=10, max_retries=1)
        completed_sources.append("Crossref")
        for candidate in candidates:
            candidate_title = clean_text(candidate.get("title") or "")
            if not title_match_is_confident(query, candidate_title):
                continue
            doi = normalize_publication_doi(str(candidate.get("doi") or ""))
            if doi_is_likely_published_version(doi):
                return {"kind": "doi", "identifier": doi, "source": "title_crossref", "lookup_status": "completed"}
    except Exception as exc:
        lookup_errors.append(f"Crossref: {exc}")
    try:
        response = openalex_request(
            "GET",
            "https://api.openalex.org/works",
            params={"search": query, "per-page": 5, "mailto": "your_email@example.com"},
            timeout=10,
            max_retries=1,
        )
        completed_sources.append("OpenAlex")
        for item in response.json().get("results") or []:
            if not isinstance(item, dict) or openalex_item_is_likely_data_repository(item):
                continue
            candidate_title = clean_text(item.get("title") or item.get("display_name") or "")
            if not title_match_is_confident(query, candidate_title):
                continue
            doi = normalize_publication_doi(clean_text(item.get("doi") or ""))
            if doi_is_likely_published_version(doi):
                return {"kind": "doi", "identifier": doi, "source": "title_openalex", "lookup_status": "completed"}
    except Exception as exc:
        lookup_errors.append(f"OpenAlex: {exc}")
    try:
        response = semantic_scholar_request(
            "GET",
            "https://api.semanticscholar.org/graph/v1/paper/search",
            params={
                "query": query,
                "limit": 5,
                "fields": "externalIds,title,year,venue",
            },
            timeout=12,
            max_retries=1,
        )
        completed_sources.append("Semantic Scholar")
        for item in response.json().get("data") or []:
            if not isinstance(item, dict):
                continue
            candidate_title = clean_text(item.get("title") or "")
            if not title_match_is_confident(query, candidate_title):
                continue
            external_ids = item.get("externalIds") if isinstance(item.get("externalIds"), dict) else {}
            doi = normalize_publication_doi(clean_text(external_ids.get("DOI") or external_ids.get("doi") or ""))
            if doi_is_likely_published_version(doi):
                return {"kind": "doi", "identifier": doi, "source": "title_semantic", "lookup_status": "completed"}
            arxiv_id = normalize_arxiv_identifier(
                clean_text(
                    external_ids.get("ArXiv")
                    or external_ids.get("arXiv")
                    or external_ids.get("ARXIV")
                    or ""
                )
            )
            if arxiv_id:
                return {"kind": "arxiv", "identifier": arxiv_id, "source": "title_semantic", "lookup_status": "completed"}
    except Exception as exc:
        lookup_errors.append(f"Semantic Scholar: {exc}")
    if completed_sources:
        return {
            "kind": "",
            "identifier": "",
            "source": "",
            "lookup_status": "completed",
            "lookup_sources": ", ".join(completed_sources),
        }
    return {
        "kind": "",
        "identifier": "",
        "source": "",
        "lookup_status": "unavailable",
        "lookup_error": "; ".join(lookup_errors) or "Identifier lookup services were unavailable",
    }


def library_workspace_publication_from_query(query: str) -> dict[str, Any] | None:
    value = clean_text(query)
    if not value:
        return None
    arxiv_id = normalize_arxiv_identifier(value)
    doi = normalize_publication_doi(value)
    if arxiv_id and not looks_like_doi(value):
        return publication_metrics_metadata_from_arxiv_id(arxiv_id)
    if doi and looks_like_doi(doi):
        if doi_is_likely_data_repository(doi):
            return publication_metrics_metadata_from_doi(
                doi,
                allow_data_repository=True,
            )
        candidates = search_crossref_publications(doi, kind="doi")
        return paper_from_publication_candidate(candidates[0]) if candidates else None
    candidate = {
        "paper": {
            "title": value,
            "journal": "",
            "publication_date": "",
            "doi": "",
            "url": "",
        },
        "raw": {},
    }
    identifier = identifier_from_title_lookup(value)
    if identifier.get("kind") == "doi":
        paper = publication_metrics_metadata_from_doi(
            identifier.get("identifier") or "",
            timeout=14,
            max_retries=1,
        )
        if paper:
            return paper
    if identifier.get("kind") == "arxiv":
        paper = publication_metrics_metadata_from_arxiv_id(
            identifier.get("identifier") or "",
            timeout=14,
            max_retries=1,
        )
        if paper:
            return paper
    return resolve_google_scholar_candidate_to_arxiv(candidate)


def title_match_is_confident(left: str, right: str) -> bool:
    left_key = normalized_title_key(left)
    right_key = normalized_title_key(right)
    if not left_key or not right_key:
        return False
    if left_key == right_key:
        return True
    return title_similarity(left, right) >= 0.88


def publication_metadata_from_doi(
    doi: str,
    *,
    timeout: int = 20,
    max_retries: int = 3,
    allow_data_repository: bool = False,
) -> dict[str, Any] | None:
    doi = normalize_publication_doi(doi)
    if not doi or not looks_like_doi(doi) or (doi_is_likely_data_repository(doi) and not allow_data_repository):
        return None
    candidates = search_crossref_publications(doi, kind="doi", timeout=timeout, max_retries=max_retries)
    if not candidates:
        return None
    normalized = paper_from_publication_candidate(candidates[0])
    return enrich_from_landing_page(dict(normalized), {}, True)


def publication_metadata_from_datacite_doi(
    doi: str,
    *,
    timeout: int = 20,
    max_retries: int = 3,
) -> dict[str, Any] | None:
    doi = normalize_publication_doi(doi)
    if not doi or not looks_like_doi(doi):
        return None
    response = request_with_retries(
        "GET",
        f"https://api.datacite.org/dois/{quote(doi, safe='')}",
        timeout=timeout,
        max_retries=max_retries,
    )
    data = response.json().get("data") or {}
    attrs = data.get("attributes") if isinstance(data.get("attributes"), dict) else {}
    if not attrs:
        return None
    titles = attrs.get("titles") if isinstance(attrs.get("titles"), list) else []
    title = normalize_publication_title(next((item.get("title") for item in titles if isinstance(item, dict) and item.get("title")), ""))
    descriptions = attrs.get("descriptions") if isinstance(attrs.get("descriptions"), list) else []
    abstract = clean_text(next((item.get("description") for item in descriptions if isinstance(item, dict) and item.get("description")), ""))
    year = clean_text(str(attrs.get("publicationYear") or ""))
    publisher = journal_name_for_doi(clean_text(attrs.get("publisher") or "DataCite"), doi)
    resource_type = attrs.get("types") if isinstance(attrs.get("types"), dict) else {}
    creators = attrs.get("creators") if isinstance(attrs.get("creators"), list) else []
    url = clean_text(attrs.get("url") or f"https://doi.org/{doi}")
    return {
        "paper_id": "doi_" + hashlib.sha1(doi.lower().encode("utf-8")).hexdigest()[:16],
        "doi": doi,
        "title": title or doi,
        "journal": publisher or "DataCite",
        "publication_date": year,
        "abstract": abstract,
        "abstract_source": "datacite" if abstract else "missing",
        "url": url,
        "landing_url": url,
        "pdf_url": "",
        "source": "datacite",
        "type": clean_text(resource_type.get("resourceTypeGeneral") or "dataset").lower(),
        "type_crossref": clean_text(resource_type.get("resourceTypeGeneral") or "dataset").lower(),
        "publisher_section": "dataset",
        "section_allowed": True,
        "raw": {"datacite": attrs, "creators": creators, "doi": doi},
    }


def publication_metrics_metadata_from_doi(
    doi: str,
    *,
    timeout: int = 20,
    max_retries: int = 3,
    allow_data_repository: bool = False,
    source_status: dict[str, str] | None = None,
    source_lookup: Callable | None = None,
) -> dict[str, Any] | None:
    doi = normalize_publication_doi(doi)
    if not doi or not looks_like_doi(doi) or (doi_is_likely_data_repository(doi) and not allow_data_repository):
        return None
    crossref_count: int | None = None
    crossref_journal = ""
    crossref_raw: dict[str, Any] = {}
    crossref = None
    outcomes = source_status if source_status is not None else {}
    lookup = source_lookup or (lambda name, call: call())
    try:
        crossref = lookup("Crossref", lambda: publication_metadata_from_doi(
            doi,
            timeout=timeout,
            max_retries=max_retries,
            allow_data_repository=allow_data_repository,
        ))
        if source_lookup is None: outcomes["Crossref"] = "found" if crossref else "not_found"
        if isinstance(crossref, dict):
            crossref_journal = normalize_openalex_journal_name(crossref.get("journal") or "")
        crossref_raw = crossref.get("raw") if isinstance(crossref, dict) else {}
        if isinstance(crossref_raw, dict):
            crossref_count = int_or_none(crossref_raw.get("is-referenced-by-count"))
        else:
            crossref_raw = {}
    except Exception as exc:
        status = getattr(getattr(exc, "response", None), "status_code", None)
        outcomes["Crossref"] = "not_found" if status == 404 else ("rate_limited" if status == 429 else "unavailable")
        crossref_count = None
        crossref_raw = {}
    try:
        item = lookup("OpenAlex", lambda: openalex_request(
            "GET",
            f"https://api.openalex.org/works/https://doi.org/{doi}",
            params={"mailto": "your_email@example.com"},
            timeout=timeout,
            max_retries=max_retries,
        ).json())
        if source_lookup is None: outcomes["OpenAlex"] = "found" if isinstance(item, dict) and item.get("id") else "not_found"
        if isinstance(item, dict) and item.get("id"):
            source_journal = normalize_openalex_journal_name(((item.get("primary_location") or {}).get("source") or {}).get("display_name"))
            journal = crossref_journal or source_journal or "Unknown Journal"
            normalized = normalize_openalex_item(item, journal)
            raw = normalized.setdefault("raw", {})
            if isinstance(raw, dict):
                merge_crossref_bibliographic_raw(raw, crossref_raw)
                if crossref_count is not None:
                    raw["is-referenced-by-count"] = crossref_count
            return normalized
    except Exception as exc:
        status = getattr(getattr(exc, "response", None), "status_code", None)
        outcomes["OpenAlex"] = "not_found" if status == 404 else ("rate_limited" if status == 429 else "unavailable")
    if allow_data_repository:
        try:
            datacite = lookup("DataCite", lambda: publication_metadata_from_datacite_doi(doi, timeout=timeout, max_retries=max_retries))
            if source_lookup is None: outcomes["DataCite"] = "found" if datacite else "not_found"
            if datacite:
                return datacite
        except Exception:
            outcomes["DataCite"] = "unavailable"
    return crossref


def publication_metrics_metadata_from_arxiv_id(
    arxiv_id: str,
    *,
    timeout: int = 20,
    max_retries: int = 3,
) -> dict[str, Any] | None:
    normalized_id = normalize_arxiv_identifier(arxiv_id)
    if not normalized_id:
        return None
    paper = fetch_arxiv_by_id(normalized_id, timeout=timeout, max_retries=max_retries)
    if not paper:
        return None
    raw = paper.setdefault("raw", {})
    arxiv_doi = normalize_publication_doi(str(paper.get("doi") or ""))
    if doi_is_likely_published_version(arxiv_doi):
        published = publication_metrics_metadata_from_doi(arxiv_doi, timeout=timeout, max_retries=max_retries)
        if published:
            return attach_arxiv_preprint_metadata(published, paper)
    title = clean_text(paper.get("title") or "")
    if title:
        try:
            response = openalex_request(
                "GET",
                "https://api.openalex.org/works",
                params={"search": title, "per-page": 1, "mailto": "your_email@example.com"},
                timeout=timeout,
                max_retries=max_retries,
            )
            for item in response.json().get("results") or []:
                if not isinstance(item, dict):
                    continue
                result_title = clean_text(item.get("title") or item.get("display_name") or "")
                if normalized_title_key(result_title) != normalized_title_key(title) and title_similarity(title, result_title) < 0.88:
                    continue
                if openalex_item_is_likely_data_repository(item):
                    continue
                if normalized_id not in metadata_refresh.linked_arxiv(item):
                    continue
                raw["openalex_id"] = clean_text(item.get("id") or "")
                raw["id"] = clean_text(item.get("id") or "")
                raw["cited_by_count"] = item.get("cited_by_count")
                raw["counts_by_year"] = item.get("counts_by_year") or []
                raw["openalex"] = item
                if not paper.get("doi"):
                    paper["doi"] = normalize_publication_doi(clean_text(item.get("doi") or ""))
                doi = normalize_publication_doi(clean_text(item.get("doi") or ""))
                if doi_is_likely_published_version(doi):
                    published = publication_metrics_metadata_from_doi(doi, timeout=timeout, max_retries=max_retries)
                    if published:
                        return attach_arxiv_preprint_metadata(published, paper)
                break
        except Exception:
            pass
    return paper


def pubmed_metadata_from_doi(
    doi: str,
    *,
    timeout: int = 20,
    max_retries: int = 2,
) -> dict[str, Any] | None:
    doi = normalize_publication_doi(doi)
    if not doi or not looks_like_doi(doi):
        return None
    pmid = ""
    pmcid = ""
    try:
        response = request_with_retries(
            "GET",
            "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi",
            params={
                "db": "pubmed",
                "term": f"{doi}[AID]",
                "retmode": "json",
                "retmax": "1",
                "tool": NCBI_EUTILS_TOOL,
                "email": NCBI_EUTILS_EMAIL,
            },
            timeout=timeout,
            max_retries=max_retries,
        )
        ids = ((response.json().get("esearchresult") or {}).get("idlist") or [])
        pmid = clean_text(str(ids[0] if ids else ""))
    except Exception:
        pmid = ""
    if not pmid:
        try:
            response = request_with_retries(
                "GET",
                "https://pmc.ncbi.nlm.nih.gov/tools/idconv/api/v1/articles/",
                params={"ids": doi, "format": "json", "tool": NCBI_EUTILS_TOOL, "email": NCBI_EUTILS_EMAIL},
                timeout=timeout,
                max_retries=max_retries,
            )
            records = response.json().get("records") or []
            record = records[0] if records and isinstance(records[0], dict) else {}
            pmid = clean_text(str(record.get("pmid") or ""))
            pmcid = clean_text(str(record.get("pmcid") or ""))
        except Exception:
            pmid = ""
    if not pmid:
        return None
    try:
        response = request_with_retries(
            "GET",
            "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi",
            params={"db": "pubmed", "id": pmid, "retmode": "xml", "tool": NCBI_EUTILS_TOOL, "email": NCBI_EUTILS_EMAIL},
            timeout=timeout,
            max_retries=max_retries,
        )
        root = ET.fromstring(response.content)
    except Exception:
        return {"pmid": pmid, "pmcid": pmcid, "doi": doi}
    article = root.find(".//PubmedArticle")
    if article is None:
        return {"pmid": pmid, "pmcid": pmcid, "doi": doi}
    parsed = parse_pubmed_article(article)
    parsed["pmid"] = clean_text(parsed.get("pmid") or pmid)
    parsed["pmcid"] = clean_text(parsed.get("pmcid") or pmcid)
    parsed["doi"] = normalize_publication_doi(str(parsed.get("doi") or doi))
    return parsed


def refresh_pubmed_if_possible(
    storage: Storage,
    paper: dict[str, Any] | None,
    *,
    doi: str = "",
    timeout: int = 20,
    max_retries: int = 2,
    sync_author_marks: bool = True,
) -> dict[str, Any] | None:
    if not paper:
        return paper
    paper_id = clean_text(paper.get("paper_id") or "")
    normalized_doi = normalize_publication_doi(doi or str(paper.get("doi") or ""))
    if not paper_id or not normalized_doi or not looks_like_doi(normalized_doi):
        return paper
    try:
        pubmed = pubmed_metadata_from_doi(normalized_doi, timeout=timeout, max_retries=max_retries)
    except Exception:
        return paper
    if not pubmed:
        return paper
    raw = parse_raw_json(paper)
    raw["pubmed"] = pubmed
    if pubmed.get("pmid"):
        raw["pmid"] = pubmed.get("pmid")
    if pubmed.get("pmcid"):
        raw["pmcid"] = pubmed.get("pmcid")
    updated = storage.update_paper_raw_json(paper_id, raw) or paper
    if sync_author_marks:
        sync_my_publication_pubmed_author_marks(storage, paper_id=paper_id, pubmed=pubmed)
    if not clean_text(updated.get("abstract") or "") and clean_text(pubmed.get("abstract") or ""):
        updated = storage.refresh_paper_metadata(
            paper_id,
            merge_refreshed_metadata(
                updated,
                {
                    "paper_id": paper_id,
                    "doi": updated.get("doi") or normalized_doi,
                    "title": updated.get("title") or pubmed.get("title") or "",
                    "journal": updated.get("journal") or pubmed.get("journal") or "",
                    "publication_date": updated.get("publication_date") or pubmed.get("publication_date") or "",
                    "abstract": clean_text(pubmed.get("abstract") or ""),
                    "abstract_source": "pubmed",
                    "source": updated.get("source") or "pubmed",
                    "raw": raw,
                },
            ),
        ) or updated
    return updated


def pubmed_author_entry_roles(item: dict[str, Any], *, index: int) -> dict[str, Any]:
    roles = item.get("roles") if isinstance(item.get("roles"), dict) else {}
    first_author = bool(roles.get("first_author"))
    co_first_author = bool(roles.get("co_first_author"))
    corresponding_author = bool(roles.get("corresponding_author"))
    notes = [clean_text(str(value)) for value in roles.get("notes") or [] if clean_text(str(value))]
    if first_author or co_first_author or corresponding_author or notes:
        return {
            "first_author": first_author,
            "co_first_author": co_first_author,
            "corresponding_author": corresponding_author,
            "notes": notes,
        }
    text = " ".join(clean_text(str(value)) for value in item.get("affiliations") or []).lower()
    equal = any(
        phrase in text
        for phrase in [
            "equal contribution",
            "contributed equally",
            "equally contributed",
            "co-first",
            "co first",
            "joint first",
            "shared first",
        ]
    )
    corresponding = pubmed_text_has_email(text) or any(
        phrase in text
        for phrase in [
            "corresponding author",
            "correspondence",
            "corresponding authors",
            "electronic address",
            "e-mail",
            "email:",
        ]
    )
    inferred_notes = []
    if index == 0 and not equal:
        inferred_notes.append("first author")
    if equal:
        inferred_notes.append("equal contribution")
    if corresponding:
        inferred_notes.append("corresponding author")
    return {
        "first_author": bool(index == 0 and not equal),
        "co_first_author": bool(equal),
        "corresponding_author": bool(corresponding),
        "notes": inferred_notes,
    }


def pubmed_author_marks(pubmed: dict[str, Any]) -> dict[str, dict[str, Any]]:
    entries = pubmed.get("author_affiliations") if isinstance(pubmed.get("author_affiliations"), list) else []
    marks: dict[str, dict[str, Any]] = {}
    for index, item in enumerate(entries):
        if not isinstance(item, dict):
            continue
        roles = pubmed_author_entry_roles(item, index=index)
        first_author = bool(roles.get("first_author"))
        co_first_author = bool(roles.get("co_first_author"))
        corresponding_author = bool(roles.get("corresponding_author"))
        if not (first_author or co_first_author or corresponding_author):
            continue
        marks[str(index)] = {
            "name": clean_text(item.get("name") or ""),
            "first_author": first_author,
            "co_first_author": co_first_author,
            "corresponding_author": corresponding_author,
            "source": "pubmed_auto",
        }
    return marks


def sync_my_publication_pubmed_author_marks(storage: Storage, *, paper_id: str, pubmed: dict[str, Any]) -> None:
    paper_id = storage.resolve_paper_id(paper_id)
    marks = pubmed_author_marks(pubmed)
    if not marks:
        return
    rows = storage.conn.execute(
        "SELECT id, author_marks FROM my_publications WHERE paper_id = ?",
        (paper_id,),
    ).fetchall()
    if not rows:
        return
    timestamp = now_iso()
    for row in rows:
        try:
            existing_marks = json.loads(row["author_marks"] or "{}")
        except json.JSONDecodeError:
            existing_marks = {}
        if not isinstance(existing_marks, dict):
            existing_marks = {}
        merged_marks = {
            str(index): value
            for index, value in existing_marks.items()
            if isinstance(value, dict) and value.get("source") != "pubmed_auto"
        }
        for index, mark in marks.items():
            # Manual marks have no automatic source tag and always win for
            # their author. PubMed fills the remaining authors and refreshes
            # marks that were previously imported from PubMed.
            if index not in merged_marks:
                merged_marks[index] = mark
        aggregate_co_first = any(
            bool(item.get("co_first_author"))
            for item in merged_marks.values()
            if isinstance(item, dict)
        )
        aggregate_corresponding = any(
            bool(item.get("corresponding_author"))
            for item in merged_marks.values()
            if isinstance(item, dict)
        )
        storage.conn.execute(
            """
            UPDATE my_publications
            SET author_marks = ?,
                first_author = ?,
                corresponding_author = ?,
                starred = CASE WHEN ? OR ? THEN 1 ELSE starred END,
                updated_at = ?
            WHERE id = ?
            """,
            (
                json.dumps(merged_marks, ensure_ascii=False),
                1 if aggregate_co_first else 0,
                1 if aggregate_corresponding else 0,
                1 if aggregate_co_first else 0,
                1 if aggregate_corresponding else 0,
                timestamp,
                int(row["id"]),
            ),
        )
    storage.conn.commit()


def sync_my_publication_existing_pubmed_marks(storage: Storage, *, paper_id: str) -> None:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(paper_id)
    if not paper:
        return
    raw = parse_raw_json(paper)
    pubmed = raw.get("pubmed") if isinstance(raw.get("pubmed"), dict) else {}
    if pubmed:
        sync_my_publication_pubmed_author_marks(storage, paper_id=paper_id, pubmed=pubmed)


def pubmed_text(element: ET.Element | None) -> str:
    if element is None:
        return ""
    return clean_text(" ".join("".join(element.itertext()).split()))


def pubmed_first_text(root: ET.Element | None, path: str) -> str:
    if root is None:
        return ""
    return pubmed_text(root.find(path))


def parse_pubmed_article(article: ET.Element) -> dict[str, Any]:
    journal = article.find(".//Article/Journal")
    pub_date = journal.find("./JournalIssue/PubDate") if journal is not None else None
    article_ids = {
        clean_text(node.attrib.get("IdType") or "").lower(): pubmed_text(node)
        for node in article.findall(".//PubmedData/ArticleIdList/ArticleId")
    }
    abstract_parts = []
    for node in article.findall(".//Article/Abstract/AbstractText"):
        label = clean_text(node.attrib.get("Label") or "")
        text = pubmed_text(node)
        if text:
            abstract_parts.append(f"{label}: {text}" if label else text)
    authors = []
    affiliations = []
    author_affiliations = []
    for index, node in enumerate(article.findall(".//Article/AuthorList/Author")):
        collective = pubmed_first_text(node, "./CollectiveName")
        current_affiliations = []
        for aff in node.findall("./AffiliationInfo/Affiliation"):
            text = pubmed_text(aff)
            if text:
                affiliations.append(text)
                current_affiliations.append(text)
        roles = pubmed_author_roles(node, current_affiliations, index=index)
        if collective:
            authors.append(collective)
            author_affiliations.append({"name": collective, "affiliations": current_affiliations, "roles": roles})
            continue
        last = pubmed_first_text(node, "./LastName")
        fore = pubmed_first_text(node, "./ForeName")
        initials = pubmed_first_text(node, "./Initials")
        name = " ".join(part for part in [fore or initials, last] if part)
        if name:
            authors.append(name)
            author_affiliations.append({"name": name, "affiliations": current_affiliations, "roles": roles})
    mesh = []
    for node in article.findall(".//MeshHeadingList/MeshHeading"):
        descriptor = node.find("./DescriptorName")
        if descriptor is None:
            continue
        qualifiers = [pubmed_text(item) for item in node.findall("./QualifierName") if pubmed_text(item)]
        mesh.append(
            {
                "descriptor": pubmed_text(descriptor),
                "ui": clean_text(descriptor.attrib.get("UI") or ""),
                "major": clean_text(descriptor.attrib.get("MajorTopicYN") or "").upper() == "Y",
                "qualifiers": qualifiers,
            }
        )
    keywords = [pubmed_text(node) for node in article.findall(".//KeywordList/Keyword") if pubmed_text(node)]
    publication_types = [pubmed_text(node) for node in article.findall(".//PublicationTypeList/PublicationType") if pubmed_text(node)]
    return {
        "pmid": pubmed_first_text(article, ".//MedlineCitation/PMID"),
        "pmcid": clean_text(article_ids.get("pmc") or ""),
        "doi": normalize_publication_doi(str(article_ids.get("doi") or "")),
        "title": normalize_publication_title(pubmed_first_text(article, ".//Article/ArticleTitle")),
        "journal": pubmed_first_text(journal, "./Title") if journal is not None else "",
        "journal_iso_abbrev": pubmed_first_text(journal, "./ISOAbbreviation") if journal is not None else "",
        "issn": pubmed_first_text(journal, "./ISSN") if journal is not None else "",
        "publication_date": pubmed_publication_date(pub_date),
        "volume": pubmed_first_text(journal, "./JournalIssue/Volume") if journal is not None else "",
        "issue": pubmed_first_text(journal, "./JournalIssue/Issue") if journal is not None else "",
        "pages": pubmed_first_text(article, ".//Article/Pagination/MedlinePgn"),
        "abstract": clean_text("\n\n".join(abstract_parts)),
        "authors": authors,
        "affiliations": affiliations[:20],
        "author_affiliations": author_affiliations,
        "mesh": mesh,
        "keywords": keywords,
        "publication_types": publication_types,
        "nlm_unique_id": pubmed_first_text(article, ".//MedlineJournalInfo/NlmUniqueID"),
        "medline_ta": pubmed_first_text(article, ".//MedlineJournalInfo/MedlineTA"),
    }


def pubmed_author_roles(node: ET.Element, affiliations: list[str], *, index: int) -> dict[str, Any]:
    text = " ".join(affiliations).lower()
    equal = clean_text(node.attrib.get("EqualContrib") or "").upper() == "Y"
    equal = equal or any(
        phrase in text
        for phrase in [
            "equal contribution",
            "contributed equally",
            "equally contributed",
            "co-first",
            "co first",
            "joint first",
            "shared first",
        ]
    )
    corresponding = pubmed_text_has_email(text) or any(
        phrase in text
        for phrase in [
            "corresponding author",
            "correspondence",
            "corresponding authors",
            "electronic address",
            "e-mail",
            "email:",
        ]
    )
    notes = []
    if index == 0 and not equal:
        notes.append("first author")
    if equal:
        notes.append("equal contribution")
    if corresponding:
        notes.append("corresponding author")
    return {
        "first_author": bool(index == 0 and not equal),
        "co_first_author": bool(equal),
        "corresponding_author": bool(corresponding),
        "notes": notes,
    }


def pubmed_text_has_email(text: str) -> bool:
    value = clean_text(str(text or ""))
    if "@" not in value:
        return False
    return bool(re.search(r"[\w.+%-]+@[\w.-]+\.[A-Za-z]{2,}", value))


def pubmed_publication_date(pub_date: ET.Element | None) -> str:
    if pub_date is None:
        return ""
    year = pubmed_first_text(pub_date, "./Year")
    month = pubmed_first_text(pub_date, "./Month")
    day = pubmed_first_text(pub_date, "./Day")
    if not year:
        return pubmed_first_text(pub_date, "./MedlineDate")
    if month.isalpha():
        month = {
            "jan": "01", "feb": "02", "mar": "03", "apr": "04", "may": "05", "jun": "06",
            "jul": "07", "aug": "08", "sep": "09", "oct": "10", "nov": "11", "dec": "12",
        }.get(month[:3].lower(), month)
    if month and month.isdigit():
        month = month.zfill(2)
    if day and day.isdigit():
        day = day.zfill(2)
    return "-".join(part for part in [year, month, day] if part)


def attach_arxiv_preprint_metadata(published: dict[str, Any], arxiv_paper: dict[str, Any]) -> dict[str, Any]:
    result = dict(published)
    raw = result.setdefault("raw", {})
    arxiv_raw = arxiv_paper.get("raw") if isinstance(arxiv_paper.get("raw"), dict) else {}
    arxiv_id = normalize_arxiv_identifier(str(arxiv_raw.get("arxiv_id") or arxiv_raw.get("versioned_arxiv_id") or arxiv_paper.get("paper_id") or ""))
    preprint = {
        "source": "arxiv",
        "arxiv_id": arxiv_id,
        "versioned_arxiv_id": clean_text(arxiv_raw.get("versioned_arxiv_id") or ""),
        "title": normalize_publication_title(arxiv_paper.get("title") or ""),
        "publication_date": clean_text(arxiv_paper.get("publication_date") or ""),
        "url": clean_text(arxiv_paper.get("url") or arxiv_paper.get("landing_url") or ""),
        "pdf_url": clean_text(arxiv_paper.get("pdf_url") or ""),
        "raw": arxiv_raw,
    }
    raw["preprint"] = {key: value for key, value in preprint.items() if value not in ("", {}, [])}
    if arxiv_id:
        raw["arxiv_id"] = arxiv_id
    if preprint.get("versioned_arxiv_id"):
        raw["versioned_arxiv_id"] = preprint["versioned_arxiv_id"]
    raw["published_doi"] = normalize_publication_doi(str(result.get("doi") or raw.get("DOI") or ""))
    return result


def semantic_scholar_enrichment_for_paper(
    paper: dict[str, Any],
    *,
    timeout: int = 20,
    max_retries: int = 2,
) -> dict[str, Any] | None:
    fields = (
        "paperId,corpusId,externalIds,url,title,abstract,venue,year,referenceCount,citationCount,"
        "influentialCitationCount,isOpenAccess,openAccessPdf,fieldsOfStudy,s2FieldsOfStudy,"
        "publicationTypes,publicationDate,journal,authors,tldr"
    )
    doi = normalize_publication_doi(str(paper.get("doi") or ""))
    arxiv_id = arxiv_identifier_for_paper(paper)
    refs: list[str] = []
    if arxiv_id and (paper.get("journal") or "").lower() == ARXIV_JOURNAL_NAME.lower():
        refs.append(f"ARXIV:{arxiv_id}")
    if doi and looks_like_doi(doi):
        refs.append(f"DOI:{doi}")
    if arxiv_id and f"ARXIV:{arxiv_id}" not in refs:
        refs.append(f"ARXIV:{arxiv_id}")
    candidates: list[dict[str, Any]] = []
    for ref in refs:
        data = semantic_scholar_enrichment_by_ref(ref, fields=fields, timeout=timeout, max_retries=max_retries)
        if data:
            candidates.append(data)
    title = clean_text(paper.get("title") or "")
    if title:
        response = semantic_scholar_request(
            "GET",
            "https://api.semanticscholar.org/graph/v1/paper/search",
            params={"query": title, "limit": 3, "fields": fields},
            timeout=timeout,
            max_retries=max_retries,
        )
        for item in response.json().get("data") or []:
            if isinstance(item, dict) and item.get("paperId"):
                candidates.append(item)
    return best_semantic_scholar_candidate(candidates, doi=doi, arxiv_id=arxiv_id, title=title)


def best_semantic_scholar_candidate(
    candidates: list[dict[str, Any]],
    *,
    doi: str = "",
    arxiv_id: str = "",
    title: str = "",
) -> dict[str, Any] | None:
    exact = []
    for candidate in candidates:
        if not isinstance(candidate, dict):
            continue
        ids = candidate.get("externalIds") or {}
        candidate_doi = normalize_publication_doi(str(ids.get("DOI") or ids.get("doi") or ""))
        candidate_arxiv = normalize_arxiv_identifier(str(ids.get("ArXiv") or ids.get("arXiv") or ids.get("ARXIV") or ""))
        if doi and candidate_doi and doi != candidate_doi and doi_is_likely_published_version(doi):
            continue
        if arxiv_id and candidate_arxiv and arxiv_id != candidate_arxiv:
            continue
        if (doi and candidate_doi == doi) or (arxiv_id and candidate_arxiv == arxiv_id):
            exact.append(candidate)
    if doi or arxiv_id:
        candidates = exact
    else:
        candidates = [c for c in candidates if isinstance(c, dict) and title
                      and normalized_title_key(c.get("title") or "") == normalized_title_key(title)]
    scored = [
        (semantic_scholar_candidate_score(candidate, doi=doi, arxiv_id=arxiv_id, title=title), candidate)
        for candidate in candidates
        if isinstance(candidate, dict) and candidate.get("paperId")
    ]
    if not scored:
        return None
    scored.sort(key=lambda item: item[0], reverse=True)
    return scored[0][1]


def semantic_scholar_candidate_score(candidate: dict[str, Any], *, doi: str = "", arxiv_id: str = "", title: str = "") -> float:
    external_ids = candidate.get("externalIds") if isinstance(candidate.get("externalIds"), dict) else {}
    candidate_doi = normalize_publication_doi(str(external_ids.get("DOI") or external_ids.get("doi") or ""))
    candidate_arxiv = normalize_arxiv_identifier(
        str(external_ids.get("ArXiv") or external_ids.get("arXiv") or external_ids.get("ARXIV") or "")
    )
    score = 0.0
    if doi and candidate_doi == doi:
        score += 120
    if arxiv_id and candidate_arxiv == arxiv_id:
        score += 140
    if clean_text(candidate.get("abstract") or ""):
        score += 80
    citation_count = int_or_none(candidate.get("citationCount"))
    if citation_count is not None:
        score += min(citation_count, 1000) / 5
    reference_count = int_or_none(candidate.get("referenceCount"))
    if reference_count:
        score += min(reference_count, 200) / 20
    if candidate.get("isOpenAccess"):
        score += 5
    if candidate.get("openAccessPdf"):
        score += 5
    if list_is_nonempty(candidate.get("authors")):
        score += 4
    if title and clean_text(candidate.get("title") or "").lower() == clean_text(title).lower():
        score += 15
    return score


def list_is_nonempty(value: Any) -> bool:
    return isinstance(value, list) and bool(value)


def semantic_scholar_enrichment_by_ref(
    ref: str,
    *,
    fields: str,
    timeout: int = 20,
    max_retries: int = 2,
) -> dict[str, Any] | None:
    if not clean_text(ref):
        return None
    try:
        response = semantic_scholar_request(
            "GET",
            f"https://api.semanticscholar.org/graph/v1/paper/{quote(ref, safe='')}",
            params={"fields": fields},
            timeout=timeout,
            max_retries=max_retries,
        )
        data = response.json()
        if isinstance(data, dict) and data.get("paperId"):
            return data
    except Exception:
        return None
    return None


def refresh_semantic_scholar_if_possible(
    storage: Storage,
    paper: dict[str, Any] | None,
    *,
    timeout: int = 20,
    max_retries: int = 2,
) -> dict[str, Any] | None:
    if not paper:
        return paper
    paper_id = clean_text(paper.get("paper_id") or "")
    if not paper_id:
        return paper
    try:
        enrichment = semantic_scholar_enrichment_for_paper(paper, timeout=timeout, max_retries=max_retries)
    except Exception:
        enrichment = None
    if not enrichment:
        enrichment = best_existing_semantic_scholar_candidate(paper)
    if not enrichment:
        return paper
    updated = storage.update_semantic_scholar_enrichment(paper_id, enrichment) or paper
    if not clean_text(updated.get("abstract") or "") and clean_text(enrichment.get("abstract") or ""):
        updated = storage.refresh_paper_metadata(
            paper_id,
            merge_refreshed_metadata(
                updated,
                {
                    "paper_id": paper_id,
                    "title": updated.get("title") or enrichment.get("title") or "",
                    "journal": updated.get("journal") or enrichment.get("venue") or "",
                    "publication_date": updated.get("publication_date") or clean_text(str(enrichment.get("year") or "")),
                    "abstract": clean_text(enrichment.get("abstract") or ""),
                    "abstract_source": "semantic_scholar",
                    "raw": parse_raw_json(updated),
                },
            ),
        ) or updated
    return refresh_preprint_citation_version_if_possible(storage, updated, timeout=timeout, max_retries=max_retries) or updated


def best_existing_semantic_scholar_candidate(paper: dict[str, Any]) -> dict[str, Any] | None:
    raw = parse_raw_json(paper)
    versions = raw.get("citation_versions") if isinstance(raw.get("citation_versions"), dict) else {}
    preprint = versions.get("preprint") if isinstance(versions.get("preprint"), dict) else {}
    preprint_sources = preprint.get("sources") if isinstance(preprint.get("sources"), dict) else {}
    candidates: list[dict[str, Any]] = []
    current = parse_semantic_scholar_json(paper)
    if current:
        candidates.append(current)
    preprint_semantic = preprint_sources.get("semantic_scholar") if isinstance(preprint_sources.get("semantic_scholar"), dict) else {}
    if preprint_semantic:
        candidates.append(preprint_semantic)
    return best_semantic_scholar_candidate(
        candidates,
        doi=normalize_publication_doi(str(paper.get("doi") or "")),
        arxiv_id=arxiv_identifier_for_paper(paper),
        title=clean_text(paper.get("title") or ""),
    )


def refresh_preprint_citation_version_if_possible(
    storage: Storage,
    paper: dict[str, Any] | None,
    *,
    timeout: int = 20,
    max_retries: int = 2,
) -> dict[str, Any] | None:
    if not paper:
        return paper
    paper_id = clean_text(paper.get("paper_id") or "")
    doi = normalize_publication_doi(str(paper.get("doi") or ""))
    arxiv_id = arxiv_identifier_for_paper(paper)
    if not paper_id or not doi or not arxiv_id:
        return paper
    fields = (
        "paperId,corpusId,externalIds,url,title,abstract,venue,year,referenceCount,citationCount,"
        "influentialCitationCount,isOpenAccess,openAccessPdf,fieldsOfStudy,s2FieldsOfStudy,"
        "publicationTypes,publicationDate,journal,authors,tldr"
    )
    semantic = semantic_scholar_enrichment_by_ref(
        f"ARXIV:{arxiv_id}",
        fields=fields,
        timeout=timeout,
        max_retries=max_retries,
    )
    if not semantic:
        raw = ensure_raw_preprint_metadata(parse_raw_json(paper), arxiv_id)
        stored = storage.update_paper_raw_json(paper_id, raw)
        return stored or paper
    raw = parse_raw_json(paper)
    raw = ensure_raw_preprint_metadata(raw, arxiv_id)
    versions = raw.get("citation_versions") if isinstance(raw.get("citation_versions"), dict) else {}
    preprint = versions.get("preprint") if isinstance(versions.get("preprint"), dict) else {}
    semantic_sources = preprint.get("sources") if isinstance(preprint.get("sources"), dict) else {}
    semantic_sources["semantic_scholar"] = semantic
    preprint["sources"] = semantic_sources
    preprint["arxiv_id"] = arxiv_id
    versions["preprint"] = preprint
    raw["citation_versions"] = versions
    stored = storage.update_paper_raw_json(paper_id, raw)
    return stored or paper


def ensure_raw_preprint_metadata(raw: dict[str, Any], arxiv_id: str) -> dict[str, Any]:
    arxiv_id = normalize_arxiv_identifier(arxiv_id)
    if not arxiv_id:
        return raw
    raw = dict(raw or {})
    preprint = raw.get("preprint") if isinstance(raw.get("preprint"), dict) else {}
    preprint = dict(preprint)
    preprint.setdefault("source", "arxiv")
    preprint["arxiv_id"] = arxiv_id
    preprint.setdefault("url", f"https://arxiv.org/abs/{arxiv_id}")
    preprint.setdefault("pdf_url", f"https://arxiv.org/pdf/{arxiv_id}")
    raw["preprint"] = preprint
    raw["arxiv_id"] = arxiv_id
    return raw


def refresh_paper_metadata_from_doi_if_possible(
    storage: Storage,
    paper: dict[str, Any] | None,
    *,
    doi: str = "",
    timeout: int = 20,
    max_retries: int = 3,
) -> dict[str, Any] | None:
    if not paper:
        return paper
    paper_id = clean_text(paper.get("paper_id") or "")
    normalized_doi = normalize_publication_doi(doi or str(paper.get("doi") or ""))
    if not paper_id or not normalized_doi or not looks_like_doi(normalized_doi):
        return paper
    try:
        normalized = publication_metrics_metadata_from_doi(
            normalized_doi,
            timeout=timeout,
            max_retries=max_retries,
            allow_data_repository=doi_is_likely_data_repository(normalized_doi),
        )
    except Exception:
        return paper
    if not normalized:
        return paper
    refreshed = storage.refresh_paper_metadata(paper_id, merge_refreshed_metadata(paper, normalized))
    refreshed = refreshed or paper
    return refresh_pubmed_if_possible(storage, refreshed, doi=normalized_doi, timeout=timeout, max_retries=max_retries) or refreshed


def refresh_paper_metadata_from_arxiv_if_possible(
    storage: Storage,
    paper: dict[str, Any] | None,
    *,
    arxiv_id: str = "",
    timeout: int = 20,
    max_retries: int = 3,
) -> dict[str, Any] | None:
    if not paper:
        return paper
    paper_id = clean_text(paper.get("paper_id") or "")
    normalized_id = normalize_arxiv_identifier(arxiv_id or arxiv_identifier_for_paper(paper))
    if not paper_id or not normalized_id:
        return paper
    try:
        normalized = publication_metrics_metadata_from_arxiv_id(normalized_id, timeout=timeout, max_retries=max_retries)
    except Exception:
        return paper
    if not normalized:
        return paper
    refreshed = storage.refresh_paper_metadata(paper_id, merge_refreshed_metadata(paper, normalized))
    refreshed = refreshed or paper
    published_doi = normalize_publication_doi(str(refreshed.get("doi") or ""))
    if published_doi and looks_like_doi(published_doi):
        refreshed = refresh_pubmed_if_possible(storage, refreshed, doi=published_doi, timeout=timeout, max_retries=max_retries) or refreshed
    return refreshed


def normalize_import_metadata_mode(value: Any) -> str:
    mode = str(value or "quick").strip().lower()
    return mode if mode in {"skip", "quick", "full"} else "quick"


def normalize_metadata_refresh_mode(value: Any) -> str:
    mode = str(value or "full").strip().lower()
    return mode if mode in {"quick", "full"} else "full"


def record_recovered_identifier(
    storage: Storage,
    *,
    paper_id: str,
    found: dict[str, str],
) -> dict[str, Any] | None:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(paper_id)
    if not paper:
        return None
    identifier = clean_text(found.get("identifier") or "")
    kind = clean_text(found.get("kind") or "")
    source = clean_text(found.get("source") or "")
    matched_title = clean_text(found.get("matched_title") or "")
    raw = parse_raw_json(paper)
    raw["identifier_recovery"] = {
        "kind": kind,
        "identifier": identifier,
        "source": source,
        "matched_title": matched_title,
        "recovered_at": now_iso(),
    }
    updates: dict[str, Any] = {
        "raw_json": json.dumps(raw, ensure_ascii=False),
    }
    if kind == "doi":
        doi = normalize_publication_doi(identifier)
        if not looks_like_doi(doi):
            return None
        updates["doi"] = doi
        updates["doi_source"] = source or "title_lookup"
    elif kind == "arxiv":
        arxiv_id = normalize_arxiv_identifier(identifier)
        if not arxiv_id:
            return None
        raw["arxiv_id"] = arxiv_id
        raw["identifier_recovery"]["identifier"] = arxiv_id
        updates["raw_json"] = json.dumps(raw, ensure_ascii=False)
        if not clean_text(paper.get("url") or ""):
            updates["url"] = f"https://arxiv.org/abs/{arxiv_id}"
        if not clean_text(paper.get("landing_url") or ""):
            updates["landing_url"] = f"https://arxiv.org/abs/{arxiv_id}"
    else:
        return None
    assignments = ", ".join(f"{key} = ?" for key in updates)
    storage.conn.execute(
        f"UPDATE papers SET {assignments} WHERE paper_id = ?",
        [*updates.values(), paper_id],
    )
    storage.conn.commit()
    return storage.get_paper(paper_id)


def recover_imported_pdf_identifiers(
    storage: Storage,
    result: dict[str, Any],
    *,
    job_id: str | None = None,
) -> set[str]:
    candidates = [
        item
        for item in (result.get("metadata_refresh_candidates") or [])
        if isinstance(item, dict)
    ]
    unresolved: list[tuple[dict[str, Any], dict[str, Any], Path]] = []
    seen: set[str] = set()
    for candidate in candidates:
        paper_id = clean_text(candidate.get("paper_id") or "")
        if not paper_id or paper_id in seen:
            continue
        seen.add(paper_id)
        paper = storage.get_paper(paper_id)
        if not paper:
            continue
        doi = normalize_publication_doi(str(paper.get("doi") or candidate.get("doi") or ""))
        arxiv_id = arxiv_identifier_for_paper(paper) or normalize_arxiv_identifier(
            str(candidate.get("arxiv_id") or "")
        )
        if looks_like_doi(doi) or arxiv_id:
            continue
        pdf_path = local_pdf_path_for_identifier_extraction(paper)
        if pdf_path and pdf_path.exists() and pdf_path.is_file():
            unresolved.append((candidate, paper, pdf_path))
    result["identifier_recovery_attempted"] = len(unresolved)
    if not unresolved:
        result["identifiers_recovered"] = 0
        result["identifier_recovery_unresolved"] = 0
        result["identifier_recovery_sources"] = {}
        result["identifier_recoveries"] = []
        return set()
    if job_id:
        log_library_import_job(
            job_id,
            f"Recovering DOI/arXiv from PDF titles for {len(unresolved)} unresolved papers",
        )
    lookup_cache: dict[str, dict[str, str]] = {}

    def cached_title_lookup(title: str) -> dict[str, str]:
        key = normalized_title_key(title)
        if key not in lookup_cache:
            lookup_cache[key] = identifier_from_title_lookup(title)
        return dict(lookup_cache[key])

    recovered: set[str] = set()
    source_counts: dict[str, int] = {}
    recovery_records: list[dict[str, str]] = []
    total = len(unresolved)
    for index, (candidate, paper, pdf_path) in enumerate(unresolved, start=1):
        if job_id and library_import_cancel_requested(job_id):
            raise ImportCancelled("Import stopped by user")
        if job_id:
            update_library_import_job(
                job_id,
                stage="identifier",
                current=index,
                total=total,
                percent=max(0, min(99, round((index / total) * 100))),
            )
            log_library_import_job(
                job_id,
                f"Recovering identifier {index} / {total}: {pdf_path.name}",
                paper_id=str(paper.get("paper_id") or ""),
            )
        found = extract_identifier_from_pdf_or_title(
            pdf_path,
            paper,
            title_lookup=cached_title_lookup,
        )
        identifier = clean_text(found.get("identifier") or "")
        kind = clean_text(found.get("kind") or "")
        if not identifier or kind not in {"doi", "arxiv"}:
            continue
        recorded = record_recovered_identifier(
            storage,
            paper_id=str(paper.get("paper_id") or ""),
            found=found,
        )
        if not recorded:
            continue
        refreshed = recorded  # Refresh once below, using the chosen Quick/Full mode.
        paper_id = str(paper.get("paper_id") or "")
        recovered.add(paper_id)
        source = clean_text(found.get("source") or "unknown")
        source_counts[source] = source_counts.get(source, 0) + 1
        if len(recovery_records) < 500:
            recovery_records.append({
                "paper_id": paper_id,
                "kind": kind,
                "identifier": identifier,
                "source": source,
                "matched_title": clean_text(found.get("matched_title") or ""),
                "pdf_path": str(pdf_path),
            })
        candidate["doi"] = normalize_publication_doi(identifier) if kind == "doi" else ""
        candidate["arxiv_id"] = normalize_arxiv_identifier(identifier) if kind == "arxiv" else ""
        if job_id:
            label = clean_text((refreshed or recorded).get("title") or identifier)
            log_library_import_job(
                job_id,
                f"Recovered {kind.upper()} via {source}: {label}",
                paper_id=paper_id,
            )
    result["identifiers_recovered"] = len(recovered)
    result["identifier_recovery_unresolved"] = max(0, total - len(recovered))
    result["identifier_recovery_sources"] = source_counts
    result["identifier_recoveries"] = recovery_records
    return recovered


def refresh_imported_doi_metadata(storage: Storage, result: dict[str, Any], *, job_id: str | None = None, mode: str = "quick") -> int:
    mode = normalize_import_metadata_mode(mode)
    result["metadata_mode"] = mode
    if mode == "skip":
        result.update(doi_metadata_refreshed=0, identifier_metadata_refreshed=0,
                      identifier_recovery_attempted=0, identifiers_recovered=0,
                      identifier_recovery_unresolved=0, identifier_recovery_sources={}, identifier_recoveries=[])
        return 0
    with metadata_refresh.metadata_network.scope(storage):
        recover_imported_pdf_identifiers(storage, result, job_id=job_id)
    ids = list(dict.fromkeys(str(p.get("paper_id") or "") for p in result.get("metadata_refresh_candidates", [])
                            if isinstance(p, dict) and p.get("paper_id")))
    refresh_job = metadata_jobs.create(storage, mode=mode, paper_ids=ids, origin="import")
    result["metadata_job_id"] = refresh_job["job_id"]
    if job_id:
        update_library_import_job(job_id, metadata_job_id=refresh_job["job_id"])
        if library_import_cancel_requested(job_id):
            metadata_jobs.control(storage, refresh_job["job_id"], "stop")
    last_progress = None
    def progress(job):
        nonlocal last_progress
        if not job_id:
            return
        if library_import_cancel_requested(job_id):
            metadata_jobs.control(storage, job["job_id"], "stop")
        update_library_import_job(job_id, stage="stopping" if library_import_cancel_requested(job_id) else "metadata",
                                  current=job["current"], total=job["total"], percent=min(99, job["percent"]))
        if job["logs"] and job["current"] != last_progress:
            entry = next((entry for entry in reversed(job["logs"]) if entry.get("paper_id")), job["logs"][-1])
            log_library_import_job(job_id, entry["message"], level=entry.get("level", "info"), paper_id=entry.get("paper_id"))
        last_progress = job["current"]
    metadata_jobs.run_job(storage, refresh_job["job_id"], progress=progress)
    job = metadata_jobs.get(storage, refresh_job["job_id"])
    # A batch worker may have claimed this import job. Keep the import attached
    # until its metadata checkpoint is final, including a requested stop.
    while job["status"] in {"queued", "running", "pausing", "stopping"}:
        progress(job)
        time.sleep(.2)
        job = metadata_jobs.get(storage, refresh_job["job_id"])
    progress(job)
    counts = job["counts"]
    result.update(doi_metadata_refreshed=job["changed_count"], identifier_metadata_refreshed=job["changed_count"], metadata_counts=counts)
    if job_id:
        update_library_import_job(job_id, current=job["current"], total=job["total"], percent=job["percent"])
    if job["status"] == "stopped" or (job_id and library_import_cancel_requested(job_id)):
        raise ImportCancelled("Import stopped. Completed files and metadata are kept; the remaining queue has ended.")
    if job["status"] == "paused":
        raise ImportCancelled("Import metadata paused. Continue it in Refresh tasks.")
    if job["status"] == "failed":
        raise RuntimeError(job.get("error") or "Metadata refresh stopped. Continue it in Refresh tasks.")
    return job["changed_count"]


def library_metadata_refresh_candidates(storage: Storage) -> list[dict[str, Any]]:
    rows = storage.conn.execute(
        """
        SELECT DISTINCT papers.*
        FROM papers
        JOIN library_items ON library_items.paper_id = papers.paper_id
        LEFT JOIN library_folders ON library_folders.id = library_items.folder_id
        WHERE (library_items.trashed_at IS NULL OR library_items.trashed_at = '')
          AND (library_folders.trashed_at IS NULL OR library_folders.trashed_at = '')
        ORDER BY COALESCE(papers.publication_date, '') DESC, papers.journal ASC, papers.title ASC
        """
    ).fetchall()
    candidates: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        paper = dict(row)
        paper_id = clean_text(paper.get("paper_id") or "")
        if not paper_id or paper_id in seen:
            continue
        doi = normalize_publication_doi(str(paper.get("doi") or ""))
        arxiv_id = arxiv_identifier_for_paper(paper)
        if looks_like_doi(doi) or arxiv_id:
            paper["doi"] = doi
            paper["arxiv_id"] = arxiv_id
            candidates.append(paper)
            seen.add(paper_id)
    return candidates


def library_missing_identifier_candidates(storage: Storage) -> list[dict[str, Any]]:
    rows = storage.conn.execute(
        """
        SELECT DISTINCT papers.*
        FROM papers
        JOIN library_items ON library_items.paper_id = papers.paper_id
        LEFT JOIN library_folders ON library_folders.id = library_items.folder_id
        WHERE (library_items.trashed_at IS NULL OR library_items.trashed_at = '')
          AND (library_folders.trashed_at IS NULL OR library_folders.trashed_at = '')
        ORDER BY COALESCE(papers.publication_date, '') DESC, papers.title ASC
        """
    ).fetchall()
    candidates: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        paper = dict(row)
        paper_id = clean_text(paper.get("paper_id") or "")
        if not paper_id or paper_id in seen:
            continue
        seen.add(paper_id)
        doi = normalize_publication_doi(str(paper.get("doi") or ""))
        if looks_like_doi(doi) or arxiv_identifier_for_paper(paper):
            continue
        pdf_path = readable_local_pdf_path_for_identifier_recovery(paper)
        if pdf_path is None:
            continue
        paper["_identifier_recovery_pdf_path"] = str(pdf_path)
        candidates.append(paper)
    return candidates


def reliable_paper_title_for_identifier_lookup(paper: dict[str, Any]) -> str:
    title = clean_text(paper.get("title") or "")
    if not title or is_placeholder_publication_title(title):
        return ""
    if title.lower().endswith((".pdf", ".doc", ".docx", ".ppt", ".pptx")):
        return ""
    if len(title) < 12 or len(title_tokens(title)) < 3:
        return ""
    return title


def identifier_recovery_recently_attempted(
    storage: Storage,
    paper_id: str,
    *,
    skip_days: int,
) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    if skip_days <= 0:
        return False
    cutoff = (datetime.now().astimezone() - timedelta(days=skip_days)).isoformat(timespec="seconds")
    retry_cutoff = (datetime.now().astimezone() - timedelta(hours=1)).isoformat(timespec="seconds")
    row = storage.conn.execute(
        """
        SELECT 1
        FROM paper_metadata_refreshes
        WHERE paper_id = ?
          AND mode = 'identifier'
          AND (
            (
              status IN ('recovered', 'unresolved_checked')
              AND COALESCE(finished_at, started_at) >= ?
            )
            OR (
              status IN ('retryable', 'failed')
              AND COALESCE(finished_at, started_at) >= ?
            )
          )
        ORDER BY COALESCE(finished_at, started_at) DESC
        LIMIT 1
        """,
        (paper_id, cutoff, retry_cutoff),
    ).fetchone()
    return row is not None


def metadata_refresh_recently_completed(storage: Storage, paper_id: str, mode: str, *, skip_days: int) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    return metadata_refresh.recently_completed(storage, paper_id, mode, skip_days)


def record_metadata_refresh_start(storage: Storage, *, paper_id: str, mode: str, source_summary: str) -> int:
    paper_id = storage.resolve_paper_id(paper_id)
    started_at = datetime.now().astimezone().isoformat(timespec="seconds")
    cursor = storage.conn.execute(
        """
        INSERT INTO paper_metadata_refreshes (paper_id, mode, status, started_at, source_summary)
        VALUES (?, ?, 'running', ?, ?)
        """,
        (paper_id, mode, started_at, source_summary),
    )
    storage.conn.commit()
    return int(cursor.lastrowid)


def record_metadata_refresh_finish(storage: Storage, refresh_id: int, *, status: str, error: str = "") -> None:
    storage.conn.execute(
        """
        UPDATE paper_metadata_refreshes
        SET status = ?, finished_at = ?, error = ?
        WHERE id = ?
        """,
        (status, datetime.now().astimezone().isoformat(timespec="seconds"), error, refresh_id),
    )
    storage.conn.commit()


def refresh_single_paper_metadata_for_mode(storage: Storage, paper: dict[str, Any], *, mode: str) -> dict[str, Any] | None:
    return metadata_refresh.refresh(storage, str(paper["paper_id"]),
                                    mode=normalize_metadata_refresh_mode(mode), origin="batch")["paper"]


def run_library_metadata_refresh_job(*, job_id: str, db_path: Path, metadata_mode: str = "full", skip_days: int = 3) -> None:
    """Compatibility entry for callers that created an in-memory Loader job."""
    storage = Storage(db_path)
    try:
        job = metadata_jobs.create(storage, mode=normalize_metadata_refresh_mode(metadata_mode), skip_days=skip_days, job_id=job_id)
        metadata_jobs.run_job(storage, job["job_id"])
        snapshot = metadata_jobs.get(storage, job["job_id"]) or {}
        snapshot.pop("job_id", None)
        update_library_import_job(job_id, **snapshot)
    finally:
        storage.close()


def run_library_identifier_recovery_job(
    *,
    job_id: str,
    db_path: Path,
    skip_days: int = 7,
) -> None:
    storage = Storage(db_path)
    attempted = 0
    recovered_count = 0
    unresolved_count = 0
    skipped_recent = 0
    failed_count = 0
    errors: list[str] = []
    source_counts: dict[str, int] = {}
    recoveries: list[dict[str, str]] = []
    lookup_cache: dict[str, dict[str, str]] = {}

    def cached_title_lookup(title: str) -> dict[str, str]:
        key = normalized_title_key(title)
        if key not in lookup_cache:
            lookup_cache[key] = identifier_from_title_lookup(title)
        return dict(lookup_cache[key])

    try:
        candidates = library_missing_identifier_candidates(storage)
        total = len(candidates)
        log_library_import_job(
            job_id,
            f"Finding missing DOI/arXiv identifiers for {total} Library PDF files",
        )
        log_library_import_job(
            job_id,
            (
                f"Skipping verified identifier checks made in the last {skip_days} "
                f"day{'s' if skip_days != 1 else ''}; transient failures cool down for 1 hour"
            ),
        )
        log_library_import_job(
            job_id,
            "Using local PDF content first, then Crossref, OpenAlex, and Semantic Scholar title matching",
        )
        update_library_import_job(
            job_id,
            status="running",
            stage="identifier",
            total=total,
            current=0,
            percent=0,
        )
        for index, paper in enumerate(candidates, start=1):
            if library_import_cancel_requested(job_id):
                raise ImportCancelled("Identifier recovery stopped by user")
            paper_id = clean_text(paper.get("paper_id") or "")
            title = reliable_paper_title_for_identifier_lookup(paper)
            pdf_path = readable_local_pdf_path_for_identifier_recovery(paper)
            if pdf_path is None:
                continue
            label = title or pdf_path.name or paper_id
            percent = max(0, min(99, round((index / max(1, total)) * 100)))
            update_library_import_job(
                job_id,
                current=index,
                total=total,
                percent=percent,
                stage="identifier",
            )
            if identifier_recovery_recently_attempted(
                storage,
                paper_id,
                skip_days=skip_days,
            ):
                skipped_recent += 1
                continue
            attempted += 1
            log_library_import_job(
                job_id,
                f"Finding identifier {index} / {total}: {label}",
                paper_id=paper_id,
            )
            refresh_id = record_metadata_refresh_start(
                storage,
                paper_id=paper_id,
                mode="identifier",
                source_summary=label or paper_id,
            )
            used_title_lookup = False
            try:
                found = extract_identifier_from_pdf_or_title(
                    pdf_path,
                    paper,
                    title_lookup=cached_title_lookup,
                )
                used_title_lookup = clean_text(found.get("source") or "") != "pdf_title_page"
                identifier = clean_text(found.get("identifier") or "")
                kind = clean_text(found.get("kind") or "")
                if not identifier or kind not in {"doi", "arxiv"}:
                    if clean_text(found.get("lookup_status") or "") == "unavailable":
                        raise RuntimeError(
                            clean_text(found.get("lookup_error") or "Identifier lookup services were unavailable")
                        )
                    unresolved_count += 1
                    record_metadata_refresh_finish(
                        storage,
                        refresh_id,
                        status="unresolved_checked",
                        error="",
                    )
                    log_library_import_job(
                        job_id,
                        f"No confident identifier found: {label}",
                        level="warn",
                        paper_id=paper_id,
                    )
                else:
                    recorded = record_recovered_identifier(
                        storage,
                        paper_id=paper_id,
                        found=found,
                    )
                    if not recorded:
                        raise ValueError(f"Could not save recovered {kind} identifier")
                    refreshed = refresh_single_paper_metadata_for_mode(
                        storage,
                        recorded,
                        mode="quick",
                    ) or recorded
                    source = clean_text(found.get("source") or "unknown")
                    source_counts[source] = source_counts.get(source, 0) + 1
                    recovered_count += 1
                    record_metadata_refresh_finish(
                        storage,
                        refresh_id,
                        status="recovered",
                    )
                    if len(recoveries) < 500:
                        recoveries.append(
                            {
                                "paper_id": paper_id,
                                "kind": kind,
                                "identifier": identifier,
                                "source": source,
                                "matched_title": clean_text(found.get("matched_title") or ""),
                                "pdf_path": str(pdf_path) if pdf_path else "",
                            }
                        )
                    log_library_import_job(
                        job_id,
                        f"Recovered {kind.upper()} via {source}: {clean_text(refreshed.get('title') or identifier)}",
                        paper_id=paper_id,
                    )
            except Exception as exc:
                failed_count += 1
                record_metadata_refresh_finish(
                    storage,
                    refresh_id,
                    status="retryable",
                    error=str(exc),
                )
                if len(errors) < 100:
                    errors.append(f"{label}: {exc}")
                log_library_import_job(
                    job_id,
                    f"Identifier recovery failed for {label}: {exc}",
                    level="warn",
                    paper_id=paper_id,
                )
            if used_title_lookup:
                time.sleep(0.75)
        result = {
            "job_type": "identifier_recovery",
            "total_candidates": total,
            "attempted": attempted,
            "identifiers_recovered": recovered_count,
            "identifier_recovery_unresolved": unresolved_count,
            "skipped_recent": skipped_recent,
            "failed": failed_count,
            "skip_days": skip_days,
            "identifier_recovery_sources": source_counts,
            "identifier_recoveries": recoveries,
            "errors": errors,
        }
        log_library_import_job(
            job_id,
            (
                f"Done: {recovered_count} identifiers recovered, "
                f"{unresolved_count} unresolved, {skipped_recent} skipped recent, "
                f"{failed_count} failed"
            ),
        )
        update_library_import_job(
            job_id,
            status="completed",
            stage="complete",
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
            percent=100,
            result=result,
            library_ready=True,
        )
    except ImportCancelled as exc:
        log_library_import_job(job_id, str(exc), level="warn")
        update_library_import_job(
            job_id,
            status="cancelled",
            stage="cancelled",
            error=str(exc),
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    except Exception as exc:
        log_library_import_job(job_id, f"Identifier recovery failed: {exc}", level="error")
        update_library_import_job(
            job_id,
            status="failed",
            stage="failed",
            error=str(exc),
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    finally:
        storage.close()


def new_library_navigation_tab_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:12]}"


def library_navigation_setting_list(storage: Storage, key: str) -> list[dict[str, Any]]:
    raw = storage.get_setting(key, "[]")
    try:
        values = json.loads(raw)
    except json.JSONDecodeError:
        values = []
    if not isinstance(values, list):
        return []
    return [dict(item) for item in values if isinstance(item, dict)]


def library_shortcut_tabs_to_setting(tabs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for tab in tabs:
        if not isinstance(tab, dict):
            continue
        folder_id = int(tab.get("folder_id") or 0)
        if not folder_id:
            continue
        result.append({
            "tab_id": str(tab.get("tab_id") or new_library_navigation_tab_id("shortcut")),
            "folder_id": folder_id,
            "label": " ".join(str(tab.get("label") or "").split())[:80],
        })
    return result


def library_shortcut_tabs(storage: Storage) -> list[dict[str, Any]]:
    values = library_navigation_setting_list(storage, "library_shortcut_tabs")
    result: list[dict[str, Any]] = []
    seen_tab_ids: set[str] = set()
    for item in values:
        folder_id = int(item.get("folder_id") or 0)
        folder = storage.get_library_folder(folder_id) if folder_id else None
        if not folder or folder_id == 1 or not library_folder_is_within(storage, folder_id, 1):
            continue
        tab_id = str(item.get("tab_id") or "").strip()
        if not tab_id or tab_id in seen_tab_ids:
            tab_id = new_library_navigation_tab_id("shortcut")
        seen_tab_ids.add(tab_id)
        label = " ".join(str(item.get("label") or folder.get("name") or "Shortcut").split())
        result.append({"tab_id": tab_id, "folder_id": folder_id, "label": label[:80]})
    normalized = library_shortcut_tabs_to_setting(result)
    if normalized != values:
        storage.set_setting("library_shortcut_tabs", json.dumps(normalized, ensure_ascii=False))
    return normalized


def workspace_tabs_to_setting(tabs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for tab in tabs:
        if not isinstance(tab, dict):
            continue
        root_folder_id = int(tab.get("root_folder_id") or 0)
        if not root_folder_id:
            continue
        label = " ".join(str(tab.get("label") or "Space").split()) or "Space"
        result.append({
            "tab_id": str(tab.get("tab_id") or f"space-{root_folder_id}"),
            "label": label[:80],
            "root_folder_id": root_folder_id,
        })
    return result


def library_workspace_tabs(storage: Storage) -> list[dict[str, Any]]:
    values = library_navigation_setting_list(storage, "library_workspace_tabs")
    result: list[dict[str, Any]] = []
    seen_root_ids: set[int] = set()
    seen_tab_ids: set[str] = set()
    changed = False
    for item in values:
        root_folder_id = int(item.get("root_folder_id") or 0)
        folder = storage.get_library_folder(root_folder_id) if root_folder_id else None
        if not folder or folder.get("parent_id") is not None or root_folder_id == 1 or root_folder_id in seen_root_ids:
            changed = True
            continue
        tab_id = str(item.get("tab_id") or "").strip() or f"space-{root_folder_id}"
        if tab_id in seen_tab_ids:
            tab_id = new_library_navigation_tab_id("space")
            changed = True
        seen_tab_ids.add(tab_id)
        seen_root_ids.add(root_folder_id)
        legacy_paper_ids = [str(paper_id) for paper_id in item.get("paper_ids", []) if paper_id] if isinstance(item.get("paper_ids"), list) else []
        for paper_id in legacy_paper_ids:
            if storage.get_paper(paper_id):
                storage.add_library_item(paper_id=paper_id, folder_id=root_folder_id)
                changed = True
        result.append({
            "tab_id": tab_id,
            "label": str(folder.get("name") or item.get("label") or "Space")[:80],
            "root_folder_id": root_folder_id,
        })
    for folder in storage.list_library_folders():
        root_folder_id = int(folder.get("id") or 0)
        if root_folder_id == 1 or folder.get("parent_id") is not None or root_folder_id in seen_root_ids:
            continue
        result.append({
            "tab_id": f"space-{root_folder_id}",
            "label": str(folder.get("name") or "Space")[:80],
            "root_folder_id": root_folder_id,
        })
        seen_root_ids.add(root_folder_id)
        changed = True
    normalized = workspace_tabs_to_setting(result)
    if changed or normalized != values:
        storage.set_setting("library_workspace_tabs", json.dumps(normalized, ensure_ascii=False))
    return normalized


def library_navigation_tab_index(tabs: list[dict[str, Any]], payload: dict[str, Any]) -> int:
    tab_id = str(payload.get("tab_id") or "").strip()
    if tab_id:
        for index, tab in enumerate(tabs):
            if str(tab.get("tab_id") or "") == tab_id:
                return index
        raise ValueError("Navigation tab not found")
    try:
        index = int(payload.get("index"))
    except (TypeError, ValueError):
        raise ValueError("Navigation tab is required")
    if index < 0 or index >= len(tabs):
        raise ValueError("Navigation tab is out of range")
    return index


def save_library_shortcut_tabs(storage: Storage, tabs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    normalized = library_shortcut_tabs_to_setting(tabs)
    storage.set_setting("library_shortcut_tabs", json.dumps(normalized, ensure_ascii=False))
    return normalized


def save_library_workspace_tabs(storage: Storage, tabs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    normalized = workspace_tabs_to_setting(tabs)
    storage.set_setting("library_workspace_tabs", json.dumps(normalized, ensure_ascii=False))
    return normalized


def add_library_shortcut_tab(storage: Storage, *, folder_id: int, label: str = "") -> dict[str, Any]:
    folder_id = int(folder_id or 0)
    folder = storage.get_library_folder(folder_id) if folder_id else None
    if not folder or folder_id == 1 or not library_folder_is_within(storage, folder_id, 1):
        raise ValueError("Choose a folder inside the main Library")
    tabs = library_shortcut_tabs(storage)
    if any(int(tab.get("folder_id") or 0) == folder_id for tab in tabs):
        raise ValueError("This Library folder already has a shortcut")
    clean_label = " ".join(str(label or folder.get("name") or "Shortcut").split()) or "Shortcut"
    tab = {
        "tab_id": new_library_navigation_tab_id("shortcut"),
        "folder_id": folder_id,
        "label": clean_label[:80],
    }
    tabs.append(tab)
    save_library_shortcut_tabs(storage, tabs)
    return tab


def remove_library_shortcut_tab(storage: Storage, payload: dict[str, Any]) -> dict[str, Any]:
    tabs = library_shortcut_tabs(storage)
    index = library_navigation_tab_index(tabs, payload)
    removed = tabs.pop(index)
    save_library_shortcut_tabs(storage, tabs)
    return removed


def reorder_library_navigation_tabs(tabs: list[dict[str, Any]], ordered_tab_ids: list[Any]) -> list[dict[str, Any]]:
    requested = [str(tab_id) for tab_id in ordered_tab_ids if str(tab_id or "").strip()]
    existing = [str(tab.get("tab_id") or "") for tab in tabs]
    if len(requested) != len(existing) or set(requested) != set(existing):
        raise ValueError("Tab order does not match the current tabs")
    by_id = {str(tab.get("tab_id") or ""): tab for tab in tabs}
    return [by_id[tab_id] for tab_id in requested]


def add_library_workspace_tab(storage: Storage, *, name: str) -> dict[str, Any]:
    base_name = " ".join(str(name or "").split()) or "Space"
    tabs = library_workspace_tabs(storage)
    SPACES_LOCAL_COPY_ROOT.mkdir(parents=True, exist_ok=True)
    folder: dict[str, Any] | None = None
    target_dir: Path | None = None
    for suffix in range(0, 1000):
        candidate = base_name if suffix == 0 else f"{base_name} {suffix + 1}"
        candidate_path = SPACES_LOCAL_COPY_ROOT / finder_safe_name(candidate)
        if candidate_path.exists():
            continue
        created = storage.create_library_root_folder(name=candidate[:80])
        created_path = SPACES_LOCAL_COPY_ROOT / finder_safe_name(created.get("name") or candidate)
        if created_path.exists():
            storage.delete_library_folder(folder_id=int(created.get("id") or 0))
            continue
        try:
            created_path.mkdir(parents=True, exist_ok=False)
        except Exception:
            storage.delete_library_folder(folder_id=int(created.get("id") or 0))
            raise
        folder = created
        target_dir = created_path
        break
    if not folder or not target_dir:
        raise ValueError("Could not create a unique Space folder")
    tab = {
        "tab_id": f"space-{int(folder.get('id') or 0)}",
        "label": str(folder.get("name") or base_name)[:80],
        "root_folder_id": int(folder.get("id") or 0),
    }
    tabs.append(tab)
    save_library_workspace_tabs(storage, tabs)
    return tab


def library_navigation_add_target_folder_id(
    storage: Storage,
    *,
    root_folder_id: int,
    requested_folder_id: int,
    root_label: str,
) -> int:
    root_folder_id = int(root_folder_id or 0)
    target_folder_id = int(requested_folder_id or root_folder_id)
    if not root_folder_id or not storage.get_library_folder(root_folder_id):
        raise ValueError(f"{root_label} folder not found")
    target_folder = storage.get_library_folder(target_folder_id)
    if (
        not target_folder
        or not library_folder_is_within(storage, target_folder_id, root_folder_id)
    ):
        raise ValueError(f"The selected folder is not inside this {root_label}")
    return target_folder_id


def library_workspace_add_target_folder_id(
    storage: Storage,
    *,
    root_folder_id: int,
    requested_folder_id: int,
) -> int:
    return library_navigation_add_target_folder_id(
        storage,
        root_folder_id=root_folder_id,
        requested_folder_id=requested_folder_id,
        root_label="Space",
    )


def remove_library_workspace_tab(storage: Storage, payload: dict[str, Any]) -> dict[str, Any]:
    tabs = library_workspace_tabs(storage)
    index = library_navigation_tab_index(tabs, payload)
    removed = tabs[index]
    root_folder_id = int(removed.get("root_folder_id") or 0)
    folder = storage.get_library_folder(root_folder_id)
    if not folder or root_folder_id == 1 or folder.get("parent_id") is not None:
        raise ValueError("Space root folder not found")
    child_count = storage.conn.execute(
        "SELECT COUNT(*) AS count FROM library_folders WHERE parent_id = ?",
        (root_folder_id,),
    ).fetchone()
    item_count = storage.conn.execute(
        "SELECT COUNT(*) AS count FROM library_items WHERE folder_id = ?",
        (root_folder_id,),
    ).fetchone()
    if int(child_count["count"] or 0) or int(item_count["count"] or 0):
        raise ValueError("This Space is not empty. Move or delete its contents before removing it")
    target_dir = local_copy_dir_for_library_folder(storage, root_folder_id)
    if target_dir.exists():
        if not target_dir.is_dir() or any(target_dir.iterdir()):
            raise ValueError("This Space still contains files in Finder and cannot be removed")
        target_dir.rmdir()
    try:
        storage.delete_library_folder(folder_id=root_folder_id)
        tabs.pop(index)
        save_library_workspace_tabs(storage, tabs)
    except Exception:
        target_dir.mkdir(parents=True, exist_ok=True)
        raise
    return removed


def remap_managed_path(value: Any, source_root: Path, target_root: Path) -> str:
    text = str(value or "").strip()
    if not text:
        return text
    try:
        relative = Path(text).expanduser().resolve().relative_to(source_root.resolve())
    except (OSError, ValueError):
        return text
    return str(target_root.resolve() / relative)


def remap_space_managed_paths(
    storage: Storage,
    *,
    paper_ids: list[str],
    source_root: Path,
    target_root: Path,
) -> None:
    for paper_id in dict.fromkeys(str(value) for value in paper_ids if str(value or "").strip()):
        paper = storage.get_paper(paper_id)
        if not paper:
            continue
        updates: dict[str, Any] = {}
        for key in ("main_pdf_path", "merged_pdf_path", "source_path"):
            current = str(paper.get(key) or "")
            remapped = remap_managed_path(current, source_root, target_root)
            if remapped != current:
                updates[key] = remapped
        try:
            supplements = json.loads(paper.get("supplement_pdf_paths") or "[]")
        except (TypeError, ValueError, json.JSONDecodeError):
            supplements = []
        if isinstance(supplements, list):
            remapped_supplements = [remap_managed_path(path, source_root, target_root) for path in supplements]
            if remapped_supplements != supplements:
                updates["supplement_pdf_paths"] = json.dumps(remapped_supplements, ensure_ascii=False)
        if updates:
            columns = ", ".join(f"{key} = ?" for key in updates)
            storage.conn.execute(
                f"UPDATE papers SET {columns} WHERE paper_id = ?",
                (*updates.values(), paper_id),
            )
        resource_rows = storage.conn.execute(
            "SELECT id, source_path, stored_path FROM resources WHERE paper_id = ?",
            (paper_id,),
        ).fetchall()
        for row in resource_rows:
            resource_updates: dict[str, str] = {}
            for key in ("source_path", "stored_path"):
                current = str(row[key] or "")
                remapped = remap_managed_path(current, source_root, target_root)
                if remapped != current:
                    resource_updates[key] = remapped
            if resource_updates:
                columns = ", ".join(f"{key} = ?" for key in resource_updates)
                storage.conn.execute(
                    f"UPDATE resources SET {columns}, updated_at = ? WHERE id = ?",
                    (*resource_updates.values(), now_iso(), int(row["id"])),
                )
    storage.conn.commit()


def move_library_workspace_to_library(
    storage: Storage,
    payload: dict[str, Any],
    *,
    target_folder_id: int,
) -> dict[str, Any]:
    tabs = library_workspace_tabs(storage)
    original_tabs = [dict(tab) for tab in tabs]
    index = library_navigation_tab_index(tabs, payload)
    tab = tabs[index]
    root_folder_id = int(tab.get("root_folder_id") or 0)
    root_folder = storage.get_library_folder(root_folder_id)
    target_folder_id = int(target_folder_id or 1)
    target_folder = storage.get_library_folder(target_folder_id)
    if not root_folder or root_folder_id == 1 or root_folder.get("parent_id") is not None:
        raise ValueError("Space root folder not found")
    if not target_folder or not library_folder_is_within(storage, target_folder_id, 1):
        raise ValueError("Choose a destination inside the main Library")
    recycle_id = int(ensure_library_special_folders(storage)["recycle"].get("id") or 0)
    if recycle_id and library_folder_is_within(storage, target_folder_id, recycle_id):
        raise ValueError("Recycle cannot be used as the destination")
    duplicate = storage.conn.execute(
        "SELECT id FROM library_folders WHERE parent_id = ? AND lower(name) = lower(?)",
        (target_folder_id, str(root_folder.get("name") or "Space")),
    ).fetchone()
    if duplicate:
        raise ValueError("A folder with this Space name already exists at the selected destination")

    source_dir = local_copy_dir_for_library_folder(storage, root_folder_id).expanduser().resolve()
    target_parent_dir = local_copy_dir_for_library_folder(storage, target_folder_id).expanduser().resolve()
    target_dir = target_parent_dir / finder_safe_name(str(root_folder.get("name") or "Space"))
    if target_dir.exists():
        raise ValueError("A Finder folder with this Space name already exists at the selected destination")
    paper_ids = [str(item.get("paper_id") or "") for item in library_items_in_folder_tree(storage, root_folder_id)]
    moved_native_dir = False
    moved_database_folder = False
    try:
        if source_dir.exists():
            target_parent_dir.mkdir(parents=True, exist_ok=True)
            shutil.move(str(source_dir), str(target_dir))
            moved_native_dir = True
        moved = storage.move_library_folder(folder_id=root_folder_id, parent_id=target_folder_id)
        moved_database_folder = True
        if moved_native_dir:
            remap_space_managed_paths(
                storage,
                paper_ids=paper_ids,
                source_root=source_dir,
                target_root=target_dir,
            )
        tabs.pop(index)
        save_library_workspace_tabs(storage, tabs)
        for paper_id in dict.fromkeys(paper_ids):
            if paper_id:
                sync_all_pdf_aliases_for_paper(storage, paper_id)
        return moved
    except Exception:
        save_library_workspace_tabs(storage, original_tabs)
        if moved_database_folder:
            storage.conn.execute(
                "UPDATE library_folders SET parent_id = NULL, updated_at = ? WHERE id = ?",
                (now_iso(), root_folder_id),
            )
            storage.conn.commit()
        if moved_native_dir and target_dir.exists() and not source_dir.exists():
            source_dir.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(target_dir), str(source_dir))
            remap_space_managed_paths(
                storage,
                paper_ids=paper_ids,
                source_root=target_dir,
                target_root=source_dir,
            )
        raise


def ensure_library_special_folders(storage: Storage) -> dict[str, dict[str, Any]]:
    return {
        "unsorted": storage.ensure_library_folder(parent_id=1, name=LIBRARY_UNSORTED_FOLDER_NAME),
        "recycle": storage.ensure_library_folder(parent_id=1, name=LIBRARY_RECYCLE_FOLDER_NAME),
    }


def library_folder_to_api(
    folder: dict[str, Any],
    storage: Storage | None = None,
    *,
    include_native_path: bool = True,
) -> dict[str, Any]:
    name = folder.get("name") or "New Folder"
    parent_id = int(folder["parent_id"]) if folder.get("parent_id") is not None else None
    is_recycle = parent_id == 1 and name == LIBRARY_RECYCLE_FOLDER_NAME
    is_unsorted = parent_id == 1 and name == LIBRARY_UNSORTED_FOLDER_NAME
    result = {
        "id": int(folder.get("id") or 0),
        "name": name,
        "parent_id": parent_id,
        "color": folder.get("color") or "",
        "created_at": folder.get("created_at") or "",
        "updated_at": folder.get("updated_at") or "",
        "sort_order": int(folder.get("sort_order") or 0),
        "original_parent_id": int(folder["original_parent_id"]) if folder.get("original_parent_id") is not None else None,
        "trashed_at": folder.get("trashed_at") or "",
        "is_recycle": is_recycle,
        "is_unsorted": is_unsorted,
        "protected": parent_id is None or is_unsorted or is_recycle,
    }
    if storage is not None and include_native_path:
        result["native_folder_path"] = str(local_copy_dir_for_library_folder(storage, int(folder.get("id") or 0)))
    return result


def library_item_to_api(item: dict[str, Any], paper: dict[str, Any]) -> dict[str, Any]:
    display_name = item.get("display_name") or ""
    if clean_text(display_name) == clean_text(paper.get("title") or ""):
        display_name = ""
    result = {
        "id": int(item.get("id") or 0),
        "folder_id": int(item.get("folder_id") or 1),
        "paper_id": paper.get("paper_id") or item.get("paper_id") or "",
        "created_at": item.get("created_at") or "",
        "paper": paper_to_library_summary_api(paper),
    }
    if display_name:
        result["display_name"] = display_name
    sort_order = int(item.get("sort_order") or 0)
    if sort_order:
        result["sort_order"] = sort_order
    if item.get("original_folder_id") is not None:
        result["original_folder_id"] = int(item["original_folder_id"])
    if item.get("trashed_at"):
        result["trashed_at"] = item.get("trashed_at") or ""
    return result


def paper_to_library_summary_api(paper: dict[str, Any], *, verify_paths: bool = False, parse_metadata_json: bool = False) -> dict[str, Any]:
    raw = parse_raw_json(paper) if parse_metadata_json else {}
    path_value = existing_path_or_empty if verify_paths else (lambda path: str(path or ""))
    merged_pdf = path_value(paper.get("merged_pdf_path") or "")
    main_pdf = path_value(paper.get("main_pdf_path") or "")
    source_path = path_value(paper.get("source_path") or "")
    imported = raw.get("import") if isinstance(raw.get("import"), dict) else {}
    file_meta = raw.get("file") if isinstance(raw.get("file"), dict) else {}
    stored_import_path = path_value(imported.get("stored_path") or "")
    native_file_path = merged_pdf or main_pdf or stored_import_path or source_path
    storage_mode = paper_storage_mode(paper, merged_pdf=merged_pdf, main_pdf=main_pdf, source_path=source_path)
    summary = {
        "paper_id": paper.get("paper_id") or "",
        "title": paper.get("title") or "",
        "full_detail": False,
        "storage_mode": storage_mode,
        "source": paper.get("source") or "",
        "import_batch_id": paper.get("import_batch_id") or "",
        "import_kind": paper.get("import_kind") or "",
        "import_as": paper.get("import_as") or "",
        "file_mime_type": file_meta.get("mime_type") or "",
        "file_extension": file_meta.get("extension") or Path(str(paper.get("original_filename") or "")).suffix.lower(),
        "file_size_bytes": int(paper.get("size_bytes") or 0),
        "original_filename": paper.get("original_filename") or "",
    }
    for key in ["journal", "publication_date", "doi", "modified_at", "downloaded_at", "first_seen_at", "last_seen_at"]:
        value = paper.get(key) or ""
        if value:
            summary[key] = value
    authors = author_summary(paper)
    if authors:
        summary["authors"] = authors
    full_authors = full_author_names(paper)
    if full_authors:
        summary["full_authors"] = full_authors
    citation = citation_label(paper)
    if citation:
        summary["citation_label"] = citation
    reference = nature_reference(paper)
    if any(reference.values()):
        summary["nature_reference"] = reference
    download_status = paper.get("download_status") or "not_attempted"
    if download_status != "not_attempted":
        summary["download_status"] = download_status
    analysis_status = paper.get("analysis_status") or "not_started"
    if analysis_status != "not_started":
        summary["analysis_status"] = analysis_status
    if merged_pdf:
        summary["merged_pdf_path"] = merged_pdf
    if parse_metadata_json:
        preprint_id = preprint_identifier(paper, raw=raw)
        if preprint_id:
            summary["preprint_id"] = preprint_id
        preprint_category = preprint_primary_category(paper, raw=raw)
        if preprint_category:
            summary["preprint_category"] = preprint_category
    if main_pdf and main_pdf != merged_pdf:
        summary["main_pdf_path"] = main_pdf
    if native_file_path and native_file_path not in {merged_pdf, main_pdf, source_path}:
        summary["native_file_path"] = native_file_path
    if source_path and not merged_pdf and not main_pdf:
        summary["source_path"] = source_path
    return summary


def library_naming_rule(storage: Storage) -> str:
    rule = storage.get_setting(LIBRARY_NAMING_RULE_SETTING, DEFAULT_LIBRARY_NAMING_RULE).strip().lower()
    return rule if rule in LIBRARY_NAMING_RULES else DEFAULT_LIBRARY_NAMING_RULE


def normalize_pdf_rename_template(template: str) -> str:
    normalized = " ".join(str(template or "").strip().split())
    return normalized[:240] or DEFAULT_PDF_RENAME_TEMPLATE


def pdf_rename_template(storage: Storage) -> str:
    return normalize_pdf_rename_template(storage.get_setting(PDF_RENAME_TEMPLATE_SETTING, DEFAULT_PDF_RENAME_TEMPLATE))


def normalize_quick_look_mode(value: str) -> str:
    mode = str(value or "").strip().lower()
    return mode if mode in QUICK_LOOK_MODES else DEFAULT_QUICK_LOOK_MODE


def quick_look_settings_payload(storage: Storage) -> dict[str, Any]:
    return {
        "mode": normalize_quick_look_mode(
            storage.get_setting(QUICK_LOOK_MODE_SETTING, DEFAULT_QUICK_LOOK_MODE)
        ),
        "default_mode": DEFAULT_QUICK_LOOK_MODE,
        "modes": sorted(QUICK_LOOK_MODES),
    }


def website_link_settings_payload(storage: Storage) -> dict[str, Any]:
    browser = storage.get_setting(WEBSITE_LINK_BROWSER_SETTING, "builtin")
    return {"browser": browser if browser in WEBSITE_LINK_BROWSERS else "builtin",
            "capture_details_expanded": storage.get_setting(BROWSER_CAPTURE_DETAILS_SETTING, "false") == "true"}


def workspace_html(storage: Storage) -> str:
    # Embed only the validated enum so even the first click after reload uses
    # SQLite's preference, without delaying browser-hosted popup gestures.
    settings = website_link_settings_payload(storage)
    browser = settings["browser"]
    details = "true" if settings["capture_details_expanded"] else "false"
    return INDEX_HTML.replace('websiteLinkBrowser: "builtin",', f'websiteLinkBrowser: "{browser}",', 1).replace(
        'browserCaptureDetailsExpanded: false,', f'browserCaptureDetailsExpanded: {details},', 1).replace(
        'aiAccessEnabled: false,', 'aiAccessEnabled: ' + ('true' if storage.get_setting('ai_access_enabled', 'false') == 'true' else 'false') + ',', 1)


def normalize_font_size_scale(value: Any) -> int:
    try:
        scale = int(str(value).strip())
    except (TypeError, ValueError):
        return DEFAULT_FONT_SIZE_SCALE
    return scale if scale in FONT_SIZE_SCALES else DEFAULT_FONT_SIZE_SCALE


def font_size_settings_payload(storage: Storage) -> dict[str, Any]:
    return {
        "scale": normalize_font_size_scale(
            storage.get_setting(FONT_SIZE_SCALE_SETTING, str(DEFAULT_FONT_SIZE_SCALE))
        ),
        "default_scale": DEFAULT_FONT_SIZE_SCALE,
        "scales": list(FONT_SIZE_SCALES),
    }


