def bibtex_key(paper: dict[str, Any]) -> str:
    authors = full_author_names(paper) or author_summary(paper)
    lead = author_last_name(authors[0]).lower() if authors else "paper"
    year = publication_year(paper) or "undated"
    title_word = next((part.lower() for part in re.findall(r"[A-Za-z0-9]+", paper.get("title") or "") if len(part) > 3), "paper")
    key = re.sub(r"[^a-z0-9]+", "", f"{lead}{year}{title_word}")
    return key or safe_slug(paper.get("paper_id") or "paper").replace("-", "")


def bibtex_escape(value: str) -> str:
    return str(value).replace("\\", "\\\\").replace("{", "\\{").replace("}", "\\}")


def int_or_none(value: Any) -> int | None:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def count_by_journal(papers: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for paper in papers:
        journal = paper.get("journal") or "Unknown"
        counts[journal] = counts.get(journal, 0) + 1
    return counts


def paper_first_seen_date(paper: dict[str, Any]) -> str:
    return str(paper.get("first_seen_at") or "")[:10]


def paper_is_late_arrival(paper: dict[str, Any]) -> bool:
    publication_date = str(paper.get("publication_date") or "")[:10]
    first_seen = paper_first_seen_date(paper)
    if not publication_date or not first_seen or first_seen <= publication_date:
        return False
    try:
        delta = date.fromisoformat(first_seen) - date.fromisoformat(publication_date)
    except ValueError:
        return False
    return timedelta(days=1) <= delta <= timedelta(days=LATE_ARRIVAL_LOOKBACK_DAYS)


def unread_late_arrival_paper_ids(storage: Storage, selected: str, journals: list[str]) -> set[str]:
    if not journals:
        return set()
    placeholders = ", ".join(["?"] * len(journals))
    rows = storage.conn.execute(
        f"""
        SELECT papers.paper_id
        FROM papers
        LEFT JOIN paper_reads ON paper_reads.paper_id = papers.paper_id
        WHERE papers.publication_date = ?
          AND length(papers.publication_date) = 10
          AND substr(papers.first_seen_at, 1, 10) > papers.publication_date
          AND julianday(substr(papers.first_seen_at, 1, 10)) - julianday(papers.publication_date) <= ?
          AND papers.source IN ('crossref', 'openalex', 'arxiv')
          AND papers.journal IN ({placeholders})
          AND (papers.section_allowed IS NULL OR papers.section_allowed != 0)
          AND paper_reads.late_arrival_seen_at IS NULL
        """,
        (selected, LATE_ARRIVAL_LOOKBACK_DAYS, *journals),
    ).fetchall()
    return {str(row["paper_id"]) for row in rows}


def late_arrivals_for_seen_date(storage: Storage, selected: str, journals: list[str]) -> list[dict[str, Any]]:
    if not journals:
        return []
    try:
        window_start = (date.fromisoformat(selected) - timedelta(days=LATE_ARRIVAL_LOOKBACK_DAYS)).isoformat()
    except ValueError:
        return []
    placeholders = ", ".join(["?"] * len(journals))
    rows = storage.conn.execute(
        f"""
        SELECT papers.*
        FROM papers
        LEFT JOIN paper_reads ON paper_reads.paper_id = papers.paper_id
        WHERE substr(papers.first_seen_at, 1, 10) = ?
          AND length(papers.publication_date) = 10
          AND papers.publication_date >= ?
          AND papers.publication_date < ?
          AND papers.source IN ('crossref', 'openalex', 'arxiv')
          AND papers.journal IN ({placeholders})
          AND (papers.section_allowed IS NULL OR papers.section_allowed != 0)
          AND paper_reads.late_arrival_seen_at IS NULL
        ORDER BY papers.publication_date DESC, papers.journal ASC, papers.title ASC
        """,
        (selected, window_start, selected, *journals),
    ).fetchall()
    return [dict(row) for row in rows]


def late_arrival_summaries(papers: list[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[str, dict[str, Any]] = {}
    for paper in papers:
        publication_date = str(paper.get("publication_date") or "")[:10]
        if not publication_date:
            continue
        summary = grouped.setdefault(
            publication_date,
            {"publication_date": publication_date, "count": 0, "journals": {}, "paper_ids": []},
        )
        summary["count"] += 1
        summary["paper_ids"].append(str(paper.get("paper_id") or ""))
        journal = paper.get("journal") or "Unknown Journal"
        summary["journals"][journal] = int(summary["journals"].get(journal, 0)) + 1
    return sorted(grouped.values(), key=lambda item: str(item["publication_date"]), reverse=True)


def author_summary(paper: dict[str, Any]) -> list[str]:
    raw = parse_raw_json(paper)
    names = authors_from_openalex(raw) or authors_from_crossref(raw) or authors_from_arxiv(raw) or authors_from_datacite(raw) or authors_from_google_scholar(raw)
    if len(names) <= 6:
        return names
    return names[:3] + ["…"] + names[-3:]


def authors_from_openalex(raw: dict[str, Any]) -> list[str]:
    names: list[str] = []
    for item in raw.get("authorships") or []:
        if not isinstance(item, dict):
            continue
        author = item.get("author") or {}
        name = clean_author_name(str(author.get("display_name") or item.get("raw_author_name") or ""))
        if name:
            names.append(name)
    return dedup_names(names)


def authors_from_crossref(raw: dict[str, Any]) -> list[str]:
    names: list[str] = []
    for item in raw.get("author") or []:
        if not isinstance(item, dict):
            continue
        literal = clean_author_name(str(item.get("name") or ""))
        given = clean_author_name(str(item.get("given") or ""))
        family = clean_author_name(str(item.get("family") or ""))
        name = literal or clean_author_name(" ".join(part for part in [given, family] if part))
        if name:
            names.append(name)
    return dedup_names(names)


def authors_from_arxiv(raw: dict[str, Any]) -> list[str]:
    if clean_text(raw.get("source") or "").lower() != "arxiv" and not (raw.get("arxiv_id") or raw.get("versioned_arxiv_id")):
        return []
    return dedup_names([clean_author_name(str(name)) for name in raw.get("authors") or [] if name])


def authors_from_datacite(raw: dict[str, Any]) -> list[str]:
    datacite = raw.get("datacite") if isinstance(raw.get("datacite"), dict) else raw
    creators = raw.get("creators") or datacite.get("creators") or []
    names: list[str] = []
    for item in creators:
        if not isinstance(item, dict):
            continue
        name = clean_author_name(str(item.get("name") or ""))
        if not name:
            given = clean_author_name(str(item.get("givenName") or ""))
            family = clean_author_name(str(item.get("familyName") or ""))
            name = clean_author_name(" ".join(part for part in [given, family] if part))
        if name:
            names.append(name)
    return dedup_names(names)


def authors_from_google_scholar(raw: dict[str, Any]) -> list[str]:
    authors = raw.get("authors") or []
    if isinstance(authors, str):
        authors = re.split(r"\s*(?:,|，|、|;|；)\s*", authors)
    elif isinstance(authors, list):
        split_authors: list[str] = []
        for author in authors:
            split_authors.extend(re.split(r"\s*(?:，|、|;|；)\s*", str(author)))
        authors = split_authors
    return dedup_names([clean_author_name(str(name)) for name in authors if name])


def preprint_identifier(paper: dict[str, Any], *, raw: dict[str, Any] | None = None) -> str:
    raw = raw if isinstance(raw, dict) else None
    raw = raw if raw is not None else parse_raw_json(paper)
    if raw.get("manual_preprint_identifier_override") is True:
        return normalize_arxiv_identifier(str(raw.get("manual_preprint_identifier") or ""))
    if (paper.get("journal") or "").lower() != ARXIV_JOURNAL_NAME.lower():
        preprint = raw.get("preprint") if isinstance(raw.get("preprint"), dict) else {}
        versions = raw.get("citation_versions") if isinstance(raw.get("citation_versions"), dict) else {}
        preprint_version = versions.get("preprint") if isinstance(versions.get("preprint"), dict) else {}
        return clean_text(preprint.get("arxiv_id") or preprint_version.get("arxiv_id") or raw.get("arxiv_id") or raw.get("versioned_arxiv_id") or "")
    return clean_text(raw.get("arxiv_id") or raw.get("versioned_arxiv_id") or "")


def update_manual_preprint_identifier(
    storage: Storage,
    paper_id: str,
    identifier: str,
) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    cleaned = clean_text(identifier)
    normalized = normalize_arxiv_identifier(cleaned)
    if cleaned and not normalized:
        raise ValueError("Enter a valid arXiv identifier or arXiv URL")
    raw = parse_raw_json(paper)
    previous = arxiv_identifier_for_paper(paper)
    if normalized == previous:
        return paper
    raw["manual_preprint_identifier_override"] = True
    raw["manual_preprint_identifier"] = normalized
    raw["manual_preprint_identifier_updated_at"] = datetime.now().astimezone().isoformat(timespec="microseconds")
    from . import identifier_correction, paper_identity
    identifier_correction.mark(raw, 'arxiv', normalized, previous, raw['manual_preprint_identifier_updated_at'])
    # An edit changes this object; matching an existing ID must not merge objects
    # implicitly before the user can inspect the corrected information.
    with paper_identity.transaction(storage):
        payload = {**paper, 'raw': raw}
        if normalized and any(p['paper_id'] != paper_id and ('arxiv', normalized) in paper_identity.identifiers(storage, p)
                              for p in paper_identity.find(storage, payload)):
            raise ValueError('This arXiv ID is already registered to another Gewu Key. Existing papers were not changed.')
        updated = storage._update_paper_raw_json_unresolved(str(paper_id), raw)
        paper_identity.register(storage, updated)
    if not updated:
        raise KeyError(str(paper_id))
    return updated


def arxiv_record_version_info(record: dict[str, Any], requested_identifier: str) -> tuple[str, int, str, str]:
    raw = record.get("raw") if isinstance(record.get("raw"), dict) else {}
    versioned = clean_text(raw.get("versioned_arxiv_id") or raw.get("arxiv_id") or requested_identifier)
    identifier = normalize_arxiv_identifier(versioned)
    requested = normalize_arxiv_identifier(requested_identifier)
    if not identifier or identifier != requested:
        raise RuntimeError("arXiv returned metadata for a different identifier")
    match = re.search(r"v(\d+)$", versioned, flags=re.I)
    latest_version = max(1, int(match.group(1))) if match else 1
    return (
        identifier,
        latest_version,
        clean_text(raw.get("published") or ""),
        clean_text(raw.get("updated") or ""),
    )


def arxiv_version_filename(identifier: str, version_number: int) -> str:
    safe_identifier = finder_safe_name(identifier.replace("/", "_"), "arXiv")
    return finder_safe_name(
        f"{safe_identifier}v{int(version_number)} [Preprint v{int(version_number)}].pdf",
        f"arXiv v{int(version_number)} [Preprint v{int(version_number)}].pdf",
    )


def download_arxiv_preprint_versions(
    storage: Storage,
    paper_id: str,
    *,
    include_history: bool = False,
) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    if preferred_local_pdf_dir_for_paper(storage, str(paper_id)) is None:
        raise ValueError("Add this paper to Library or My Publications before downloading arXiv files")
    requested_identifier = normalize_arxiv_identifier(preprint_identifier(paper))
    if not requested_identifier:
        raise ValueError("This paper does not have a valid arXiv identifier")
    record = fetch_arxiv_by_id(requested_identifier)
    if not record:
        raise RuntimeError("arXiv metadata was not found for this identifier")
    identifier, latest_version, published_at, updated_at = arxiv_record_version_info(
        record,
        requested_identifier,
    )
    target_versions = list(range(1, latest_version + 1)) if include_history else [latest_version]
    resources = refresh_paper_resource_fingerprints(storage, str(paper_id))
    version_resources: dict[int, dict[str, Any]] = {}
    stale_synced_resources: list[dict[str, Any]] = []
    for resource in resources:
        if (
            clean_text(resource.get("file_role") or "") != "publication_version"
            or clean_text(resource.get("version_role") or "") != "preprint"
        ):
            continue
        source_identifier = normalize_arxiv_identifier(clean_text(resource.get("source_url") or ""))
        if source_identifier != identifier:
            if source_identifier and clean_text(resource.get("added_via") or "") == "arxiv_version_sync":
                stale_synced_resources.append(resource)
            continue
        number = int(resource.get("version_number") or 0)
        if number <= 0:
            continue
        current = version_resources.get(number)
        if current is None or (not current.get("exists") and resource.get("exists")):
            version_resources[number] = resource

    versions_dir = associated_work_dir_for_paper(storage, str(paper_id)) / "Versions"
    downloaded_versions: list[int] = []
    existing_versions: list[int] = []
    failed_versions: list[dict[str, Any]] = []
    for version_number in target_versions:
        existing = version_resources.get(version_number)
        if existing and existing.get("exists"):
            existing_versions.append(version_number)
            continue
        versioned_identifier = f"{identifier}v{version_number}"
        source_url = f"https://arxiv.org/pdf/{quote(versioned_identifier, safe='/.-')}"
        filename = arxiv_version_filename(identifier, version_number)
        temporary_dir = Path(tempfile.mkdtemp(prefix="gewu-arxiv-version-"))
        temporary = temporary_dir / filename
        target: Path | None = None
        messages: list[str] = []
        try:
            downloaded = False
            for _attempt in range(2):
                wait_for_arxiv_rate_limit()
                if try_download_pdf(
                    source_url,
                    temporary,
                    messages,
                    request_max_retries=1,
                ):
                    downloaded = True
                    break
            if not downloaded:
                raise RuntimeError(messages[-1] if messages else "arXiv did not return a valid PDF")
            fingerprint = fingerprint_file(temporary)
            exact_duplicate = next(
                (
                    resource
                    for resource in resources
                    if clean_text(resource.get("sha256") or "") == fingerprint.sha256
                    and resource.get("exists")
                ),
                None,
            )
            version_date = published_at if version_number == 1 else (updated_at if version_number == latest_version else "")
            label = f"Preprint v{version_number}"
            if exact_duplicate:
                duplicate_id = int(exact_duplicate.get("id") or 0)
                duplicate_role = clean_text(exact_duplicate.get("version_role") or "other")
                if storage.resource_is_pdf(exact_duplicate) and duplicate_role in {"", "other", "preprint"}:
                    storage.conn.execute(
                        """
                        UPDATE resources
                        SET file_role = 'publication_version', version_role = 'preprint',
                            version_label = ?, version_date = ?, version_number = ?,
                            file_type = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN file_type ELSE 'preprint' END,
                            file_source = 'preprint_server', source_detail = 'arxiv.org',
                            source_url = ?, sha256 = ?, content_sha256 = ?,
                            annotation_count = ?,
                            is_annotated = CASE
                                WHEN COALESCE(annotation_override, 0) = 1 THEN is_annotated
                                WHEN ? > 0 THEN 1 ELSE 0
                            END,
                            annotation_state = CASE
                                WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                                WHEN ? > 0 THEN 'annotated' ELSE 'unannotated'
                            END,
                            missing_status = '', updated_at = ?
                        WHERE id = ? AND paper_id = ?
                        """,
                        (
                            label,
                            version_date or None,
                            version_number,
                            source_url,
                            fingerprint.sha256,
                            fingerprint.content_sha256 or None,
                            fingerprint.annotation_count,
                            fingerprint.annotation_count,
                            fingerprint.annotation_count,
                            now_iso(),
                            duplicate_id,
                            str(paper_id),
                        ),
                    )
                    storage.conn.commit()
                resource = storage.get_paper_resource(duplicate_id) or exact_duplicate
                resource = {**resource, "exists": True, "local_path": storage.resource_local_path(resource)}
                version_resources[version_number] = resource
                existing_versions.append(version_number)
                continue
            versions_dir.mkdir(parents=True, exist_ok=True)
            target = unique_path_in_dir(versions_dir / filename)
            shutil.move(str(temporary), str(target))
            digest = fingerprint.sha256
            previous = max(
                (
                    resource
                    for number, resource in version_resources.items()
                    if number < version_number and int(resource.get("id") or 0)
                ),
                key=lambda resource: int(resource.get("version_number") or 0),
                default=None,
            )
            if existing:
                storage.conn.execute(
                    """
                    UPDATE resources
                    SET stored_path = ?, original_filename = ?, display_name = ?,
                        file_role = 'publication_version', version_role = 'preprint',
                        version_label = ?, version_date = ?, version_number = ?,
                        file_type = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN file_type ELSE 'preprint' END,
                        file_source = 'preprint_server', source_detail = 'arxiv.org',
                        source_url = ?, storage_mode = 'managed', sha256 = ?, content_sha256 = ?,
                        annotation_count = ?,
                        is_annotated = CASE WHEN COALESCE(annotation_override, 0) = 1 THEN is_annotated ELSE ? END,
                        annotation_state = CASE
                            WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                            WHEN ? > 0 THEN 'annotated' ELSE 'unannotated'
                        END,
                        added_via = 'arxiv_version_sync', mime_type = 'application/pdf',
                        kind = 'pdf', size_bytes = ?, modified_at = ?,
                        supersedes_resource_id = ?, missing_status = '', status = 'imported',
                        updated_at = ?
                    WHERE id = ?
                    """,
                    (
                        str(target),
                        target.name,
                        target.name,
                        label,
                        version_date or None,
                        version_number,
                        source_url,
                        digest,
                        fingerprint.content_sha256 or None,
                        fingerprint.annotation_count,
                        1 if fingerprint.is_annotated else 0,
                        fingerprint.annotation_count,
                        int(target.stat().st_size),
                        now_iso(),
                        int(previous.get("id") or 0) if previous else None,
                        now_iso(),
                        int(existing.get("id") or 0),
                    ),
                )
                storage.conn.commit()
                resource = storage.get_paper_resource(int(existing.get("id") or 0)) or existing
            else:
                resource = storage.create_paper_resource(
                    paper_id=str(paper_id),
                    stored_path=str(target),
                    display_name=target.name,
                    file_role="publication_version",
                    version_role="preprint",
                    version_label=label,
                    version_date=version_date,
                    version_number=version_number,
                    source_url=source_url,
                    storage_mode="managed",
                    sha256=digest,
                    content_sha256=fingerprint.content_sha256,
                    annotation_count=fingerprint.annotation_count,
                    is_annotated=fingerprint.is_annotated,
                    file_type="preprint",
                    file_source="preprint_server",
                    source_detail="arxiv.org",
                    annotation_state="annotated" if fingerprint.is_annotated else "unannotated",
                    added_via="arxiv_version_sync",
                    mime_type="application/pdf",
                    kind="pdf",
                    supersedes_resource_id=int(previous.get("id") or 0) if previous else None,
                )
            version_resources[version_number] = {**resource, "exists": True, "local_path": str(target)}
            resources.append(version_resources[version_number])
            downloaded_versions.append(version_number)
        except Exception as exc:
            if target and target.exists() and not any(
                clean_text(resource.get("stored_path") or "") == str(target)
                for resource in version_resources.values()
            ):
                target.unlink(missing_ok=True)
            failed_versions.append({"version": version_number, "error": str(exc)})
        finally:
            shutil.rmtree(temporary_dir, ignore_errors=True)

    available_targets = [
        version_resources[number]
        for number in target_versions
        if number in version_resources and version_resources[number].get("exists")
    ]
    if not available_targets:
        detail = failed_versions[-1]["error"] if failed_versions else "No arXiv PDF was downloaded"
        raise RuntimeError(detail)
    if stale_synced_resources:
        timestamp = now_iso()
        storage.conn.executemany(
            """
            UPDATE resources
            SET version_role = 'other', version_label = 'Previous arXiv PDF', updated_at = ?
            WHERE id = ?
            """,
            [
                (timestamp, int(resource.get("id") or 0))
                for resource in stale_synced_resources
                if int(resource.get("id") or 0)
            ],
        )
        storage.conn.commit()
    best_preprint = max(
        (resource for resource in version_resources.values() if resource.get("exists")),
        key=lambda resource: int(resource.get("version_number") or 0),
    )
    if should_promote_new_paper_version(storage, str(paper_id), best_preprint):
        promote_paper_resource(storage, str(paper_id), int(best_preprint.get("id") or 0))

    updated = storage.get_paper(str(paper_id)) or paper
    raw = parse_raw_json(updated)
    raw["arxiv_version_sync"] = {
        "identifier": identifier,
        "latest_version": latest_version,
        "checked_at": now_iso(),
        "downloaded_versions": downloaded_versions,
        "failed_versions": [int(item["version"]) for item in failed_versions],
    }
    storage.update_paper_raw_json(str(paper_id), raw)
    return {
        "identifier": identifier,
        "latest_version": latest_version,
        "requested_versions": target_versions,
        "downloaded_versions": downloaded_versions,
        "existing_versions": existing_versions,
        "failed_versions": failed_versions,
    }


def preprint_categories(paper: dict[str, Any], *, raw: dict[str, Any] | None = None) -> list[str]:
    raw = raw if isinstance(raw, dict) else None
    if (paper.get("journal") or "").lower() != ARXIV_JOURNAL_NAME.lower():
        raw = raw if raw is not None else parse_raw_json(paper)
        preprint = raw.get("preprint") if isinstance(raw.get("preprint"), dict) else {}
        preprint_raw = preprint.get("raw") if isinstance(preprint.get("raw"), dict) else {}
        return [clean_text(category) for category in preprint_raw.get("categories") or [] if clean_text(category)]
    raw = raw if raw is not None else parse_raw_json(paper)
    return [clean_text(category) for category in raw.get("categories") or [] if clean_text(category)]


def preprint_primary_category(paper: dict[str, Any], *, raw: dict[str, Any] | None = None) -> str:
    raw = raw if isinstance(raw, dict) else None
    if (paper.get("journal") or "").lower() != ARXIV_JOURNAL_NAME.lower():
        raw = raw if raw is not None else parse_raw_json(paper)
        preprint = raw.get("preprint") if isinstance(raw.get("preprint"), dict) else {}
        preprint_raw = preprint.get("raw") if isinstance(preprint.get("raw"), dict) else {}
        return clean_text(preprint_raw.get("primary_category") or "")
    raw = raw if raw is not None else parse_raw_json(paper)
    primary = clean_text(raw.get("primary_category") or "")
    categories = preprint_categories(paper, raw=raw)
    return primary or (categories[0] if categories else "")


def parse_raw_json(paper: dict[str, Any]) -> dict[str, Any]:
    try:
        raw = json.loads(paper.get("raw_json") or "{}")
    except (TypeError, json.JSONDecodeError):
        return {}
    return raw if isinstance(raw, dict) else {}


def paper_storage_mode(paper: dict[str, Any], *, merged_pdf: str = "", main_pdf: str = "", source_path: str = "") -> str:
    copy_mode = clean_text(paper.get("import_copy_mode") or paper.get("copy_mode") or "").lower()
    if copy_mode in {"copy", "link"}:
        return copy_mode
    if source_path and source_path in {merged_pdf, main_pdf}:
        return "link"
    return "local"


def parse_semantic_scholar_json(paper: dict[str, Any]) -> dict[str, Any]:
    try:
        raw = json.loads(paper.get("semantic_scholar_json") or "{}")
    except (TypeError, json.JSONDecodeError):
        return {}
    return raw if isinstance(raw, dict) else {}


def clean_author_name(value: str) -> str:
    value = " ".join(value.strip().split())
    return "" if value.lower() in {"none", "null"} else value


def dedup_names(names: list[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for name in names:
        key = name.lower()
        if key in seen:
            continue
        seen.add(key)
        result.append(name)
    return result


def start_fetch_progress(selected: str, journals: list[str]) -> None:
    with FETCH_PROGRESS_LOCK:
        FETCH_PROGRESS[fetch_progress_key("journal", selected)] = {
            "active": True,
            "kind": "journal",
            "completed": 0,
            "total": len(journals),
            "percent": 0,
            "currentJournal": "",
        }


def try_start_fetch(selected: str) -> bool:
    with FETCH_PROGRESS_LOCK:
        if selected in ACTIVE_FETCH_DATES:
            return False
        ACTIVE_FETCH_DATES.add(selected)
        return True


def finish_active_fetch(selected: str) -> None:
    with FETCH_PROGRESS_LOCK:
        ACTIVE_FETCH_DATES.discard(selected)


def is_fetch_active(selected: str) -> bool:
    with FETCH_PROGRESS_LOCK:
        return selected in ACTIVE_FETCH_DATES


def try_start_theme_fetch(selected: str) -> bool:
    with FETCH_PROGRESS_LOCK:
        if selected in ACTIVE_THEME_FETCH_DATES:
            return False
        ACTIVE_THEME_FETCH_DATES.add(selected)
        return True


def finish_theme_fetch(selected: str) -> None:
    with FETCH_PROGRESS_LOCK:
        ACTIVE_THEME_FETCH_DATES.discard(selected)


def is_theme_fetch_active(selected: str) -> bool:
    with FETCH_PROGRESS_LOCK:
        return selected in ACTIVE_THEME_FETCH_DATES


def update_fetch_progress(selected: str, *, journal: str, completed: int, total: int) -> None:
    percent = round((completed / total) * 100) if total else 100
    with FETCH_PROGRESS_LOCK:
        FETCH_PROGRESS[fetch_progress_key("journal", selected)] = {
            "active": True,
            "kind": "journal",
            "completed": completed,
            "total": total,
            "percent": percent,
            "currentJournal": journal,
        }


def finish_fetch_progress(selected: str) -> None:
    with FETCH_PROGRESS_LOCK:
        progress = FETCH_PROGRESS.get(fetch_progress_key("journal", selected))
        if not progress:
            return
        total = int(progress.get("total") or 0)
        progress.update(
            {
                "active": False,
                "completed": total,
                "percent": 100,
                "currentJournal": progress.get("currentJournal") or "",
            }
        )


def start_theme_fetch_progress(
    selected: str,
    group_keys: list[str],
    theme_groups: dict[str, dict[str, Any]],
    source_totals: dict[str, int] | None = None,
) -> None:
    subjects = []
    source_totals = source_totals or {}
    for key in group_keys:
        group = theme_groups.get(key) or {}
        subjects.append(
            {
                "key": key,
                "name": str(group.get("name") or key),
                "status": "pending",
                "records_found": 0,
                "raw_results": 0,
                "message": "",
                "current_source": "",
                "current_query": "",
                "source_completed": 0,
                "source_total": int(source_totals.get(key) or 0),
            }
        )
    with FETCH_PROGRESS_LOCK:
        FETCH_PROGRESS[fetch_progress_key("theme", selected)] = theme_fetch_progress_payload(subjects, active=True)


def update_theme_fetch_progress(
    selected: str,
    group_key: str,
    *,
    status: str,
    records_found: int | None = None,
    raw_results: int | None = None,
    message: str = "",
    current_source: str = "",
    current_query: str = "",
    source_completed: int | None = None,
    source_total: int | None = None,
) -> None:
    with FETCH_PROGRESS_LOCK:
        progress = FETCH_PROGRESS.get(fetch_progress_key("theme", selected))
        if not progress or progress.get("kind") != "theme":
            return
        subjects = [dict(item) for item in progress.get("subjects") or [] if isinstance(item, dict)]
        for item in subjects:
            if item.get("key") != group_key:
                continue
            item["status"] = status
            if records_found is not None:
                item["records_found"] = int(records_found or 0)
            if raw_results is not None:
                item["raw_results"] = int(raw_results or 0)
            item["message"] = message
            if current_source or status != "running":
                item["current_source"] = current_source
            if current_query or status != "running":
                item["current_query"] = current_query
            if source_completed is not None:
                item["source_completed"] = int(source_completed or 0)
            if source_total is not None:
                item["source_total"] = int(source_total or 0)
            break
        FETCH_PROGRESS[fetch_progress_key("theme", selected)] = theme_fetch_progress_payload(subjects, active=True)


def finish_theme_fetch_progress(selected: str) -> None:
    with FETCH_PROGRESS_LOCK:
        progress = FETCH_PROGRESS.get(fetch_progress_key("theme", selected))
        if not progress or progress.get("kind") != "theme":
            return
        subjects = [dict(item) for item in progress.get("subjects") or [] if isinstance(item, dict)]
        FETCH_PROGRESS[fetch_progress_key("theme", selected)] = theme_fetch_progress_payload(subjects, active=False)


def theme_fetch_progress_payload(subjects: list[dict[str, Any]], *, active: bool) -> dict[str, Any]:
    total = len(subjects)
    terminal_statuses = {"success", "empty", "partial", "deferred", "error", "waiting", "cooldown"}
    completed = sum(1 for item in subjects if item.get("status") in terminal_statuses)
    source_total = 0
    source_completed = 0
    for item in subjects:
        item_source_total = int(item.get("source_total") or 0)
        if item_source_total <= 0:
            continue
        source_total += item_source_total
        if item.get("status") in terminal_statuses:
            source_completed += item_source_total
        else:
            source_completed += max(0, min(item_source_total, int(item.get("source_completed") or 0)))
    percent = round((source_completed / source_total) * 100) if source_total else (round((completed / total) * 100) if total else 100)
    current = next((item.get("name") or "" for item in subjects if item.get("status") == "running"), "")
    running = next((item for item in subjects if item.get("status") == "running"), {})
    return {
        "active": active,
        "kind": "theme",
        "completed": completed,
        "total": total,
        "percent": percent,
        "currentSubject": current,
        "currentSource": running.get("current_source") or "",
        "currentQuery": running.get("current_query") or "",
        "sourceCompleted": source_completed,
        "sourceTotal": source_total,
        "subjects": subjects,
    }


def fetch_progress_key(kind: str, selected: str) -> str:
    normalized_kind = "theme" if kind == "theme" else "journal"
    return f"{normalized_kind}:{selected}"


def get_fetch_progress(selected: str, *, kind: str = "") -> dict[str, Any] | None:
    with FETCH_PROGRESS_LOCK:
        if kind in {"journal", "theme"}:
            progress = FETCH_PROGRESS.get(fetch_progress_key(kind, selected))
            return dict(progress) if progress else None
        progress = FETCH_PROGRESS.get(fetch_progress_key("journal", selected)) or FETCH_PROGRESS.get(fetch_progress_key("theme", selected))
        return dict(progress) if progress else None


def create_author_monitor_enrichment_job(
    *,
    author_monitor_id: int = 0,
    paper_id: str = "",
    force: bool = False,
    identifiers_only: bool = False,
    max_papers: int = 0,
    automatic: bool = False,
) -> str:
    job_id = uuid.uuid4().hex[:12]
    now = datetime.now().astimezone().isoformat(timespec="seconds")
    with AUTHOR_MONITOR_ENRICHMENT_JOBS_LOCK:
        AUTHOR_MONITOR_ENRICHMENT_JOBS[job_id] = {
            "job_id": job_id,
            "author_id": int(author_monitor_id or 0),
            "paper_id": clean_text(paper_id),
            "force": bool(force),
            "identifiers_only": bool(identifiers_only),
            "max_papers": max(0, int(max_papers or 0)),
            "automatic": bool(automatic),
            "status": "queued",
            "stage": "queued",
            "started_at": now,
            "finished_at": "",
            "current": 0,
            "total": 0,
            "percent": 0,
            "matched": 0,
            "enriched": 0,
            "unresolved": 0,
            "skipped": 0,
            "current_title": "",
            "priority_paper_ids": [],
            "errors": [],
        }
    return job_id


def get_author_monitor_enrichment_job(job_id: str | None) -> dict[str, Any] | None:
    if not job_id:
        return None
    with AUTHOR_MONITOR_ENRICHMENT_JOBS_LOCK:
        job = AUTHOR_MONITOR_ENRICHMENT_JOBS.get(job_id)
        return dict(job) if job else None


def active_author_monitor_enrichment_job(*, author_monitor_id: int = 0) -> dict[str, Any] | None:
    with AUTHOR_MONITOR_ENRICHMENT_JOBS_LOCK:
        for job in reversed(list(AUTHOR_MONITOR_ENRICHMENT_JOBS.values())):
            if job.get("status") not in {"queued", "running"}:
                continue
            # Identifier services are shared and rate limited, so Author Monitor
            # deliberately runs only one enrichment worker at a time.
            return dict(job)
    return None


def update_author_monitor_enrichment_job(job_id: str, **updates: Any) -> None:
    with AUTHOR_MONITOR_ENRICHMENT_JOBS_LOCK:
        job = AUTHOR_MONITOR_ENRICHMENT_JOBS.get(job_id)
        if job:
            job.update(updates)


def queue_author_monitor_enrichment_priority(job_id: str, paper_id: str) -> bool:
    target = clean_text(paper_id)
    if not target:
        return False
    with AUTHOR_MONITOR_ENRICHMENT_JOBS_LOCK:
        job = AUTHOR_MONITOR_ENRICHMENT_JOBS.get(job_id)
        if not job or job.get("status") not in {"queued", "running"}:
            return False
        queued = [
            clean_text(value)
            for value in job.get("priority_paper_ids") or []
            if clean_text(value)
        ]
        if target not in queued:
            queued.append(target)
        job["priority_paper_ids"] = queued
        return True


def take_author_monitor_enrichment_priorities(job_id: str) -> list[str]:
    with AUTHOR_MONITOR_ENRICHMENT_JOBS_LOCK:
        job = AUTHOR_MONITOR_ENRICHMENT_JOBS.get(job_id)
        if not job:
            return []
        queued = [
            clean_text(value)
            for value in job.get("priority_paper_ids") or []
            if clean_text(value)
        ]
        job["priority_paper_ids"] = []
        return queued


def author_monitor_enrichment_marker(paper: dict[str, Any]) -> dict[str, Any]:
    raw = parse_raw_json(paper)
    marker = raw.get("author_monitor_enrichment")
    return marker if isinstance(marker, dict) else {}


def author_monitor_enrichment_recently_attempted(paper: dict[str, Any]) -> bool:
    marker = author_monitor_enrichment_marker(paper)
    attempted_at = clean_text(marker.get("attempted_at") or "")
    if not attempted_at:
        return False
    try:
        attempted = datetime.fromisoformat(attempted_at)
    except ValueError:
        return False
    now = datetime.now(local_timezone())
    if attempted.tzinfo is None:
        attempted = attempted.replace(tzinfo=now.tzinfo)
    return now - attempted.astimezone(now.tzinfo) < timedelta(days=AUTHOR_MONITOR_ENRICHMENT_RETRY_DAYS)


def author_monitor_paper_needs_enrichment(paper: dict[str, Any]) -> bool:
    has_identifier = author_monitor_paper_has_identifier(paper)
    has_abstract = bool(clean_text(paper.get("abstract") or ""))
    return not has_identifier or not has_abstract


def author_monitor_paper_has_identifier(paper: dict[str, Any]) -> bool:
    return bool(
        looks_like_doi(normalize_publication_doi(str(paper.get("doi") or "")))
        or arxiv_identifier_for_paper(paper)
    )


def author_monitor_candidate_from_paper(paper: dict[str, Any]) -> dict[str, Any]:
    raw = parse_raw_json(paper)
    return {
        "paper": {
            "paper_id": paper.get("paper_id") or "",
            "title": paper.get("title") or "",
            "journal": paper.get("journal") or "",
            "publication_date": paper.get("publication_date") or "",
            "doi": paper.get("doi") or "",
            "url": paper.get("url") or paper.get("landing_url") or "",
            "landing_url": paper.get("landing_url") or paper.get("url") or "",
            "abstract": paper.get("abstract") or "",
            "raw": raw,
        },
        "raw": raw,
    }


def record_author_monitor_enrichment_attempt(
    storage: Storage,
    paper_id: str,
    paper: dict[str, Any],
    *,
    status: str,
    message: str = "",
    automatic: bool = False,
) -> dict[str, Any] | None:
    paper_id = storage.resolve_paper_id(paper_id)
    current = storage.get_paper(paper_id) or paper
    raw = parse_raw_json(current)
    attempts = author_metadata_work.attempt_count(current, sys.modules[__name__])
    raw["author_monitor_enrichment"] = {
        "status": status,
        "message": clean_text(message),
        "attempted_at": now_iso(),
        "automatic_attempts": attempts + int(automatic),
    }
    return storage.update_paper_raw_json(paper_id, raw)


def run_author_monitor_enrichment_job(
    *,
    job_id: str,
    db_path: Path,
    author_monitor_id: int = 0,
    paper_id: str = "",
    force: bool = False,
    identifiers_only: bool = False,
    max_papers: int = 0,
    paper_ids: list[str] | None = None,
    time_budget_seconds: float = 0,
) -> None:
    storage = Storage(db_path)
    matched = 0
    enriched = 0
    unresolved = 0
    skipped = 0
    errors: list[str] = []
    try:
        rows = ([paper for pid in paper_ids if (paper := storage.get_paper(pid))]
                if paper_ids is not None else storage.list_author_monitor_papers(int(author_monitor_id or 0)))
        selected_paper_id = storage.resolve_paper_id(clean_text(paper_id))
        if selected_paper_id:
            rows = [
                paper for paper in rows
                if clean_text(paper.get("paper_id") or "") == selected_paper_id
            ]
        automatic = bool((get_author_monitor_enrichment_job(job_id) or {}).get("automatic"))
        pending = [
            paper for paper in rows
            if (
                (not author_monitor_paper_has_identifier(paper))
                if identifiers_only
                else author_monitor_paper_needs_enrichment(paper)
            )
            and (force or not author_monitor_enrichment_recently_attempted(paper))
            and (not automatic or author_metadata_work.attempt_count(paper, sys.modules[__name__]) < author_metadata_work.MAX_ATTEMPTS)
        ]
        if int(max_papers or 0) > 0:
            pending = pending[: int(max_papers)]
        skipped = len(rows) - len(pending)
        total = len(pending)
        row_by_id = {
            clean_text(item.get("paper_id") or ""): item
            for item in rows
            if clean_text(item.get("paper_id") or "")
        }
        work_queue = list(pending)
        processed_ids: set[str] = set()

        def promote_priority_requests() -> None:
            nonlocal total
            priority_ids = take_author_monitor_enrichment_priorities(job_id)
            for priority_id in reversed(priority_ids):
                if not priority_id or priority_id in processed_ids:
                    continue
                queued_index = next(
                    (
                        index
                        for index, item in enumerate(work_queue)
                        if clean_text(item.get("paper_id") or "") == priority_id
                    ),
                    -1,
                )
                if queued_index >= 0:
                    priority_paper = work_queue.pop(queued_index)
                else:
                    priority_paper = row_by_id.get(priority_id)
                if priority_paper and not author_monitor_paper_has_identifier(priority_paper):
                    work_queue.insert(0, priority_paper)
            total = max(total, len(processed_ids) + len(work_queue))

        update_author_monitor_enrichment_job(
            job_id,
            status="running",
            stage="identifiers",
            total=total,
            skipped=skipped,
        )
        index = 0
        started = time.monotonic()
        while True:
            if index and time_budget_seconds and time.monotonic() - started >= time_budget_seconds:
                break
            promote_priority_requests()
            if not work_queue:
                break
            paper = work_queue.pop(0)
            paper_id = storage.resolve_paper_id(clean_text(paper.get("paper_id") or ""))
            processed_ids = {storage.resolve_paper_id(pid) for pid in processed_ids}
            if not paper_id or paper_id in processed_ids:
                continue
            paper = storage.get_paper(paper_id) or paper
            processed_ids.add(paper_id)
            if automatic and not author_monitor_paper_needs_enrichment(paper):
                skipped += 1
                continue  # A concurrent explicit refresh already completed it.
            index += 1
            title = clean_text(paper.get("title") or paper_id or "Untitled paper")
            update_author_monitor_enrichment_job(
                job_id,
                current=index,
                total=total,
                current_title=title,
                percent=max(1, min(99, round((index - 1) / max(1, total) * 100))),
            )
            try:
                doi = normalize_publication_doi(str(paper.get("doi") or ""))
                arxiv_id = arxiv_identifier_for_paper(paper)
                normalized: dict[str, Any] | None = None
                if looks_like_doi(doi):
                    normalized = publication_metrics_metadata_from_doi(doi, timeout=12, max_retries=1)
                elif arxiv_id:
                    normalized = publication_metrics_metadata_from_arxiv_id(arxiv_id, timeout=12, max_retries=1)
                else:
                    normalized = resolve_google_scholar_candidate_to_identifier(
                        author_monitor_candidate_from_paper(paper)
                    )
                    if normalized and looks_like_doi(normalize_publication_doi(str(normalized.get("doi") or ""))):
                        resolved_doi = normalize_publication_doi(str(normalized.get("doi") or ""))
                        richer = publication_metrics_metadata_from_doi(resolved_doi, timeout=12, max_retries=1)
                        normalized = richer or normalized
                if normalized:
                    matched += 1
                    merged = merge_refreshed_metadata(paper, normalized)
                    updated = storage.refresh_paper_metadata(paper_id, merged) or paper
                    updated_doi = normalize_publication_doi(str(updated.get("doi") or ""))
                    if doi_is_likely_published_version(updated_doi):
                        updated = refresh_pubmed_if_possible(
                            storage,
                            updated,
                            doi=updated_doi,
                            timeout=12,
                            max_retries=1,
                        ) or updated
                    if clean_text(updated.get("abstract") or ""):
                        enriched += 1
                    record_author_monitor_enrichment_attempt(
                        storage,
                        paper_id,
                        updated,
                        status="complete",
                        message="Identifier metadata refreshed",
                        automatic=automatic,
                    )
                else:
                    unresolved += 1
                    record_author_monitor_enrichment_attempt(
                        storage,
                        paper_id,
                        paper,
                        status="unresolved",
                        message="No confident DOI or arXiv match",
                        automatic=automatic,
                    )
            except Exception as exc:
                unresolved += 1
                if len(errors) < 8:
                    errors.append(f"{title}: {exc}")
                record_author_monitor_enrichment_attempt(
                    storage,
                    paper_id,
                    paper,
                    status="error",
                    message=str(exc),
                    automatic=automatic,
                )
            update_author_monitor_enrichment_job(
                job_id,
                current=index,
                percent=max(1, min(99, round(index / max(1, total) * 100))),
                matched=matched,
                enriched=enriched,
                unresolved=unresolved,
                skipped=skipped,
                errors=list(errors),
            )
            promote_priority_requests()
            if work_queue:
                time.sleep(AUTHOR_MONITOR_ENRICHMENT_REQUEST_PAUSE_SECONDS)
        total = index
        update_author_monitor_enrichment_job(
            job_id,
            status="completed",
            stage="completed",
            current=total,
            total=total,
            percent=100,
            matched=matched,
            enriched=enriched,
            unresolved=unresolved,
            skipped=skipped,
            errors=list(errors),
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    except Exception as exc:
        update_author_monitor_enrichment_job(
            job_id,
            status="failed",
            stage="failed",
            errors=[str(exc)],
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    finally:
        storage.close()


def create_my_publication_metrics_job() -> str:
    job_id = uuid.uuid4().hex[:12]
    now = datetime.now().astimezone().isoformat(timespec="seconds")
    with MY_PUBLICATION_METRICS_JOBS_LOCK:
        MY_PUBLICATION_METRICS_JOBS[job_id] = {
            "job_id": job_id,
            "status": "queued",
            "stage": "queued",
            "started_at": now,
            "finished_at": "",
            "current": 0,
            "total": 0,
            "percent": 0,
            "refreshed": 0,
            "skipped": 0,
            "current_title": "",
            "errors": [],
            "publications": [],
        }
    return job_id


def get_my_publication_metrics_job(job_id: str | None) -> dict[str, Any] | None:
    if not job_id:
        return None
    with MY_PUBLICATION_METRICS_JOBS_LOCK:
        job = MY_PUBLICATION_METRICS_JOBS.get(job_id)
        return dict(job) if job else None


def active_my_publication_metrics_job() -> dict[str, Any] | None:
    with MY_PUBLICATION_METRICS_JOBS_LOCK:
        for job in reversed(list(MY_PUBLICATION_METRICS_JOBS.values())):
            if job.get("status") in {"queued", "running"}:
                return dict(job)
    return None


def update_my_publication_metrics_job(job_id: str, **updates: Any) -> None:
    with MY_PUBLICATION_METRICS_JOBS_LOCK:
        job = MY_PUBLICATION_METRICS_JOBS.get(job_id)
        if job:
            job.update(updates)


def run_my_publication_metrics_job(*, job_id: str, db_path: Path) -> None:
    storage = Storage(db_path)
    refreshed = 0
    skipped = 0
    errors: list[str] = []
    try:
        all_publications = storage.list_my_publications()
        publications = [
            publication
            for publication in all_publications
            if clean_text(publication.get("paper_id") or "")
            and (
                looks_like_doi(normalize_publication_doi(str(publication.get("doi") or "")))
                or arxiv_identifier_for_paper(publication)
            )
        ]
        total = len(publications)
        update_my_publication_metrics_job(job_id, status="running", stage="metrics", total=total)
        if not total:
            skipped = len(all_publications)
        for index, publication in enumerate(publications, start=1):
            doi = normalize_publication_doi(str(publication.get("doi") or ""))
            paper_id = clean_text(publication.get("paper_id") or "")
            title = clean_text(publication.get("title") or doi)
            update_my_publication_metrics_job(
                job_id,
                current=index,
                current_title=title,
                percent=max(1, min(99, round((index - 1) / max(1, total) * 100))),
            )
            try:
                arxiv_id = arxiv_identifier_for_paper(publication)
                if looks_like_doi(doi):
                    normalized = publication_metrics_metadata_from_doi(doi, timeout=10, max_retries=1)
                else:
                    normalized = publication_metrics_metadata_from_arxiv_id(arxiv_id, timeout=10, max_retries=1)
                updated = storage.refresh_paper_metadata(paper_id, merge_refreshed_metadata(publication, normalized)) if normalized else publication
                pubmed_doi = normalize_publication_doi(str((updated or {}).get("doi") or doi))
                pubmed_enriched = False
                if pubmed_doi and looks_like_doi(pubmed_doi):
                    before_pubmed = parse_raw_json(updated or {})
                    updated = refresh_pubmed_if_possible(
                        storage,
                        updated,
                        doi=pubmed_doi,
                        timeout=12,
                        max_retries=1,
                        sync_author_marks=False,
                    ) or updated
                    after_pubmed = parse_raw_json(updated or {})
                    pubmed_enriched = bool(after_pubmed.get("pubmed")) and after_pubmed.get("pubmed") != before_pubmed.get("pubmed")
                    updated = storage.get_paper(paper_id) or updated
                enriched = refresh_semantic_scholar_if_possible(storage, updated, timeout=6, max_retries=1)
                ads_enriched = refresh_ads_if_possible(storage, enriched or updated, timeout=6, max_retries=1)
                final_paper = ads_enriched or enriched or updated
                final_raw = parse_raw_json(final_paper or {})
                final_pubmed_doi = normalize_publication_doi(
                    str((final_paper or {}).get("doi") or final_raw.get("published_doi") or final_raw.get("doi") or doi)
                )
                if final_pubmed_doi and looks_like_doi(final_pubmed_doi) and not final_raw.get("pubmed"):
                    final_paper = refresh_pubmed_if_possible(
                        storage,
                        final_paper,
                        doi=final_pubmed_doi,
                        timeout=12,
                        max_retries=1,
                        sync_author_marks=False,
                    ) or final_paper
                    pubmed_enriched = bool(parse_raw_json(final_paper or {}).get("pubmed"))
                if normalized or pubmed_enriched or (enriched and enriched.get("semantic_scholar_json")) or (ads_enriched and ads_summary(ads_enriched)):
                    refreshed += 1
                else:
                    skipped += 1
            except Exception as exc:
                skipped += 1
                if len(errors) < 8:
                    errors.append(f"{title}: {exc}")
            update_my_publication_metrics_job(
                job_id,
                current=index,
                percent=max(1, min(99, round(index / max(1, total) * 100))),
                refreshed=refreshed,
                skipped=skipped,
                errors=list(errors),
            )
        api_rows = [my_publication_to_api(row) for row in storage.list_my_publications()]
        update_my_publication_metrics_job(
            job_id,
            status="completed",
            stage="completed",
            current=total,
            percent=100,
            refreshed=refreshed,
            skipped=skipped,
            errors=list(errors),
            publications=api_rows,
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    except Exception as exc:
        update_my_publication_metrics_job(
            job_id,
            status="failed",
            stage="failed",
            errors=[str(exc)],
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    finally:
        storage.close()


def create_library_import_job(
    *,
    folder_path: Path,
    copy_mode: str,
    source_paths: list[Path] | None = None,
    local_copy_plan: dict[str, Any] | None = None,
    target_folder_id: int = 1,
    preserve_top_level: bool = False,
    metadata_mode: str = "quick",
) -> str:
    job_id = uuid.uuid4().hex[:12]
    now = datetime.now().astimezone().isoformat(timespec="seconds")
    import_paths = source_paths or [folder_path]
    with LIBRARY_IMPORT_JOBS_LOCK:
        LIBRARY_IMPORT_JOBS[job_id] = {
            "job_id": job_id,
            "status": "queued",
            "stage": "queued",
            "folder_path": str(folder_path),
            "source_paths": [str(path) for path in import_paths],
            "target_folder_id": int(target_folder_id or 1),
            "preserve_top_level": bool(preserve_top_level),
            "metadata_mode": normalize_import_metadata_mode(metadata_mode),
            "copy_mode": copy_mode,
            "dry_run": False,
            "started_at": now,
            "finished_at": "",
            "current": 0,
            "total": 0,
            "percent": 0,
            "logs": [{"time": now, "level": "info", "message": "Queued loader job"}],
            "result": None,
            "inventory_path": "",
            "error": "",
            "cancel_requested": False,
            "library_ready": False,
            "local_copy_plan": local_copy_plan or {},
            "scan_files": 0,
            "scan_dirs": 0,
        }
    return job_id


def create_library_metadata_refresh_job(*, metadata_mode: str = "full", skip_days: int = 3) -> str:
    job_id = uuid.uuid4().hex[:12]
    now = datetime.now().astimezone().isoformat(timespec="seconds")
    with LIBRARY_IMPORT_JOBS_LOCK:
        LIBRARY_IMPORT_JOBS[job_id] = {
            "job_id": job_id,
            "job_type": "metadata_refresh",
            "status": "queued",
            "stage": "queued",
            "metadata_mode": normalize_metadata_refresh_mode(metadata_mode),
            "skip_days": int(skip_days),
            "started_at": now,
            "finished_at": "",
            "current": 0,
            "total": 0,
            "percent": 0,
            "logs": [{"time": now, "level": "info", "message": "Queued metadata refresh job"}],
            "result": None,
            "error": "",
            "cancel_requested": False,
            "library_ready": True,
        }
    return job_id


def create_library_identifier_recovery_job(*, skip_days: int = 7) -> str:
    job_id = uuid.uuid4().hex[:12]
    now = datetime.now().astimezone().isoformat(timespec="seconds")
    with LIBRARY_IMPORT_JOBS_LOCK:
        LIBRARY_IMPORT_JOBS[job_id] = {
            "job_id": job_id,
            "job_type": "identifier_recovery",
            "status": "queued",
            "stage": "queued",
            "skip_days": int(skip_days),
            "started_at": now,
            "finished_at": "",
            "current": 0,
            "total": 0,
            "percent": 0,
            "logs": [{"time": now, "level": "info", "message": "Queued missing identifier job"}],
            "result": None,
            "error": "",
            "cancel_requested": False,
            "library_ready": True,
        }
    return job_id


def get_library_import_job(job_id: str | None) -> dict[str, Any] | None:
    if not job_id:
        return None
    with LIBRARY_IMPORT_JOBS_LOCK:
        job = LIBRARY_IMPORT_JOBS.get(job_id)
        if not job:
            return None
        result = job.get("result")
        if isinstance(result, dict) and result.get("report_path") and "missing_sources" not in result:
            report = load_import_report_summary(result.get("report_path"))
            if report:
                job["result"] = report
        snapshot = dict(job)
        snapshot["logs"] = list(job.get("logs") or [])[-20000:]
        return snapshot


def update_library_import_job(job_id: str, **updates: Any) -> None:
    with LIBRARY_IMPORT_JOBS_LOCK:
        job = LIBRARY_IMPORT_JOBS.get(job_id)
        if not job:
            return
        job.update(updates)


def request_stop_library_import_job(job_id: str, *, storage: Storage | None = None) -> dict[str, Any] | None:
    with LIBRARY_IMPORT_JOBS_LOCK:
        job = LIBRARY_IMPORT_JOBS.get(job_id)
        if not job:
            return None
        if job.get("status") not in {"completed", "failed", "cancelled", "deleted"}:
            job["cancel_requested"] = True
            job["status"] = "stopping"
            job["stage"] = "stopping"
        snapshot = dict(job)
        snapshot["logs"] = list(job.get("logs") or [])[-300:]
    # Stop the durable child as well, including during an in-flight lookup.
    # Otherwise Stop Import leaves an orphaned paused Refresh Info task.
    refresh_id = snapshot.get("metadata_job_id")
    if storage is not None and refresh_id and snapshot.get("cancel_requested"):
        metadata_jobs.control(storage, refresh_id, "stop")
    label = {
        "metadata_refresh": "metadata refresh",
        "identifier_recovery": "identifier recovery",
    }.get(job.get("job_type"), "loader")
    log_library_import_job(job_id, f"Stop requested. The {label} will stop at the next safe checkpoint.", level="warn")
    return get_library_import_job(job_id)


def library_import_cancel_requested(job_id: str) -> bool:
    with LIBRARY_IMPORT_JOBS_LOCK:
        job = LIBRARY_IMPORT_JOBS.get(job_id)
        return bool(job and job.get("cancel_requested"))


def log_library_import_job(job_id: str, message: str, *, level: str = "info", paper_id: str | None = None,
                           library_item_id: int | None = None) -> None:
    stamp = datetime.now().astimezone().isoformat(timespec="seconds")
    with LIBRARY_IMPORT_JOBS_LOCK:
        job = LIBRARY_IMPORT_JOBS.get(job_id)
        if not job:
            return
        logs = job.setdefault("logs", [])
        entry = {"time": stamp, "level": level, "message": message}
        if paper_id:
            entry["paper_id"] = str(paper_id)
            if library_item_id:
                entry["library_item_id"] = int(library_item_id)
        logs.append(entry)
        if len(logs) > 20000:
            del logs[:-20000]


def library_import_progress_callback(job_id: str):
    def progress(event: dict[str, Any]) -> None:
        if library_import_cancel_requested(job_id):
            raise ImportCancelled("Import stopped by user")
        current = event.get("current")
        total = event.get("total")
        percent = 0
        if isinstance(current, int) and isinstance(total, int) and total > 0:
            percent = max(0, min(100, round((current / total) * 100)))
        updates = {
            "stage": event.get("stage") or "running",
            "current": current or 0,
            "total": total or 0,
            "percent": percent,
        }
        message = clean_text(event.get("message"))
        if event.get("stage") == "import" and message == "Import complete":
            updates["library_ready"] = True
        if event.get("stage") == "scan":
            updates["scan_files"] = int(event.get("files_scanned") or 0)
            updates["scan_dirs"] = int(event.get("directories_scanned") or 0)
        update_library_import_job(job_id, **updates)
        if message:
            log_library_import_job(job_id, message, paper_id=event.get("paper_id"), library_item_id=event.get("library_item_id"))

    return progress


def library_loader_copy_plan(
    storage: Storage,
    *,
    source_folder: Path,
    timestamp: str,
    slug: str,
    source_paths: list[Path] | None = None,
    target_folder_id: int = 1,
    preserve_top_level: bool = False,
) -> dict[str, Any]:
    target_folder_id = int(target_folder_id or 1)
    base_root = local_copy_dir_for_library_folder(storage, target_folder_id).resolve()
    paths = [path.expanduser().resolve() for path in (source_paths or [source_folder])]
    source_root = str(source_folder.expanduser().resolve())
    previous_batches = int(
        storage.conn.execute(
            """
            SELECT COUNT(*) AS count
            FROM inventory_import_batches
            WHERE source_root = ?
              AND COALESCE(status, '') != 'deleted'
            """,
            (source_root,),
        ).fetchone()["count"]
        or 0
    )
    copied_files = 0
    for path in paths:
        path_text_value = str(path)
        path_prefix = path_text_value.rstrip("/") + "/%"
        copied_files += int(
            storage.conn.execute(
                """
                SELECT COUNT(*) AS count
                FROM resources
                WHERE (source_path = ? OR source_path LIKE ?)
                  AND stored_path IS NOT NULL
                  AND stored_path != ''
                  AND stored_path != source_path
                """,
                (path_text_value, path_prefix),
            ).fetchone()["count"]
            or 0
        )
    target = base_root
    action = "reuse" if previous_batches or copied_files else "new"
    target_folder = storage.get_library_folder(target_folder_id) or {}
    target_name = str(target_folder.get("name") or "Library")
    target_library_path = library_folder_path_label(storage, target_folder_id)
    imported_label = "dropped item" if preserve_top_level and len(paths) == 1 else ("dropped items" if preserve_top_level else "source folder")
    return {
        "source_root": source_root,
        "source_paths": [str(path) for path in paths],
        "copy_target_root": str(target),
        "target_folder_id": target_folder_id,
        "target_folder_name": target_name,
        "target_library_path": target_library_path,
        "preserve_top_level": bool(preserve_top_level),
        "action": action,
        "previous_batches": previous_batches,
        "copied_files": copied_files,
        "message": (
            f"This {imported_label} was loaded before. New files will be merged into the selected Library folder."
            if action == "reuse"
            else f"This import will copy the {imported_label} into the selected Library folder."
        ),
        "finder_behavior": (
            "Existing local copies are reused and not overwritten; newly readable files are copied into matching relative paths under the selected Library folder."
            if action == "reuse"
            else "Files are copied under the selected Library folder while preserving the dragged file/folder structure."
        ),
    }


def library_folder_path_label(storage: Storage, folder_id: int) -> str:
    parts: list[str] = []
    current = storage.get_library_folder(int(folder_id or 1))
    guard = 0
    while current and guard < 80:
        guard += 1
        parts.append(str(current.get("name") or "Library"))
        if current.get("parent_id") is None:
            break
        current = storage.get_library_folder(int(current.get("parent_id") or 0))
    if not parts:
        return "Library"
    return " / ".join(reversed(parts))


def resolve_library_loader_copy_target_root(storage: Storage, *, source_folder: Path, timestamp: str, slug: str) -> Path:
    plan = library_loader_copy_plan(storage, source_folder=source_folder, timestamp=timestamp, slug=slug)
    return Path(str(plan.get("copy_target_root") or ""))


def safe_inventory_path_parts(value: str) -> list[str]:
    parts = []
    for part in Path(value or "").parts:
        if part in {"", ".", ".."}:
            continue
        parts.append(part)
    return parts


def read_gewu_complete_export_manifest(source_root: Path) -> dict[str, Any] | None:
    manifest_path = source_root.expanduser().resolve() / "Gewu Insight Manifest.json"
    if not manifest_path.is_file():
        return None
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(manifest, dict):
        return None
    if manifest.get("format") != "Gewu Insight Complete Folder Export":
        return None
    if int(manifest.get("format_version") or 0) != 1 or not isinstance(manifest.get("items"), list):
        return None
    return manifest


def path_from_export_manifest(source_root: Path, value: str) -> Path | None:
    relative = Path(str(value or ""))
    if not str(relative) or relative.is_absolute() or ".." in relative.parts:
        return None
    root = source_root.expanduser().resolve()
    candidate = (root / relative).resolve()
    try:
        candidate.relative_to(root)
    except ValueError:
        return None
    return candidate


def filter_complete_export_inventory(
    inventory_path: Path,
    *,
    source_root: Path,
    manifest: dict[str, Any],
) -> None:
    data = json.loads(inventory_path.read_text(encoding="utf-8"))
    files = data.get("files") if isinstance(data, dict) else None
    if not isinstance(files, list):
        raise ValueError("Generated inventory has no files list")
    associated_root = (source_root.expanduser().resolve() / "Associated Files").resolve()
    manifest_path = (source_root.expanduser().resolve() / "Gewu Insight Manifest.json").resolve()
    filtered: list[Any] = []
    for record in files:
        if not isinstance(record, dict):
            filtered.append(record)
            continue
        raw_path = clean_text(record.get("path") or "")
        try:
            candidate = Path(raw_path).expanduser().resolve()
        except OSError:
            filtered.append(record)
            continue
        if candidate == manifest_path:
            continue
        try:
            candidate.relative_to(associated_root)
            continue
        except ValueError:
            filtered.append(record)
    data["files"] = filtered
    summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
    summary["file_count"] = len(filtered)
    summary["gewu_complete_export"] = True
    data["summary"] = summary
    inventory_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def restore_complete_export_associations(
    storage: Storage,
    *,
    source_root: Path,
    manifest: dict[str, Any],
) -> dict[str, int]:
    restored = 0
    reused = 0
    missing = 0
    paper_ids: set[str] = set()
    for item in manifest.get("items") or []:
        if not isinstance(item, dict):
            continue
        primary_source = path_from_export_manifest(source_root, str(item.get("primary_file") or ""))
        if not primary_source:
            missing += 1
            continue
        row = storage.conn.execute(
            """
            SELECT paper_id FROM resources
            WHERE source_path IN (?, ?)
            ORDER BY id DESC LIMIT 1
            """,
            (str(primary_source), str(primary_source.absolute())),
        ).fetchone()
        paper_id = str(row["paper_id"] or "") if row else ""
        if not paper_id:
            missing += 1
            continue
        paper_ids.add(paper_id)
        for resource in item.get("resources") or []:
            if not isinstance(resource, dict):
                continue
            if resource.get("is_primary"):
                primary = storage.ensure_primary_pdf_resource(paper_id)
                if primary:
                    storage.conn.execute(
                        """
                        UPDATE resources
                        SET file_role = ?, version_role = ?, version_label = ?,
                            sha256 = COALESCE(NULLIF(?, ''), sha256), updated_at = ?
                        WHERE id = ?
                        """,
                        (
                            clean_text(resource.get("file_role") or "publication_version"),
                            clean_text(resource.get("version_role") or "other"),
                            clean_text(resource.get("version_label") or ""),
                            clean_text(resource.get("sha256") or ""),
                            now_iso(),
                            int(primary.get("id") or 0),
                        ),
                    )
                    storage.conn.commit()
                continue
            source = path_from_export_manifest(source_root, str(resource.get("file") or ""))
            if not source or not source.is_file():
                missing += 1
                continue
            added = attach_file_to_paper(
                storage,
                paper_id=paper_id,
                filename=source.name,
                content=source.read_bytes(),
                file_role=clean_text(resource.get("file_role") or "other"),
                version_role=clean_text(resource.get("version_role") or ""),
                version_label=clean_text(resource.get("version_label") or ""),
                added_via="complete_export_restore",
            )
            if added.get("duplicate"):
                reused += 1
            else:
                restored += 1
    for paper_id in paper_ids:
        storage.resolve_primary_paper_resource(paper_id)
    return {"restored": restored, "reused": reused, "missing": missing}


def run_library_import_job(
    *,
    job_id: str,
    folder_path: Path,
    source_paths: list[Path] | None = None,
    copy_mode: str,
    db_path: Path,
    timestamp: str | None = None,
    slug: str | None = None,
    copy_plan: dict[str, Any] | None = None,
    target_folder_id: int = 1,
    preserve_top_level: bool = False,
    metadata_mode: str = "quick",
) -> None:
    timestamp = timestamp or datetime.now().strftime("%Y%m%d-%H%M%S")
    slug = slug or safe_slug(folder_path.name or "library-folder", 60)
    source_paths = source_paths or [folder_path]
    metadata_mode = normalize_import_metadata_mode(metadata_mode)
    import_prefix = "finder-drop" if preserve_top_level else "folder"
    result = None
    inventory_path = ROOT / "reports" / "imports" / f"{import_prefix}-inventory-{slug}-{timestamp}.json"
    report_path = ROOT / "reports" / "imports" / f"{import_prefix}-import-{slug}-import-{timestamp}.json"
    progress = library_import_progress_callback(job_id)
    complete_export_manifest = (
        read_gewu_complete_export_manifest(folder_path)
        if folder_path.expanduser().is_dir()
        else None
    )
    update_library_import_job(job_id, status="running", stage="scan", inventory_path=str(inventory_path))
    if preserve_top_level:
        log_library_import_job(job_id, f"Source paths: {', '.join(str(path) for path in source_paths)}")
    else:
        log_library_import_job(job_id, f"Source folder: {folder_path}")
    log_library_import_job(job_id, f"Mode: import / {copy_mode}")
    log_library_import_job(job_id, f"Metadata mode: {metadata_mode}")
    try:
        if not copy_plan:
            storage = Storage(db_path)
            try:
                copy_plan = library_loader_copy_plan(
                    storage,
                    source_folder=folder_path,
                    timestamp=timestamp,
                    slug=slug,
                    source_paths=source_paths,
                    target_folder_id=target_folder_id,
                    preserve_top_level=preserve_top_level,
                )
            finally:
                storage.close()
        update_library_import_job(job_id, local_copy_plan=copy_plan)
        log_library_import_job(job_id, f"Local copy plan: {copy_plan.get('message')} Target: {copy_plan.get('copy_target_root')}")
        if copy_plan.get("target_library_path"):
            log_library_import_job(job_id, f"Target Library path: {copy_plan.get('target_library_path')}")
        if preserve_top_level:
            build_inventory_from_paths(
                source_paths,
                output_path=inventory_path,
                parse_pdfs=True,
                preserve_top_level=True,
                progress_callback=progress,
            )
        else:
            build_inventory_from_folder(folder_path, output_path=inventory_path, parse_pdfs=True, progress_callback=progress)
        if complete_export_manifest:
            filter_complete_export_inventory(
                inventory_path,
                source_root=folder_path,
                manifest=complete_export_manifest,
            )
            log_library_import_job(
                job_id,
                "Verified Gewu complete-export manifest; Associated Files will be restored after the visible folder structure.",
            )
        log_library_import_job(job_id, f"Inventory written: {inventory_path}")
        storage = Storage(db_path)
        try:
            target_root_text = str(copy_plan.get("copy_target_root") or "")
            target_root = Path(target_root_text) if target_root_text else resolve_library_loader_copy_target_root(storage, source_folder=folder_path, timestamp=timestamp, slug=slug)
            log_library_import_job(job_id, f"Local copy folder: {target_root}")
            result = import_library_inventory(
                inventory_path,
                copy_mode=copy_mode,
                preserve_folders=True,
                dedupe_by=("doi", "arxiv", "path"),
                dry_run=False,
                storage=storage,
                report_path=report_path,
                target_root=target_root,
                library_item_name="filename",
                library_root_folder_id=target_folder_id,
                progress_callback=progress,
            )
            if complete_export_manifest and not result.get("errors"):
                restored = restore_complete_export_associations(
                    storage,
                    source_root=folder_path,
                    manifest=complete_export_manifest,
                )
                result["complete_export_associated_restored"] = restored["restored"]
                result["complete_export_associated_reused"] = restored["reused"]
                result["complete_export_associated_missing"] = restored["missing"]
                log_library_import_job(
                    job_id,
                    (
                        f"Restored complete-export associations: {restored['restored']} copied, "
                        f"{restored['reused']} reused, {restored['missing']} missing."
                    ),
                )
            refreshed = refresh_imported_doi_metadata(storage, result, job_id=job_id, mode=metadata_mode)
            if refreshed:
                log_library_import_job(job_id, f"Refreshed DOI/arXiv metadata for {refreshed} imported papers")
        finally:
            storage.close()
        if copy_plan:
            result.setdefault("copy_target_root", copy_plan.get("copy_target_root"))
            result.setdefault("target_folder_id", copy_plan.get("target_folder_id"))
            result.setdefault("target_folder_name", copy_plan.get("target_folder_name"))
            result.setdefault("target_library_path", copy_plan.get("target_library_path"))
        result.setdefault("metadata_mode", metadata_mode)
        summary = summarize_import_result(result)
        level = "error" if summary.get("errors") else "info"
        log_library_import_job(job_id, f"Report written: {summary.get('report_path') or report_path}", level=level)
        log_library_import_job(
            job_id,
            (
                f"Done: {summary.get('created_papers', 0)} created, "
                f"{summary.get('existing_papers', 0)} existing matched, "
                f"{summary.get('updated_papers', 0)} updated, "
                f"{summary.get('library_items_created', 0)} library items created/restored, "
                f"{summary.get('pdf_doi_extracted_count', 0)} DOI found, "
                f"{summary.get('pdf_doi_missing_count', 0)} no DOI, "
                f"{summary.get('identifiers_recovered', 0)} identifiers recovered by title, "
                f"{summary.get('doi_metadata_refreshed', 0)} DOI/arXiv metadata refreshed, "
                f"{summary.get('resources_or_attachments_to_import', 0)} resources/attachments, "
                f"{summary.get('reused_existing_files', 0)} reused, "
                f"{summary.get('skipped', 0)} skipped"
            ),
            level=level,
        )
        update_library_import_job(
            job_id,
            status="failed" if summary.get("errors") else "completed",
            stage="complete",
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
            percent=(min(100, round(100 * int(summary.get("processed_files") or 0) / max(1, int(summary.get("total_files") or 0)))) if summary.get("errors") else 100),
            result=summary,
        )
    except ImportCancelled as exc:
        log_library_import_job(job_id, str(exc) or "Import stopped by user", level="warn")
        # Metadata may have been stopped after the files were fully imported.
        # Keep that result available in Details; Stop never deletes the batch.
        if result is not None:
            update_library_import_job(job_id, result=summarize_import_result(result))
        update_library_import_job(
            job_id,
            status="cancelled",
            stage="cancelled",
            error=str(exc),
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )
    except Exception as exc:
        log_library_import_job(job_id, f"Loader failed: {exc}", level="error")
        update_library_import_job(
            job_id,
            status="failed",
            stage="failed",
            error=str(exc),
            finished_at=datetime.now().astimezone().isoformat(timespec="seconds"),
        )


def load_import_report_summary(report_path: Any) -> dict[str, Any] | None:
    try:
        path = Path(str(report_path or "")).expanduser().resolve()
        imports_root = (ROOT / "reports" / "imports").resolve()
        if not is_allowed_file(path, [imports_root]) or not path.exists():
            return None
        data = json.loads(path.read_text(encoding="utf-8"))
        return summarize_import_result(data) if isinstance(data, dict) else None
    except Exception:
        return None


def load_library_import_report(report_path: Any) -> dict[str, Any]:
    path_text = str(report_path or "").strip()
    if not path_text:
        raise ValueError("Report path is required")
    try:
        path = Path(path_text).expanduser().resolve()
    except OSError as exc:
        raise ValueError(f"Could not resolve report path: {exc}") from exc
    imports_root = (ROOT / "reports" / "imports").resolve()
    if not is_allowed_file(path, [imports_root]):
        raise ValueError("Loader reports must be inside reports/imports")
    if not path.exists() or not path.is_file():
        raise ValueError("Loader report file was not found")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise ValueError(f"Could not read loader report JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise ValueError("Loader report JSON is invalid")
    result = summarize_import_result(data)
    result["report_path"] = str(path)
    if not result.get("source_root"):
        inventory_summary = data.get("inventory_summary") if isinstance(data.get("inventory_summary"), dict) else {}
        if inventory_summary.get("root"):
            result["source_root"] = str(inventory_summary.get("root") or "")
    return result


def list_library_import_reports(*, limit: int = 80) -> list[dict[str, Any]]:
    imports_root = (ROOT / "reports" / "imports").resolve()
    if not imports_root.exists():
        return []
    candidates: list[Path] = []
    for pattern in ("folder-import-*-import-*.json", "finder-drop-import-*.json", "inventory-import-*.json"):
        candidates.extend(path for path in imports_root.glob(pattern) if path.is_file())
    unique_candidates = sorted({path.resolve() for path in candidates}, key=lambda path: path.stat().st_mtime, reverse=True)
    reports: list[dict[str, Any]] = []
    for path in unique_candidates[: max(1, limit * 3)]:
        try:
            result = load_library_import_report(path)
        except ValueError:
            continue
        stat = path.stat()
        label = library_import_report_label(path, result)
        reports.append(
            {
                "path": str(path),
                "label": label,
                "mtime": int(stat.st_mtime),
                "source_root": result.get("source_root") or "",
                "created_papers": result.get("created_papers") or 0,
                "existing_papers": result.get("existing_papers") or 0,
                "missing_source_files": result.get("missing_source_files") or 0,
                "pdf_doi_missing_count": result.get("pdf_doi_missing_count") or 0,
            }
        )
        if len(reports) >= limit:
            break
    return reports


def library_import_report_label(path: Path, result: dict[str, Any]) -> str:
    source_root = str(result.get("source_root") or "")
    source_name = Path(source_root).name if source_root else ""
    stem = path.stem
    match = re.search(r"(\d{8}-\d{6})", stem)
    stamp = match.group(1) if match else datetime.fromtimestamp(path.stat().st_mtime).strftime("%Y%m%d-%H%M%S")
    created = int(result.get("created_papers") or 0)
    existing = int(result.get("existing_papers") or 0)
    missing = int(result.get("missing_source_files") or 0)
    bits = [stamp]
    if source_name:
        bits.append(source_name)
    bits.append(f"{created} created")
    bits.append(f"{existing} existing")
    if missing:
        bits.append(f"{missing} missing")
    return " · ".join(bits)


def delete_library_import_job_data(storage: Storage, job_id: str) -> dict[str, Any]:
    job = get_library_import_job(job_id)
    if not job:
        job = {
            "job_id": "",
            "status": "failed",
            "stage": "failed",
            "inventory_path": "",
            "result": {},
        }
    if job.get("status") not in {"completed", "failed", "cancelled", "deleted"}:
        raise ValueError("Stop the import before deleting it.")
    result = job.get("result") if isinstance(job.get("result"), dict) else {}
    batch_id = clean_text(result.get("import_batch_id"))
    batch = None
    if batch_id:
        batch = storage.conn.execute("SELECT * FROM inventory_import_batches WHERE id = ?", (batch_id,)).fetchone()
    if not batch:
        batch = storage.conn.execute(
            "SELECT * FROM inventory_import_batches ORDER BY started_at DESC LIMIT 1"
        ).fetchone()
        batch_id = clean_text(batch["id"] if batch else "")
    if not batch_id:
        deleted_paths = []
        for path_value in [job.get("inventory_path"), result.get("report_path")]:
            path_text = clean_text(path_value)
            if delete_import_path(path_text, ROOT / "reports" / "imports"):
                deleted_paths.append(path_text)
        with LIBRARY_IMPORT_JOBS_LOCK:
            live_job = LIBRARY_IMPORT_JOBS.get(job_id)
            if live_job:
                live_job["status"] = "deleted"
                live_job["stage"] = "deleted"
                live_job["result"] = None
                live_job["cancel_requested"] = True
        log_library_import_job(job_id, "Deleted loader scan files", level="warn")
        return {
            "batch_id": "",
            "deleted_papers": 0,
            "deleted_resources": 0,
            "deleted_folders": 0,
            "deleted_paths": deleted_paths,
        }

    started_at = clean_text(batch["started_at"] if batch else "")
    paper_count = storage.conn.execute(
        "SELECT COUNT(*) AS count FROM papers WHERE import_batch_id = ?",
        (batch_id,),
    ).fetchone()["count"]
    resource_count = storage.conn.execute(
        "SELECT COUNT(*) AS count FROM resources WHERE import_batch_id = ?",
        (batch_id,),
    ).fetchone()["count"]
    resource_paths = [
        clean_text(row["stored_path"])
        for row in storage.conn.execute(
            """
            SELECT stored_path
            FROM resources
            WHERE import_batch_id = ?
              AND stored_path IS NOT NULL
              AND stored_path != ''
              AND stored_path != source_path
            """,
            (batch_id,),
        ).fetchall()
    ]
    removed_resources = [dict(row) for row in storage.conn.execute(
        "SELECT * FROM resources WHERE import_batch_id = ?", (batch_id,))]
    storage.conn.execute("DELETE FROM resources WHERE import_batch_id = ?", (batch_id,))
    # A file explicitly reassigned after import is no longer owned by this batch.
    # Preserve its destination paper, including destinations created by the batch.
    paper_count = storage.conn.execute(
        """DELETE FROM papers WHERE import_batch_id = ? AND NOT EXISTS
           (SELECT 1 FROM resources WHERE resources.paper_id = papers.paper_id)""",
        (batch_id,),
    ).rowcount
    storage.conn.execute("UPDATE papers SET import_batch_id = NULL WHERE import_batch_id = ?", (batch_id,))
    from .file_reassignment import _repair_source_pointers
    for resource in removed_resources:
        surviving_paper = storage.get_paper(resource.get("paper_id"))
        if surviving_paper:
            _repair_source_pointers(storage, surviving_paper, resource)
    storage.conn.execute("DELETE FROM inventory_import_batches WHERE id = ?", (batch_id,))
    deleted_folders = cleanup_empty_import_folders(storage, started_at)
    storage.conn.commit()

    # Reassigned files no longer belong to the import batch. Never trash a surviving
    # file, or an import directory that still contains one of those files.
    protected_paths = set()
    for row in storage.conn.execute("""SELECT stored_path, source_path FROM resources
        UNION ALL SELECT main_pdf_path, merged_pdf_path FROM papers
        UNION ALL SELECT source_path, analysis_path FROM papers"""):
        for value in row:
            if not value:
                continue
            try:
                path = Path(value).expanduser().resolve()
                protected_paths.update([str(path), *(str(parent) for parent in path.parents)])
            except (OSError, RuntimeError, ValueError):
                continue

    def trash_unreferenced_import_path(value, root):
        try:
            if value and str(Path(value).expanduser().resolve()) in protected_paths:
                return False
        except (OSError, RuntimeError, ValueError):
            return False
        return delete_import_path(value, root)

    deleted_paths: list[str] = []
    copy_target = str(result.get("copy_target_root") or "") or str(DEFAULT_LIBRARY_IMPORT_DIR / batch_id)
    deletable_roots = [DEFAULT_LIBRARY_DIR, DEFAULT_SPACES_DIR, DEFAULT_MY_PUBLICATIONS_DIR, DEFAULT_LIBRARY_IMPORT_DIR]
    for path_value in resource_paths:
        for root in deletable_roots:
            if trash_unreferenced_import_path(path_value, root):
                deleted_paths.append(path_value)
                break
    try:
        copy_target_path = Path(copy_target).expanduser().resolve() if copy_target else None
    except OSError:
        copy_target_path = None
    protected_copy_roots = {str(root.resolve()) for root in deletable_roots}
    if copy_target_path and str(copy_target_path) not in protected_copy_roots:
        for root in deletable_roots:
            if trash_unreferenced_import_path(str(copy_target_path), root):
                deleted_paths.append(str(copy_target_path))
                break
    cleanup_local_copy_empty_parents(deleted_paths)
    for path_value in [job.get("inventory_path"), result.get("report_path")]:
        if delete_import_path(clean_text(path_value), ROOT / "reports" / "imports"):
            deleted_paths.append(clean_text(path_value))

    with LIBRARY_IMPORT_JOBS_LOCK:
        live_job = LIBRARY_IMPORT_JOBS.get(job_id)
        if live_job:
            live_job["status"] = "deleted"
            live_job["stage"] = "deleted"
            live_job["result"] = None
            live_job["cancel_requested"] = True
    log_library_import_job(job_id, f"Deleted import batch {batch_id}", level="warn")
    return {
        "batch_id": batch_id,
        "deleted_papers": int(paper_count or 0),
        "deleted_resources": int(resource_count or 0),
        "deleted_folders": deleted_folders,
        "deleted_paths": deleted_paths,
    }


def cleanup_empty_import_folders(storage: Storage, started_at: str) -> int:
    if not started_at:
        return 0
    deleted = 0
    while True:
        rows = storage.conn.execute(
            """
            SELECT folder.id
            FROM library_folders AS folder
            LEFT JOIN library_folders AS child ON child.parent_id = folder.id
            LEFT JOIN library_items AS item ON item.folder_id = folder.id
            WHERE folder.id NOT IN (1)
              AND folder.created_at >= ?
              AND child.id IS NULL
              AND item.id IS NULL
            """,
            (started_at,),
        ).fetchall()
        if not rows:
            return deleted
        for row in rows:
            storage.conn.execute("DELETE FROM library_folders WHERE id = ?", (int(row["id"]),))
            deleted += 1


def delete_import_path(path_value: str, allowed_root: Path) -> bool:
    if not path_value:
        return False
    try:
        path = Path(path_value).expanduser().resolve()
        root = allowed_root.resolve()
    except OSError:
        return False
    if not is_allowed_file(path, [root]) or not path.exists():
        return False
    if path == root:
        return False
    try:
        move_path_to_macos_trash(path)
        return True
    except OSError:
        return False


def missing_fetch_journals_for_date(storage: Storage, selected: str, journals: list[str]) -> list[str]:
    selected_date = date.fromisoformat(selected)
    if selected_date > today_local():
        return []
    if not journals:
        return []
    placeholders = ", ".join(["?"] * len(journals))
    rows = storage.conn.execute(
        f"""
        SELECT journal, source, status, records_found, timezone_name, started_at, finished_at
        FROM fetch_runs
        WHERE monitor_type = 'journal'
          AND window_start <= ?
          AND window_end >= ?
          AND status IN ('success', 'empty', 'error', 'running')
          AND source IN ('journal', 'arxiv')
          AND journal IN ({placeholders})
        ORDER BY finished_at DESC, id DESC
        """,
        (selected, selected, *journals),
    ).fetchall()
    now = datetime.now().astimezone()
    arxiv_ready_at = arxiv_ready_time(selected_date)
    arxiv_ready_at = arxiv_ready_at.astimezone(now.tzinfo) if arxiv_ready_at else None
    current_timezone_name = system_timezone_name()
    fetched: set[str] = journals_with_papers_for_date(storage, selected, journals)
    for row in rows:
        journal = row["journal"]
        if journal in fetched:
            continue
        if journal == ARXIV_JOURNAL_NAME and str(row["timezone_name"] or "") != current_timezone_name:
            continue
        status = row["status"]
        if status == "running":
            if is_fetch_active(selected) and not running_fetch_is_stale(row["started_at"], row["finished_at"], now):
                fetched.add(journal)
            continue
        if status == "error":
            continue
        if journal == ARXIV_JOURNAL_NAME:
            if arxiv_ready_at is None:
                fetched.add(journal)
                continue
            if now < arxiv_ready_at:
                fetched.add(journal)
                continue
            if fetch_finished_before(row["finished_at"], now, arxiv_ready_at):
                continue
            fetched.add(journal)
            continue
        fetched.add(journal)
    missing = [journal for journal in journals if journal not in fetched]
    if ARXIV_JOURNAL_NAME in missing and (arxiv_ready_at is None or now < arxiv_ready_at):
        missing.remove(ARXIV_JOURNAL_NAME)
    return missing


def journal_fetch_errors_for_date(storage: Storage, selected: str, journals: list[str]) -> list[dict[str, str]]:
    if not journals:
        return []
    placeholders = ", ".join(["?"] * len(journals))
    rows = storage.conn.execute(
        f"""
        SELECT id, journal, source, status, message, started_at
        FROM fetch_runs
        WHERE monitor_type = 'journal'
          AND window_start <= ?
          AND window_end >= ?
          AND journal IN ({placeholders})
        ORDER BY started_at DESC, id DESC
        """,
        (selected, selected, *journals),
    ).fetchall()
    latest_any: dict[str, Any] = {}
    latest_summary: dict[str, Any] = {}
    for row in rows:
        journal = clean_text(row["journal"] or "")
        if not journal:
            continue
        if journal not in latest_any:
            latest_any[journal] = row
        if row["source"] in {"journal", "arxiv"} and journal not in latest_summary:
            latest_summary[journal] = row
    errors: list[dict[str, str]] = []
    for journal in journals:
        row = latest_summary.get(journal) or latest_any.get(journal)
        if row is None or row["status"] != "error":
            continue
        raw_message = clean_text(row["message"] or "")
        message_key = raw_message.casefold()
        if "proxyerror" in message_key or "127.0.0.1" in message_key or "localhost" in message_key:
            message = "The configured local proxy is unavailable."
        elif "nameresolution" in message_key or "name or service not known" in message_key:
            message = "The network DNS lookup failed."
        elif "timeout" in message_key:
            message = "The network request timed out."
        else:
            message = "The network request failed."
        errors.append(
            {
                "journal": journal,
                "source": clean_text(row["source"] or "network"),
                "message": message,
            }
        )
    return errors


def manual_refresh_journals_for_date(selected: str, journals: list[str]) -> list[str]:
    selected_date = date.fromisoformat(selected)
    if selected_date > today_local():
        return []
    return list(journals)


def journals_with_papers_for_date(storage: Storage, selected: str, journals: list[str]) -> set[str]:
    if not journals:
        return set()
    placeholders = ", ".join(["?"] * len(journals))
    rows = storage.conn.execute(
        f"""
        SELECT DISTINCT journal
        FROM papers
        WHERE publication_date = ?
          AND (section_allowed IS NULL OR section_allowed != 0)
          AND journal IN ({placeholders})
        """,
        (selected, *journals),
    ).fetchall()
    return {row["journal"] for row in rows}


def journal_fetch_start_date(selected_date: date) -> date:
    local_today = today_local()
    if selected_date >= local_today:
        return selected_date - timedelta(days=1)
    return selected_date


def arxiv_ready_time(selected_date: date) -> datetime | None:
    eastern = ZoneInfo("America/New_York")
    local_tz = local_timezone()
    announcement_days = local_arxiv_announcement_days(selected_date, selected_date, local_tz=local_tz)
    if not announcement_days:
        return None
    announcement_date = max(announcement_days)
    announcement = datetime(
        announcement_date.year,
        announcement_date.month,
        announcement_date.day,
        20,
        0,
        tzinfo=eastern,
    )
    return announcement.astimezone(local_tz) + ARXIV_ANNOUNCEMENT_BUFFER


def parse_fetch_time(value: str, now: datetime) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=now.tzinfo)
    return parsed.astimezone(now.tzinfo)


def running_fetch_is_stale(started_at: str, finished_at: str, now: datetime) -> bool:
    started = parse_fetch_time(started_at, now) or parse_fetch_time(finished_at, now)
    if not started:
        return True
    return now - started > INTERRUPTED_FETCH_RESUME_AFTER


def fetch_finished_before(finished_at: str, now: datetime, threshold: datetime) -> bool:
    finished = parse_fetch_time(finished_at, now)
    return not finished or finished < threshold


def config_for_journals(config: AppConfig, journal_names: list[str]) -> AppConfig:
    wanted = set(journal_names)
    return AppConfig(
        fetch_lookback_days=config.fetch_lookback_days,
        report_days=config.report_days,
        keep_unknown_sections=config.keep_unknown_sections,
        journals=[journal for journal in config.journals if journal.name in wanted],
        section_policies=config.section_policies,
    )


def read_config_json() -> dict[str, Any]:
    return json.loads(DEFAULT_CONFIG_PATH.read_text(encoding="utf-8"))


def journal_subscription_config_entry(item: dict[str, Any]) -> dict[str, Any]:
    return {
        "name": str(item.get("name") or ""),
        "issns": list(item.get("issns") or []),
        "openalex_source_id": item.get("openalex_source_id"),
        "section_policy": str(item.get("section_policy") or "science"),
        "skip_landing_enrichment": bool(item.get("skip_landing_enrichment", True)),
        "logo_url": str(item.get("logo_url") or ""),
    }


def read_journal_config_json(db_path: Path = DEFAULT_DB_PATH) -> dict[str, Any]:
    raw = read_config_json()
    storage = Storage(db_path)
    try:
        storage.seed_journal_subscriptions(
            raw.get("journals", []),
            raw.get("journal_history", []),
        )
        active = storage.list_journal_subscriptions(enabled=True)
        inactive = storage.list_journal_subscriptions(enabled=False)
    finally:
        storage.close()
    raw["journals"] = [journal_subscription_config_entry(item) for item in active]
    raw["journal_history"] = [journal_subscription_config_entry(item) for item in inactive]
    return raw


def configured_journal_entry(name: str, raw: dict[str, Any] | None = None) -> dict[str, Any]:
    key = clean_journal_name(name).casefold()
    if not key:
        return {}
    config = raw if raw is not None else read_config_json()
    return next(
        (
            dict(item)
            for item in config.get("journals", [])
            if clean_journal_name(str(item.get("name") or "")).casefold() == key
        ),
        {},
    )


def journal_uses_text_label(name: str) -> bool:
    key = clean_journal_name(name).casefold()
    # APS pages expose publisher/campaign artwork rather than a dependable
    # journal wordmark. Keep their names readable even if an old logo is cached.
    return (
        key in {ARXIV_JOURNAL_NAME.casefold(), "physical review", "prl", "prx", "rmp", "reviews of modern physics"}
        or key.startswith("physical review ")
        or key.startswith("prx ")
    )


def local_journal_logo_url(name: str) -> str:
    cleaned = clean_journal_name(name)
    if not cleaned or journal_uses_text_label(cleaned):
        return ""
    return f"/api/journal-logo-image?name={quote(cleaned)}"


def journals_for_api(raw: dict[str, Any]) -> list[dict[str, Any]]:
    journals: list[dict[str, Any]] = []
    for item in raw.get("journals", []):
        journal = dict(item)
        journal["logo_url"] = local_journal_logo_url(str(journal.get("name") or ""))
        journals.append(journal)
    return journals


def journal_logo_cache_dir(db_path: Path = DEFAULT_DB_PATH) -> Path:
    return Path(db_path).expanduser().resolve().parent / "cache" / "journal_logos"


def journal_logo_cache_stem(name: str) -> str:
    cleaned = clean_journal_name(name)
    slug = safe_slug(cleaned).strip("._-") or "journal"
    digest = hashlib.sha256(cleaned.casefold().encode("utf-8")).hexdigest()[:12]
    return f"{slug[:64]}-{digest}"


def journal_logo_cache_key(db_path: Path, name: str) -> str:
    return f"{Path(db_path).expanduser().resolve()}::{clean_journal_name(name).casefold()}"


def cached_journal_logo_path(db_path: Path, name: str) -> Path | None:
    cache_key = journal_logo_cache_key(db_path, name)
    memory_path = Path(JOURNAL_LOGO_CACHE.get(cache_key, "")) if JOURNAL_LOGO_CACHE.get(cache_key) else None
    if memory_path and memory_path.exists() and memory_path.is_file():
        return memory_path
    cache_dir = journal_logo_cache_dir(db_path)
    stem = journal_logo_cache_stem(name)
    for extension in sorted(JOURNAL_LOGO_EXTENSIONS):
        candidate = cache_dir / f"{stem}.{extension}"
        if candidate.exists() and candidate.is_file():
            JOURNAL_LOGO_CACHE[cache_key] = str(candidate)
            return candidate
    return None


def journal_logo_file_type(content: bytes, content_type: str = "", source_url: str = "") -> tuple[str, str]:
    if not content:
        raise ValueError("Journal logo is empty")
    if len(content) > JOURNAL_LOGO_MAX_BYTES:
        raise ValueError("Journal logo is too large")
    prefix = content[:8192].lstrip().lower()
    if b"<svg" in prefix:
        return "svg", "image/svg+xml"
    if content.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png", "image/png"
    if content.startswith(b"\xff\xd8\xff"):
        return "jpg", "image/jpeg"
    if content.startswith((b"GIF87a", b"GIF89a")):
        return "gif", "image/gif"
    if len(content) >= 12 and content[:4] == b"RIFF" and content[8:12] == b"WEBP":
        return "webp", "image/webp"
    marker = f"{content_type} {urlparse(source_url).path}".casefold()
    if "image/svg+xml" in marker and b"<svg" in content.lower():
        return "svg", "image/svg+xml"
    raise ValueError("Downloaded journal logo is not a supported image")


def direct_journal_logo_source(name: str, configured: dict[str, Any] | None = None) -> str:
    if journal_uses_text_label(name):
        return ""
    journal = dict(configured or {})
    configured_url = clean_text(journal.get("logo_url") or "")
    if configured_url and not is_icon_logo_candidate(configured_url, configured_url):
        return configured_url
    return KNOWN_JOURNAL_LOGOS.get(clean_journal_name(name).casefold(), "")


def prewarm_configured_journal_logos(db_path: Path) -> None:
    raw = read_journal_config_json(db_path)
    for configured in raw.get("journals", []):
        name = clean_journal_name(str(configured.get("name") or ""))
        if not name or not direct_journal_logo_source(name, configured):
            continue
        cache_journal_logo(db_path, name, configured)


def cache_journal_logo(
    db_path: Path,
    name: str,
    configured: dict[str, Any] | None = None,
) -> Path | None:
    cleaned = clean_journal_name(name)
    if not cleaned or journal_uses_text_label(cleaned):
        return None
    cache_key = journal_logo_cache_key(db_path, cleaned)
    existing = cached_journal_logo_path(db_path, cleaned)
    if existing:
        return existing
    if cache_key in JOURNAL_LOGO_FAILED:
        return None
    with JOURNAL_LOGO_DOWNLOAD_LOCK:
        existing = cached_journal_logo_path(db_path, cleaned)
        if existing:
            return existing
        if cache_key in JOURNAL_LOGO_FAILED:
            return None
        journal = dict(
            configured
            or configured_journal_entry(cleaned, read_journal_config_json(db_path))
        )
        source_url = direct_journal_logo_source(cleaned, journal) or resolve_journal_logo_url(cleaned)
        if not source_url:
            JOURNAL_LOGO_FAILED.add(cache_key)
            return None
        try:
            response = request_with_retries(
                "GET",
                source_url,
                headers={"Accept": "image/svg+xml,image/png,image/jpeg,image/webp,image/gif,*/*;q=0.5"},
                timeout=20,
                max_retries=1,
                retry_on_429=False,
            )
            content = bytes(response.content or b"")
            extension, _content_type = journal_logo_file_type(
                content,
                str(response.headers.get("Content-Type") or ""),
                str(response.url or source_url),
            )
            cache_dir = journal_logo_cache_dir(db_path)
            cache_dir.mkdir(parents=True, exist_ok=True)
            target = cache_dir / f"{journal_logo_cache_stem(cleaned)}.{extension}"
            temp_path = cache_dir / f".{target.name}-{uuid.uuid4().hex}.tmp"
            try:
                temp_path.write_bytes(content)
                temp_path.replace(target)
            finally:
                if temp_path.exists():
                    temp_path.unlink()
            JOURNAL_LOGO_CACHE[cache_key] = str(target)
            return target
        except (OSError, ValueError, RuntimeError, requests.RequestException):
            JOURNAL_LOGO_FAILED.add(cache_key)
            return None


def clean_journal_name(value: str) -> str:
    return " ".join(value.strip().split())


def resolve_journal_metadata(name: str) -> dict[str, Any]:
    try:
        response = openalex_request(
            "GET",
            "https://api.openalex.org/sources",
            params={"search": name, "per-page": 1},
            timeout=12,
        )
        results = response.json().get("results") or []
    except Exception:
        return {}
    if not results:
        return {}
    source = results[0]
    source_id = clean_openalex_source_id(str(source.get("id") or ""))
    issns = [clean_journal_name(str(value)) for value in (source.get("issn") or []) if value]
    issn_l = clean_journal_name(str(source.get("issn_l") or ""))
    if issn_l and issn_l not in issns:
        issns.insert(0, issn_l)
    return {
        "name": clean_journal_name(str(source.get("display_name") or name)),
        "issns": issns,
        "openalex_source_id": source_id or None,
        "logo_url": resolve_journal_logo_url(
            clean_journal_name(str(source.get("display_name") or name)),
            clean_journal_name(str(source.get("homepage_url") or "")),
        ),
    }


def resolve_journal_logo_url(name: str, homepage_url: str = "") -> str:
    if journal_uses_text_label(name):
        return ""
    known = KNOWN_JOURNAL_LOGOS.get(name.lower().strip())
    if known:
        return known
    for url in [homepage_url, journal_homepage_guess(name)]:
        if not url:
            continue
        try:
            response = request_with_retries("GET", url, timeout=12)
            soup = BeautifulSoup(response.text, "html.parser")
        except Exception:
            continue
        logo = extract_logo_url(soup, response.url, name)
        if logo:
            return logo
    return ""


def extract_logo_url(soup: BeautifulSoup, base_url: str, name: str) -> str:
    name_key = re.sub(r"[^a-z0-9]+", "", name.lower())
    selectors = [
        ".c-header__logo source",
        ".c-header__logo img",
        "picture[class*=logo i] source",
        "picture[class*=logo i] img",
        "img[alt*=logo i]",
        "img[class*=logo i]",
        "img[id*=logo i]",
        "svg[aria-label*=logo i]",
    ]
    for selector in selectors:
        for tag in soup.select(selector):
            value = (
                tag.get("srcset")
                or tag.get("src")
                or tag.get("href")
                or tag.get("content")
                or tag.get("data-src")
                or ""
            )
            if value and "," in str(value):
                value = str(value).split(",", 1)[0].strip().split(" ", 1)[0]
            marker = " ".join(
                [
                    str(value),
                    str(tag.get("alt") or ""),
                    str(tag.get("aria-label") or ""),
                    str(tag.get("class") or ""),
                    str(tag.get("id") or ""),
                ]
            ).lower()
            if is_icon_logo_candidate(str(value), marker):
                continue
            normalized_marker = re.sub(r"[^a-z0-9]+", "", marker)
            if value and ("logo" in marker or (name_key and name_key in normalized_marker)):
                return urljoin(base_url, str(value))
    return ""


def is_icon_logo_candidate(value: str, marker: str) -> bool:
    value = value.lower()
    marker = marker.lower()
    return any(token in value or token in marker for token in ["favicon", "apple-touch-icon", "mask-icon", "browserconfig", "og:image"])


def journal_homepage_guess(name: str) -> str:
    value = name.lower().strip()
    if value in KNOWN_JOURNAL_HOME_PAGES:
        return KNOWN_JOURNAL_HOME_PAGES[value]
    slug = re.sub(r"[^a-z0-9]+", "-", value).strip("-")
    if value == "nature":
        return "https://www.nature.com/nature/"
    if value.startswith("nature "):
        return f"https://www.nature.com/{slug.replace('-', '')}/"
    if value == "science":
        return "https://www.science.org/journal/science"
    if value.startswith("physical review"):
        return f"https://journals.aps.org/{slug.replace('-', '')}/"
    return ""


