def journal_issns_for_add(name: str, supplied_issns: list[str]) -> list[str]:
    preset = JOURNAL_PRESETS.get(clean_journal_name(name).lower(), {})
    if preset and (not supplied_issns or preset.get("authoritative_issns")):
        return list(preset["issns"])
    return list(supplied_issns)


def canonical_journal_name_for_add(name: str, resolved_name: str = "") -> str:
    preset = JOURNAL_PRESETS.get(clean_journal_name(name).lower(), {})
    return clean_journal_name(str(preset.get("canonical_name") or resolved_name or name))


def existing_path_or_empty(path: str) -> str:
    if not path:
        return ""
    requested = Path(path).expanduser()
    return path if requested.exists() else ""


def finder_safe_name(value: str, fallback: str = "Untitled", *, preserve_extension: bool = False) -> str:
    clean = " ".join(str(value or "").strip().split()) or fallback
    clean = re.sub(r"[/:\0]+", "-", clean)
    clean = clean.strip(" .")
    if preserve_extension:
        # File attachment names must retain their type after truncation. Folder
        # names keep the existing policy. Leave room for collision/temp suffixes
        # under the filesystem's 255-byte component limit, including Unicode.
        suffix = Path(clean).suffix
        if len(suffix) >= 120 or len(suffix.encode("utf-8")) >= 220:
            suffix = ""
        stem = clean[:-len(suffix)] if suffix else clean
        stem = stem[:120 - len(suffix)]
        stem = stem.encode("utf-8")[:220 - len(suffix.encode("utf-8"))].decode("utf-8", errors="ignore")
        return (stem.rstrip(" .") or "File") + suffix
    return clean[:120] or fallback


def library_folder_chain(storage: Storage, folder_id: int) -> list[dict[str, Any]]:
    chain: list[dict[str, Any]] = []
    current = int(folder_id or 0)
    seen: set[int] = set()
    while current and current not in seen:
        seen.add(current)
        folder = storage.get_library_folder(current)
        if not folder:
            break
        chain.append(folder)
        if folder.get("parent_id") is None:
            break
        current = int(folder.get("parent_id") or 0)
    chain.reverse()
    return chain


def local_copy_dir_for_library_folder(storage: Storage, folder_id: int) -> Path:
    chain = library_folder_chain(storage, folder_id)
    if not chain:
        return LIBRARY_LOCAL_COPY_ROOT
    root = chain[0]
    root_id = int(root.get("id") or 0)
    if root_id == 1:
        base = LIBRARY_LOCAL_COPY_ROOT
        parts = [finder_safe_name(folder.get("name") or "Folder") for folder in chain[1:]]
    else:
        base = SPACES_LOCAL_COPY_ROOT / finder_safe_name(root.get("name") or f"Space {root_id}")
        parts = [finder_safe_name(folder.get("name") or "Folder") for folder in chain[1:]]
    return base.joinpath(*parts)


def local_copy_dir_for_download_context(storage: Storage, payload: dict[str, Any]) -> Path | None:
    context = clean_text(str(payload.get("context") or "")).lower()
    if context == "my-publications":
        return MY_PUBLICATIONS_LOCAL_COPY_ROOT
    if context in {"library", "workspace", "space"}:
        item_id = int(payload.get("item_id") or 0)
        folder_id = int(payload.get("folder_id") or 0)
        if item_id:
            item = storage.get_library_item(item_id)
            if item:
                folder_id = int(item.get("folder_id") or folder_id or 1)
        if not folder_id:
            folder_id = 1
        return local_copy_dir_for_library_folder(storage, folder_id)
    return None


def associated_scope_for_path(path: Path) -> tuple[str, Path] | None:
    resolved = path.expanduser().resolve()
    for label, root in [
        ("Library", LIBRARY_LOCAL_COPY_ROOT),
        ("Spaces", SPACES_LOCAL_COPY_ROOT),
        ("My Publications", MY_PUBLICATIONS_LOCAL_COPY_ROOT),
    ]:
        root_resolved = root.expanduser().resolve()
        try:
            return label, resolved.relative_to(root_resolved)
        except ValueError:
            continue
    return None


def associated_work_dir_for_paper(storage: Storage, paper_id: str) -> Path:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    storage_key = clean_text(paper.get("storage_key") or "") or storage.storage_key_for_paper_id(str(paper_id))
    resources = storage.list_paper_resources(str(paper_id), ensure_primary=False)
    marker = f"[{storage_key}]"
    for resource in resources:
        path_text = clean_text(resource.get("stored_path") or "")
        if not path_text:
            continue
        path = Path(path_text).expanduser()
        try:
            relative = path.resolve().relative_to(ASSOCIATED_FILES_ROOT.resolve())
        except (OSError, ValueError):
            continue
        current = ASSOCIATED_FILES_ROOT.resolve()
        for part in relative.parts:
            current /= part
            if current.name.endswith(marker):
                return current
    canonical = canonical_file_path_for_paper(paper)
    scope = associated_scope_for_path(canonical) if canonical else None
    if scope:
        scope_name, relative = scope
        mirrored_parent = ASSOCIATED_FILES_ROOT / scope_name / relative.parent
        title_stem = canonical.stem if canonical else clean_text(paper.get("title") or "Paper")
    else:
        preferred = preferred_local_pdf_dir_for_paper(storage, str(paper_id))
        preferred_scope = associated_scope_for_path(preferred) if preferred else None
        if preferred_scope:
            scope_name, relative = preferred_scope
            mirrored_parent = ASSOCIATED_FILES_ROOT / scope_name / relative
        else:
            mirrored_parent = ASSOCIATED_FILES_ROOT / "Library"
        title_stem = clean_text(paper.get("title") or "Paper")
    folder_name = bundle_name(finder_safe_name(title_stem, 'Paper'), storage_key)
    return mirrored_parent / folder_name


def existing_associated_work_dir(storage: Storage, paper_id: str) -> Path | None:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id)) or {}
    storage_key = clean_text(paper.get("storage_key") or "") or storage.storage_key_for_paper_id(str(paper_id))
    marker = f"[{storage_key}]"
    for resource in storage.list_paper_resources(str(paper_id), ensure_primary=False):
        path_text = storage.resource_local_path(resource)
        if not path_text:
            continue
        try:
            relative = Path(path_text).expanduser().resolve().relative_to(ASSOCIATED_FILES_ROOT.resolve())
        except (OSError, ValueError):
            continue
        current = ASSOCIATED_FILES_ROOT.resolve()
        for part in relative.parts:
            current /= part
            if current.name.endswith(marker):
                return current
    return None


def relocate_associated_work_dir(
    storage: Storage,
    paper_id: str,
    canonical: Path,
) -> Path | None:
    paper_id = storage.resolve_paper_id(paper_id)
    source = existing_associated_work_dir(storage, str(paper_id))
    scope = associated_scope_for_path(canonical)
    if not source or not source.exists() or not scope:
        return source
    paper = storage.get_paper(str(paper_id)) or {}
    storage_key = clean_text(paper.get("storage_key") or "") or storage.storage_key_for_paper_id(str(paper_id))
    scope_name, relative = scope
    destination = (
        ASSOCIATED_FILES_ROOT
        / scope_name
        / relative.parent
        / bundle_name(finder_safe_name(canonical.stem, 'Paper'), storage_key)
    )
    if source.resolve() == destination.resolve():
        return source
    destination.parent.mkdir(parents=True, exist_ok=True)
    if destination.exists() or finder_alias.is_alias(destination):
        destination = unique_path_in_dir(destination)
    old_source = source
    path_moves: dict[Path, tuple[Path, list[str]]] = {}
    for resource in storage.list_paper_resources(str(paper_id), ensure_primary=False):
        value = storage.resource_local_path(resource)
        if not value:
            continue
        old_file = Path(value).expanduser().resolve()
        try:
            relative_file = old_file.relative_to(old_source.resolve())
        except ValueError:
            continue
        owners = paper_ids_referencing_pdf_path(storage, old_file, include_resources=True)
        path_moves[old_file] = (destination / relative_file, list(dict.fromkeys([str(paper_id), *owners])))
    shutil.move(str(source), str(destination))
    try:
        storage.conn.execute("BEGIN IMMEDIATE")
        for old_file, (new_file, owners) in path_moves.items():
            for owner_id in owners:
                update_paper_file_path_references(storage, owner_id, old_file, new_file, commit=False)
        storage.conn.commit()
    except Exception:
        storage.conn.rollback()
        if destination.exists() and not old_source.exists():
            old_source.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(destination), str(old_source))
        raise
    cleanup_empty_parents([str(old_source)], ASSOCIATED_FILES_ROOT.resolve())
    return destination


def adopt_existing_paper_resource(
    storage: Storage,
    resource_id: int,
    *,
    file_role: str,
    version_role: str = "",
    added_via: str = "manual_resource_repair",
) -> dict[str, Any]:
    resource = storage.get_paper_resource(int(resource_id))
    if not resource or not resource.get("paper_id"):
        raise ValueError("Paper file was not found")
    paper_id = str(resource.get("paper_id") or "")
    paper = storage.get_paper(paper_id) or {}
    if int(paper.get("primary_resource_id") or 0) == int(resource_id):
        raise ValueError("The current primary PDF cannot be adopted as an associated file")
    stored_text = clean_text(resource.get("stored_path") or "")
    source_text = clean_text(resource.get("source_path") or "")
    stored_source = Path(stored_text).expanduser().resolve() if stored_text else None
    original_source = Path(source_text).expanduser().resolve() if source_text else None
    source = stored_source if stored_source and stored_source.is_file() else original_source
    if not source or not source.is_file():
        raise FileNotFoundError(stored_text or source_text or "Paper file not found")
    move_source = bool(stored_source and source == stored_source)
    role = clean_text(file_role or "other").lower().replace("-", "_")
    if role not in {"publication_version", "supplement", "figure", "note", "presentation", "data", "code", "other"}:
        role = "other"
    version = clean_text(version_role or "").lower().replace("-", "_") if role == "publication_version" else ""
    if role == "publication_version" and version not in {"version_of_record", "first_published", "accepted_manuscript", "preprint", "other"}:
        version = "other"
    adopted_file_type = legacy_paper_file_type(role, version, display_name=source.name)
    projected_role, projected_version, projected_label = legacy_role_projection(adopted_file_type)
    destination_dir = associated_work_dir_for_paper(storage, paper_id) / associated_resource_subdir(role)
    destination_dir.mkdir(parents=True, exist_ok=True)
    destination = unique_path_in_dir(destination_dir / finder_safe_name(source.name, "Attached File"))
    digest = sha256_for_file(source)
    if move_source:
        shutil.move(str(source), str(destination))
    else:
        shutil.copy2(str(source), str(destination))
    try:
        storage.conn.execute("BEGIN IMMEDIATE")
        storage.conn.execute(
            """
            UPDATE resources
            SET stored_path = ?, display_name = ?, file_role = ?, version_role = ?,
                version_label = ?, file_type = ?, file_type_override = 1,
                file_source = 'user_import',
                storage_mode = 'managed', sha256 = ?, added_via = ?,
                missing_status = '', updated_at = ?
            WHERE id = ?
            """,
            (
                str(destination),
                destination.name,
                projected_role,
                projected_version or None,
                projected_label,
                adopted_file_type,
                digest,
                clean_text(added_via or "manual_resource_repair"),
                now_iso(),
                int(resource_id),
            ),
        )
        storage.conn.commit()
    except Exception:
        storage.conn.rollback()
        if destination.exists():
            if move_source and not source.exists():
                source.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(destination), str(source))
            elif not move_source:
                destination.unlink()
        raise
    if move_source:
        cleanup_local_copy_empty_parents([str(source)])
    return storage.get_paper_resource(int(resource_id)) or {}


def update_paper_resource_role(
    storage: Storage,
    paper_id: str,
    resource_id: int,
    file_type: str,
    version_role: str | None = None,
    *,
    annotation_state: str = "unknown",
    is_annotated: bool | None = None,
    file_source: str = "",
    source_detail: str | None = None,
) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    resource = storage.get_paper_resource(int(resource_id))
    if not paper or not resource or str(resource.get("paper_id") or "") != str(paper_id):
        raise KeyError(int(resource_id))
    legacy_call = version_role is not None or clean_text(file_type or "").lower().replace("-", "_") not in PAPER_FILE_TYPES
    legacy_role = clean_text(file_type or "other").lower().replace("-", "_")
    legacy_version = clean_text(version_role or "").lower().replace("-", "_")
    raw_type = (
        legacy_paper_file_type(
            legacy_role,
            legacy_version,
            display_name=resource.get("display_name"),
        )
        if legacy_call
        else clean_text(file_type or "").lower().replace("-", "_").replace(" ", "_")
    )
    if raw_type not in PAPER_FILE_TYPES:
        raise ValueError("Unknown file type")
    if legacy_call and legacy_role == "publication_version" and not storage.resource_is_pdf(resource):
        raise ValueError("Only PDFs can be classified as paper versions")
    if (
        legacy_call
        and int(paper.get("primary_resource_id") or 0) == int(resource_id)
        and legacy_role != "publication_version"
    ):
        raise ValueError("The current default PDF must remain a paper version")
    normalized_type = normalize_paper_file_type(raw_type)
    if is_annotated is not None:
        annotation_state = "annotated" if is_annotated else "unannotated"
    raw_annotation = clean_text(annotation_state or "unknown").lower().replace("-", "_").replace(" ", "_")
    if raw_annotation not in PAPER_FILE_ANNOTATION_STATES:
        raise ValueError("Unknown annotation state")
    normalized_annotation = normalize_annotation_state(raw_annotation)
    current_source = normalize_paper_file_source(resource.get("file_source"))
    raw_source_input = clean_text(file_source or "")
    raw_source = clean_text(raw_source_input or current_source or "unknown").lower().replace("-", "_").replace(" ", "_")
    if raw_source not in PAPER_FILE_SOURCES:
        raise ValueError("Unknown file source")
    normalized_source = normalize_paper_file_source(raw_source)
    source_changed = bool(raw_source_input) and normalized_source != current_source
    if source_detail is None:
        resolved_source_detail = "" if source_changed else clean_text(resource.get("source_detail") or "")
    else:
        resolved_source_detail = clean_text(source_detail)
    resolved_source_detail = visible_paper_file_source_detail(
        resolved_source_detail,
        resource.get("added_via"),
    )
    role, version, version_label = legacy_role_projection(normalized_type)
    if legacy_call:
        legacy_labels = {
            "supplement": "Supplement",
            "figure": "Image",
            "note": "Note",
            "presentation": "Presentation",
            "data": "Data",
            "code": "Code",
            "other": "Other File",
        }
        if legacy_role == "publication_version":
            role = "publication_version"
            version = legacy_version or "other"
            version_label = {
                "version_of_record": "Published Version",
                "first_published": "Published Version",
                "accepted_manuscript": "Accepted Manuscript",
                "preprint": "Preprint",
                "other": "Imported PDF",
            }.get(version, "Imported PDF")
        else:
            role = legacy_role if legacy_role in legacy_labels else "other"
            version = ""
            version_label = legacy_labels.get(role, "Other File")
    version_number = (
        int(resource.get("version_number") or 0)
        if normalized_type == "preprint"
        else 0
    )
    if normalized_type == "preprint" and version_number:
        version_label = f"Preprint v{version_number}"
    storage.conn.execute(
        """
        UPDATE resources
        SET file_type = ?, annotation_state = ?, file_source = ?, source_detail = ?,
            file_type_override = 1, annotation_override = 1,
            file_role = ?, version_role = ?, version_label = ?, version_number = ?,
            is_annotated = CASE
                WHEN ? = 'annotated' THEN 1
                WHEN ? = 'unannotated' THEN 0
                ELSE is_annotated
            END,
            updated_at = ?
        WHERE id = ? AND paper_id = ?
        """,
        (
            normalized_type,
            normalized_annotation,
            normalized_source,
            resolved_source_detail or None,
            role,
            version or None,
            version_label,
            version_number or None,
            normalized_annotation,
            normalized_annotation,
            now_iso(),
            int(resource_id),
            str(paper_id),
        ),
    )
    storage.conn.commit()
    try:
        synchronize_default_pdf_location(storage, str(paper_id))
    except Exception:
        # A failed file transition must not leave the new classification visible.
        fields = ("file_type", "annotation_state", "file_source", "source_detail",
                  "file_type_override", "annotation_override", "file_role", "version_role",
                  "version_label", "version_number", "is_annotated", "updated_at")
        storage.conn.execute(
            "UPDATE resources SET " + ", ".join(f"{field} = ?" for field in fields) + " WHERE id = ?",
            [*(resource.get(field) for field in fields), int(resource_id)],
        )
        storage.conn.commit()
        raise
    return storage.get_paper_resource(int(resource_id)) or {}


def delete_paper_resource(storage: Storage, paper_id: str, resource_id: int) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    resource = storage.get_paper_resource(int(resource_id))
    if not paper or not resource or str(resource.get("paper_id") or "") != str(paper_id):
        raise KeyError(int(resource_id))
    if (int(paper.get("primary_resource_id") or 0) == int(resource_id)
            or int(parse_raw_json(paper).get("file_layout", {}).get("default_resource_id") or 0) == int(resource_id)):
        raise ValueError("The current default file cannot be deleted. Select another version first.")

    stored_text = clean_text(resource.get("stored_path") or "")
    stored_path = Path(stored_text).expanduser().resolve() if stored_text else None
    managed_roots = local_copy_roots(include_legacy=True)
    managed_file = bool(
        stored_path
        and stored_path.is_file()
        and is_allowed_file(stored_path, managed_roots)
    )
    shared_file = False
    if managed_file and stored_path:
        shared_resource = storage.conn.execute(
            "SELECT 1 FROM resources WHERE id != ? AND stored_path = ? LIMIT 1",
            (int(resource_id), stored_text),
        ).fetchone()
        shared_paper = storage.conn.execute(
            """
            SELECT 1 FROM papers
            WHERE main_pdf_path = ? OR merged_pdf_path = ?
            LIMIT 1
            """,
            (stored_text, stored_text),
        ).fetchone()
        shared_file = bool(shared_resource or shared_paper)

    trash_destination: Path | None = None
    if managed_file and stored_path and not shared_file:
        trash_destination = move_path_to_macos_trash(stored_path)
    try:
        storage.conn.execute("BEGIN IMMEDIATE")
        storage.conn.execute(
            """
            UPDATE papers
            SET preferred_resource_id = NULL, preferred_resource_manual = 0
            WHERE paper_id = ? AND preferred_resource_id = ?
            """,
            (str(paper_id), int(resource_id)),
        )
        storage.conn.execute("DELETE FROM resources WHERE id = ?", (int(resource_id),))
        storage.conn.commit()
    except Exception:
        storage.conn.rollback()
        if stored_path and not stored_path.exists() and trash_destination and trash_destination.exists():
            stored_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(trash_destination), str(stored_path))
        raise
    if managed_file and stored_path and not shared_file:
        cleanup_local_copy_empty_parents([str(stored_path)])
    sync_associated_aliases(storage, str(paper_id))
    return {
        "resource_id": int(resource_id),
        "name": clean_text(resource.get("display_name") or "") or (stored_path.name if stored_path else "Attached File"),
        "trashed": bool(managed_file and not shared_file),
        "shared_file_preserved": bool(shared_file),
        "external_source_preserved": bool(stored_path and not is_allowed_file(stored_path, managed_roots)),
    }


def associated_resource_subdir(file_role: str) -> str:
    if file_role == "publication_version":
        return "Versions"
    if file_role == "supplement":
        return "Supplements"
    if file_role == "figure":
        return "Figures"
    return "Files"


def sha256_for_file(path: Path) -> str:
    return exact_sha256_for_file(path)


def refresh_paper_resource_fingerprints(
    storage: Storage,
    paper_id: str,
    *,
    commit: bool = True,
) -> list[dict[str, Any]]:
    """Refresh exact and annotation-insensitive fingerprints for one work on demand."""
    paper_id = storage.resolve_paper_id(paper_id)

    storage.ensure_primary_pdf_resource(str(paper_id), commit=commit)
    resources = storage.list_paper_resources(str(paper_id), ensure_primary=False)
    changed = False
    for resource in resources:
        path_text = clean_text(resource.get("stored_path") or resource.get("source_path") or "")
        path = Path(path_text).expanduser() if path_text else None
        if not path or not path.is_file():
            continue
        try:
            fingerprint = fingerprint_file(path)
        except OSError:
            continue
        storage.conn.execute(
            """
            UPDATE resources
            SET sha256 = ?, content_sha256 = ?, annotation_count = ?,
                is_annotated = CASE
                    WHEN COALESCE(annotation_override, 0) = 1 THEN COALESCE(is_annotated, 0)
                    WHEN ? > 0 THEN 1
                    ELSE 0
                END,
                annotation_state = CASE
                    WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                    WHEN ? > 0 THEN 'annotated'
                    ELSE 'unannotated'
                END,
                size_bytes = ?, modified_at = ?, missing_status = '', updated_at = ?
            WHERE id = ? AND paper_id = ?
            """,
            (
                fingerprint.sha256,
                fingerprint.content_sha256 or None,
                fingerprint.annotation_count,
                fingerprint.annotation_count,
                fingerprint.annotation_count,
                fingerprint.size_bytes,
                fingerprint.modified_at,
                now_iso(),
                int(resource.get("id") or 0),
                str(paper_id),
            ),
        )
        changed = True
    if changed and commit:
        storage.conn.commit()
    return storage.list_paper_resources(str(paper_id), ensure_primary=False)


def snapshot_primary_resource_before_download(
    storage: Storage,
    paper_id: str,
    *,
    force: bool,
) -> dict[str, Any] | None:
    paper_id = storage.resolve_paper_id(paper_id)
    if not force:
        return None
    paper = storage.get_paper(str(paper_id))
    canonical = canonical_pdf_path_for_paper(paper)
    if not paper or not canonical:
        return None
    primary = storage.ensure_primary_pdf_resource(str(paper_id))
    if not primary:
        return None
    handle, temporary_name = tempfile.mkstemp(prefix="gewu-pdf-version-", suffix=canonical.suffix or ".pdf")
    os.close(handle)
    temporary = Path(temporary_name)
    try:
        shutil.copy2(canonical, temporary)
        # The on-disk bytes are authoritative here.  A resource hash can be stale
        # after an older in-place refresh, which must not make a changed PDF look
        # identical and suppress version archiving.
        fingerprint = fingerprint_file(temporary)
    except Exception:
        temporary.unlink(missing_ok=True)
        raise
    return {
        "temporary_path": temporary,
        "canonical_path": canonical,
        "resource": primary,
        "sha256": fingerprint.sha256,
        "content_sha256": fingerprint.content_sha256,
        "annotation_count": fingerprint.annotation_count,
        "is_annotated": fingerprint.is_annotated,
    }


def cleanup_download_resource_snapshot(snapshot: dict[str, Any] | None) -> None:
    if not snapshot:
        return
    temporary = snapshot.get("temporary_path")
    if isinstance(temporary, Path):
        temporary.unlink(missing_ok=True)


def downloaded_version_role(paper: dict[str, Any], source_url: str = "", *, pdf_path: Path | None = None) -> str:
    resolved_url = clean_text(source_url or paper.get("pdf_url") or "")
    host = urlparse(resolved_url).netloc.casefold()
    if host == "arxiv.org" or host.endswith(".arxiv.org"):
        return "preprint"
    if is_nature_reference_pdf_url(resolved_url):
        return "accepted_manuscript"
    if (pdf_path and normalize_doi(paper.get("doi") or "").startswith("10.1126/")
            and is_science_first_release_pdf(pdf_path)):
        return "accepted_manuscript"
    if resolved_url and clean_text(paper.get("doi") or ""):
        return "version_of_record"
    if resolved_url and clean_text(paper.get("arxiv_id") or ""):
        return "preprint"
    return "other"


def downloaded_version_label(version_role: str) -> str:
    return {
        "version_of_record": "Published Version",
        "preprint": "Preprint",
        "accepted_manuscript": "Accepted Manuscript",
        "first_published": "Published Version",
    }.get(clean_text(version_role or ""), "Imported PDF")


def downloaded_file_source(source_url: str) -> tuple[str, str]:
    host = (urlparse(clean_text(source_url or "")).hostname or "").casefold()
    if host == "arxiv.org" or host.endswith(".arxiv.org"):
        return "preprint_server", host
    return ("publisher", host) if host else ("unknown", "")


def downloaded_primary_filename(
    paper: dict[str, Any],
    *,
    version_role: str,
    fallback_path: Path,
) -> str:
    if version_role != "version_of_record":
        return fallback_path.name
    doi = normalize_doi(paper.get("doi") or "")
    suffix = doi.split("/", 1)[1] if "/" in doi else doi
    base = finder_safe_name(suffix.replace("/", "_"), safe_slug(paper.get("title") or "Published Version", 80))
    return finder_safe_name(
        f"{base} [Published Version].pdf",
        f"{safe_slug(paper.get('title') or 'Published Version', 80)} [Published Version].pdf",
    )


def register_downloaded_paper_resource(
    storage: Storage,
    paper_id: str,
    *,
    result: dict[str, Any],
    snapshot: dict[str, Any] | None,
) -> dict[str, Any] | None:
    paper_id = storage.resolve_paper_id(paper_id)
    status = clean_text(result.get("status") or "").lower()
    if status not in {"success", "partial", "skipped"}:
        return None
    paper = storage.get_paper(str(paper_id))
    canonical = canonical_pdf_path_for_paper(paper)
    if not paper or not canonical:
        return None
    new_fingerprint = fingerprint_file(canonical)
    new_digest = new_fingerprint.sha256
    if status == "skipped":
        # No bytes were downloaded in this call.  Metadata such as a newly found
        # DOI or publisher URL must not relabel an existing preprint as a VOR.
        primary = storage.ensure_primary_pdf_resource(str(paper_id))
        if not primary:
            return None
        storage.conn.execute(
            """
            UPDATE resources
            SET sha256 = ?, content_sha256 = ?, annotation_count = ?,
                is_annotated = CASE
                    WHEN COALESCE(annotation_override, 0) = 1 THEN is_annotated ELSE ?
                END,
                annotation_state = CASE
                    WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                    WHEN ? > 0 THEN 'annotated' ELSE 'unannotated'
                END,
                size_bytes = ?, modified_at = ?, missing_status = '', updated_at = ?
            WHERE id = ?
            """,
            (
                new_digest,
                new_fingerprint.content_sha256 or None,
                new_fingerprint.annotation_count,
                1 if new_fingerprint.is_annotated else 0,
                new_fingerprint.annotation_count,
                new_fingerprint.size_bytes,
                new_fingerprint.modified_at,
                now_iso(),
                int(primary.get("id") or 0),
            ),
        )
        storage.conn.commit()
        return storage.get_paper_resource(int(primary.get("id") or 0))
    download_source_url = clean_text(result.get("main_pdf_url") or paper.get("pdf_url") or "")
    new_version_role = downloaded_version_role(paper, download_source_url, pdf_path=canonical)
    new_version_label = downloaded_version_label(new_version_role)
    new_file_type = normalize_paper_file_type(new_version_role)
    new_file_source, new_source_detail = downloaded_file_source(download_source_url)
    if not snapshot:
        primary = storage.ensure_primary_pdf_resource(str(paper_id))
        if primary:
            storage.conn.execute(
                """
                UPDATE resources
                SET sha256 = ?, content_sha256 = ?, annotation_count = ?, is_annotated = ?,
                    size_bytes = ?, modified_at = ?, file_role = 'publication_version',
                    version_role = ?, version_label = ?,
                    file_type = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN file_type ELSE ? END,
                    file_source = CASE WHEN COALESCE(file_source, 'unknown') = 'unknown' THEN ? ELSE file_source END,
                    source_detail = COALESCE(NULLIF(source_detail, ''), ?),
                    annotation_state = CASE
                        WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                        WHEN ? > 0 THEN 'annotated' ELSE 'unannotated'
                    END,
                    source_url = COALESCE(NULLIF(?, ''), source_url),
                    added_via = 'download_initial', missing_status = '', updated_at = ?
                WHERE id = ?
                """,
                (
                    new_digest,
                    new_fingerprint.content_sha256 or None,
                    new_fingerprint.annotation_count,
                    1 if new_fingerprint.is_annotated else 0,
                    new_fingerprint.size_bytes,
                    new_fingerprint.modified_at,
                    new_version_role,
                    new_version_label,
                    new_file_type,
                    new_file_source,
                    new_source_detail or None,
                    new_fingerprint.annotation_count,
                    download_source_url,
                    now_iso(),
                    int(primary.get("id") or 0),
                ),
            )
            storage.conn.commit()
            return storage.get_paper_resource(int(primary.get("id") or 0))
        return None

    old_resource = dict(snapshot.get("resource") or {})
    old_id = int(old_resource.get("id") or 0)
    old_digest = clean_text(snapshot.get("sha256") or "")
    old_content_digest = clean_text(snapshot.get("content_sha256") or "")
    old_annotation_count = int(snapshot.get("annotation_count") or 0)
    old_is_annotated = bool(snapshot.get("is_annotated"))
    if new_digest == old_digest:
        old_canonical = Path(snapshot.get("canonical_path") or canonical).expanduser().resolve()
        if canonical != old_canonical and old_canonical.exists() and old_canonical.is_file():
            canonical.unlink(missing_ok=True)
            canonical = old_canonical
        final_path = canonical
        desired_name = downloaded_primary_filename(
            paper,
            version_role=new_version_role,
            fallback_path=canonical,
        )
        if desired_name != canonical.name:
            final_path = unique_path_in_dir(canonical.parent / desired_name)
            shutil.move(str(canonical), str(final_path))
        try:
            storage.conn.execute("BEGIN IMMEDIATE")
            storage.conn.execute(
                """
                UPDATE resources
                SET sha256 = ?, stored_path = ?, display_name = ?, file_role = 'publication_version',
                    version_role = ?, version_label = ?, source_url = COALESCE(NULLIF(?, ''), source_url),
                    file_type = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN file_type ELSE ? END,
                    file_source = CASE WHEN COALESCE(file_source, 'unknown') = 'unknown' THEN ? ELSE file_source END,
                    source_detail = COALESCE(NULLIF(source_detail, ''), ?),
                    content_sha256 = ?, annotation_count = ?, is_annotated = ?,
                    annotation_state = CASE
                        WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                        WHEN ? > 0 THEN 'annotated' ELSE 'unannotated'
                    END,
                    size_bytes = ?, modified_at = ?,
                    missing_status = '', updated_at = ?
                WHERE id = ?
                """,
                (
                    new_digest,
                    str(final_path),
                    final_path.name,
                    new_version_role,
                    new_version_label,
                    download_source_url,
                    new_file_type,
                    new_file_source,
                    new_source_detail or None,
                    new_fingerprint.content_sha256 or None,
                    new_fingerprint.annotation_count,
                    1 if new_fingerprint.is_annotated else 0,
                    new_fingerprint.annotation_count,
                    new_fingerprint.size_bytes,
                    new_fingerprint.modified_at,
                    now_iso(),
                    old_id,
                ),
            )
            storage.conn.execute(
                """
                UPDATE papers
                SET main_pdf_path = ?, merged_pdf_path = ?
                WHERE paper_id = ?
                """,
                (str(final_path), str(final_path), str(paper_id)),
            )
            storage.conn.commit()
        except Exception:
            storage.conn.rollback()
            if final_path != canonical and final_path.exists() and not canonical.exists():
                shutil.move(str(final_path), str(canonical))
            raise
        return storage.get_paper_resource(old_id)

    temporary = snapshot.get("temporary_path")
    if not isinstance(temporary, Path) or not temporary.exists():
        raise FileNotFoundError("Previous PDF snapshot was not preserved")
    versions_dir = associated_work_dir_for_paper(storage, str(paper_id)) / "Versions"
    versions_dir.mkdir(parents=True, exist_ok=True)
    old_canonical = Path(snapshot.get("canonical_path") or canonical).expanduser().resolve()
    archived_name = paper_resource_archive_name(old_resource, old_canonical)
    archived_path = unique_path_in_dir(versions_dir / archived_name)
    archive_source = (
        old_canonical
        if old_canonical != canonical and old_canonical.exists() and old_canonical.is_file()
        else temporary
    )
    desired_name = downloaded_primary_filename(
        paper,
        version_role=new_version_role,
        fallback_path=canonical,
    )
    final_path = canonical
    created_id = 0
    archived = False
    try:
        archive_source.replace(archived_path)
        archived = True
        if desired_name != canonical.name:
            final_path = unique_path_in_dir(canonical.parent / desired_name)
            shutil.move(str(canonical), str(final_path))
        storage.conn.execute("BEGIN IMMEDIATE")
        timestamp = now_iso()
        storage.conn.execute(
            """
            UPDATE resources
            SET stored_path = ?, display_name = ?, sha256 = ?, content_sha256 = ?,
                annotation_count = ?,
                is_annotated = CASE
                    WHEN COALESCE(annotation_override, 0) = 1 THEN is_annotated ELSE ?
                END,
                annotation_state = CASE
                    WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state
                    WHEN ? > 0 THEN 'annotated' ELSE 'unannotated'
                END,
                missing_status = '', updated_at = ?
            WHERE id = ?
            """,
            (
                str(archived_path),
                archived_path.name,
                old_digest,
                old_content_digest or None,
                old_annotation_count,
                1 if old_is_annotated else 0,
                old_annotation_count,
                timestamp,
                old_id,
            ),
        )
        created = storage.create_paper_resource(
            paper_id=str(paper_id),
            stored_path=str(final_path),
            display_name=final_path.name,
            file_role="publication_version",
            version_role=new_version_role,
            version_label=new_version_label,
            source_url=download_source_url,
            storage_mode="managed",
            sha256=new_digest,
            content_sha256=new_fingerprint.content_sha256,
            annotation_count=new_fingerprint.annotation_count,
            is_annotated=new_fingerprint.is_annotated,
            file_type=new_file_type,
            file_source=new_file_source,
            source_detail=new_source_detail,
            annotation_state="annotated" if new_fingerprint.is_annotated else "unannotated",
            added_via="download_refresh",
            mime_type="application/pdf",
            kind="pdf",
            supersedes_resource_id=old_id or None,
            commit=False,
        )
        created_id = int(created.get("id") or 0)
        storage.conn.execute(
            """
            UPDATE papers
            SET primary_resource_id = ?, main_pdf_path = ?, merged_pdf_path = ?
            WHERE paper_id = ?
            """,
            (created_id, str(final_path), str(final_path), str(paper_id)),
        )
        storage.conn.commit()
    except Exception:
        storage.conn.rollback()
        try:
            if archived and final_path.exists():
                final_path.unlink()
            if archived:
                old_canonical.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(archived_path), str(old_canonical))
            elif temporary.exists() and old_canonical == canonical:
                canonical.unlink(missing_ok=True)
                temporary.replace(old_canonical)
        except OSError:
            pass
        raise
    return storage.get_paper_resource(created_id)


@serialize_paper_file_writes
def attach_file_to_paper(
    storage: Storage,
    *,
    paper_id: str,
    filename: str,
    content: bytes,
    file_role: str = "other",
    version_role: str = "",
    version_label: str = "",
    file_type: str = "",
    file_source: str = "user_import",
    source_detail: str = "",
    annotation_state: str = "",
    added_via: str = "paper_details",
    source_url: str = "",
    refresh_existing: bool = True,
    mime_type: str = "",
) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    if not content:
        raise ValueError("File is empty")
    allowed_roles = {"publication_version", "supplement", "figure", "note", "presentation", "data", "code", "other"}
    role = clean_text(file_role or "other").lower().replace("-", "_")
    if role not in allowed_roles:
        role = "other"
    allowed_versions = {"version_of_record", "first_published", "accepted_manuscript", "preprint", "other"}
    version = clean_text(version_role or "").lower().replace("-", "_")
    if role == "publication_version" and version not in allowed_versions:
        version = "other"
    elif role != "publication_version":
        version = ""
    safe_name = finder_safe_name(Path(filename or "Attached File").name, "Attached File", preserve_extension=True)
    suffix = Path(safe_name).suffix.lower()
    resolved_type = normalize_paper_file_type(
        file_type
        or legacy_paper_file_type(role, version, display_name=safe_name)
    )
    from .publication_notices import title_kind, KINDS
    if suffix == '.pdf': resolved_type=title_kind(Path(safe_name).stem) or resolved_type
    if resolved_type in KINDS: role,version,version_label=legacy_role_projection(resolved_type)
    if suffix == ".pdf" and not is_valid_pdf_bytes(content):
        raise ValueError("The selected file is not a valid PDF")
    digest = hashlib.sha256(content).hexdigest()
    if refresh_existing:
        refresh_paper_resource_fingerprints(storage, str(paper_id))
    from .resource_dedup import find_content
    duplicate = find_content(storage, str(paper_id), digest, len(content))
    if duplicate:
        resource = storage.get_paper_resource(int(duplicate["id"])) or {}
        resource["duplicate"] = True
        return resource
    work_dir = associated_work_dir_for_paper(storage, str(paper_id))
    target_dir = work_dir / associated_resource_subdir(role)
    target_dir.mkdir(parents=True, exist_ok=True)
    target = unique_path_in_dir(target_dir / safe_name)
    temporary = target.with_name(
        f".{target.stem}-{uuid.uuid4().hex[:8]}.upload{target.suffix}"
    )
    try:
        temporary.write_bytes(content)
        fingerprint = fingerprint_file(temporary)
        temporary.replace(target)
        resource = storage.create_paper_resource(
            paper_id=str(paper_id),
            stored_path=str(target),
            display_name=Path(safe_name).name,
            file_role=role,
            version_role=version,
            version_label=clean_text(version_label or ""),
            storage_mode="managed",
            sha256=fingerprint.sha256,
            content_sha256=fingerprint.content_sha256,
            annotation_count=fingerprint.annotation_count,
            is_annotated=fingerprint.is_annotated,
            file_type=resolved_type,
            file_source=file_source,
            source_detail=source_detail,
            source_url=source_url,
            annotation_state=(
                annotation_state
                or ("annotated" if fingerprint.is_annotated else "unannotated")
            ),
            added_via=added_via,
            mime_type=mime_type or mimetypes.guess_type(safe_name)[0] or "application/octet-stream",
            kind=suffix.lstrip(".") or "file",
        )
        if resolved_type in AUTOMATIC_DEFAULT_FILE_TYPE_RANK and should_promote_new_paper_version(storage, str(paper_id), resource):
            resource = promote_paper_resource(storage, str(paper_id), int(resource.get("id") or 0))
    except Exception:
        temporary.unlink(missing_ok=True)
        target.unlink(missing_ok=True)
        raise
    # MCP analysis writes remain append-only; they must not trigger relocation
    # of other files. Ordinary App attachment writes reconcile the work.
    if added_via not in {"ai_analysis", "browser_capture"}:
        from .file_layout import reconcile_after_write
        reconcile_after_write(storage, str(paper_id))
        resource = storage.get_paper_resource(int(resource["id"])) or resource
    elif added_via == "ai_analysis":
        sync_associated_aliases(storage, str(paper_id))
    resource["duplicate"] = False
    return resource


def convert_library_item_to_paper_attachment(
    storage: Storage,
    *,
    source_item_id: int,
    target_paper_id: str,
) -> dict[str, Any]:
    from .file_reassignment import attach_library_item
    return attach_library_item(storage, int(source_item_id), str(target_paper_id))


@serialize_paper_file_writes
def attach_downloaded_publisher_pdf_to_paper(
    storage: Storage,
    *,
    paper_id: str,
    context: dict[str, Any],
    source_path: Path,
) -> tuple[Path, dict[str, Any]]:
    """Register a browser-downloaded publisher PDF without replacing history."""
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    source = source_path.expanduser().resolve()
    if not source.exists() or not source.is_file():
        raise FileNotFoundError(f"PDF file was not found: {source_path}")
    if not is_valid_pdf_file(source):
        raise ValueError("Publisher download must be a valid PDF")

    publisher_kind = clean_text(context.get("publisher_download_kind") or "")
    source_url = clean_text(
        context.get("publisher_download_final_url")
        or context.get("publisher_download_target_url")
        or context.get("publisher_download_referer")
        or paper.get("pdf_url")
        or ""
    )
    original_name = Path(clean_text(context.get("publisher_download_filename") or "") or source.name).name
    is_science = publisher_kind == "aaas-published-pdf" or normalize_doi(paper.get("doi") or "").startswith("10.1126/")
    if is_science:
        rejection = science_main_pdf_rejection(source, url=source_url, filename=original_name)
        if rejection:
            raise ValueError(f"{rejection}. The main article was not saved; check article access with Open Website.")
    # A native staging name is never a durable Paper Files title. Use the
    # publisher's name, or the existing metadata naming preference as fallback.
    if re.match(r"^(?:daiqo-published|gewu-publisher)-", original_name, re.I) or not original_name.lower().endswith(".pdf"):
        original_name = pdf_rename_filename_for_paper(paper, pdf_rename_template(storage), Path("paper.pdf"))
    classification_text = " ".join(
        [publisher_kind, original_name, source_url, clean_text(context.get("publisher_download_referer") or "")]
    ).casefold()
    if re.search(r"\b(correction|erratum|corrigendum)\b", classification_text):
        publisher_file_type = "correction_notice"
    elif (
        is_nature_reference_pdf_url(source_url)
        or "first release" in classification_text
        or "first_release" in classification_text
        or (is_science and is_science_first_release_pdf(source))
    ):
        publisher_file_type = "accepted_manuscript"
    else:
        publisher_file_type = "published_version"
    projected_role, projected_version, projected_label = legacy_role_projection(publisher_file_type)
    source_host = (urlparse(source_url).hostname or "").casefold()
    resource = attach_file_to_paper(
        storage,
        paper_id=str(paper_id),
        filename=original_name,
        content=source.read_bytes(),
        file_role=projected_role,
        version_role=projected_version,
        version_label=projected_label,
        file_type=publisher_file_type,
        file_source="publisher",
        source_detail=source_host,
        added_via=publisher_kind or "publisher_browser_download",
    )
    resource_id = int(resource.get("id") or 0)
    if resource.get("duplicate") and resource_id:
        # A prior buggy refresh may already have written the publisher bytes into a
        # resource still labelled Preprint.  The publisher origin is authoritative
        # for this copy, so repair its classification without renaming the file.
        storage.conn.execute(
            """
            UPDATE resources
            SET file_role = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN file_role ELSE ? END,
                version_role = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN version_role ELSE ? END,
                version_label = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN version_label ELSE ? END,
                version_number = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN version_number ELSE NULL END,
                file_type = CASE WHEN COALESCE(file_type_override, 0) = 1 THEN file_type ELSE ? END,
                file_source = 'publisher', source_detail = COALESCE(NULLIF(?, ''), source_detail),
                source_url = COALESCE(NULLIF(?, ''), source_url), updated_at = ?
            WHERE id = ? AND paper_id = ?
            """,
            (
                projected_role,
                projected_version or None,
                projected_label,
                publisher_file_type,
                source_host or None,
                source_url,
                now_iso(),
                resource_id,
                str(paper_id),
            ),
        )
        storage.conn.commit()
        resource = storage.get_paper_resource(resource_id) or resource
        if (
            publisher_file_type in AUTOMATIC_DEFAULT_FILE_TYPE_RANK
            and should_promote_new_paper_version(storage, str(paper_id), resource)
        ):
            resource = promote_paper_resource(storage, str(paper_id), resource_id)
    elif resource_id and source_url:
        storage.conn.execute(
            "UPDATE resources SET source_url = ?, updated_at = ? WHERE id = ?",
            (source_url, now_iso(), resource_id),
        )
        storage.conn.commit()
        resource = storage.get_paper_resource(resource_id) or resource

    refreshed = storage.get_paper(str(paper_id)) or paper
    if (
        publisher_file_type in AUTOMATIC_DEFAULT_FILE_TYPE_RANK
        and resource_id
        and int(refreshed.get("primary_resource_id") or 0) != resource_id
        and should_promote_new_paper_version(storage, str(paper_id), resource)
    ):
        resource = promote_paper_resource(storage, str(paper_id), resource_id)

    refreshed = storage.get_paper(str(paper_id)) or paper
    is_primary = int(refreshed.get("primary_resource_id") or 0) == resource_id
    if is_primary:
        # Old native downloads also persisted their temporary UUID name in
        # Library placements. Repair those names before a later supplement or
        # alias sync can rename the valid publisher PDF back to its staging name.
        # A custom placement name or a manually preferred other version wins.
        placements = storage.conn.execute(
            "SELECT id, display_name FROM library_items WHERE paper_id = ? AND trashed_at IS NULL",
            (str(paper_id),),
        ).fetchall()
        for placement in placements:
            if re.fullmatch(
                r"(?:daiqo-published|gewu-publisher)-[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}(?:\.pdf)?",
                clean_text(placement["display_name"] or ""), re.I,
            ):
                rename_library_item_and_sync_files(
                    storage, item_id=int(placement["id"]),
                    name=library_item_display_name_for_synced_filename(dict(placement), original_name),
                )
        resource = storage.get_paper_resource(resource_id) or resource
    message = (
        "Science main PDF saved; supplementary PDF pending"
        if publisher_kind == "aaas-published-pdf"
        else "publisher PDF downloaded and saved as a paper file"
    )
    storage.conn.execute(
        """
        UPDATE papers
        SET download_status = ?, download_message = ?, downloaded_at = ?,
            pdf_url = COALESCE(NULLIF(?, ''), pdf_url)
        WHERE paper_id = ?
        """,
        (
            "partial" if publisher_kind == "aaas-published-pdf" else "success",
            message if is_primary else f"{message}; current preferred version kept",
            now_iso(),
            source_url,
            str(paper_id),
        ),
    )
    storage.conn.commit()
    refreshed = storage.get_paper(str(paper_id)) or refreshed
    stored_path = storage.resource_local_path(resource)
    if not stored_path:
        raise FileNotFoundError("Downloaded publisher PDF was not stored")
    return Path(stored_path).expanduser().resolve(), refreshed


def paper_resource_archive_name(resource: dict[str, Any], fallback_path: Path) -> str:
    labels = {
        "version_of_record": "Published Version",
        "first_published": "Published Version",
        "accepted_manuscript": "Accepted Manuscript",
        "preprint": resource.get("version_label") or (
            f"Preprint v{int(resource.get('version_number') or 0)}"
            if int(resource.get("version_number") or 0)
            else "Preprint"
        ),
        "other": resource.get("version_label") or "Previous Version",
    }
    label = clean_text(labels.get(str(resource.get("version_role") or "other"), "Previous Version"))
    suffix = fallback_path.suffix or ".pdf"
    stem = fallback_path.stem or "Paper"
    if stem.casefold().endswith(f" [{label}]".casefold()):
        return finder_safe_name(f"{stem}{suffix}", f"Paper [{label}]{suffix}")
    return finder_safe_name(f"{stem} [{label}]{suffix}", f"Paper [{label}]{suffix}")


def should_promote_new_paper_version(
    storage: Storage,
    paper_id: str,
    resource: dict[str, Any],
) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id)) or {}
    if int(paper.get("preferred_resource_id") or 0):
        return False
    current_id = int(paper.get("primary_resource_id") or 0)
    current = storage.get_paper_resource(current_id) if current_id else None
    if not current or not canonical_pdf_path_for_paper(paper):
        return True
    current_role = str(current.get("version_role") or "other")
    new_role = str(resource.get("version_role") or "other")
    if str(current.get("added_via") or "") == "legacy_backfill" and current_role == "other":
        return new_role == "version_of_record"
    resolved = storage.resolve_primary_paper_resource(str(paper_id))
    return int((resolved or {}).get("id") or 0) == int(resource.get("id") or 0)


def synchronize_default_pdf_location(storage: Storage, paper_id: str) -> dict[str, Any] | None:
    """Keep the resolved PDF Default and managed primary path in agreement."""
    paper_id = storage.resolve_paper_id(paper_id)
    resolved = storage.resolve_default_paper_resource(str(paper_id))
    if not resolved:
        return resolved
    if storage.resource_is_pdf(resolved):
        promote_paper_resource(storage, str(paper_id), int(resolved["id"]), allow_any_pdf=True)
    sync_all_pdf_aliases_for_paper(storage, str(paper_id), preserve_canonical_name=True)
    return storage.get_paper_resource(int(resolved["id"]))


def set_preferred_paper_file(storage: Storage, paper_id: str, resource_id: int | None) -> None:
    paper_id = storage.resolve_paper_id(paper_id)
    previous = storage.get_paper(str(paper_id)) or {}
    storage.set_preferred_paper_resource(str(paper_id), resource_id)
    try:
        synchronize_default_pdf_location(storage, str(paper_id))
    except Exception:
        storage.conn.execute(
            "UPDATE papers SET preferred_resource_id = ?, preferred_resource_manual = ? WHERE paper_id = ?",
            (previous.get("preferred_resource_id"), previous.get("preferred_resource_manual", 0), str(paper_id)),
        )
        storage.conn.commit()
        raise


def paper_resource_path_is_shared(storage: Storage, path: Path, paper_id: str, resource_id: int) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    if any(other != str(paper_id) for other in paper_ids_referencing_pdf_path(storage, path)):
        return True
    values = {str(path), str(path.expanduser().resolve())}
    for value in list(values):
        if value.startswith(("/private/var/", "/private/tmp/")):
            values.add(value.removeprefix("/private"))
        elif value.startswith(("/var/", "/tmp/")):
            values.add(f"/private{value}")
    for value in values:
        if storage.conn.execute(
            "SELECT 1 FROM resources WHERE id != ? AND (stored_path = ? OR (COALESCE(stored_path, '') = '' AND source_path = ?)) LIMIT 1",
            (int(resource_id), value, value),
        ).fetchone():
            return True
    return False


def promote_paper_resource(
    storage: Storage,
    paper_id: str,
    resource_id: int,
    *,
    manual_preferred: bool = False,
    allow_any_pdf: bool = False,
) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    candidate = storage.get_paper_resource(int(resource_id))
    if not paper or not candidate or str(candidate.get("paper_id") or "") != str(paper_id):
        raise ValueError("File does not belong to this paper")
    if not storage.resource_is_pdf(candidate):
        raise ValueError("Primary file must be a PDF")
    if normalize_paper_file_type(candidate.get("file_type")) == "invalid_file":
        raise ValueError("Invalid files cannot be selected as the default")
    if not allow_any_pdf and clean_text(candidate.get("file_role") or "") != "publication_version":
        raise ValueError("Only paper-version PDFs can be selected as current")
    candidate_path_text = storage.resource_local_path(candidate)
    candidate_path = Path(candidate_path_text).expanduser().resolve() if candidate_path_text else None
    if not candidate_path or not candidate_path.exists() or not candidate_path.is_file():
        raise FileNotFoundError(candidate_path_text or "Paper file not found")
    current_id = int(paper.get("primary_resource_id") or 0)
    current = storage.get_paper_resource(current_id) if current_id else None
    current_path = canonical_pdf_path_for_paper(paper)
    managed_roots = allowed_pdf_roots()
    current_is_main = bool(current_path and is_allowed_file(current_path, managed_roots)
                           and not is_relative_to(current_path, ASSOCIATED_FILES_ROOT.resolve()))
    if current_id == int(resource_id) and current_path == candidate_path and current_is_main:
        if manual_preferred:
            storage.set_preferred_paper_resource(str(paper_id), int(resource_id))
        return candidate

    target_dir = current_path.parent if current_is_main else preferred_local_pdf_dir_for_paper(storage, str(paper_id))
    if target_dir is None:
        target_dir = DEFAULT_PDF_DIR / finder_safe_name(str(paper_id), "paper")
    target_dir.mkdir(parents=True, exist_ok=True)
    candidate_name = finder_safe_name(
        str(candidate.get("original_filename") or candidate.get("display_name") or candidate_path.name),
        candidate_path.name or "paper.pdf",
    )
    desired_target_path = target_dir / candidate_name

    work_dir = associated_work_dir_for_paper(storage, str(paper_id))
    archived_path: Path | None = None
    candidate_original = candidate_path
    target_path = desired_target_path
    candidate_moved = False
    candidate_copied = False
    archive_moved = False
    current_private = bool(current_path and is_allowed_file(current_path, managed_roots)
                           and not paper_resource_path_is_shared(storage, current_path, str(paper_id), current_id))
    candidate_private = bool(is_allowed_file(candidate_path, managed_roots)
                             and not paper_resource_path_is_shared(storage, candidate_path, str(paper_id), int(resource_id)))
    try:
        if current_path and current_path != candidate_path and current_path.exists():
            versions_dir = work_dir / "Versions"
            versions_dir.mkdir(parents=True, exist_ok=True)
            original_current_name = finder_safe_name(
                str((current or {}).get("original_filename") or current_path.name),
                current_path.name or "paper.pdf",
            )
            archived_name = paper_resource_archive_name(current or {}, Path(original_current_name))
            archived_path = unique_path_in_dir(versions_dir / archived_name)
            if current_private:
                shutil.move(str(current_path), str(archived_path))
                archive_moved = True
            else:
                shutil.copy2(current_path, archived_path)
        if candidate_path != target_path:
            if target_path.exists() or finder_alias.is_alias(target_path):
                target_path = unique_path_in_dir(target_path)
            if candidate_private:
                shutil.move(str(candidate_path), str(target_path))
                candidate_moved = True
            else:
                shutil.copy2(candidate_path, target_path)
                candidate_copied = True

        storage.conn.execute("BEGIN IMMEDIATE")
        timestamp = now_iso()
        if current and archived_path:
            storage.conn.execute(
                """
                UPDATE resources
                SET stored_path = ?, display_name = ?, storage_mode = 'managed', missing_status = '', updated_at = ?
                WHERE id = ?
                """,
                (
                    str(archived_path),
                    archived_path.name,
                    timestamp,
                    current_id,
                ),
            )
        storage.conn.execute(
            """
            UPDATE resources
            SET stored_path = ?, display_name = ?, storage_mode = 'managed', missing_status = '', updated_at = ?
            WHERE id = ?
            """,
            (
                str(target_path),
                clean_text(candidate.get("original_filename") or candidate.get("display_name") or target_path.name),
                timestamp,
                int(resource_id),
            ),
        )
        storage.conn.execute(
            """
            UPDATE papers
            SET primary_resource_id = ?,
                preferred_resource_id = CASE WHEN ? THEN ? ELSE preferred_resource_id END,
                preferred_resource_manual = CASE WHEN ? THEN 1 ELSE preferred_resource_manual END,
                main_pdf_path = ?, merged_pdf_path = ?, download_status = 'success',
                download_message = ?, downloaded_at = ?
            WHERE paper_id = ?
            """,
            (
                int(resource_id),
                1 if manual_preferred else 0,
                int(resource_id),
                1 if manual_preferred else 0,
                str(target_path),
                str(target_path),
                "preferred PDF selected" if manual_preferred else "new publication version selected",
                timestamp,
                str(paper_id),
            ),
        )
        storage.conn.commit()
    except Exception:
        storage.conn.rollback()
        try:
            if candidate_copied and target_path.exists():
                target_path.unlink()
            if candidate_moved and target_path.exists() and not candidate_original.exists():
                candidate_original.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(target_path), str(candidate_original))
            if archived_path and archived_path.exists():
                if archive_moved and current_path and not current_path.exists():
                    current_path.parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(str(archived_path), str(current_path))
                elif not archive_moved:
                    archived_path.unlink()
        except OSError:
            pass
        raise
    try:
        sync_all_pdf_aliases_for_paper(
            storage,
            str(paper_id),
            old_target=current_path if current_private else None,
            preserve_canonical_name=True,
        )
    except (OSError, sqlite3.Error):
        # The primary transition is committed and recoverable; do not roll back
        # preference/classification after a later alias operation has failed.
        logging.getLogger(__name__).exception("Default PDF saved but folder links could not be synchronized for %s", paper_id)
        storage.conn.rollback()
        storage.conn.execute(
            "UPDATE papers SET download_message = ? WHERE paper_id = ?",
            ("Default PDF saved; some folder links could not be updated.", str(paper_id)),
        )
        storage.conn.commit()
    resources = storage.list_paper_resources(str(paper_id), ensure_primary=False)
    return next(
        (resource for resource in resources if int(resource.get("id") or 0) == int(resource_id)),
        storage.get_paper_resource(int(resource_id)) or {},
    )


def active_local_pdf_dirs_for_paper(storage: Storage, paper_id: str) -> list[Path]:
    paper_id = storage.resolve_paper_id(paper_id)
    if not paper_id:
        return []
    # Directory lookup is also used inside file-move transactions. It must
    # never create a special folder and commit the caller's pending changes.
    recycle = storage.conn.execute(
        "SELECT id FROM library_folders WHERE parent_id=1 AND name=? COLLATE NOCASE",
        (LIBRARY_RECYCLE_FOLDER_NAME,),
    ).fetchone()
    recycle_id = int(recycle["id"]) if recycle else 0
    rows = storage.conn.execute(
        """
        SELECT id, folder_id, trashed_at
        FROM library_items
        WHERE paper_id = ?
        ORDER BY id ASC
        """,
        (str(paper_id),),
    ).fetchall()
    directories: list[Path] = []
    for row in rows:
        folder_id = int(row["folder_id"] or 0)
        if not folder_id or row["trashed_at"]:
            continue
        if recycle_id and library_folder_is_within(storage, folder_id, recycle_id):
            continue
        directories.append(local_copy_dir_for_library_folder(storage, folder_id))
    if paper_has_my_publication_reference(storage, paper_id):
        directories.append(MY_PUBLICATIONS_LOCAL_COPY_ROOT)
    unique: list[Path] = []
    seen: set[str] = set()
    for directory in directories:
        key = str(directory.expanduser().resolve())
        if key in seen:
            continue
        seen.add(key)
        unique.append(directory)
    return unique


def preferred_local_pdf_dir_for_paper(storage: Storage, paper_id: str) -> Path | None:
    paper_id = storage.resolve_paper_id(paper_id)
    directories = active_local_pdf_dirs_for_paper(storage, paper_id)
    if not directories:
        return None
    canonical = canonical_file_path_for_paper(storage.get_paper(paper_id))
    if canonical:
        canonical_parent = canonical.parent.resolve()
        for directory in directories:
            if directory.expanduser().resolve() == canonical_parent:
                return directory
    return directories[0]


def paper_pdf_paths(paper: dict[str, Any] | None) -> list[Path]:
    if not paper:
        return []
    raw_paths: list[Any] = [paper.get("merged_pdf_path"), paper.get("main_pdf_path")]
    raw_supplements = paper.get("supplement_pdf_paths") or ""
    if isinstance(raw_supplements, list):
        raw_paths.extend(raw_supplements)
    elif raw_supplements:
        try:
            supplements = json.loads(raw_supplements)
        except (TypeError, json.JSONDecodeError):
            supplements = []
        if isinstance(supplements, list):
            raw_paths.extend(supplements)
    paths: list[Path] = []
    seen: set[str] = set()
    for raw_path in raw_paths:
        if not raw_path:
            continue
        try:
            path = Path(str(raw_path)).expanduser().resolve()
        except OSError:
            continue
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        paths.append(path)
    return paths


def pdf_path_referenced_by_other_paper(storage: Storage, path: Path, paper_id: str) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    requested = path.expanduser().resolve()
    rows = storage.conn.execute(
        """
        SELECT paper_id, main_pdf_path, merged_pdf_path, supplement_pdf_paths, source_path
        FROM papers
        WHERE paper_id != ?
        """,
        (str(paper_id),),
    ).fetchall()
    for row in rows:
        other = dict(row)
        candidates = paper_pdf_paths(other)
        raw_source = str(other.get("source_path") or "")
        if raw_source:
            try:
                candidates.append(Path(raw_source).expanduser().resolve())
            except OSError:
                pass
        if any(candidate == requested for candidate in candidates):
            return True
    resource_rows = storage.conn.execute(
        """
        SELECT source_path, stored_path
        FROM resources
        WHERE paper_id IS NULL OR paper_id != ?
        """,
        (str(paper_id),),
    ).fetchall()
    for row in resource_rows:
        for raw_path in (row["source_path"], row["stored_path"]):
            if not raw_path:
                continue
            try:
                if Path(str(raw_path)).expanduser().resolve() == requested:
                    return True
            except OSError:
                continue
    return False


def paper_ids_referencing_pdf_path(storage: Storage, path: Path, *, include_resources: bool = False) -> list[str]:
    requested = path.expanduser().resolve()
    values = {
        str(path),
        str(path.expanduser().absolute()),
        str(requested),
    }
    # macOS exposes the same filesystem locations through both /var and
    # /private/var (likewise /tmp and /private/tmp).  SQLite may contain the
    # spelling used before Path.resolve(), so include both aliases without
    # falling back to an expensive scan of every paper on each rename.
    for value in list(values):
        if value.startswith("/private/var/") or value.startswith("/private/tmp/"):
            values.add(value.removeprefix("/private"))
        elif value.startswith("/var/") or value.startswith("/tmp/"):
            values.add(f"/private{value}")
    values = sorted(values)
    rows = storage.conn.execute(
        f"""
        SELECT paper_id
        FROM papers
        WHERE main_pdf_path IN ({",".join("?" for _ in values)})
           OR merged_pdf_path IN ({",".join("?" for _ in values)})
           OR source_path IN ({",".join("?" for _ in values)})
        """,
        [*values, *values, *values],
    ).fetchall()
    if include_resources:
        slots = ",".join("?" for _ in values)
        rows += storage.conn.execute(
            f"SELECT paper_id FROM resources WHERE stored_path IN ({slots}) OR source_path IN ({slots})",
            [*values, *values],
        ).fetchall()
        rows += storage.conn.execute(
            f"SELECT paper_id FROM papers WHERE analysis_path IN ({slots})", values,
        ).fetchall()
        rows += storage.conn.execute(
            f"""SELECT DISTINCT papers.paper_id FROM papers,
                json_each(CASE WHEN json_valid(supplement_pdf_paths) THEN supplement_pdf_paths ELSE '[]' END) AS paths
                WHERE paths.value IN ({slots})""", values,
        ).fetchall()
    return sorted(
        dict.fromkeys(str(row["paper_id"] or "") for row in rows if row["paper_id"])
    )


def retire_replaced_managed_pdf_paths(
    storage: Storage,
    *,
    paper_id: str,
    old_paths: list[Path],
    new_path: Path,
) -> tuple[list[str], list[str]]:
    paper_id = storage.resolve_paper_id(paper_id)
    managed_roots = allowed_pdf_roots()
    replacement = new_path.expanduser().resolve()
    trashed: list[str] = []
    warnings: list[str] = []
    for old_path in old_paths:
        requested = old_path.expanduser().resolve()
        if requested == replacement or not requested.exists() or not requested.is_file():
            continue
        # A dragged external source is never Gewu Insight's file to remove. Shared managed
        # files also remain until every paper has stopped referencing them.
        if not is_allowed_file(requested, managed_roots):
            continue
        if pdf_path_referenced_by_other_paper(storage, requested, str(paper_id)):
            continue
        try:
            move_path_to_macos_trash(requested)
            trashed.append(str(requested))
        except (OSError, subprocess.SubprocessError) as exc:
            warnings.append(f"old PDF retained: {clean_text(str(exc)) or requested.name}")
    if trashed:
        clear_deleted_library_file_references(storage, trashed)
        for root in managed_roots:
            cleanup_empty_parents(trashed, root)
    return trashed, warnings


def attach_manual_pdf_to_paper(
    storage: Storage,
    *,
    paper_id: str,
    filename: str,
    context: dict[str, Any],
    content: bytes | None = None,
    source_path: Path | None = None,
    preserve_filename: bool = False,
) -> tuple[Path, dict[str, Any]]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    old_canonical = canonical_pdf_path_for_paper(paper)
    old_pdf_paths = paper_pdf_paths(paper)
    replacing = bool(old_pdf_paths)
    old_canonical_is_shared = bool(
        old_canonical
        and pdf_path_referenced_by_other_paper(storage, old_canonical, str(paper_id))
    )
    original_name = Path(str(filename or "")).name
    if not original_name.lower().endswith(".pdf"):
        raise ValueError("Dropped file must be a PDF")
    resolved_source: Path | None = None
    if source_path is not None:
        resolved_source = source_path.expanduser().resolve()
        if not resolved_source.exists() or not resolved_source.is_file():
            raise FileNotFoundError(f"PDF file was not found: {source_path}")
        valid_pdf = is_valid_pdf_file(resolved_source)
    else:
        valid_pdf = is_valid_pdf_bytes(bytes(content or b""))
    if not valid_pdf:
        raise ValueError("Dropped file must be a valid PDF")

    target_dir = local_copy_dir_for_download_context(storage, context) or (DEFAULT_PDF_DIR / str(paper_id))
    target_dir.mkdir(parents=True, exist_ok=True)
    if preserve_filename:
        target_name = finder_safe_name(original_name, f"{safe_slug(paper.get('title') or paper_id, 80)}.pdf")
        if not target_name.lower().endswith(".pdf"):
            target_name = f"{target_name}.pdf"
    else:
        target_name = f"{safe_slug(paper.get('title') or paper_id, 80)}_manual.pdf"
    target_path = unique_path_in_dir(target_dir / target_name)
    if resolved_source is not None:
        shutil.copy2(resolved_source, target_path)
    else:
        target_path.write_bytes(bytes(content or b""))
    try:
        storage.update_download_status(
            str(paper_id),
            status="success",
            message=f"manual PDF {'replaced' if replacing else 'imported'}: {original_name}",
            main_pdf_path=str(target_path),
            supplement_pdf_paths=[],
            merged_pdf_path=str(target_path),
        )
    except Exception:
        try:
            target_path.unlink()
        except OSError:
            pass
        raise
    warnings: list[str] = []
    try:
        sync_all_pdf_aliases_for_paper(
            storage,
            str(paper_id),
            old_target=None if old_canonical_is_shared else old_canonical,
        )
    except (OSError, sqlite3.Error) as exc:
        warnings.append(f"shortcut sync incomplete: {clean_text(str(exc)) or type(exc).__name__}")
    else:
        _, retirement_warnings = retire_replaced_managed_pdf_paths(
            storage,
            paper_id=str(paper_id),
            old_paths=old_pdf_paths,
            new_path=target_path,
        )
        warnings.extend(retirement_warnings)
    if warnings:
        storage.conn.execute(
            "UPDATE papers SET download_message = ? WHERE paper_id = ?",
            (
                f"manual PDF {'replaced' if replacing else 'imported'}: {original_name}; "
                + "; ".join(warnings),
                str(paper_id),
            ),
        )
        storage.conn.commit()
    updated = storage.get_paper(str(paper_id))
    if not updated:
        raise KeyError(str(paper_id))
    return target_path, updated


def attach_science_supplement_to_paper(
    storage: Storage, *, paper_id: str, context: dict[str, Any], supplement_path: Path,
) -> tuple[Path, dict[str, Any]]:
    """Merge into the downloaded Science version, retaining any manual Default."""
    paper = storage.get_paper(paper_id)
    requested_id = int(context.get("publisher_main_resource_id") or 0)
    resource = storage.get_paper_resource(requested_id) if requested_id else None
    if requested_id and (not resource or resource.get("paper_id") != paper_id
                         or resource.get("file_type") not in {"published_version", "accepted_manuscript"}):
        raise ValueError("The downloaded Science main paper file is no longer available")
    path_text = storage.resource_local_path(resource) if resource else ""
    main_path = Path(path_text).expanduser().resolve() if path_text else canonical_pdf_path_for_paper(paper)
    if not main_path or not is_valid_pdf_file(main_path):
        raise ValueError("The main PDF must be downloaded before its supplementary PDF")
    rejection = science_main_pdf_rejection(main_path)
    if rejection:
        raise ValueError("The saved PDF contains supplementary material without the Science main article. Refresh the main PDF before merging supplements.")
    is_canonical = main_path == canonical_pdf_path_for_paper(paper)
    if not resource:
        resource = next((item for item in storage.list_paper_resources(paper_id, ensure_primary=False)
                         if storage.resource_local_path(item)
                         and Path(storage.resource_local_path(item)).expanduser().resolve() == main_path), None)
    can_replace = (is_allowed_file(main_path, allowed_pdf_roots())
                   and not pdf_path_referenced_by_other_paper(storage, main_path, paper_id)
                   and (not resource or resource.get("storage_mode") != "linked"))
    if can_replace:
        target = main_path
    else:
        target_dir = local_copy_dir_for_download_context(storage, context) or (DEFAULT_PDF_DIR / paper_id)
        target_dir.mkdir(parents=True, exist_ok=True)
        target = unique_path_in_dir(target_dir / f"{safe_slug(paper.get('title') or paper_id, 80)}_merged.pdf")
    working = target.with_name(f".{target.stem}-supplement-{uuid.uuid4().hex}.pdf")
    backup = working.with_suffix(".original")
    published = False
    committed = False
    try:
        if not merge_science_pdfs(main_path, [supplement_path], working):
            return main_path, paper
        fingerprint = fingerprint_file(working)
        page_count = len(PdfReader(str(working)).pages)
        if can_replace:
            shutil.copy2(main_path, backup)
        storage.conn.execute("SAVEPOINT science_supplement")
        try:
            if not resource:
                resource = storage.ensure_primary_pdf_resource(paper_id, commit=False)
            if not resource:
                raise ValueError("The Science main paper file could not be registered")
            working.replace(target)
            published = True
            storage.conn.execute(
                """UPDATE resources SET stored_path = ?, storage_mode = 'managed',
                    display_name = ?, sha256 = ?, content_sha256 = ?, size_bytes = ?,
                    page_count = ?, modified_at = ?, annotation_count = ?,
                    is_annotated = CASE WHEN COALESCE(annotation_override, 0) = 1 THEN is_annotated ELSE ? END,
                    annotation_state = CASE WHEN COALESCE(annotation_override, 0) = 1 THEN annotation_state ELSE ? END,
                    missing_status = '', updated_at = ? WHERE id = ? AND paper_id = ?""",
                (str(target), resource.get("display_name") if target == main_path else target.name,
                 fingerprint.sha256, fingerprint.content_sha256, fingerprint.size_bytes, page_count,
                 fingerprint.modified_at, fingerprint.annotation_count, int(fingerprint.is_annotated),
                 "annotated" if fingerprint.is_annotated else "unannotated", now_iso(), resource["id"], paper_id),
            )
            storage.conn.execute(
                """UPDATE papers SET download_status = 'success', download_message = ?, downloaded_at = ?,
                    main_pdf_path = COALESCE(?, main_pdf_path), merged_pdf_path = COALESCE(?, merged_pdf_path),
                    supplement_pdf_paths = CASE WHEN ? THEN '[]' ELSE supplement_pdf_paths END
                    WHERE paper_id = ?""",
                ("downloaded and merged Science supplementary PDF; temporary PDF removed", now_iso(),
                 str(target) if is_canonical else None, str(target) if is_canonical else None,
                 is_canonical, paper_id),
            )
            storage.conn.execute("RELEASE science_supplement")
            storage.conn.commit()
            committed = True
        except Exception:
            try:
                storage.conn.execute("ROLLBACK TO science_supplement")
                storage.conn.execute("RELEASE science_supplement")
            except sqlite3.Error:
                storage.conn.rollback()
            if published:
                if can_replace:
                    backup.replace(main_path)
                else:
                    target.unlink(missing_ok=True)
                published = False
            raise
    finally:
        working.unlink(missing_ok=True)
        # If restoring bytes itself fails, retain the recovery copy.
        if not published or committed:
            backup.unlink(missing_ok=True)
    if is_canonical:
        try:
            sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=main_path if target != main_path else None)
        except (OSError, sqlite3.Error):
            logging.getLogger(__name__).exception("Science PDF saved; shortcut sync incomplete for %s", paper_id)
    return target, storage.get_paper(paper_id)


@serialize_paper_file_writes
def attach_publisher_supplement_pdf_to_paper(
    storage: Storage,
    *,
    paper_id: str,
    context: dict[str, Any],
    source_path: Path,
) -> tuple[Path, dict[str, Any]]:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(str(paper_id))
    if not paper:
        raise KeyError(str(paper_id))
    is_science = clean_text(context.get("publisher_download_kind") or "") == "aaas-supplement-pdf"
    main_path = canonical_pdf_path_for_paper(paper)
    if not main_path and not is_science:
        raise ValueError("The main PDF must be downloaded before its supplementary PDF")
    source_supplement_path = source_path.expanduser().resolve()
    if not source_supplement_path.exists() or not source_supplement_path.is_file():
        raise FileNotFoundError(f"PDF file was not found: {source_path}")
    converted_path: Path | None = None
    supplement_path = source_supplement_path
    if is_valid_pdf_file(supplement_path):
        pass
    elif supplement_path.suffix.lower() in {".doc", ".docx"}:
        converted_path = supplement_path.with_name(
            f".{supplement_path.stem}-converted-{uuid.uuid4().hex}.pdf"
        )
        try:
            supplement_path = convert_word_document_to_pdf(supplement_path, converted_path)
        except Exception:
            converted_path.unlink(missing_ok=True)
            raise
    else:
        raise ValueError("Publisher supplement must be a valid PDF, DOC, or DOCX file")

    if is_science:
        try:
            return attach_science_supplement_to_paper(
                storage, paper_id=str(paper_id), context=context, supplement_path=supplement_path,
            )
        finally:
            if converted_path:
                converted_path.unlink(missing_ok=True)

    main_is_shared = pdf_path_referenced_by_other_paper(storage, main_path, str(paper_id))
    can_replace_in_place = is_allowed_file(main_path, allowed_pdf_roots()) and not main_is_shared
    if can_replace_in_place:
        target_path = main_path
        working_path = main_path.with_name(f".{main_path.stem}-supplement-{uuid.uuid4().hex}.pdf")
    else:
        target_dir = local_copy_dir_for_download_context(storage, context) or (DEFAULT_PDF_DIR / str(paper_id))
        target_dir.mkdir(parents=True, exist_ok=True)
        target_path = unique_path_in_dir(
            target_dir / f"{safe_slug(paper.get('title') or paper_id, 80)}_merged.pdf"
        )
        working_path = target_path

    try:
        merge_pdfs([main_path, supplement_path], working_path)
        if can_replace_in_place:
            working_path.replace(target_path)
        storage.update_download_status(
            str(paper_id),
            status="success",
            message=(
                "downloaded and merged Science supplementary PDF; temporary PDF removed"
                if clean_text(context.get("publisher_download_kind") or "") == "aaas-supplement-pdf"
                else "downloaded and merged publisher supplementary file; temporary file removed"
            ),
            main_pdf_path=str(target_path),
            supplement_pdf_paths=[],
            merged_pdf_path=str(target_path),
        )
        sync_all_pdf_aliases_for_paper(
            storage,
            str(paper_id),
            old_target=main_path if target_path != main_path else None,
        )
    except Exception:
        if working_path != target_path or target_path != main_path:
            working_path.unlink(missing_ok=True)
        raise
    finally:
        if converted_path:
            converted_path.unlink(missing_ok=True)

    updated = storage.get_paper(str(paper_id))
    if not updated:
        raise KeyError(str(paper_id))
    return target_path, updated


def canonical_pdf_path_for_paper(paper: dict[str, Any] | None) -> Path | None:
    if not paper:
        return None
    for key in ("merged_pdf_path", "main_pdf_path"):
        raw = str(paper.get(key) or "")
        if not raw:
            continue
        path = Path(raw).expanduser()
        if path.exists() and path.is_file():
            return path.resolve()
    return None


def canonical_file_path_for_paper(paper: dict[str, Any] | None) -> Path | None:
    pdf = canonical_pdf_path_for_paper(paper)
    if pdf:
        return pdf
    layout = parse_raw_json(paper).get("file_layout", {})
    raw = layout.get("canonical_path") if isinstance(layout, dict) else ""
    if raw and Path(raw).is_file():
        return Path(raw).resolve()
    return None


def unique_path_in_dir(path: Path) -> Path:
    if not path.exists() and not finder_alias.is_alias(path):
        return path
    parent = path.parent
    stem = path.stem
    suffix = path.suffix
    for index in range(2, 1000):
        candidate = parent / f"{stem} {index}{suffix}"
        if not candidate.exists() and not finder_alias.is_alias(candidate):
            return candidate
    raise FileExistsError(str(path))


def library_item_export_filename(item: dict[str, Any], source: Path) -> str:
    display_name = clean_text(item.get("display_name") or "")
    if not display_name:
        return finder_safe_name(source.name, "file")
    filename = finder_safe_name(display_name, source.stem or "file")
    if source.suffix and not filename.lower().endswith(source.suffix.lower()):
        filename = f"{filename}{source.suffix}"
    return filename


def copy_library_folder_real_files(
    storage: Storage,
    folder_id: int,
    destination_parent: Path,
    *,
    unique_root: bool,
) -> dict[str, Any]:
    folder = storage.get_library_folder(folder_id)
    if not folder:
        raise ValueError("Library folder not found")
    destination_parent.mkdir(parents=True, exist_ok=True)
    requested_root = destination_parent / finder_safe_name(
        folder.get("name") or "Library Folder",
        "Library Folder",
    )
    target_root = unique_path_in_dir(requested_root) if unique_root else requested_root
    folders = library_folder_tree_rows(storage, folder_id)
    relative_by_id = library_folder_export_relative_paths(folders, folder_id)
    for export_folder_id, relative_path in relative_by_id.items():
        (target_root / relative_path).mkdir(parents=True, exist_ok=True)
    copied = 0
    missing = 0
    associated_copied = 0
    associated_missing = 0
    manifest_items: list[dict[str, Any]] = []
    exported_papers: set[str] = set()
    for item in library_items_in_folder_tree(storage, folder_id):
        item_folder_id = int(item.get("folder_id") or folder_id)
        export_dir = target_root / relative_by_id.get(item_folder_id, Path())
        export_dir.mkdir(parents=True, exist_ok=True)
        paper_id = str(item.get("paper_id") or "")
        paper = storage.get_paper(paper_id)
        source = library_item_real_file_for_export(paper)
        if not source:
            missing += 1
            continue
        target = unique_path_in_dir(
            export_dir / library_item_export_filename(item, source)
        )
        shutil.copy2(source, target)
        copied += 1
        manifest_item = {
            "library_item_id": int(item.get("id") or 0),
            "paper_id": paper_id,
            "storage_key": clean_text((paper or {}).get("storage_key") or ""),
            "display_name": clean_text(item.get("display_name") or ""),
            "folder": str(relative_by_id.get(item_folder_id, Path())),
            "primary_file": str(target.relative_to(target_root)),
            "resources": [],
        }
        if paper_id not in exported_papers:
            exported_papers.add(paper_id)
            storage_key = clean_text((paper or {}).get("storage_key") or "") or storage.storage_key_for_paper_id(paper_id)
            bundle_name = finder_safe_name(f"{target.stem} [{storage_key}]", f"Paper [{storage_key}]")
            bundle_root = target_root / "Associated Files" / relative_by_id.get(item_folder_id, Path()) / bundle_name
            primary_id = int((paper or {}).get("primary_resource_id") or 0)
            for resource in storage.list_paper_resources(paper_id):
                resource_path_text = storage.resource_local_path(resource)
                resource_path = Path(resource_path_text).expanduser() if resource_path_text else None
                resource_entry = {
                    "resource_id": int(resource.get("id") or 0),
                    "file_role": clean_text(resource.get("file_role") or "other"),
                    "version_role": clean_text(resource.get("version_role") or ""),
                    "version_label": clean_text(resource.get("version_label") or ""),
                    "sha256": clean_text(resource.get("sha256") or ""),
                    "is_primary": int(resource.get("id") or 0) == primary_id,
                    "file": "",
                }
                if int(resource.get("id") or 0) == primary_id:
                    resource_entry["file"] = str(target.relative_to(target_root))
                elif resource_path and resource_path.is_file():
                    role_dir = bundle_root / associated_resource_subdir(str(resource.get("file_role") or "other"))
                    role_dir.mkdir(parents=True, exist_ok=True)
                    resource_target = unique_path_in_dir(role_dir / finder_safe_name(resource_path.name, "Attached File"))
                    shutil.copy2(resource_path, resource_target)
                    resource_entry["file"] = str(resource_target.relative_to(target_root))
                    associated_copied += 1
                else:
                    associated_missing += 1
                manifest_item["resources"].append(resource_entry)
        manifest_items.append(manifest_item)
    manifest = {
        "format": "Gewu Insight Complete Folder Export",
        "format_version": 1,
        "exported_at": now_iso(),
        "source_folder_id": int(folder_id),
        "source_folder_name": clean_text(folder.get("name") or "Library Folder"),
        "items": manifest_items,
    }
    manifest_path = target_root / "Gewu Insight Manifest.json"
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    return {
        "desktop_path": str(target_root),
        "folder_name": target_root.name,
        "files_copied": copied,
        "missing_files": missing,
        "associated_files_copied": associated_copied,
        "associated_missing_files": associated_missing,
        "manifest_path": str(manifest_path),
        "folders_created": len(relative_by_id),
    }


def copy_library_folder_real_files_to_desktop(storage: Storage, folder_id: int) -> dict[str, Any]:
    return copy_library_folder_real_files(
        storage,
        folder_id,
        Path.home() / "Desktop",
        unique_root=True,
    )


def prepare_library_folder_real_files_for_drag(storage: Storage, folder_id: int) -> dict[str, Any]:
    staging_parent = Path(tempfile.mkdtemp(prefix="daiqo-folder-drag-"))
    try:
        result = copy_library_folder_real_files(
            storage,
            folder_id,
            staging_parent,
            unique_root=False,
        )
    except Exception:
        shutil.rmtree(staging_parent, ignore_errors=True)
        raise
    result["cleanup_path"] = str(staging_parent)
    return result


def library_folder_tree_rows(storage: Storage, folder_id: int) -> list[dict[str, Any]]:
    rows = storage.conn.execute(
        """
        WITH RECURSIVE folder_tree(id) AS (
          SELECT id FROM library_folders WHERE id = ?
          UNION ALL
          SELECT library_folders.id
          FROM library_folders
          JOIN folder_tree ON library_folders.parent_id = folder_tree.id
        )
        SELECT *
        FROM library_folders
        WHERE id IN (SELECT id FROM folder_tree)
        ORDER BY COALESCE(parent_id, 0), sort_order, name
        """,
        (int(folder_id),),
    ).fetchall()
    return [dict(row) for row in rows]


def library_folder_export_relative_paths(folders: list[dict[str, Any]], root_folder_id: int) -> dict[int, Path]:
    by_id = {int(folder.get("id") or 0): folder for folder in folders}
    result: dict[int, Path] = {}
    root_folder_id = int(root_folder_id)

    def relative_for(folder_id: int) -> Path:
        if folder_id in result:
            return result[folder_id]
        if folder_id == root_folder_id:
            result[folder_id] = Path()
            return result[folder_id]
        folder = by_id.get(folder_id)
        if not folder:
            result[folder_id] = Path()
            return result[folder_id]
        parent_id = int(folder.get("parent_id") or root_folder_id)
        parent_relative = relative_for(parent_id)
        result[folder_id] = parent_relative / finder_safe_name(folder.get("name") or "Folder", "Folder")
        return result[folder_id]

    for folder_id in by_id:
        relative_for(folder_id)
    return result


def library_item_real_file_for_export(paper: dict[str, Any] | None) -> Path | None:
    if not paper:
        return None
    canonical = canonical_file_path_for_paper(paper)
    if canonical:
        return canonical
    raw = parse_raw_json(paper)
    imported = raw.get("import") if isinstance(raw.get("import"), dict) else {}
    for key in ("stored_path",):
        value = clean_text(imported.get(key) or "")
        path = Path(value).expanduser() if value else None
        if path and path.exists() and path.is_file():
            return path.resolve()
    for key in ("source_path",):
        value = clean_text(paper.get(key) or "")
        path = Path(value).expanduser() if value else None
        if path and path.exists() and path.is_file():
            return path.resolve()
    return None


def pdf_file_path_for_rename(paper: dict[str, Any] | None) -> Path | None:
    if not paper:
        return None
    candidates: list[str] = []
    for key in ("merged_pdf_path", "main_pdf_path", "source_path"):
        value = clean_text(paper.get(key) or "")
        if value:
            candidates.append(value)
    raw = parse_raw_json(paper)
    imported = raw.get("import") if isinstance(raw.get("import"), dict) else {}
    value = clean_text(imported.get("stored_path") or "")
    if value:
        candidates.append(value)
    for value in candidates:
        path = Path(value).expanduser()
        if path.exists() and path.is_file() and path.suffix.lower() == ".pdf":
            return path.resolve()
    return None


def paper_pdf_basename(paper: dict[str, Any], canonical_path: Path | None = None) -> str:
    if canonical_path:
        return finder_safe_name(canonical_path.name, "paper.pdf")
    title = paper.get("title") or paper.get("paper_id") or "paper"
    return f"{safe_slug(title, 80)}_merged.pdf"


def update_paper_pdf_paths(storage: Storage, paper_id: str, path: Path, *, message: str = "local PDF moved") -> None:
    paper_id = storage.resolve_paper_id(paper_id)
    storage.update_download_status(
        paper_id,
        status="success",
        message=message,
        main_pdf_path=str(path),
        supplement_pdf_paths=[],
        merged_pdf_path=str(path),
    )


def update_paper_file_path_references(
    storage: Storage, paper_id: str, old_path: Path, new_path: Path, *, commit: bool = True,
) -> None:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(paper_id)
    if not paper:
        return
    old_value = str(old_path)
    new_value = str(new_path)
    updates: dict[str, str] = {}
    for key in ("main_pdf_path", "merged_pdf_path", "source_path", "analysis_path"):
        raw_value = str(paper.get(key) or "")
        try:
            matches_old = bool(raw_value) and Path(raw_value).expanduser().resolve() == old_path.expanduser().resolve()
        except OSError:
            matches_old = raw_value == old_value
        if matches_old:
            updates[key] = new_value
    supplements = paper.get("supplement_pdf_paths") or "[]"
    if isinstance(supplements, str):
        try:
            supplements = json.loads(supplements)
        except (TypeError, ValueError):
            supplements = []
    if isinstance(supplements, list):
        remapped = [new_value if value and Path(value).expanduser().resolve() == old_path.expanduser().resolve()
                    else value for value in supplements]
        if remapped != supplements:
            updates["supplement_pdf_paths"] = json.dumps(remapped, ensure_ascii=False)
    raw = parse_raw_json(paper)
    imported = raw.get("import") if isinstance(raw.get("import"), dict) else {}
    stored_path = clean_text(imported.get("stored_path") or "")
    try:
        stored_matches_old = bool(stored_path) and Path(stored_path).expanduser().resolve() == old_path.expanduser().resolve()
    except OSError:
        stored_matches_old = stored_path == old_value
    if stored_matches_old:
        imported["stored_path"] = new_value
        raw["import"] = imported
        updates["raw_json"] = json.dumps(raw, ensure_ascii=False)
    layout = raw.get("file_layout", {})
    if isinstance(layout, dict) and layout.get("canonical_path") == old_value:
        layout["canonical_path"] = new_value
        updates["raw_json"] = json.dumps(raw, ensure_ascii=False)
    # Update the file registration in the same transaction, including the case
    # where only a resource still refers to the old name. Source provenance for
    # managed copies remains unchanged; linked files use source_path directly.
    resource_updates = []
    for resource in storage.conn.execute(
        "SELECT id, stored_path, source_path, display_name FROM resources WHERE paper_id = ?", (paper_id,),
    ):
        field = "stored_path" if resource["stored_path"] else "source_path"
        value = str(resource[field] or "")
        try:
            matches = bool(value) and Path(value).expanduser().resolve() == old_path.expanduser().resolve()
        except OSError:
            matches = value == old_value
        if matches:
            display = resource["display_name"] or ""
            if not display or display == old_path.name:
                display = new_path.name
            resource_updates.append((int(resource["id"]), field, display))
    if not updates and not resource_updates:
        return
    storage.conn.execute("SAVEPOINT gewu_file_path_update")
    try:
        if updates:
            assignments = ", ".join(f"{key} = ?" for key in updates)
            storage.conn.execute(f"UPDATE papers SET {assignments} WHERE paper_id = ?", list(updates.values()) + [paper_id])
        for resource_id, field, display in resource_updates:
            storage.conn.execute(
                f"UPDATE resources SET {field} = ?, display_name = ?, missing_status = ?, updated_at = ? WHERE id = ? AND paper_id = ?",
                (new_value, display, "" if new_path.is_file() else "missing", now_iso(), resource_id, paper_id),
            )
        storage.conn.execute("RELEASE gewu_file_path_update")
        if commit:
            storage.conn.commit()
    except Exception:
        storage.conn.execute("ROLLBACK TO gewu_file_path_update")
        storage.conn.execute("RELEASE gewu_file_path_update")
        raise


def rename_library_item_pdf_from_metadata(storage: Storage, item_id: int) -> dict[str, Any]:
    item = storage.get_library_item(int(item_id or 0))
    if not item:
        raise ValueError("Library item not found")
    paper_id = str(item.get("paper_id") or "")
    paper = storage.get_paper(paper_id)
    if not paper:
        raise ValueError("Paper metadata not found")
    current_path = pdf_file_path_for_rename(paper)
    if not current_path:
        raise FileNotFoundError("No local PDF file was found for this item")
    template = pdf_rename_template(storage)
    values = pdf_rename_values_for_paper(paper)
    missing = missing_pdf_rename_metadata_tokens(template, values)
    if missing:
        return {
            "item_id": int(item_id),
            "paper_id": paper_id,
            "old_path": str(current_path),
            "new_path": str(current_path),
            "filename": current_path.name,
            "display_name": item.get("display_name") or "",
            "changed": False,
            "skipped": True,
            "missing": missing,
        }
    target_name = pdf_rename_filename_from_values(template, values, current_path.suffix or ".pdf")
    display_name = Path(target_name).stem
    renamed_item, updated_paper, _sync = rename_library_item_and_sync_files(
        storage,
        item_id=int(item_id),
        name=display_name,
    )
    target_path = library_item_local_pdf_path(storage, renamed_item, updated_paper) or current_path
    return {
        "item_id": int(item_id),
        "paper_id": paper_id,
        "old_path": str(current_path),
        "new_path": str(target_path),
        "filename": target_path.name,
        "display_name": renamed_item.get("display_name") or display_name,
        "changed": target_path != current_path or target_path.name != current_path.name,
    }


def local_copy_roots(*, include_legacy: bool = True) -> list[Path]:
    roots = [
        LIBRARY_LOCAL_COPY_ROOT.resolve(),
        SPACES_LOCAL_COPY_ROOT.resolve(),
        MY_PUBLICATIONS_LOCAL_COPY_ROOT.resolve(),
        ASSOCIATED_FILES_ROOT.resolve(),
    ]
    if include_legacy:
        roots.append(DEFAULT_LIBRARY_IMPORT_DIR.resolve())
    return roots


def cleanup_local_copy_empty_parents(deleted_paths: list[str]) -> None:
    for root in local_copy_roots(include_legacy=True):
        cleanup_empty_parents(deleted_paths, root)


def cleanup_monitor_pdf_cache_for_db(db_path: Path, *, retention_days: int = MONITOR_PDF_CACHE_RETENTION_DAYS) -> dict[str, Any]:
    try:
        storage = Storage(db_path)
        try:
            return cleanup_monitor_pdf_cache(storage, retention_days=retention_days)
        finally:
            storage.close()
    except Exception as exc:
        return {"deleted": [], "cleared_paper_ids": [], "retention_days": retention_days, "error": str(exc)}


def cleanup_monitor_pdf_cache(
    storage: Storage,
    *,
    pdf_dir: Path = DEFAULT_PDF_DIR,
    retention_days: int = MONITOR_PDF_CACHE_RETENTION_DAYS,
) -> dict[str, Any]:
    root = pdf_dir.expanduser().resolve()
    if retention_days <= 0 or not root.exists():
        return {"deleted": [], "cleared_paper_ids": [], "retention_days": retention_days}
    cutoff = time.time() - (retention_days * 24 * 60 * 60)
    deleted: list[str] = []
    cleared_paper_ids: list[str] = []
    rows = storage.conn.execute(
        """
        SELECT papers.*
        FROM papers
        WHERE (main_pdf_path IS NOT NULL OR merged_pdf_path IS NOT NULL OR supplement_pdf_paths IS NOT NULL)
          AND NOT EXISTS (
            SELECT 1 FROM library_items WHERE library_items.paper_id = papers.paper_id
          )
          AND NOT EXISTS (
            SELECT 1 FROM my_publications WHERE my_publications.paper_id = papers.paper_id
          )
        """
    ).fetchall()
    for row in rows:
        paper = dict(row)
        cache_paths = monitor_pdf_cache_paths_for_paper(paper, root)
        if not cache_paths:
            continue
        existing_paths = [path for path in cache_paths if path.exists() and path.is_file()]
        if not existing_paths:
            continue
        stale_paths = [path for path in existing_paths if path_mtime_before(path, cutoff)]
        if len(stale_paths) != len(existing_paths):
            continue
        for path in stale_paths:
            try:
                move_path_to_macos_trash(path)
                deleted.append(str(path))
            except FileNotFoundError:
                continue
        storage.clear_download_status(str(paper.get("paper_id") or ""))
        cleared_paper_ids.append(str(paper.get("paper_id") or ""))

    referenced_paths = referenced_monitor_pdf_cache_paths(storage, root)
    for path in sorted(root.rglob("*.pdf")):
        try:
            resolved = path.expanduser().resolve()
        except OSError:
            continue
        if str(resolved) in referenced_paths or not path_mtime_before(resolved, cutoff):
            continue
        try:
            move_path_to_macos_trash(resolved)
            deleted.append(str(resolved))
        except FileNotFoundError:
            continue

    cleanup_empty_parents(deleted, root)
    return {
        "deleted": deleted,
        "cleared_paper_ids": cleared_paper_ids,
        "retention_days": retention_days,
    }


def monitor_pdf_cache_paths_for_paper(paper: dict[str, Any], root: Path) -> list[Path]:
    paths: list[Path] = []
    for key in ("merged_pdf_path", "main_pdf_path"):
        path = monitor_pdf_cache_path(paper.get(key), root)
        if path:
            paths.append(path)
    raw_supplements = paper.get("supplement_pdf_paths") or ""
    try:
        supplements = json.loads(raw_supplements) if raw_supplements else []
    except (TypeError, json.JSONDecodeError):
        supplements = []
    if isinstance(supplements, list):
        for item in supplements:
            path = monitor_pdf_cache_path(item, root)
            if path:
                paths.append(path)
    unique: dict[str, Path] = {}
    for path in paths:
        unique[str(path)] = path
    return list(unique.values())


def monitor_pdf_cache_path(raw_path: Any, root: Path) -> Path | None:
    if not raw_path:
        return None
    try:
        path = Path(str(raw_path)).expanduser().resolve()
    except OSError:
        return None
    return path if is_relative_to(path.parent, root) else None


def referenced_monitor_pdf_cache_paths(storage: Storage, root: Path) -> set[str]:
    rows = storage.conn.execute(
        "SELECT main_pdf_path, merged_pdf_path, supplement_pdf_paths FROM papers"
    ).fetchall()
    referenced: set[str] = set()
    for row in rows:
        for path in monitor_pdf_cache_paths_for_paper(dict(row), root):
            referenced.add(str(path))
    return referenced


def path_mtime_before(path: Path, cutoff: float) -> bool:
    try:
        return path.stat().st_mtime < cutoff
    except OSError:
        return False


def is_path_inside_dir(path: Path, folder: Path) -> bool:
    try:
        path.resolve().relative_to(folder.resolve())
        return True
    except (OSError, ValueError):
        return False


def remove_symlinks_to(target: Path, roots: list[Path]) -> list[str]:
    removed: list[str] = []
    try:
        target_resolved = target.expanduser().resolve()
    except OSError:
        return removed
    for root in roots:
        if not root.exists():
            continue
        for candidate in finder_alias.iter_aliases(root):
            try:
                if finder_alias.points_to(candidate, target_resolved):
                    candidate.unlink()
                    removed.append(str(candidate))
            except OSError:
                continue
    return removed


def remove_direct_symlinks_to(target: Path, folders: list[Path]) -> list[str]:
    removed: list[str] = []
    try:
        target_resolved = target.expanduser().resolve()
    except OSError:
        return removed
    for folder in folders:
        if not folder.exists() or not folder.is_dir():
            continue
        for candidate in folder.iterdir():
            if not finder_alias.is_alias(candidate):
                continue
            try:
                if finder_alias.points_to(candidate, target_resolved):
                    candidate.unlink()
                    removed.append(str(candidate))
            except OSError:
                continue
    return removed


def library_item_pdf_filename(
    item: dict[str, Any],
    paper: dict[str, Any],
    canonical_path: Path | None = None,
) -> str:
    if canonical_path and canonical_path.suffix.lower() != ".pdf":
        return library_item_export_filename(item, canonical_path)
    display_name = clean_text(item.get("display_name") or "")
    if not display_name:
        if canonical_path:
            return finder_safe_name(canonical_path.name, "paper.pdf")
        display_name = default_library_item_display_name(paper)
    filename = finder_safe_name(display_name, "paper")
    if not filename.lower().endswith(".pdf"):
        filename = f"{filename}.pdf"
    stem = Path(filename).stem[:116].strip(" .") or "paper"
    return f"{stem}.pdf"


def library_item_display_name_for_synced_filename(
    item: dict[str, Any],
    filename: str,
) -> str:
    original = clean_text(item.get("display_name") or "")
    return filename if original.lower().endswith(".pdf") or not original else Path(filename).stem


def library_item_local_pdf_path(
    storage: Storage,
    item: dict[str, Any],
    paper: dict[str, Any] | None = None,
) -> Path | None:
    paper = paper or storage.get_paper(str(item.get("paper_id") or ""))
    canonical = canonical_file_path_for_paper(paper)
    if not canonical:
        return None
    target_dir = local_copy_dir_for_library_folder(storage, int(item.get("folder_id") or 1)).resolve()
    if not target_dir.exists():
        return None
    desired_name = library_item_pdf_filename(item, paper, canonical)
    desired_path = target_dir / desired_name
    if desired_path.exists() or finder_alias.is_alias(desired_path):
        try:
            if finder_alias.resolve(desired_path) == canonical:
                return desired_path
        except OSError:
            pass
    shared_paper_ids = paper_ids_referencing_pdf_path(storage, canonical)
    canonical_owner_paper_id = shared_paper_ids[0] if shared_paper_ids else str(item.get("paper_id") or "")
    if (
        str(item.get("paper_id") or "") == canonical_owner_paper_id
        and canonical.parent.resolve() == target_dir
    ):
        return canonical
    for candidate in target_dir.iterdir():
        if not finder_alias.is_alias(candidate):
            continue
        try:
            if finder_alias.resolve(candidate) == canonical:
                return candidate
        except OSError:
            continue
    return None


def create_pdf_alias(
    canonical_path: Path,
    target_dir: Path,
    filename: str | None = None,
) -> Path | None:
    canonical = canonical_path.expanduser().resolve()
    target_dir.mkdir(parents=True, exist_ok=True)
    desired_name = finder_safe_name(filename or canonical.name, canonical.name)
    suffix = canonical.suffix
    if suffix and not desired_name.lower().endswith(suffix.lower()):
        desired_name = f"{desired_name}{suffix}"
    desired_path = target_dir / desired_name
    if desired_path == canonical:
        return canonical
    if finder_alias.points_to(desired_path, canonical):
        return finder_alias.ensure(canonical, desired_path)
    return finder_alias.create(canonical, unique_path_in_dir(desired_path))


def sync_alias_for_library_item(
    storage: Storage,
    paper_id: str,
    folder_id: int,
    *,
    item: dict[str, Any] | None = None,
) -> Path | None:
    """Create only the Finder alias required by one Library placement.

    Full-paper reconciliation is intentionally kept out of this hot path. A
    normal copy or alias-only move does not change the canonical PDF and must
    not rescan every placement of the paper.
    """
    paper_id = storage.resolve_paper_id(paper_id)
    paper_id = str(paper_id or "")
    folder_id = int(folder_id or 0)
    if not paper_id or not folder_id:
        return None
    if item is None:
        row = storage.conn.execute(
            """
            SELECT *
            FROM library_items
            WHERE paper_id = ? AND folder_id = ?
            ORDER BY id ASC
            LIMIT 1
            """,
            (paper_id, folder_id),
        ).fetchone()
        item = dict(row) if row else None
    paper = storage.get_paper(paper_id)
    if paper and not canonical_file_path_for_paper(paper):
        normalize_files(storage, paper_id)
        paper = storage.get_paper(paper_id)
    canonical = canonical_file_path_for_paper(paper)
    if not item or not paper or not canonical:
        return None
    old_target = rescue_active_original(storage, paper_id)
    if old_target:
        sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=old_target)
        paper = storage.get_paper(paper_id)
        canonical = canonical_file_path_for_paper(paper)
    target_dir = local_copy_dir_for_library_folder(storage, folder_id).resolve()
    alias = create_pdf_alias(
        canonical,
        target_dir,
        library_item_pdf_filename(item, paper, canonical),
    )
    sync_associated_aliases(storage, paper_id)
    return alias or library_item_local_pdf_path(storage, item, paper)


def sync_my_publication_alias(storage: Storage, paper_id: str) -> Path | None:
    paper_id = storage.resolve_paper_id(paper_id)
    old_target = rescue_active_original(storage, paper_id)
    sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=old_target, preserve_canonical_name=True)
    canonical = canonical_file_path_for_paper(storage.get_paper(paper_id))
    if not canonical:
        return None
    alias = create_pdf_alias(canonical, MY_PUBLICATIONS_LOCAL_COPY_ROOT, canonical.name)
    sync_associated_aliases(storage, paper_id)
    return alias


def sync_all_pdf_aliases_for_paper(
    storage: Storage,
    paper_id: str,
    *,
    old_target: Path | None = None,
    preserve_canonical_name: bool = False,
) -> dict[str, Any]:
    paper_id = storage.resolve_paper_id(paper_id)
    normalized = normalize_files(storage, paper_id)
    if normalized.get("old_target") and not old_target:
        old_target = normalized["old_target"]
    rescued_target = rescue_active_original(storage, paper_id)
    if rescued_target:
        if old_target:
            remove_symlinks_to(old_target, [LIBRARY_LOCAL_COPY_ROOT, MY_PUBLICATIONS_LOCAL_COPY_ROOT, SPACES_LOCAL_COPY_ROOT])
        old_target = rescued_target
    paper = storage.get_paper(str(paper_id))
    canonical = canonical_file_path_for_paper(paper)
    if not paper or not canonical:
        return {"paper_id": str(paper_id), "canonical_renamed": False, "aliases_updated": 0}
    shared_paper_ids = paper_ids_referencing_pdf_path(storage, canonical)
    if str(paper_id) not in shared_paper_ids:
        shared_paper_ids.append(str(paper_id))
        shared_paper_ids.sort()
    canonical_owner_paper_id = shared_paper_ids[0] if shared_paper_ids else str(paper_id)
    placeholders = ",".join("?" for _ in shared_paper_ids)
    rows = storage.conn.execute(
        f"""
        SELECT *
        FROM library_items
        WHERE paper_id IN ({placeholders})
        ORDER BY paper_id ASC, CASE WHEN trashed_at IS NULL THEN 0 ELSE 1 END, id ASC
        """,
        shared_paper_ids,
    ).fetchall()
    items = [dict(row) for row in rows]
    papers = {
        shared_paper_id: storage.get_paper(shared_paper_id)
        for shared_paper_id in shared_paper_ids
    }
    item_dirs = {
        int(item.get("id") or 0): local_copy_dir_for_library_folder(
            storage,
            int(item.get("folder_id") or 1),
        ).resolve()
        for item in items
    }
    alias_dirs = list(dict.fromkeys(item_dirs.values()))
    has_my_publication = bool(
        storage.conn.execute(
            f"SELECT 1 FROM my_publications WHERE paper_id IN ({placeholders}) LIMIT 1",
            shared_paper_ids,
        ).fetchone()
    )
    if has_my_publication:
        alias_dirs.append(MY_PUBLICATIONS_LOCAL_COPY_ROOT.resolve())
    removed: list[str] = []
    if old_target:
        removed.extend(
            remove_symlinks_to(
                old_target,
                [LIBRARY_LOCAL_COPY_ROOT, MY_PUBLICATIONS_LOCAL_COPY_ROOT, SPACES_LOCAL_COPY_ROOT],
            )
        )

    owner: dict[str, Any] | None = None
    canonical_parent = canonical.parent.resolve()
    for item in items:
        if (
            str(item.get("paper_id") or "") == canonical_owner_paper_id
            and item_dirs[int(item.get("id") or 0)] == canonical_parent
        ):
            owner = item
            break

    naming_owner = owner or next(
        (
            item
            for item in items
            if str(item.get("paper_id") or "") == canonical_owner_paper_id
        ),
        None,
    )
    canonical_renamed = False
    old_canonical = canonical
    owner_paper = papers.get(canonical_owner_paper_id) or paper
    if naming_owner and owner_paper and is_allowed_file(canonical, allowed_pdf_roots()) and not preserve_canonical_name:
        desired_name = library_item_pdf_filename(naming_owner, owner_paper, canonical)
        target_path = canonical.with_name(desired_name)
        if target_path != canonical:
            if finder_alias.is_alias(target_path):
                try:
                    if finder_alias.resolve(target_path) == canonical:
                        target_path.unlink()
                except OSError:
                    pass
            target_path = unique_path_in_dir(target_path)
            storage.conn.execute("SAVEPOINT gewu_pdf_rename")
            renamed = False
            try:
                canonical.rename(target_path)
                renamed = True
                for referenced_paper_id in shared_paper_ids or [str(paper_id)]:
                    update_paper_file_path_references(
                        storage, referenced_paper_id, canonical, target_path, commit=False,
                    )
                storage.conn.execute("RELEASE gewu_pdf_rename")
            except Exception:
                storage.conn.execute("ROLLBACK TO gewu_pdf_rename")
                storage.conn.execute("RELEASE gewu_pdf_rename")
                if renamed and target_path.exists() and not canonical.exists():
                    target_path.rename(canonical)
                raise
            canonical = target_path.resolve()
            canonical_renamed = True
            removed.extend(remove_direct_symlinks_to(old_canonical, alias_dirs))
        synced_display = library_item_display_name_for_synced_filename(naming_owner, canonical.name)
        if clean_text(naming_owner.get("display_name") or "") != synced_display:
            naming_owner = storage.rename_library_item(item_id=int(naming_owner["id"]), name=synced_display)
            items = [
                naming_owner if int(item.get("id") or 0) == int(naming_owner["id"]) else item
                for item in items
            ]
            owner = (
                naming_owner
                if owner and int(owner.get("id") or 0) == int(naming_owner["id"])
                else owner
            )

    for referenced_paper_id in shared_paper_ids or [str(paper_id)]:
        relocate_associated_work_dir(storage, referenced_paper_id, canonical)

    aliases_updated = 0
    item_names_adjusted = 0
    for item in items:
        item_id = int(item.get("id") or 0)
        target_dir = item_dirs[item_id]
        is_owner_item = bool(
            owner
            and item_id == int(owner.get("id") or 0)
            and str(item.get("paper_id") or "") == canonical_owner_paper_id
            and canonical.parent.resolve() == target_dir
        )
        if is_owner_item:
            continue
        item_paper = papers.get(str(item.get("paper_id") or ""))
        if not item_paper:
            continue
        desired_name = library_item_pdf_filename(item, item_paper, canonical)
        before = library_item_local_pdf_path(storage, item, item_paper)
        alias = create_pdf_alias(canonical, target_dir, desired_name)
        if alias and (not before or before != alias or before.name != alias.name):
            aliases_updated += 1
        if alias:
            synced_display = library_item_display_name_for_synced_filename(item, alias.name)
            if clean_text(item.get("display_name") or "") != synced_display:
                storage.rename_library_item(item_id=int(item["id"]), name=synced_display)
                item_names_adjusted += 1
    if has_my_publication:
        before = None
        if MY_PUBLICATIONS_LOCAL_COPY_ROOT.exists():
            for candidate in MY_PUBLICATIONS_LOCAL_COPY_ROOT.iterdir():
                if not finder_alias.is_alias(candidate):
                    continue
                try:
                    if finder_alias.resolve(candidate) == canonical:
                        before = candidate
                        break
                except OSError:
                    continue
        alias = create_pdf_alias(canonical, MY_PUBLICATIONS_LOCAL_COPY_ROOT, canonical.name)
        if alias and (not before or before != alias or before.name != alias.name):
            aliases_updated += 1

    # Remove obsolete shortcut names only after every valid alias for this
    # shared physical PDF has been created.  Multiple DOI/arXiv records may
    # legitimately point to the same target from the same Finder folder.
    valid_names_by_dir: dict[Path, set[str]] = {}
    refreshed_rows = storage.conn.execute(
        f"""
        SELECT *
        FROM library_items
        WHERE paper_id IN ({placeholders})
        ORDER BY paper_id ASC, id ASC
        """,
        shared_paper_ids,
    ).fetchall()
    for row in refreshed_rows:
        item = dict(row)
        target_dir = local_copy_dir_for_library_folder(
            storage,
            int(item.get("folder_id") or 1),
        ).resolve()
        item_paper = papers.get(str(item.get("paper_id") or ""))
        if not item_paper:
            continue
        valid_names_by_dir.setdefault(target_dir, set()).add(
            library_item_pdf_filename(item, item_paper, canonical)
        )
    if has_my_publication:
        valid_names_by_dir.setdefault(MY_PUBLICATIONS_LOCAL_COPY_ROOT.resolve(), set()).add(canonical.name)
    for target_dir, valid_names in valid_names_by_dir.items():
        if not target_dir.exists():
            continue
        for candidate in target_dir.iterdir():
            if not finder_alias.is_alias(candidate) or candidate.name in valid_names:
                continue
            try:
                if finder_alias.resolve(candidate) == canonical:
                    candidate.unlink()
                    removed.append(str(candidate))
            except OSError:
                continue
    cleanup_local_copy_empty_parents(removed)
    for referenced_paper_id in shared_paper_ids:
        sync_associated_aliases(storage, referenced_paper_id)
        finish_aliases(storage, referenced_paper_id)
    return {
        "paper_id": str(paper_id),
        "canonical_renamed": canonical_renamed,
        "old_path": str(old_canonical),
        "new_path": str(canonical),
        "aliases_updated": aliases_updated,
        "item_names_adjusted": item_names_adjusted,
    }


def rename_library_item_and_sync_files(
    storage: Storage,
    *,
    item_id: int,
    name: str,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    original = storage.get_library_item(int(item_id or 0))
    if not original:
        raise ValueError("Library item not found")
    paper_id = str(original.get("paper_id") or "")
    try:
        storage.rename_library_item(item_id=int(item_id), name=name)
        sync = sync_all_pdf_aliases_for_paper(storage, paper_id)
    except Exception:
        storage.rename_library_item(
            item_id=int(item_id),
            name=clean_text(original.get("display_name") or ""),
        )
        try:
            sync_all_pdf_aliases_for_paper(storage, paper_id)
        except Exception:
            pass
        raise
    item = storage.get_library_item(int(item_id))
    paper = storage.get_paper(paper_id)
    if not item or not paper:
        raise ValueError("Library paper not found")
    return item, paper, sync


def reconcile_all_library_pdf_names(storage: Storage) -> dict[str, Any]:
    rows = storage.conn.execute(
        """
        SELECT DISTINCT paper_id
        FROM library_items
        ORDER BY paper_id ASC
        """
    ).fetchall()
    result = {
        "papers_checked": 0,
        "papers_with_files": 0,
        "canonical_renamed": 0,
        "aliases_updated": 0,
        "item_names_adjusted": 0,
        "errors": [],
    }
    for row in rows:
        paper_id = str(row["paper_id"] or "")
        result["papers_checked"] += 1
        if not canonical_file_path_for_paper(storage.get_paper(paper_id)):
            continue
        result["papers_with_files"] += 1
        try:
            synced = sync_all_pdf_aliases_for_paper(storage, paper_id)
            result["canonical_renamed"] += int(bool(synced.get("canonical_renamed")))
            result["aliases_updated"] += int(synced.get("aliases_updated") or 0)
            result["item_names_adjusted"] += int(synced.get("item_names_adjusted") or 0)
        except Exception as exc:
            result["errors"].append({
                "paper_id": paper_id,
                "error": clean_text(str(exc)) or type(exc).__name__,
            })
    return result


def audit_library_pdf_names(storage: Storage, *, sample_limit: int = 20) -> dict[str, Any]:
    rows = storage.conn.execute(
        """
        SELECT *
        FROM library_items
        ORDER BY paper_id ASC, id ASC
        """
    ).fetchall()
    result = {
        "items_checked": 0,
        "items_with_files": 0,
        "mismatched_real_files": 0,
        "mismatched_shortcuts": 0,
        "missing_shortcuts": 0,
        "unowned_real_files": 0,
        "samples": [],
    }
    item_paper_ids = {
        str(row["paper_id"] or "")
        for row in rows
        if row["paper_id"]
    }
    papers: dict[str, dict[str, Any] | None] = {}
    canonical_paper_ids: dict[str, list[str]] = {}
    for paper_row in storage.conn.execute("SELECT * FROM papers").fetchall():
        paper_id = str(paper_row["paper_id"] or "")
        if paper_id not in item_paper_ids:
            continue
        paper = dict(paper_row)
        papers[paper_id] = paper
        canonical = canonical_file_path_for_paper(paper)
        if canonical:
            canonical_paper_ids.setdefault(str(canonical), []).append(paper_id)
    canonical_owner_ids = {
        path: sorted(paper_ids)[0]
        for path, paper_ids in canonical_paper_ids.items()
    }
    canonical_paths_seen: set[str] = set()
    canonical_paths_owned: set[str] = set()
    for row in rows:
        item = dict(row)
        paper_id = str(item.get("paper_id") or "")
        paper = papers.get(paper_id)
        canonical = canonical_file_path_for_paper(paper)
        result["items_checked"] += 1
        if not paper or not canonical:
            continue
        result["items_with_files"] += 1
        canonical_key = str(canonical)
        canonical_paths_seen.add(canonical_key)
        target_dir = local_copy_dir_for_library_folder(
            storage,
            int(item.get("folder_id") or 1),
        ).resolve()
        expected = library_item_pdf_filename(item, paper, canonical)
        actual = library_item_local_pdf_path(storage, item, paper)
        mismatch_type = ""
        canonical_owner_paper_id = canonical_owner_ids.get(canonical_key, paper_id)
        is_real_owner = (
            paper_id == canonical_owner_paper_id
            and target_dir == canonical.parent.resolve()
        )
        if is_real_owner:
            canonical_paths_owned.add(canonical_key)
            if canonical.name != expected:
                result["mismatched_real_files"] += 1
                mismatch_type = "real"
        elif not actual:
            result["missing_shortcuts"] += 1
            mismatch_type = "missing_shortcut"
        elif actual.name != expected:
            result["mismatched_shortcuts"] += 1
            mismatch_type = "shortcut"
        if mismatch_type and len(result["samples"]) < max(0, int(sample_limit)):
            result["samples"].append({
                "item_id": int(item.get("id") or 0),
                "paper_id": paper_id,
                "type": mismatch_type,
                "expected": expected,
                "actual": actual.name if actual else "",
                "folder": str(target_dir),
            })
    result["unowned_real_files"] = len(canonical_paths_seen - canonical_paths_owned)
    return result


def remove_pdf_aliases_for_paper_in_folders(storage: Storage, paper_id: str, folder_ids: list[int]) -> list[str]:
    paper_id = storage.resolve_paper_id(paper_id)
    canonical = canonical_file_path_for_paper(storage.get_paper(paper_id))
    if not canonical:
        return []
    folders = [local_copy_dir_for_library_folder(storage, int(folder_id or 0)) for folder_id in dict.fromkeys(folder_ids)]
    return remove_direct_symlinks_to(canonical, folders)


def remove_pdf_aliases_for_paths_in_folders(storage: Storage, paths: list[str], folder_ids: list[int]) -> list[str]:
    folders = [local_copy_dir_for_library_folder(storage, int(folder_id or 0)) for folder_id in dict.fromkeys(folder_ids)]
    removed: list[str] = []
    for raw_path in dict.fromkeys(str(path or "") for path in paths if path):
        removed.extend(remove_direct_symlinks_to(Path(raw_path), folders))
    return removed


def move_monitor_pdf_into_context_if_needed(storage: Storage, paper_id: str, target_dir: Path) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(paper_id)
    canonical = canonical_pdf_path_for_paper(paper)
    if not paper or not canonical:
        return False
    try:
        canonical.relative_to(DEFAULT_PDF_DIR.resolve())
    except ValueError:
        return False
    old_path = canonical
    target_path = move_original(storage, paper_id, canonical, target_dir,
                                filename=paper_pdf_basename(paper, canonical))
    if target_path == old_path:
        return False
    cleanup_empty_parents([str(old_path)], DEFAULT_PDF_DIR.resolve())
    sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=old_path)
    return True


def reconcile_paper_pdf_storage(
    storage: Storage,
    paper_id: str,
    *,
    target_dir: Path | None = None,
) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    old_target = rescue_active_original(storage, paper_id)
    if old_target:
        sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=old_target)
    target = target_dir or preferred_local_pdf_dir_for_paper(storage, paper_id)
    if not target:
        return bool(old_target)
    changed = move_monitor_pdf_into_context_if_needed(storage, paper_id, target) or bool(old_target)
    paper = storage.get_paper(paper_id)
    canonical = canonical_file_path_for_paper(paper)
    if not paper or not canonical:
        return changed
    if canonical.parent.resolve() != target.expanduser().resolve():
        return changed
    canonical_value = str(canonical)
    stored_paths = [str(paper.get(key) or "") for key in ("main_pdf_path", "merged_pdf_path")]
    for path in stored_paths:
        if path and str(Path(path).expanduser().absolute()) != canonical_value and Path(path).expanduser().resolve() == canonical:
            update_paper_file_path_references(storage, paper_id, Path(path), canonical)
            changed = True
    sync_all_pdf_aliases_for_paper(storage, paper_id)
    return changed


def move_or_alias_library_item_pdf(storage: Storage, *, item: dict[str, Any], target_folder_id: int) -> bool:
    """Move one canonical PDF or relocate one alias.

    Returns True only when the canonical file path changed and a subsequent
    full-paper alias reconciliation is therefore required.
    """
    paper_id = str(item.get("paper_id") or "")
    paper = storage.get_paper(paper_id)
    canonical = canonical_file_path_for_paper(paper)
    if not paper or not canonical:
        return False
    source_dir = local_copy_dir_for_library_folder(storage, int(item.get("folder_id") or 1)).resolve()
    target_dir = local_copy_dir_for_library_folder(storage, int(target_folder_id or 1)).resolve()
    if source_dir == target_dir:
        return False
    if is_path_inside_dir(canonical, source_dir) and canonical.parent == source_dir:
        old_path = canonical
        target_path = move_original(
            storage, paper_id, canonical, target_dir,
            filename=paper_pdf_basename(paper, canonical), exclude_item_id=int(item.get("id") or 0),
        )
        if old_path != target_path:
            remove_symlinks_to(old_path, [LIBRARY_LOCAL_COPY_ROOT, MY_PUBLICATIONS_LOCAL_COPY_ROOT, SPACES_LOCAL_COPY_ROOT])
            cleanup_local_copy_empty_parents([str(old_path)])
            return True
        return False
    removed = remove_symlinks_to(canonical, [source_dir])
    target_item_exists = bool(
        storage.conn.execute(
            """
            SELECT 1
            FROM library_items
            WHERE paper_id = ? AND folder_id = ? AND id != ?
            LIMIT 1
            """,
            (paper_id, int(target_folder_id or 1), int(item.get("id") or 0)),
        ).fetchone()
    )
    if not target_item_exists:
        create_pdf_alias(
            canonical,
            target_dir,
            library_item_pdf_filename(item, paper, canonical),
        )
    cleanup_local_copy_empty_parents(removed)
    return False


def library_items_in_folder_tree(storage: Storage, folder_id: int) -> list[dict[str, Any]]:
    rows = storage.conn.execute(
        """
        WITH RECURSIVE folder_tree(id) AS (
          SELECT id FROM library_folders WHERE id = ?
          UNION ALL
          SELECT library_folders.id
          FROM library_folders
          JOIN folder_tree ON library_folders.parent_id = folder_tree.id
        )
        SELECT *
        FROM library_items
        WHERE folder_id IN (SELECT id FROM folder_tree)
        ORDER BY id ASC
        """,
        (int(folder_id),),
    ).fetchall()
    return [dict(row) for row in rows]


def library_folder_tree_ids(storage: Storage, folder_id: int) -> list[int]:
    rows = storage.conn.execute(
        """
        WITH RECURSIVE folder_tree(id) AS (
          SELECT id FROM library_folders WHERE id = ?
          UNION ALL
          SELECT library_folders.id
          FROM library_folders
          JOIN folder_tree ON library_folders.parent_id = folder_tree.id
        )
        SELECT id FROM folder_tree
        """,
        (int(folder_id),),
    ).fetchall()
    return [int(row["id"] or 0) for row in rows]


def folder_tree_pdf_move_plan(storage: Storage, folder_id: int) -> list[dict[str, Any]]:
    plan: list[dict[str, Any]] = []
    papers: dict[str, dict[str, Any] | None] = {}
    source_dirs: dict[int, Path] = {}
    for item in library_items_in_folder_tree(storage, folder_id):
        paper_id = str(item.get("paper_id") or "")
        if paper_id not in papers:
            papers[paper_id] = storage.get_paper(paper_id)
        paper = papers[paper_id]
        canonical = canonical_file_path_for_paper(paper)
        if not paper or not canonical:
            continue
        item_folder_id = int(item.get("folder_id") or 1)
        if item_folder_id not in source_dirs:
            source_dirs[item_folder_id] = local_copy_dir_for_library_folder(
                storage,
                item_folder_id,
            ).resolve()
        source_dir = source_dirs[item_folder_id]
        plan.append({
            "item_id": int(item.get("id") or 0),
            "item": item,
            "folder_id": item_folder_id,
            "paper_id": paper_id,
            "old_path": canonical,
            "old_dir": source_dir,
            "basename": paper_pdf_basename(paper, canonical),
            "is_canonical_here": is_path_inside_dir(canonical, source_dir) and canonical.parent == source_dir,
        })
    return plan


def apply_folder_tree_pdf_move_plan(storage: Storage, plan: list[dict[str, Any]]) -> None:
    canonical_moves: dict[str, tuple[str, Path]] = {}
    canonical_moved_paper_ids: set[str] = set()
    removed_paths: list[str] = []
    target_dirs: dict[int, Path] = {}

    # Move each physical Current File first.  The complete paper sync below
    # relocates its Associated Files bundle and creates every required alias,
    # so placements of the same work must not be reconciled a second time.
    for entry in plan:
        if not entry.get("is_canonical_here"):
            continue
        item = entry.get("item")
        if not isinstance(item, dict):
            item = storage.get_library_item(int(entry.get("item_id") or 0))
        paper_id = str(entry.get("paper_id") or "")
        if not item or not paper_id:
            continue
        item_folder_id = int(entry.get("folder_id") or item.get("folder_id") or 1)
        if item_folder_id not in target_dirs:
            target_dirs[item_folder_id] = local_copy_dir_for_library_folder(
                storage,
                item_folder_id,
            ).resolve()
        target_dir = target_dirs[item_folder_id]
        old_path = entry.get("old_path")
        if isinstance(old_path, Path) and old_path.exists():
            target_path = move_original(storage, paper_id, old_path, target_dir,
                                        filename=str(entry.get("basename") or old_path.name))
            if old_path != target_path:
                canonical_moves.setdefault(str(old_path.resolve()), (paper_id, old_path))
                canonical_moved_paper_ids.add(paper_id)
                removed_paths.append(str(old_path))

    for paper_id, old_path in canonical_moves.values():
        sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=old_path)

    # Papers whose Current File stayed elsewhere only need the alias for the
    # moved placement.  This is the hot path for copied works and avoids a
    # repository-wide alias scan for every item in a folder.
    for entry in plan:
        paper_id = str(entry.get("paper_id") or "")
        if not paper_id or paper_id in canonical_moved_paper_ids:
            continue
        item = entry.get("item")
        if not isinstance(item, dict):
            item = storage.get_library_item(int(entry.get("item_id") or 0))
        if not item:
            continue
        old_dir = entry.get("old_dir")
        old_path = entry.get("old_path")
        if isinstance(old_path, Path) and isinstance(old_dir, Path):
            removed_paths.extend(remove_direct_symlinks_to(old_path, [old_dir]))
        sync_alias_for_library_item(
            storage,
            paper_id,
            int(entry.get("folder_id") or item.get("folder_id") or 1),
            item=item,
        )
    cleanup_local_copy_empty_parents(removed_paths)


def first_outside_reference_dir(storage: Storage, paper_id: str, recycle_folder_id: int) -> Path | None:
    paper_id = storage.resolve_paper_id(paper_id)
    directories = active_directories(storage, [paper_id])
    return directories[0] if directories else None


def first_outside_reference_item(
    storage: Storage,
    paper_id: str,
    recycle_folder_id: int,
    *,
    exclude_item_id: int = 0,
) -> dict[str, Any] | None:
    paper_id = storage.resolve_paper_id(paper_id)
    active_ids = {folder["id"] for folder in active_folders(storage)}
    rows = storage.conn.execute(
        """
        SELECT *
        FROM library_items
        WHERE paper_id = ?
          AND id != ?
        ORDER BY id ASC
        """,
        (str(paper_id), int(exclude_item_id or 0)),
    ).fetchall()
    for row in rows:
        item = dict(row)
        folder_id = int(item.get("folder_id") or 0)
        if folder_id in active_ids and not item.get("trashed_at"):
            return item
    return None


def promote_canonical_pdf_outside_recycle(storage: Storage, paper_id: str, recycle_folder_id: int) -> None:
    paper_id = storage.resolve_paper_id(paper_id)
    paper = storage.get_paper(paper_id)
    canonical = canonical_file_path_for_paper(paper)
    target_dir = first_outside_reference_dir(storage, paper_id, recycle_folder_id)
    if not paper or not canonical or not target_dir:
        return
    if canonical.parent.resolve() == target_dir.resolve():
        sync_all_pdf_aliases_for_paper(storage, paper_id)
        return
    old_path = canonical
    move_original(storage, paper_id, canonical, target_dir, filename=paper_pdf_basename(paper, canonical))
    sync_all_pdf_aliases_for_paper(storage, paper_id, old_target=old_path)
    cleanup_local_copy_empty_parents([str(old_path)])


def library_folder_is_within(storage: Storage, folder_id: int, ancestor_id: int) -> bool:
    current = int(folder_id or 0)
    target = int(ancestor_id or 0)
    seen: set[int] = set()
    while current and current not in seen:
        if current == target:
            return True
        seen.add(current)
        row = storage.conn.execute("SELECT parent_id FROM library_folders WHERE id = ?", (current,)).fetchone()
        if not row:
            return False
        current = int(row["parent_id"] or 0)
    return False


def paper_has_reference_outside_recycle(storage: Storage, paper_id: str, recycle_folder_id: int) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    if not paper_id:
        return False
    if paper_has_my_publication_reference(storage, paper_id):
        return True
    rows = storage.conn.execute("SELECT folder_id FROM library_items WHERE paper_id = ?", (paper_id,)).fetchall()
    for row in rows:
        if not library_folder_is_within(storage, int(row["folder_id"] or 0), recycle_folder_id):
            return True
    return False


def paper_has_my_publication_reference(storage: Storage, paper_id: str) -> bool:
    paper_id = storage.resolve_paper_id(paper_id)
    if not paper_id:
        return False
    return bool(
        storage.conn.execute(
            "SELECT 1 FROM my_publications WHERE paper_id = ? LIMIT 1",
            (str(paper_id),),
        ).fetchone()
    )


def recycle_delete_preview_for_entries(
    storage: Storage,
    entries: list[dict[str, Any]],
    *,
    recycle_folder_id: int,
) -> dict[str, Any]:
    paper_ids: list[str] = []
    item_count = 0
    folder_count = 0
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("Each entry must be an object")
        entry_type = str(entry.get("type") or "")
        entry_id = int(entry.get("id") or 0)
        if entry_type == "item":
            item = storage.get_library_item(entry_id)
            if not item:
                continue
            if not library_folder_is_within(storage, int(item.get("folder_id") or 0), recycle_folder_id):
                continue
            item_count += 1
            paper_ids.append(str(item.get("paper_id") or ""))
            continue
        if entry_type == "folder":
            folder = storage.get_library_folder(entry_id)
            if not folder:
                continue
            if not library_folder_is_within(storage, int(folder.get("id") or 0), recycle_folder_id):
                continue
            folder_count += 1
            paper_ids.extend(storage.library_paper_ids_in_folder_tree(folder_id=entry_id))
            continue
        raise ValueError("type must be item or folder")
    return recycle_delete_preview_for_papers(
        storage,
        paper_ids,
        recycle_folder_id=recycle_folder_id,
        item_count=item_count,
        folder_count=folder_count,
    )


def recycle_delete_preview_for_papers(
    storage: Storage,
    paper_ids: list[str],
    *,
    recycle_folder_id: int,
    item_count: int = 0,
    folder_count: int = 0,
) -> dict[str, Any]:
    destructive_papers: list[str] = []
    shortcut_only_papers: list[str] = []
    local_copy_paths: list[str] = []
    seen_paths: set[str] = set()
    for paper_id in dict.fromkeys(str(paper_id or "") for paper_id in paper_ids if paper_id):
        if paper_has_reference_outside_recycle(storage, paper_id, recycle_folder_id):
            shortcut_only_papers.append(paper_id)
            continue
        destructive_papers.append(paper_id)
        paper = storage.get_paper(paper_id)
        if not paper:
            continue
        for path in library_file_paths_for_delete(storage, paper):
            path_key = str(path)
            if path_key in seen_paths:
                continue
            seen_paths.add(path_key)
            local_copy_paths.append(path_key)
    return {
        "requires_confirmation": bool(destructive_papers),
        "metadata_paper_count": len(destructive_papers),
        "shortcut_only_paper_count": len(shortcut_only_papers),
        "local_copy_paths": local_copy_paths,
        "local_copy_count": len(local_copy_paths),
        "item_count": int(item_count or 0),
        "folder_count": int(folder_count or 0),
    }


def trash_unreferenced_recycle_paper_files(
    storage: Storage,
    paper_ids: list[str],
    *,
    recycle_folder_id: int,
) -> dict[str, Any]:
    trashed_files: list[str] = []
    skipped: list[str] = []
    for paper_id in dict.fromkeys(str(paper_id or "") for paper_id in paper_ids if paper_id):
        if paper_has_reference_outside_recycle(storage, paper_id, recycle_folder_id):
            skipped.append(paper_id)
            continue
        trashed_files.extend(delete_library_paper_files(storage, [paper_id]))
    return {"trashed_files": trashed_files, "skipped_papers": skipped}


def cleanup_unreferenced_recycle_papers(
    storage: Storage,
    paper_ids: list[str],
    *,
    recycle_folder_id: int,
    delete_files: bool = True,
) -> dict[str, Any]:
    cleaned: list[str] = []
    skipped: list[str] = []
    deleted_files: list[str] = []
    for paper_id in dict.fromkeys(str(paper_id or "") for paper_id in paper_ids if paper_id):
        if paper_has_reference_outside_recycle(storage, paper_id, recycle_folder_id):
            skipped.append(paper_id)
            continue
        if delete_files:
            deleted_files.extend(delete_library_paper_files(storage, [paper_id]))
        storage.conn.execute("DELETE FROM resources WHERE paper_id = ?", (paper_id,))
        storage.conn.execute("DELETE FROM papers WHERE paper_id = ?", (paper_id,))
        cleaned.append(paper_id)
    storage.conn.commit()
    return {"cleaned_papers": cleaned, "skipped_papers": skipped, "deleted_files": deleted_files}


def delete_pdf_files_for_paper(paper: dict[str, Any]) -> list[str]:
    paths = []
    for key in ("merged_pdf_path", "main_pdf_path"):
        if paper.get(key):
            paths.append(str(paper[key]))
    supplements = paper.get("supplement_pdf_paths")
    if supplements:
        try:
            paths.extend(str(path) for path in json.loads(supplements) if path)
        except (TypeError, json.JSONDecodeError):
            pass
    deleted = delete_allowed_files(paths, allowed_pdf_roots())
    for root in allowed_pdf_roots():
        cleanup_empty_parents(deleted, root)
    return deleted


def daiqo_copy_path(raw_path: str) -> Path | None:
    if not raw_path:
        return None
    try:
        path = Path(raw_path).expanduser().resolve()
    except OSError:
        return None
    if not path.exists() or not path.is_file():
        return None
    return path if is_allowed_file(path, allowed_pdf_roots()) else None


def library_file_paths_for_delete(storage: Storage, paper: dict[str, Any]) -> list[Path]:
    paths: list[Path] = []
    for key in ("merged_pdf_path", "main_pdf_path", "source_path"):
        raw_path = str(paper.get(key) or "")
        path = daiqo_copy_path(raw_path)
        if path:
            paths.append(path)
    paper_id = str(paper.get("paper_id") or "")
    if paper_id:
        rows = storage.conn.execute(
            """
            SELECT stored_path
            FROM resources
            WHERE paper_id = ?
              AND stored_path IS NOT NULL
              AND stored_path != ''
            """,
            (paper_id,),
        ).fetchall()
        for row in rows:
            path = daiqo_copy_path(str(row["stored_path"] or ""))
            if path:
                paths.append(path)
    # Folder aliases are files in Finder, never the attachment directory they
    # point at. Include only this work's managed projections in final cleanup.
    for value in parse_raw_json(paper).get("file_layout", {}).get("associated_aliases", []):
        path = Path(value).expanduser().absolute()
        if path.is_relative_to(ASSOCIATED_FILES_ROOT.resolve()) and finder_alias.is_alias(path):
            paths.append(path)
    unique: list[Path] = []
    seen: set[str] = set()
    for path in paths:
        key = str(path)
        if key not in seen:
            seen.add(key)
            unique.append(path)
    return unique


def library_recycle_orphan_paths(storage: Storage, recycle_folder_id: int) -> list[Path]:
    recycle_dir = local_copy_dir_for_library_folder(storage, int(recycle_folder_id or 0)).expanduser()
    recycle_root = recycle_dir.resolve()
    if not recycle_root.exists() or not recycle_root.is_dir():
        return []
    referenced: set[str] = set()
    recycle_prefixes = list(dict.fromkeys(
        str(path).rstrip(os.sep) + os.sep + "%"
        for path in (recycle_dir.absolute(), recycle_root)
    ))
    paper_path_columns = ("main_pdf_path", "merged_pdf_path", "source_path")
    paper_path_where = " OR ".join(
        f"{column} LIKE ?"
        for column in paper_path_columns
        for _ in recycle_prefixes
    )
    paper_path_params = [prefix for _ in paper_path_columns for prefix in recycle_prefixes]
    rows = storage.conn.execute(
        f"""
        SELECT main_pdf_path, merged_pdf_path, source_path
        FROM papers
        WHERE {paper_path_where}
        """,
        paper_path_params,
    ).fetchall()
    for row in rows:
        for raw_path in (row["main_pdf_path"], row["merged_pdf_path"], row["source_path"]):
            if not raw_path:
                continue
            try:
                path = Path(str(raw_path)).expanduser().resolve()
            except OSError:
                continue
            if is_relative_to(path, recycle_root):
                referenced.add(str(path))
    resource_rows = storage.conn.execute(
        f"SELECT stored_path FROM resources WHERE {' OR '.join('stored_path LIKE ?' for _ in recycle_prefixes)}",
        recycle_prefixes,
    ).fetchall()
    for row in resource_rows:
        try:
            path = Path(str(row["stored_path"])).expanduser().resolve()
        except OSError:
            continue
        if is_relative_to(path, recycle_root):
            referenced.add(str(path))
    orphans: list[Path] = []
    for candidate in recycle_root.rglob("*"):
        if not candidate.is_file() and not finder_alias.is_alias(candidate):
            continue
        try:
            resolved = candidate.expanduser().resolve()
        except OSError:
            resolved = candidate.absolute()
        if str(resolved) not in referenced:
            orphans.append(candidate.absolute())
    return sorted(orphans, key=lambda path: str(path).lower())


def delete_library_paper_files(storage: Storage, paper_ids: list[str]) -> list[str]:
    deleted: list[str] = []
    seen_paths: set[str] = set()
    cleared_paper_ids: set[str] = set()
    for paper_id in dict.fromkeys(str(paper_id or "") for paper_id in paper_ids if paper_id):
        paper = storage.get_paper(paper_id)
        if not paper:
            continue
        paths = library_file_paths_for_delete(storage, paper)
        if not paths:
            continue
        for path in paths:
            path_key = str(path)
            if path_key in seen_paths:
                cleared_paper_ids.add(paper_id)
                continue
            seen_paths.add(path_key)
            try:
                move_path_to_macos_trash(path)
                deleted.append(path_key)
            except FileNotFoundError:
                continue
        cleared_paper_ids.add(paper_id)
    for raw_path in deleted:
        path = Path(raw_path)
        if is_relative_to(path.parent, DEFAULT_LIBRARY_IMPORT_DIR.resolve()):
            cleanup_empty_parents([raw_path], DEFAULT_LIBRARY_IMPORT_DIR.resolve())
        elif is_relative_to(path.parent, DEFAULT_PDF_DIR.resolve()):
            cleanup_empty_parents([raw_path], DEFAULT_PDF_DIR.resolve())
    for paper_id in cleared_paper_ids:
        storage.clear_download_status(paper_id)
    clear_deleted_library_file_references(storage, deleted)
    return deleted


def clear_deleted_library_file_references(storage: Storage, deleted_paths: list[str]) -> None:
    paths = [str(Path(path).expanduser().resolve()) for path in deleted_paths if path]
    if not paths:
        return
    placeholders = ", ".join(["?"] * len(paths))
    storage.conn.execute(f"DELETE FROM resources WHERE stored_path IN ({placeholders})", paths)
    storage.conn.execute(f"UPDATE papers SET source_path = NULL WHERE source_path IN ({placeholders})", paths)
    storage.conn.commit()


def clear_library_folder_contents(storage: Storage, *, folder_id: int) -> dict[str, int]:
    folder_id = int(folder_id)
    tree_sql = """
        WITH RECURSIVE folder_tree(id, depth) AS (
          SELECT id, 0 FROM library_folders WHERE id = ?
          UNION ALL
          SELECT library_folders.id, folder_tree.depth + 1
          FROM library_folders
          JOIN folder_tree ON library_folders.parent_id = folder_tree.id
        )
    """
    exists = storage.conn.execute("SELECT 1 FROM library_folders WHERE id = ?", (folder_id,)).fetchone()
    if not exists:
        return {"items": 0, "folders": 0}
    item_count = int(
        storage.conn.execute(
            tree_sql
            + """
            SELECT COUNT(*) AS count
            FROM library_items
            WHERE folder_id IN (SELECT id FROM folder_tree)
            """,
            (folder_id,),
        ).fetchone()["count"]
        or 0
    )
    folder_count = int(
        storage.conn.execute(
            tree_sql
            + """
            SELECT COUNT(*) AS count
            FROM library_folders
            WHERE id != ? AND id IN (SELECT id FROM folder_tree)
            """,
            (folder_id, folder_id),
        ).fetchone()["count"]
        or 0
    )
    folders_to_delete = [
        int(row["id"])
        for row in storage.conn.execute(
            tree_sql
            + """
            SELECT id
            FROM folder_tree
            WHERE id != ?
            ORDER BY depth DESC, id DESC
            """,
            (folder_id, folder_id),
        ).fetchall()
    ]
    storage.conn.execute(
        tree_sql
        +
        """
        DELETE FROM library_items
        WHERE folder_id IN (SELECT id FROM folder_tree)
        """,
        (folder_id,),
    )
    for child_folder_id in folders_to_delete:
        storage.conn.execute("DELETE FROM library_folders WHERE id = ?", (child_folder_id,))
    storage.conn.commit()
    return {"items": item_count, "folders": folder_count}


def delete_analysis_file_for_paper(paper: dict[str, Any]) -> list[str]:
    return delete_allowed_files([str(paper.get("analysis_path") or "")], [DEFAULT_ANALYSIS_DIR.resolve()])


def delete_allowed_files(paths: list[str], roots: list[Path]) -> list[str]:
    deleted: list[str] = []
    for raw_path in dict.fromkeys(path for path in paths if path):
        requested = Path(raw_path).expanduser().resolve()
        if not is_allowed_file(requested, roots) or not requested.exists() or not requested.is_file():
            continue
        move_path_to_macos_trash(requested)
        deleted.append(str(requested))
    return deleted


def move_path_to_macos_trash(path: Path) -> Path:
    # Move the link itself, even when its target no longer exists.
    requested = path.expanduser().absolute()
    requested = requested.parent.resolve() / requested.name
    if not os.path.lexists(requested):
        raise FileNotFoundError(str(requested))
    if sys.platform != "darwin":
        trash_dir = Path.home() / ".Trash"
        trash_dir.mkdir(parents=True, exist_ok=True)
        target = unique_trash_path(trash_dir / requested.name)
        shutil.move(str(requested), str(target))
        return target
    helper = ROOT / "Gewu Insight.app" / "Contents" / "MacOS" / "Gewu Insight"
    result = subprocess.run(
        [str(helper), "--trash-item", str(requested)], check=False,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=30,
    )
    destination = str(result.stdout or "").strip()
    if result.returncode == 0 and destination and not os.path.lexists(requested):
        return Path(destination).expanduser()
    detail = clean_text(result.stderr or "") or "macOS did not confirm the Trash operation"
    message = f"Could not move {requested.name} to macOS Trash. {detail}"
    if any(word in detail.lower() for word in ("permission", "not authorized", "operation not permitted")):
        raise PermissionError(message)
    raise MacOSTrashError(message)


def unique_trash_path(target: Path) -> Path:
    if not os.path.lexists(target):
        return target
    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    stem = target.stem
    suffix = target.suffix
    parent = target.parent
    for index in range(1, 1000):
        candidate = parent / f"{stem} {timestamp}-{index}{suffix}"
        if not os.path.lexists(candidate):
            return candidate
    raise FileExistsError(str(target))


def cleanup_empty_parents(deleted_paths: list[str], root: Path) -> None:
    root = root.expanduser().resolve()
    for raw_path in deleted_paths:
        current = Path(raw_path).expanduser().absolute().parent.resolve()
        while is_relative_to(current, root) and current != root:
            try:
                current.rmdir()
            except OSError:
                break
            current = current.parent


def file_url(path: str) -> str:
    if not path:
        return ""
    return "/files?path=" + quote(path)


def normalize_file_icon_extension(ext: str) -> str:
    value = str(ext or "").strip().lower()
    value = value[1:] if value.startswith(".") else value
    value = re.sub(r"[^a-z0-9]+", "", value)
    return value or "none"


def file_type_icon_svg(ext: str) -> str:
    normalized = normalize_file_icon_extension(ext)
    style = FILE_ICON_STYLES.get(normalized, FILE_ICON_DEFAULT_STYLE)
    label = html.escape(str(style.get("label") or normalized.upper() or "FILE")[:5])
    kind = str(style.get("kind") or "document")
    accent = str(style.get("accent") or FILE_ICON_DEFAULT_STYLE["accent"])
    fill = str(style.get("fill") or FILE_ICON_DEFAULT_STYLE["fill"])
    glyph = file_type_icon_glyph(kind, accent)
    label_size = file_type_icon_label_size(label)
    return f"""<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64" role="img" aria-label="{label} file icon">
  <defs>
    <linearGradient id="paper" x1="12" y1="5" x2="52" y2="59" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="#ffffff"/>
      <stop offset="1" stop-color="{fill}"/>
    </linearGradient>
    <linearGradient id="badge" x1="13" y1="42" x2="51" y2="58" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="{accent}"/>
      <stop offset="1" stop-color="{accent}" stop-opacity="0.82"/>
    </linearGradient>
  </defs>
  <path d="M15 5.5h24.8L51.5 17v39.5c0 1.7-1.3 3-3 3h-33c-1.7 0-3-1.3-3-3v-48c0-1.7 1.3-3 3-3z" fill="url(#paper)" stroke="#aeb8c6" stroke-width="1.6"/>
  <path d="M40 6.4V16c0 1 .8 1.8 1.8 1.8h9" fill="#e5ecf4" stroke="#aeb8c6" stroke-width="1.2"/>
  {glyph}
  <rect x="12.5" y="42" width="39" height="16" rx="4.2" fill="url(#badge)"/>
  <text x="32" y="53.5" text-anchor="middle" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif" font-size="{label_size}" font-weight="800" letter-spacing=".2" fill="#ffffff">{label}</text>
</svg>"""


def file_type_icon_label_size(label: str) -> int:
    length = len(label)
    if length >= 5:
        return 7
    if length == 4:
        return 8
    return 9


